do
    local function CriarCaminhoRecursivo(Path: string, IsFile: boolean?)
        if not isfolder or not makefolder then
            return
        end

        local Segmentos = Path:split("/")
        local PercorridoCaminho = ""

        if IsFile then
            table.remove(Segmentos, #Segmentos)
        end

        for _, Segmento in ipairs(Segmentos) do
            if not isfolder(PercorridoCaminho .. Segmento) then
                makefolder(PercorridoCaminho .. Segmento)
            end

            PercorridoCaminho = PercorridoCaminho .. Segmento .. "/"
        end

        return PercorridoCaminho
    end

    function GerenciadorImagens.AddAsset(
        RecursoNome: string,
        RobloxRecursoId: number,
        URL: string,
        ForcarBaixarNovamente: boolean?
    )
        if RecursosGerenciadorImagens[RecursoNome] ~= nil then
            error(string.format("Asset %q already exists", RecursoNome))
        end

        assert(typeof(RobloxRecursoId) == "number", "RobloxAssetId must be a number")

        RecursosGerenciadorImagens[RecursoNome] = {
            RobloxId = RobloxRecursoId,
            Path = string.format("Resonance/custom_assets/%s", RecursoNome),
            URL = URL,

            Id = nil,
        }

        GerenciadorImagens.DownloadAsset(RecursoNome, ForcarBaixarNovamente)
    end

    function GerenciadorImagens.GetAsset(RecursoNome: string)
        if not RecursosGerenciadorImagens[RecursoNome] then
            return nil
        end

        local RecursoDados = RecursosGerenciadorImagens[RecursoNome]
        if RecursoDados.Id then
            return RecursoDados.Id
        end

        local RecursoID = string.format("rbxassetid://%s", RecursoDados.RobloxId)

        if getcustomasset then
            local Sucesso, NovoID = pcall(getcustomasset, RecursoDados.Path)

            if Sucesso and NovoID then
                RecursoID = NovoID
            end
        end

        RecursoDados.Id = RecursoID
        return RecursoID
    end

    function GerenciadorImagens.DownloadAsset(RecursoNome: string, ForcarBaixarNovamente: boolean?)
        if not getcustomasset or not writefile or not isfile then
            return false, "missing functions"
        end

        local RecursoDados = RecursosGerenciadorImagens[RecursoNome]

        CriarCaminhoRecursivo(RecursoDados.Path, true)

        if ForcarBaixarNovamente ~= true and isfile(RecursoDados.Path) then
            return true, nil
        end

        local sucesso, erroMensagem = pcall(function()
            writefile(RecursoDados.Path, game:HttpGet(RecursoDados.URL))
        end)

        return sucesso, erroMensagem
    end

end

