local function ObterEsquemaValor(Indice_2)
    if not Indice_2 then
        return nil
    end

    local SubstituirApelidoIndice = EsquemaSubstituirApelido[Indice_2]
    if SubstituirApelidoIndice and Library.Scheme[SubstituirApelidoIndice] ~= nil then
        Library.Scheme[Indice_2] = Library.Scheme[SubstituirApelidoIndice]
        Library.Scheme[SubstituirApelidoIndice] = nil

        return Library.Scheme[Indice_2]
    end

    local ApelidoIndice = EsquemaApelido[Indice_2]
    if ApelidoIndice and Library.Scheme[ApelidoIndice] ~= nil then
        warn(string.format("Scheme Value %q is deprecated, please use %q instead.", Indice_2, ApelidoIndice))
        return Library.Scheme[ApelidoIndice]
    end

    return Library.Scheme[Indice_2]
end

local function AguardarParaEvento(Event, Timeout, Condition)
    local Vinculavel = Instance.new("BindableEvent")
    local Conexao = Event:Once(function(...)
        if not Condition or typeof(Condition) == "function" and Condition(...) then
            Vinculavel:Fire(true)
        else
            Vinculavel:Fire(false)
        end
    end)
    task.delay(Timeout, function()
        Conexao:Disconnect()
        Vinculavel:Fire(false)
    end)

    local Resultado = Vinculavel.Event:Wait()
    Vinculavel:Destroy()

    return Resultado
end

local function EhMouseEntrada(Entrada_2: InputObject, IncludeM2: boolean?)
    return Entrada_2.UserInputType == Enum.UserInputType.MouseButton1
        or (IncludeM2 == true and Entrada_2.UserInputType == Enum.UserInputType.MouseButton2)
        or Entrada_2.UserInputType == Enum.UserInputType.Touch
end
local function EhCliqueEntrada(Entrada_2: InputObject, IncludeM2: boolean?)
    return EhMouseEntrada(Entrada_2, IncludeM2)
        and Entrada_2.UserInputState == Enum.UserInputState.Begin
        and Library.IsRobloxFocused
end
local function EhPairarEntrada(Entrada_2: InputObject)
    return (Entrada_2.UserInputType == Enum.UserInputType.MouseMovement or Entrada_2.UserInputType == Enum.UserInputType.Touch)
        and Entrada_2.UserInputState == Enum.UserInputState.Change
end
local function EhArrastarEntrada(Entrada_2: InputObject, IncludeM2: boolean?)
    return EhMouseEntrada(Entrada_2, IncludeM2)
        and (Entrada_2.UserInputState == Enum.UserInputState.Begin or Entrada_2.UserInputState == Enum.UserInputState.Change)
        and Library.IsRobloxFocused
end
local function EhMouseCliqueEntrada(Entrada_2: InputObject)
    return Entrada_2.UserInputType == Enum.UserInputType.MouseButton1 or
        Entrada_2.UserInputType == Enum.UserInputType.MouseButton2 or
        Entrada_2.UserInputType == Enum.UserInputType.MouseButton3
end
local function EhMovimentoEntrada(Entrada_2: InputObject)
    return (Entrada_2.UserInputType == Enum.UserInputType.MouseMovement or Entrada_2.UserInputType == Enum.UserInputType.Touch)
        and Library.IsRobloxFocused
end

local function ObterTabelaTamanho(Tabela: { [any]: any })
    local Tamanho = 0

    for _, _ in Tabela do
        Tamanho += 1
    end

    return Tamanho
end
local function EhSequencialVetor(Tabela: { [any]: any })
    for Tecla in Tabela do
        if typeof(Tecla) ~= "number" or Tecla < 1 or Tecla % 1 ~= 0 then
            return false
        end
    end

    return true
end

local function PararInterpolacao(Interpolacao: TweenBase, Destroy: boolean?)
    if not Interpolacao then
        return
    end

    if Interpolacao.PlaybackState == Enum.PlaybackState.Playing then
        Interpolacao:Cancel()
    end

    if Destroy == true then
        pcall(Interpolacao.Destroy, Interpolacao)
    end
end

local function Aparar(Texto_2: string)
    return Texto_2:match("^%s*(.-)%s*$")
end
local function Arredondar(Valor, Rounding)
    assert(Rounding >= 0, "Invalid rounding number.")

    if Rounding == 0 then
        return math.floor(Valor)
    end

    return tonumber(string.format("%." .. Rounding .. "f", Valor))
end

local function AproximadoPontuacao(Texto_2: string, Pesquisa: string): (boolean, number)
    if Pesquisa == "" then
        return true, 0
    end
    if Texto_2 == "" then
        return false, 0
    end

    local ExatoIndice = Texto_2:find(Pesquisa, 1, true)
    if ExatoIndice then
        local AnteriorPers = ExatoIndice > 1 and Texto_2:sub(ExatoIndice - 1, ExatoIndice - 1) or ""
        local EmBoundary = ExatoIndice == 1 or AnteriorPers:match("[%s%p_]") ~= nil

        return true, 1e5 - ExatoIndice + (EmBoundary and 500 or 0) + (Pesquisa:len() * 5)
    end

    local TextoTam, PesquisaTam = Texto_2:len(), Pesquisa:len()
    if PesquisaTam > TextoTam then
        return false, 0
    end

    local PesquisaIndice = 1
    local Pontuacao = 0
    local ExecutarComprimento = 0
    local UltimoCorrespondenciaIndice = 0

    for TextoIndice = 1, TextoTam do
        if PesquisaIndice > PesquisaTam then
            break
        end

        if Texto_2:sub(TextoIndice, TextoIndice) == Pesquisa:sub(PesquisaIndice, PesquisaIndice) then
            local AnteriorPers = TextoIndice > 1 and Texto_2:sub(TextoIndice - 1, TextoIndice - 1) or ""
            local EmBoundary = TextoIndice == 1 or AnteriorPers:match("[%s%p_]") ~= nil

            ExecutarComprimento = (UltimoCorrespondenciaIndice == TextoIndice - 1) and (ExecutarComprimento + 1) or 1
            Pontuacao += 1 + (EmBoundary and 6 or 0) + math.min(ExecutarComprimento - 1, 5) * 3

            UltimoCorrespondenciaIndice = TextoIndice
            PesquisaIndice += 1
        end
    end

    if PesquisaIndice <= PesquisaTam then
        return false, 0 
    end

    Pontuacao -= (UltimoCorrespondenciaIndice - PesquisaTam) * 0.05 
    return true, Pontuacao
end

local function NormalizarPesquisa(Pesquisa: string): string
    return (Pesquisa:gsub("%s+", ""))
end

local function TentarAproximadoCorrespondencia(Texto_2: any, Pesquisa: string): (boolean, number)
    if typeof(Texto_2) ~= "string" or Texto_2 == "" then
        return false, 0
    end

    return AproximadoPontuacao(Texto_2:lower(), Pesquisa)
end

local function AproximadoCorrespondenciaPontuacao(Texto_2: any, Pesquisa: string): number
    if typeof(Texto_2) ~= "string" or Texto_2 == "" then
        return 0
    end

    local Normalizado = NormalizarPesquisa(Texto_2:lower())
    local Correspondeu, Pontuacao = AproximadoPontuacao(Normalizado, Pesquisa)
    if not Correspondeu then
        return 0
    end

    if Normalizado == Pesquisa then
        Pontuacao += 1000
    end

    return Pontuacao
end

local function CorrespondePesquisa(ElementoInfo, Pesquisa: string, ForceMatch: boolean?): boolean
    if not ElementoInfo then
        return false
    end
    if ForceMatch then
        return true
    end

    if TentarAproximadoCorrespondencia(ElementoInfo.Text, Pesquisa) then
        return true
    end
    if TentarAproximadoCorrespondencia(ElementoInfo.Tooltip, Pesquisa) then
        return true
    end
    if TentarAproximadoCorrespondencia(ElementoInfo.DisabledTooltip, Pesquisa) then
        return true
    end

    if typeof(ElementoInfo.Values) == "table" then
        local Marcado = 0
        for Tecla, Valor in ElementoInfo.Values do
            Marcado += 1
            if Marcado > 200 then
                break
            end

            if TentarAproximadoCorrespondencia(Valor, Pesquisa) or (typeof(Valor) ~= "string" and TentarAproximadoCorrespondencia(tostring(Valor), Pesquisa)) then
                return true
            end
            if typeof(Tecla) == "string" and TentarAproximadoCorrespondencia(Tecla, Pesquisa) then
                return true
            end
        end
    end

    return false
end

local function ObterJogadores(ExcludeLocalPlayer: boolean?)
    local JogadorLista = Players:GetPlayers()

    if ExcludeLocalPlayer then
        local Indice = table.find(JogadorLista, JogadorLocal)
        if Indice then
            table.remove(JogadorLista, Indice)
        end
    end

    table.sort(JogadorLista, function(Jogador1, Jogador2)
        return Jogador1.Name:lower() < Jogador2.Name:lower()
    end)

    return JogadorLista
end
local function ObterEquipes()
    local EquipeLista = Teams:GetTeams()

    table.sort(EquipeLista, function(Equipe1, Equipe2)
        return Equipe1.Name:lower() < Equipe2.Name:lower()
    end)

    return EquipeLista
end

function Library:UpdateDependencyBoxes()
    for _, CaixaDep in Library.DependencyBoxes do
        CaixaDep:Update(true)
    end

    if Library.Searching then
        Library:UpdateSearch(Library.SearchText)
    end
end

function Library:UpdateAddons(Pai)
    if not Pai or not Pai.Addons then
        return
    end

    for _, Complemento in Pai.Addons do
        Complemento:Update()
    end
end

local function VerificarCaixaDep(Caixa, Pesquisa, ForceVisible: boolean?)
    local VisivelElementos = 0
    local MelhorPontuacao = 0

    for _, ElementoInfo in Caixa.Elements do
        if ElementoInfo.Type == "Divider" then
            ElementoInfo.Holder.Visible = false
            continue
        elseif ElementoInfo.SubButton then
            
            local Visivel = false

            if CorrespondePesquisa(ElementoInfo, Pesquisa, ForceVisible) and ElementoInfo.Visible then
                Visivel = true
                MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(ElementoInfo.Text, Pesquisa))
            else
                ElementoInfo.Base.Visible = false
            end
            if CorrespondePesquisa(ElementoInfo.SubButton, Pesquisa, ForceVisible) and ElementoInfo.SubButton.Visible then
                Visivel = true
                MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(ElementoInfo.SubButton.Text, Pesquisa))
            else
                ElementoInfo.SubButton.Base.Visible = false
            end
            ElementoInfo.Holder.Visible = Visivel
            if Visivel then
                VisivelElementos += 1
            end

            continue
        end

        if ElementoInfo.Text and CorrespondePesquisa(ElementoInfo, Pesquisa, ForceVisible) and ElementoInfo.Visible then
            ElementoInfo.Holder.Visible = true
            VisivelElementos += 1
            MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(ElementoInfo.Text, Pesquisa))
        else
            ElementoInfo.Holder.Visible = false
        end
    end

    for _, CaixaDep in Caixa.DependencyBoxes do
        if not CaixaDep.Visible then
            continue
        end

        local DepVisivel, DepPontuacao = VerificarCaixaDep(CaixaDep, Pesquisa, ForceVisible)
        VisivelElementos += DepVisivel
        if DepPontuacao > MelhorPontuacao then
            MelhorPontuacao = DepPontuacao
        end
    end

    Caixa.Holder.Visible = VisivelElementos > 0
    return VisivelElementos, MelhorPontuacao
end
local function RestaurarCaixaDep(Caixa)
    for _, ElementoInfo in Caixa.Elements do
        ElementoInfo.Holder.Visible = ElementoInfo.Visible ~= false

        if ElementoInfo.SubButton then
            ElementoInfo.Base.Visible = ElementoInfo.Visible
            ElementoInfo.SubButton.Base.Visible = ElementoInfo.SubButton.Visible
        end
    end

    Caixa:Resize()
    Caixa.Holder.Visible = true

    for _, CaixaDep in Caixa.DependencyBoxes do
        if not CaixaDep.Visible then
            continue
        end

        RestaurarCaixaDep(CaixaDep)
    end
end

function SyncPopOutVisibility(Caixa: any)
    if not Caixa.PopOutFloat then
        return
    end

    Caixa.PopOutFloat.Visible = Caixa.BoxHolder.Visible ~= false and Caixa.Visible ~= false
end

local function EscurecerDestacarForaClonar(Root: GuiObject)
    for _, Descendente in Root:QueryDescendants("TextLabel, TextButton, TextBox") do
        Descendente.TextTransparency = math.max(Descendente.TextTransparency, 0.45)
    end

    for _, Descendente in Root:QueryDescendants("ImageLabel, ImageButton") do
        Descendente.ImageTransparency = math.max(Descendente.ImageTransparency, 0.45)
    end

    for _, Descendente in Root:QueryDescendants("GuiButton") do
        Descendente.Active = false
        Descendente.AutoButtonColor = false
    end
end

local function EhTelaPontoForaPrincipal(Ponto: Vector2): boolean
    local PrincipalQuadro = Library.Window and Library.Window.MainFrame
    if not PrincipalQuadro or not Library.Toggled or not PrincipalQuadro.Visible then
        return true
    end

    return not Library:MouseIsOverFrame(PrincipalQuadro, Ponto)
end

local function ObterTopoFlutuanteEm(Ponto: Vector2): GuiObject?
    local Melhor: GuiObject? = nil
    local MelhorOrdem = -math.huge
    local Flutuantes = Library.Floats

    for _, Superficie in Library.DraggableElements do
        if not Superficie or not Superficie.Parent or not Superficie.Visible then
            continue
        end
        if Flutuantes and Superficie.Parent ~= Flutuantes then
            continue
        end
        if not Library:MouseIsOverFrame(Superficie, Ponto) then
            continue
        end

        local IrmaoIndice = tonumber(select(2, pcall(function() return Superficie:GetSiblingIndex() end))) or 0
        local Ordem = Superficie.ZIndex * 100000 + IrmaoIndice
        if Ordem >= MelhorOrdem then
            MelhorOrdem = Ordem
            Melhor = Superficie
        end
    end

    return Melhor
end

local function ObterDestacarForaCorpoMaxAltura(Caixa: any, Reserved: number): number
    local Flutuante = Caixa.PopOutFloat
    local ScreenGui = Library.ScreenGui
    if not Flutuante or not ScreenGui then
        return math.huge
    end

    local Espaco = 12 * Library.DPIScale
    local MaxInferior = ScreenGui.AbsolutePosition.Y + ScreenGui.AbsoluteSize.Y - Espaco
    local Disponivel = math.min(MaxInferior - Flutuante.AbsolutePosition.Y, ScreenGui.AbsoluteSize.Y * 0.9)
    local TelaMax = math.max(0, Disponivel / Library.DPIScale - Reserved)

    local PersonalizadoMax = Caixa.PopOutMaxHeight
    if typeof(PersonalizadoMax) == "number" then
        return math.min(TelaMax, math.max(0, PersonalizadoMax))
    end

    return TelaMax
end

local function AplicarPesquisaParaAba(Aba, Pesquisa)
    if not Aba then
        return false, 0
    end

    local TemVisivel = false
    local MelhorPontuacao = 0

    local AbaCorresponde = TentarAproximadoCorrespondencia(Aba.Name, Pesquisa) or TentarAproximadoCorrespondencia(Aba.Description, Pesquisa)
    MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(Aba.Name, Pesquisa), AproximadoCorrespondenciaPontuacao(Aba.Description, Pesquisa))

    for _, CaixaGrupo in Aba.Groupboxes do
        if CaixaGrupo.Visible == false then
            continue
        end

        local CaixaGrupoCorresponde = AbaCorresponde or (TentarAproximadoCorrespondencia(CaixaGrupo.Name, Pesquisa) or TentarAproximadoCorrespondencia(CaixaGrupo.Description, Pesquisa))
        MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(CaixaGrupo.Name, Pesquisa), AproximadoCorrespondenciaPontuacao(CaixaGrupo.Description, Pesquisa))

        local VisivelElementos = 0
        for _, ElementoInfo in CaixaGrupo.Elements do
            if ElementoInfo.Type == "Divider" then
                ElementoInfo.Holder.Visible = false
                continue
            elseif ElementoInfo.SubButton then
                
                local Visivel = false
                if CorrespondePesquisa(ElementoInfo, Pesquisa, CaixaGrupoCorresponde) and ElementoInfo.Visible then
                    Visivel = true
                    MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(ElementoInfo.Text, Pesquisa))
                else
                    ElementoInfo.Base.Visible = false
                end

                if CorrespondePesquisa(ElementoInfo.SubButton, Pesquisa, CaixaGrupoCorresponde) and ElementoInfo.SubButton.Visible then
                    Visivel = true
                    MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(ElementoInfo.SubButton.Text, Pesquisa))
                else
                    ElementoInfo.SubButton.Base.Visible = false
                end

                ElementoInfo.Holder.Visible = Visivel
                if Visivel then
                    VisivelElementos += 1
                end

                continue
            end

            if ElementoInfo.Text and CorrespondePesquisa(ElementoInfo, Pesquisa, CaixaGrupoCorresponde) and ElementoInfo.Visible then
                ElementoInfo.Holder.Visible = true
                VisivelElementos += 1
                MelhorPontuacao = math.max(MelhorPontuacao, AproximadoCorrespondenciaPontuacao(ElementoInfo.Text, Pesquisa))
            else
                ElementoInfo.Holder.Visible = false
            end
        end

        for _, CaixaDep in CaixaGrupo.DependencyBoxes do
            if not CaixaDep.Visible then
                continue
            end

            local DepVisivel, DepPontuacao = VerificarCaixaDep(CaixaDep, Pesquisa, CaixaGrupoCorresponde)
            VisivelElementos += DepVisivel
            if DepPontuacao > MelhorPontuacao then
                MelhorPontuacao = DepPontuacao
            end
        end

        if VisivelElementos > 0 then
            CaixaGrupo:Resize()
            TemVisivel = true
        end
        CaixaGrupo.BoxHolder.Visible = VisivelElementos > 0
        SyncPopOutVisibility(CaixaGrupo)
    end

    for _, CaixaAbas in Aba.Tabboxes do
        local VisivelAbas = 0
        local VisivelElementos = {}
        local SubAbaPontuacoes = {}

        for _, SubAba in CaixaAbas.Tabs do
            VisivelElementos[SubAba] = 0

            local SubAbaCorresponde = AbaCorresponde or TentarAproximadoCorrespondencia(SubAba.Name, Pesquisa)
            local SubPontuacao = AproximadoCorrespondenciaPontuacao(SubAba.Name, Pesquisa)
            MelhorPontuacao = math.max(MelhorPontuacao, SubPontuacao)

            for _, ElementoInfo in SubAba.Elements do
                if ElementoInfo.Type == "Divider" then
                    ElementoInfo.Holder.Visible = false
                    continue
                elseif ElementoInfo.SubButton then
                    
                    local Visivel = false
                    if CorrespondePesquisa(ElementoInfo, Pesquisa, SubAbaCorresponde) and ElementoInfo.Visible then
                        Visivel = true
                        local ElementoPontuacao = AproximadoCorrespondenciaPontuacao(ElementoInfo.Text, Pesquisa)
                        SubPontuacao = math.max(SubPontuacao, ElementoPontuacao)
                        MelhorPontuacao = math.max(MelhorPontuacao, ElementoPontuacao)
                    else
                        ElementoInfo.Base.Visible = false
                    end

                    if CorrespondePesquisa(ElementoInfo.SubButton, Pesquisa, SubAbaCorresponde) and ElementoInfo.SubButton.Visible then
                        Visivel = true
                        local ElementoPontuacao = AproximadoCorrespondenciaPontuacao(ElementoInfo.SubButton.Text, Pesquisa)
                        SubPontuacao = math.max(SubPontuacao, ElementoPontuacao)
                        MelhorPontuacao = math.max(MelhorPontuacao, ElementoPontuacao)
                    else
                        ElementoInfo.SubButton.Base.Visible = false
                    end

                    ElementoInfo.Holder.Visible = Visivel
                    if Visivel then
                        VisivelElementos[SubAba] += 1
                    end

                    continue
                end

                if ElementoInfo.Text and CorrespondePesquisa(ElementoInfo, Pesquisa, SubAbaCorresponde) and ElementoInfo.Visible then
                    ElementoInfo.Holder.Visible = true
                    VisivelElementos[SubAba] += 1
                    local ElementoPontuacao = AproximadoCorrespondenciaPontuacao(ElementoInfo.Text, Pesquisa)
                    SubPontuacao = math.max(SubPontuacao, ElementoPontuacao)
                    MelhorPontuacao = math.max(MelhorPontuacao, ElementoPontuacao)
                else
                    ElementoInfo.Holder.Visible = false
                end
            end

            for _, CaixaDep in SubAba.DependencyBoxes do
                if not CaixaDep.Visible then
                    continue
                end

                local DepVisivel, DepPontuacao = VerificarCaixaDep(CaixaDep, Pesquisa, SubAbaCorresponde)
                VisivelElementos[SubAba] += DepVisivel
                SubPontuacao = math.max(SubPontuacao, DepPontuacao)
                MelhorPontuacao = math.max(MelhorPontuacao, DepPontuacao)
            end

            SubAbaPontuacoes[SubAba] = SubPontuacao
        end

        local MelhorSubAba = nil
        local MelhorSubPontuacao = -1

        for SubAba, Visivel in VisivelElementos do
            SubAba.ButtonHolder.Visible = Visivel > 0
            if Visivel > 0 then
                VisivelAbas += 1
                TemVisivel = true

                local SubPontuacao = SubAbaPontuacoes[SubAba] or 0
                if SubPontuacao > MelhorSubPontuacao then
                    MelhorSubPontuacao = SubPontuacao
                    MelhorSubAba = SubAba
                end
            end
        end

        local AtivoSubAba = CaixaAbas.ActiveTab
        local AtivoSubVisivel = AtivoSubAba and (VisivelElementos[AtivoSubAba] or 0) > 0
        local AtivoSubPontuacao = AtivoSubAba and (SubAbaPontuacoes[AtivoSubAba] or -1) or -1

        if AtivoSubVisivel and AtivoSubPontuacao >= MelhorSubPontuacao then
            AtivoSubAba:Resize()
        elseif MelhorSubAba then
            MelhorSubAba:Show()
        end

        CaixaAbas.BoxHolder.Visible = VisivelAbas > 0
        SyncPopOutVisibility(CaixaAbas)
    end

    return TemVisivel, MelhorPontuacao
end
local function ResetarAba(Aba)
    if not Aba then
        return
    end

    for _, CaixaGrupo in Aba.Groupboxes do
        for _, ElementoInfo in CaixaGrupo.Elements do
            ElementoInfo.Holder.Visible = ElementoInfo.Visible ~= false

            if ElementoInfo.SubButton then
                ElementoInfo.Base.Visible = ElementoInfo.Visible
                ElementoInfo.SubButton.Base.Visible = ElementoInfo.SubButton.Visible
            end
        end

        for _, CaixaDep in CaixaGrupo.DependencyBoxes do
            if not CaixaDep.Visible then
                continue
            end

            RestaurarCaixaDep(CaixaDep)
        end

        CaixaGrupo:Resize()
        CaixaGrupo.BoxHolder.Visible = CaixaGrupo.Visible ~= false
        SyncPopOutVisibility(CaixaGrupo)
    end

    for _, CaixaAbas in Aba.Tabboxes do
        for _, SubAba in CaixaAbas.Tabs do
            for _, ElementoInfo in SubAba.Elements do
                ElementoInfo.Holder.Visible = ElementoInfo.Visible ~= false

                if ElementoInfo.SubButton then
                    ElementoInfo.Base.Visible = ElementoInfo.Visible
                    ElementoInfo.SubButton.Base.Visible = ElementoInfo.SubButton.Visible
                end
            end

            for _, CaixaDep in SubAba.DependencyBoxes do
                if not CaixaDep.Visible then
                    continue
                end

                RestaurarCaixaDep(CaixaDep)
            end

            SubAba.ButtonHolder.Visible = true
        end

        if CaixaAbas.ActiveTab then
            CaixaAbas.ActiveTab:Resize()
        end
        CaixaAbas.BoxHolder.Visible = true
        SyncPopOutVisibility(CaixaAbas)
    end
end

function Library:UpdateSearch(PesquisaTexto)
    Library.SearchText = PesquisaTexto

    local AbasParaPesquisa = {}
    for _, Aba in Library.Tabs do
        if typeof(Aba) == "table" and not Aba.IsKeyTab then
            table.insert(AbasParaPesquisa, Aba)
        end
    end

    for _, Aba in AbasParaPesquisa do
        ResetarAba(Aba)
    end

    local Pesquisa = NormalizarPesquisa(PesquisaTexto:lower())
    if Aparar(Pesquisa) == "" then
        Library.Searching = false
        Library.LastSearchTab = nil
        return
    end
    if not Library.GlobalSearch and Library.ActiveTab and Library.ActiveTab.IsKeyTab then
        Library.Searching = false
        Library.LastSearchTab = nil
        return
    end

    Library.Searching = true

    local MelhorAba = nil
    local MelhorPontuacao = -1
    local AtivoPontuacao = -1
    local AtivoTemVisivel = false

    for _, Aba in AbasParaPesquisa do
        local TemVisivel, Pontuacao = AplicarPesquisaParaAba(Aba, Pesquisa)
        if not TemVisivel then
            continue
        end

        if Aba == Library.ActiveTab then
            AtivoTemVisivel = true
            AtivoPontuacao = Pontuacao
        end
        if Pontuacao > MelhorPontuacao then
            MelhorPontuacao = Pontuacao
            MelhorAba = Aba
        end
    end

    if not Library.GlobalSearch then
        for _, Aba in AbasParaPesquisa do
            if Aba ~= MelhorAba then
                ResetarAba(Aba)
            end
        end
    end

    local ManterAoAtivo = AtivoTemVisivel and AtivoPontuacao >= MelhorPontuacao
    if ManterAoAtivo and Library.ActiveTab then
        Library.ActiveTab:RefreshSides()
    elseif MelhorAba then
        local PesquisaMarcador = PesquisaTexto
        task.defer(function()
            if Library.SearchText ~= PesquisaMarcador then
                return
            end

            if Library.ActiveTab ~= MelhorAba then
                MelhorAba:Show()
            elseif Library.ActiveTab then
                Library.ActiveTab:RefreshSides()
            end
        end)
    end

    Library.LastSearchTab = nil
end

function Library:AddToRegistry(Instance, Propriedades)
    Library.Registry[Instance] = Propriedades
end

function Library:RemoveFromRegistry(Instance)
    Library.Registry[Instance] = nil
end

function Library:UpdateColorsUsingRegistry()
    for Instance, Propriedades in Library.Registry do
        for Propriedade, Indice_2 in Propriedades do
            local EsquemaValor = ObterEsquemaValor(Indice_2)

            if EsquemaValor or typeof(Indice_2) == "function" then
                Instance[Propriedade] = EsquemaValor or Indice_2()
            end
        end
    end
end

function Library:SetDPIScale(DPIEscala: number)
    Library.DPIScale = DPIEscala / 100
    Library.MinSize = Library.OriginalMinSize * Library.DPIScale

    for _, UIScale in Library.Scales do
        UIScale.Scale = Library.DPIScale - (tonumber(Library.ScalesOffset[UIScale]) or 0)
    end

    for _, Opcao in Opcoes do
        if Opcao.Type == "Dropdown" then
            Opcao:RecalculateListSize()
            Opcao:RefreshPool()
        end
    end

    for _, Notificacao in Library.Notifications do
        Notificacao:Resize()
    end
end

function Library:GiveSignal(Conexao: RBXScriptConnection | RBXScriptSignal)
    local ConexaoTipo = typeof(Conexao)
    if Conexao and (ConexaoTipo == "RBXScriptConnection" or ConexaoTipo == "RBXScriptSignal") then
        table.insert(Library.Signals, Conexao)
    end

    return Conexao
end

function IsValidCustomIcon(Icon: string)
    return typeof(Icon) == "string" and (Icon:match("^rbxasset://textures/") or Icon:match("roblox%.com/asset/%?id=") or Icon:match("rbxthumb://type="))
end

local function EhPersonalizadoRecursoIcone(Icon: string, IncludeAssetId: boolean)
    return typeof(Icon) == "string" and (Icon:match("^content://") or (Icon:match("^rbxasset://%x+/") or Icon:match("^rbxasset://[^/]+/")) or (IncludeAssetId == true and Icon:match("^rbxassetid://")))
end

type Icon = {
    Url: string,
    Id: number,
    IconName: string,
    ImageRectOffset: Vector2,
    ImageRectSize: Vector2,
}

type IconModule = {
    Icons: { string },
    GetAsset: (Name: string) -> Icon?,
}

local BuscarIcones = false
local Icons: IconModule | nil = nil

function Library:GetIcon(IconName: string)
    if not BuscarIcones or not Icons then
        return
    end

    local Sucesso, Icon = pcall(Icons.GetAsset, IconName)
    if not Sucesso then
        return
    end

    return Icon
end

function Library:GetCustomIcon(IconName: string): any
    if not IconName then
        return nil
    end

    if tonumber(IconName) then
        IconName = string.format("rbxassetid://%s", tostring(IconName))
    end

    if EhPersonalizadoRecursoIcone(IconName, true) then
        return {
            Url = IconName,
            ImageRectOffset = Vector2.zero,
            ImageRectSize = Vector2.zero,
        }
    elseif IsValidCustomIcon(IconName) then
        return {
            Url = IconName,
            ImageRectOffset = Vector2.zero,
            ImageRectSize = Vector2.zero,
            Custom = true,
        }
    end

    local LucideIcone = Library:GetIcon(IconName)
    if LucideIcone then
        return LucideIcone
    end

    return nil
end

function Library:ApplyLucideIcon(ImagemGui: any, Icon: any, Rotacao: number?)
    if not ImagemGui or not Icon then
        return
    end

    if not (ImagemGui:IsA("ImageLabel") or ImagemGui:IsA("ImageButton")) then
        return
    end

    ImagemGui.Image = Icon.Url or ImagemGui.Image
    ImagemGui.ImageRectOffset = Icon.ImageRectOffset or ImagemGui.ImageRectOffset 
    ImagemGui.ImageRectSize = Icon.ImageRectSize or ImagemGui.ImageRectSize
    ImagemGui.Rotation = Rotacao or ImagemGui.Rotation
end

function Library:Validate(Tabela: { [string]: any }, Modelo: { [string]: any }): { [string]: any }
    if typeof(Tabela) ~= "table" then
        return Modelo
    end

    for k, v in Modelo do
        if typeof(k) == "number" then
            continue
        end

        if typeof(v) == "table" then
            Tabela[k] = Library:Validate(Tabela[k], v)
        elseif Tabela[k] == nil then
            Tabela[k] = v
        end
    end

    return Tabela
end

local function PreenchimentoInstancia(Tabela: { [string]: any }, Instance: GuiObject)
    local TemaPropriedades = Library.Registry[Instance] or {}

    for tecla, valor in Tabela do
        if tecla ~= "Text" then
            local EsquemaValor = ObterEsquemaValor(valor)

            if EsquemaValor or typeof(valor) == "function" then
                TemaPropriedades[tecla] = valor
                valor = EsquemaValor or valor()
            else
                TemaPropriedades[tecla] = nil
            end
        end

        Instance[tecla] = valor
    end

    if ObterTabelaTamanho(TemaPropriedades) > 0 then
        Library.Registry[Instance] = TemaPropriedades
    end
end

local function Novo(ClasseNome: string, Propriedades: { [string]: any }): any
    local Instance = Instance.new(ClasseNome)

    if Modelos[ClasseNome] then
        PreenchimentoInstancia(Modelos[ClasseNome], Instance)
    end
    PreenchimentoInstancia(Propriedades, Instance)

    if Propriedades["Parent"] and not Propriedades["ZIndex"] then
        pcall(function()
            Instance.ZIndex = Propriedades.Parent.ZIndex
        end)
    end

    return Instance
end

local function SeguroPaiUI(Instance: Instance, Pai: Instance | () -> Instance)
    local sucesso, _erro = pcall(function()
        if not Pai then
            Pai = CoreGui
        end

        local DestinoPai
        if typeof(Pai) == "function" then
            DestinoPai = Pai()
        else
            DestinoPai = Pai
        end

        Instance.Parent = DestinoPai
    end)

    if not (sucesso and Instance.Parent) then
        Instance.Parent = Library.LocalPlayer:WaitForChild("PlayerGui", math.huge)
    end
end

local function PaiUI(UI: Instance, SkipHiddenUI: boolean?)
    if SkipHiddenUI then
        SeguroPaiUI(UI, CoreGui)
        return
    end

    pcall(protectgui, UI)
    SeguroPaiUI(UI, gethui)
end

local function DefinirSempreAoTopo(Gui: ScreenGui, Ativado: boolean)
    if not Gui then
        return
    end

    pcall(function()
        if sethiddenproperty then
            sethiddenproperty(Gui, "OnTopOfCoreBlur", Ativado)
        elseif setscriptable then
            setscriptable(Gui, "OnTopOfCoreBlur", true)
            Gui.OnTopOfCoreBlur = Ativado
            setscriptable(Gui, "OnTopOfCoreBlur", false)
        end
    end)
end

