function Library:GetBetterColor(Cor: Color3, Adicionar: number): Color3
    Adicionar = Adicionar * (Library.IsLightTheme and -4 or 2)
    return Color3.fromRGB(
        math.clamp(Cor.R * 255 + Adicionar, 0, 255),
        math.clamp(Cor.G * 255 + Adicionar, 0, 255),
        math.clamp(Cor.B * 255 + Adicionar, 0, 255)
    )
end

function Library:GetLighterColor(Cor: Color3): Color3
    local H, S, V = Cor:ToHSV()
    return Color3.fromHSV(H, math.max(0, S - 0.1), math.min(1, V + 0.1))
end

function Library:GetDarkerColor(Cor: Color3): Color3
    local H, S, V = Cor:ToHSV()
    return Color3.fromHSV(H, S, V / 2)
end

function Library:GetKeyString(TeclaCode: Enum.KeyCode)
    if TeclaCode.EnumType == Enum.KeyCode and TeclaCode.Value > 33 and TeclaCode.Value < 127 then
        return string.char(TeclaCode.Value)
    end

    return TeclaCode.Name
end

function Library:GetTextBounds(Texto_2: string, Font: Font, Tamanho: number, Largura: number?): (number, number)
    local Escala = Library.DPIScale
    local Parametros = Instance.new("GetTextBoundsParams")
    Parametros.Text = Texto_2
    Parametros.RichText = true
    Parametros.Font = Font
    Parametros.Size = Tamanho * Escala
    if Largura then
        Parametros.Width = Largura * Escala
    else
        Parametros.Width = workspace.CurrentCamera.ViewportSize.X - 32
    end

    local Limites = TextService:GetTextBoundsAsync(Parametros)
    return math.ceil(Limites.X / Escala), math.ceil(Limites.Y / Escala)
end

function Library:MouseIsOverFrame(Frame: GuiObject, Mouse: Vector2): boolean
    local AbsPos, AbsTamanho = Frame.AbsolutePosition, Frame.AbsoluteSize
    return Mouse.X >= AbsPos.X
        and Mouse.X <= AbsPos.X + AbsTamanho.X
        and Mouse.Y >= AbsPos.Y
        and Mouse.Y <= AbsPos.Y + AbsTamanho.Y
end

function Library:IsInsideFrame(PaiQuadro: GuiObject, Frame: GuiObject)
    local GuiPos = Frame.AbsolutePosition
    local GuiTamanho = Frame.AbsoluteSize

    local QuadroPos = PaiQuadro.AbsolutePosition
    local QuadroTamanho = PaiQuadro.AbsoluteSize

    return GuiPos.X >= QuadroPos.X
        and GuiPos.X + GuiTamanho.X <= QuadroPos.X + QuadroTamanho.X
        and GuiPos.Y >= QuadroPos.Y
        and GuiPos.Y + GuiTamanho.Y <= QuadroPos.Y + QuadroTamanho.Y
end

function Library:SafeCallback(Funcao: (...any) -> ...any, ...: any)
    if not (Funcao and typeof(Funcao) == "function") then
        return
    end

    local Resultado = table.pack(xpcall(Funcao, function(Erro)
        task.defer(error, debug.traceback(Erro, 2))
        if Library.NotifyOnError and Library.Notify then
            Library:Notify(Erro)
        end

        return Erro
    end, ...))

    if not Resultado[1] then
        return nil
    end

    return table.unpack(Resultado, 2, Resultado.n)
end

function GetOverlappingDraggable(UI: GuiObject, AlvoPos: Vector2?)
    local Pos1 = AlvoPos or UI.AbsolutePosition
    local Tamanho1 = UI.AbsoluteSize

    for _, Outro in ipairs(Library.DraggableElements) do
        if Outro == UI or not Outro.Visible or not Outro.Parent then
            continue
        end

        local Pos2 = Outro.AbsolutePosition
        local Tamanho2 = Outro.AbsoluteSize

        if Pos1.X < Pos2.X + Tamanho2.X and
            Pos1.X + Tamanho1.X > Pos2.X and
            Pos1.Y < Pos2.Y + Tamanho2.Y and
            Pos1.Y + Tamanho1.Y > Pos2.Y then
            return Outro
        end
    end

    return nil
end

function GetNonOverlappingPosition(UI: GuiObject, InicioPos: UDim2?)
    local TelaTamanho = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)) - Vector2.new(100, 100)
    local Inicio = InicioPos and Vector2.new(InicioPos.X.Offset, InicioPos.Y.Offset) or Vector2.new(6, 6)
    local PreenchimentoInterno = 6

    local AtualX = Inicio.X
    local AtualY = Inicio.Y

    local Tamanho = UI.AbsoluteSize
    if Tamanho.X == 0 and Tamanho.Y == 0 then
        RunService.RenderStepped:Wait()
        Tamanho = UI.AbsoluteSize
    end

    if Tamanho.X == 0 then Tamanho = Vector2.new(150, 40) end

    local MaxXEmColuna = Tamanho.X

    while true do
        local Obstaculo = GetOverlappingDraggable(UI, Vector2.new(AtualX, AtualY))
        if not Obstaculo then
            break
        end

        if Obstaculo.AbsoluteSize.X > MaxXEmColuna then
            MaxXEmColuna = Obstaculo.AbsoluteSize.X
        end

        local ProximoY = Obstaculo.AbsolutePosition.Y + Obstaculo.AbsoluteSize.Y + PreenchimentoInterno
        if ProximoY + Tamanho.Y > TelaTamanho.Y - PreenchimentoInterno then
            local ProximoX = AtualX + MaxXEmColuna + PreenchimentoInterno

            if ProximoX + Tamanho.X > TelaTamanho.X - PreenchimentoInterno then
                break
            end

            AtualY = Inicio.Y
            AtualX = ProximoX
            MaxXEmColuna = Tamanho.X
        else
            AtualY = ProximoY
        end
    end

    return UDim2.fromOffset(AtualX, AtualY)
end

function PositionDraggable(UI: GuiObject, InicioPos: UDim2?)
    UI.Position = GetNonOverlappingPosition(UI, InicioPos)
end

local function ObterNucleoGuiMargemInterna(): (Vector2, Vector2)
    local Sucesso, TopoEsquerda, InferiorDireita = pcall(function()
        return GuiService:GetGuiInset()
    end)

    if Sucesso and TopoEsquerda and InferiorDireita then
        return TopoEsquerda, InferiorDireita
    end

    return Vector2.zero, Vector2.zero
end

local function ObterEncaixeBordas(ElemTamanho: Vector2, AreaVisaoTamanho: Vector2, Margem: number, EvitarNucleoGui: boolean)
    local SeguroMin, SeguroMax = Vector2.zero, AreaVisaoTamanho

    if EvitarNucleoGui then
        local TopoEsquerdaMargemInterna, InferiorDireitaMargemInterna = ObterNucleoGuiMargemInterna()
        SeguroMin = TopoEsquerdaMargemInterna
        SeguroMax = AreaVisaoTamanho - InferiorDireitaMargemInterna
    end

    local AlvosX = {
        LeftEdge = SeguroMin.X + Margem,
        Center = SeguroMin.X + (SeguroMax.X - SeguroMin.X - ElemTamanho.X) / 2,
        RightEdge = SeguroMax.X - ElemTamanho.X - Margem,
    }
    local AlvosY = {
        TopEdge = SeguroMin.Y + Margem,
        Center = SeguroMin.Y + (SeguroMax.Y - SeguroMin.Y - ElemTamanho.Y) / 2,
        BottomEdge = SeguroMax.Y - ElemTamanho.Y - Margem,
    }

    return AlvosX, AlvosY
end

local function ObterMaisProximoEncaixeAlvo(Valor: number, Targets: { [string]: number }, Distancia: number): (number?, string?)
    local MaisProximoNome, MaisProximoValor, MaisProximoDist = nil, nil, Distancia

    for Name, Alvo in Targets do
        local Dist = math.abs(Valor - Alvo)
        if Dist <= MaisProximoDist then
            MaisProximoDist = Dist
            MaisProximoNome = Name
            MaisProximoValor = Alvo
        end
    end

    return MaisProximoValor, MaisProximoNome
end

local function ObterEncaixeGuiaDeslocamento(Name: string, SnappedValue: number, ElemDimension: number): number
    if Name == "RightEdge" or Name == "BottomEdge" then
        return SnappedValue + ElemDimension
    elseif Name == "Center" then
        return SnappedValue + ElemDimension / 2
    end

    return SnappedValue 
end

function Library:MakeDraggable(
    UI: GuiObject,
    ArrastarQuadro: GuiObject,
    IgnorarAlternado: boolean?,
    EhPrincipalJanela: boolean?,
    EncaixeConfig: { Ativado: boolean, Distancia: number?, Margem: number?, EvitarNucleoGui: boolean? }?
)
    local InicioPos
    local QuadroPos
    local Arrastando = false
    local Alterado
    local EntradaIniciou
    local EntradaAlterado

    local EncaixeGuiaX, EncaixeGuiaY

    local function ObterEncaixeGuias()
        if not EncaixeGuiaX then
            EncaixeGuiaX = Novo("Frame", {
                BackgroundColor3 = "AccentColor",
                BackgroundTransparency = 0.25,
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(0.5, 0),
                Size = UDim2.new(0, 2, 1, 0),
                Visible = false,
                ZIndex = 10000,
                Parent = ScreenGui,
            })
        end

        if not EncaixeGuiaY then
            EncaixeGuiaY = Novo("Frame", {
                BackgroundColor3 = "AccentColor",
                BackgroundTransparency = 0.25,
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(0, 0.5),
                Size = UDim2.new(1, 0, 0, 2),
                Visible = false,
                ZIndex = 10000,
                Parent = ScreenGui,
            })
        end

        return EncaixeGuiaX, EncaixeGuiaY
    end

    local function OcultarEncaixeGuias()
        if EncaixeGuiaX then
            EncaixeGuiaX.Visible = false
        end
        if EncaixeGuiaY then
            EncaixeGuiaY.Visible = false
        end
    end

    EntradaIniciou = ArrastarQuadro.InputBegan:Connect(function(Entrada_2: InputObject)
        if not EhCliqueEntrada(Entrada_2) or EhPrincipalJanela and Library.CantDragForced then
            return
        end

        InicioPos = Entrada_2.Position
        QuadroPos = UI.Position
        Arrastando = true

        Alterado = Entrada_2.Changed:Connect(function()
            if Entrada_2.UserInputState ~= Enum.UserInputState.End then
                return
            end

            Arrastando = false
            OcultarEncaixeGuias()

            if Alterado and Alterado.Connected then
                Alterado:Disconnect()
                Alterado = nil
            end
        end)
    end)

    EntradaAlterado = UserInputService.InputChanged:Connect(function(Entrada_2: InputObject)
        if
            (not IgnorarAlternado and not Library.Toggled)
            or (EhPrincipalJanela and Library.CantDragForced)
            or not (ScreenGui and ScreenGui.Parent)
        then
            Arrastando = false
            OcultarEncaixeGuias()

            if Alterado and Alterado.Connected then
                Alterado:Disconnect()
                Alterado = nil
            end

            return
        end

        if Arrastando and EhPairarEntrada(Entrada_2) then
            local Delta = Entrada_2.Position - InicioPos
            local NovoX = QuadroPos.X.Offset + Delta.X
            local NovoY = QuadroPos.Y.Offset + Delta.Y

            if EncaixeConfig and EncaixeConfig.Enabled then
                local AreaVisaoTamanho = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
                local Distancia = EncaixeConfig.Distance or 28
                local Margem = EncaixeConfig.Margin or 8

                local AbsX = QuadroPos.X.Scale * AreaVisaoTamanho.X + NovoX
                local AbsY = QuadroPos.Y.Scale * AreaVisaoTamanho.Y + NovoY

                local ElemTamanho = UI.AbsoluteSize
                local AlvosX, AlvosY = ObterEncaixeBordas(ElemTamanho, AreaVisaoTamanho, Margem, EncaixeConfig.AvoidCoreGui ~= false)
                local EncaixadoX, EncaixadoXNome = ObterMaisProximoEncaixeAlvo(AbsX, AlvosX, Distancia)
                local EncaixadoY, EncaixadoYNome = ObterMaisProximoEncaixeAlvo(AbsY, AlvosY, Distancia)

                if EncaixadoX then
                    NovoX = EncaixadoX - QuadroPos.X.Scale * AreaVisaoTamanho.X
                end
                if EncaixadoY then
                    NovoY = EncaixadoY - QuadroPos.Y.Scale * AreaVisaoTamanho.Y
                end

                local GuiaX, GuiaY = ObterEncaixeGuias()
                GuiaX.Visible = EncaixadoX ~= nil
                if EncaixadoX then
                    GuiaX.Position = UDim2.fromOffset(ObterEncaixeGuiaDeslocamento(EncaixadoXNome, EncaixadoX, ElemTamanho.X), 0)
                end

                GuiaY.Visible = EncaixadoY ~= nil
                if EncaixadoY then
                    GuiaY.Position = UDim2.fromOffset(0, ObterEncaixeGuiaDeslocamento(EncaixadoYNome, EncaixadoY, ElemTamanho.Y))
                end
            end

            UI.Position = UDim2.new(QuadroPos.X.Scale, NovoX, QuadroPos.Y.Scale, NovoY)
        end
    end)

    Library:GiveSignal(EntradaAlterado)
    Library:GiveSignal(EntradaIniciou)

    UI.Destroying:Once(function()
        if EntradaAlterado and EntradaAlterado.Connected then
            EntradaAlterado:Disconnect()
        end

        if EntradaIniciou and EntradaIniciou.Connected then
            EntradaIniciou:Disconnect()
        end

        if Alterado and Alterado.Connected then
            Alterado:Disconnect()
        end

        if EncaixeGuiaX then
            EncaixeGuiaX:Destroy()
        end
        if EncaixeGuiaY then
            EncaixeGuiaY:Destroy()
        end

        local IndiceAlterado = table.find(Library.Signals, EntradaAlterado)
        if IndiceAlterado then
            table.remove(Library.Signals, IndiceAlterado)
        end

        local IndiceIniciou = table.find(Library.Signals, EntradaIniciou)
        if IndiceIniciou then
            table.remove(Library.Signals, IndiceIniciou)
        end
    end)
end

function Library:MakeResizable(UI: GuiObject, ArrastarQuadro: GuiObject, Retorno: () -> ()?)
    local InicioPos
    local QuadroTamanho
    local Arrastando = false
    local Alterado
    local EntradaIniciou
    local EntradaAlterado

    EntradaIniciou = ArrastarQuadro.InputBegan:Connect(function(Entrada_2: InputObject)
        if not EhCliqueEntrada(Entrada_2) then
            return
        end

        InicioPos = Entrada_2.Position
        QuadroTamanho = UI.Size
        Arrastando = true

        Alterado = Entrada_2.Changed:Connect(function()
            if Entrada_2.UserInputState ~= Enum.UserInputState.End then
                return
            end

            Arrastando = false
            if Alterado and Alterado.Connected then
                Alterado:Disconnect()
                Alterado = nil
            end
        end)
    end)

    EntradaAlterado = UserInputService.InputChanged:Connect(function(Entrada_2: InputObject)
        if not UI.Visible or not (ScreenGui and ScreenGui.Parent) then
            Arrastando = false
            if Alterado and Alterado.Connected then
                Alterado:Disconnect()
                Alterado = nil
            end

            return
        end

        if Arrastando and EhPairarEntrada(Entrada_2) then
            local Delta = Entrada_2.Position - InicioPos
            UI.Size = UDim2.new(
                QuadroTamanho.X.Scale,
                math.clamp(QuadroTamanho.X.Offset + Delta.X, Library.MinSize.X, math.huge),
                QuadroTamanho.Y.Scale,
                math.clamp(QuadroTamanho.Y.Offset + Delta.Y, Library.MinSize.Y, math.huge)
            )
            if Retorno then
                Library:SafeCallback(Retorno)
            end
        end
    end)

    Library:GiveSignal(EntradaAlterado)
    Library:GiveSignal(EntradaIniciou)

    UI.Destroying:Once(function()
        if EntradaAlterado and EntradaAlterado.Connected then
            EntradaAlterado:Disconnect()
        end

        if EntradaIniciou and EntradaIniciou.Connected then
            EntradaIniciou:Disconnect()
        end

        if Alterado and Alterado.Connected then
            Alterado:Disconnect()
        end

        local IndiceAlterado = table.find(Library.Signals, EntradaAlterado)
        if IndiceAlterado then
            table.remove(Library.Signals, IndiceAlterado)
        end

        local IndiceIniciou = table.find(Library.Signals, EntradaIniciou)
        if IndiceIniciou then
            table.remove(Library.Signals, IndiceIniciou)
        end
    end)
end

function Library:MakeCover(Suporte: GuiObject, Lugar: string)
    local Pos = Lugares[Lugar] or { 0, 0 }
    local Tamanho = Tamanhos[Lugar] or { 1, 0.5 }

    local Cobertura = Novo("Frame", {
        AnchorPoint = Vector2.new(Pos[1], Pos[2]),
        BackgroundColor3 = Suporte.BackgroundColor3,
        Position = UDim2.fromScale(Pos[1], Pos[2]),
        Size = UDim2.fromScale(Tamanho[1], Tamanho[2]),
        Parent = Suporte,
    })

    return Cobertura
end

function Library:MakeLine(Frame: GuiObject, Info)
    local Linha = Novo("Frame", {
        AnchorPoint = Info.AnchorPoint or Vector2.zero,
        BackgroundColor3 = "OutlineColor",
        LayoutOrder = Info.LayoutOrder or 0,
        Position = Info.Position,
        Size = Info.Size,
        ZIndex = Info.ZIndex or Frame.ZIndex,
        Parent = Frame,
    })

    return Linha
end

function Library:AddOutline(Frame: GuiObject)
    local ContornoBorda = Novo("UIStroke", {
        Color = "OutlineColor",
        Thickness = 1,
        ZIndex = 2,
        Parent = Frame,
    })
    local SombraBorda = Novo("UIStroke", {
        Color = "DarkColor",
        Thickness = 1.5,
        ZIndex = 1,
        Parent = Frame,
    })
    return ContornoBorda, SombraBorda
end

function Library:AddBlank(Frame: GuiObject, Tamanho: UDim2)
    return Novo("Frame", {
        BackgroundTransparency = 1,
        Size = Tamanho or UDim2.fromScale(0, 0),
        Parent = Frame,
    })
end

local TransparenciaCache = {}
local AtivoAbaInterpolacoes = setmetatable({}, { __mode = "k" })

function Library:PlayTabAnimation(Aba, Mostrando: boolean, AoConcluir: (() -> ())?)
    if type(Aba) ~= "table" or not Aba.Container then
        if AoConcluir then
            AoConcluir()
        end

        return
    end

    local AbaConteiner = Aba.Container :: Frame
    local Existente = AtivoAbaInterpolacoes[AbaConteiner]
    if Existente then
        PararInterpolacao(Existente, true)
        AtivoAbaInterpolacoes[AbaConteiner] = nil
    end

    local BaseZIndice = AbaConteiner.ZIndex
    if not (Library.Animations and Library.Animations.TabSwitch) then
        AbaConteiner.Visible = Mostrando
        AbaConteiner.Position = UDim2.fromScale(0, 0)
        AbaConteiner.ZIndex = BaseZIndice

        if AoConcluir then
            AoConcluir()
        end

        return
    end

    if Mostrando then
        local TweenInfo = Library.TabTransitionInfo or TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local Deslocamento = Library.TabSwipeOffset or 26
        local DeslizeDe = string.lower(Library.TabSwipeFrom or "bottom")
        local InicioPosicao
        local IniciandoPosicoes = {
            Left = UDim2.fromOffset(-Deslocamento, 0),
            Right = UDim2.fromOffset(Deslocamento, 0),
            Top = UDim2.fromOffset(0, -Deslocamento),
            Bottom = UDim2.fromOffset(0, Deslocamento),
        }

        if DeslizeDe == "auto" and Library.PreviousTab then
            local AtualOrdem = Aba.Button.LayoutOrder
            local AnteriorOrdem = Library.PreviousTab.Button.LayoutOrder
            if AtualOrdem and AnteriorOrdem then 
                InicioPosicao = AtualOrdem > AnteriorOrdem and IniciandoPosicoes.Top or IniciandoPosicoes.Bottom 
            else
                InicioPosicao = IniciandoPosicoes.Bottom
            end
        elseif DeslizeDe == "left" then
            InicioPosicao = IniciandoPosicoes.Left
        elseif DeslizeDe == "top" then
            InicioPosicao = IniciandoPosicoes.Top
        elseif DeslizeDe == "right" then
            InicioPosicao = IniciandoPosicoes.Right
        else 
            InicioPosicao = IniciandoPosicoes.Bottom
        end

        AbaConteiner.ZIndex = BaseZIndice + 1
        AbaConteiner.Position = InicioPosicao
        AbaConteiner.Visible = true

        local Interpolacao = TweenService:Create(AbaConteiner, TweenInfo, {
            Position = UDim2.fromScale(0, 0)
        })

        AtivoAbaInterpolacoes[AbaConteiner] = Interpolacao
        Interpolacao:Play()

        local Conexao; Conexao = Interpolacao.Completed:Connect(function(PlaybackEstado)
            if Conexao then
                Conexao:Disconnect()
            end

            if AtivoAbaInterpolacoes[AbaConteiner] == Interpolacao then
                AtivoAbaInterpolacoes[AbaConteiner] = nil
            end

            if PlaybackEstado == Enum.PlaybackState.Cancelled then
                return
            end

            AbaConteiner.ZIndex = BaseZIndice
            if AoConcluir then
                AoConcluir()
            end
        end)
    else
        AbaConteiner.Visible = false
        AbaConteiner.Position = UDim2.fromScale(0, 0)
        AbaConteiner.ZIndex = BaseZIndice

        if AoConcluir then
            AoConcluir()
        end
    end
end

function Library:MakeBoxPopOut(Caixa: any, Opcoes: {
    Ativado: boolean?,
    Cabecalho: GuiObject?,
    Filhos: (() -> { GuiObject })?,
    Before: (() -> ())?,
    After: (() -> ())?,
    MaxPopOutHeight: number?,
    PopOutWidth: number?,
})
    Caixa.PoppedOut = false
    Caixa.PopOutEnabled = Opcoes.Enabled ~= false
    Caixa.PopOutFloat = nil
    Caixa.PopOutPlaceholder = nil
    Caixa.PopOutMaxHeight = if typeof(Opcoes.MaxPopOutHeight) == "number" then Opcoes.MaxPopOutHeight else nil
    Caixa.PopOutWidth = if typeof(Opcoes.PopOutWidth) == "number" then Opcoes.PopOutWidth else nil

    if not Caixa.PopOutEnabled then
        function Caixa:SetPoppedOut(_Valor: boolean, _DefinirDestacadoFora: UDim2) end
        function Caixa:TogglePoppedOut() end
        function Caixa:RefreshPopOutPlaceholder() end
        function Caixa:SetMaxPopOutHeight(_Altura: number?) end
        function Caixa:SetPopOutWidth(_Largura: number?) end
        return
    end

    local CaixaSuporte = Caixa.BoxHolder
    local Suporte = Caixa.Holder
    local Cabecalho = Opcoes.Header

    local Marcador
    local MarcadorCabecalho
    local Flutuante
    local FlutuanteEscala

    local HandledFilhos: { GuiObject } = {}
    local OriginalParents: { [GuiObject]: Instance? } = {}
    local OriginalLeiauteOrders: { [GuiObject]: number } = {}

    local ArrastarEstado: "Idle" | "Holding" | "Dragging" = "Idle"
    local ArrastarEntrada: InputObject?
    local PressMouse: Vector2?

    local DragStartPos: UDim2?
    local DragChanged: RBXScriptConnection?
    local DragDidMove = false

    local function ObterDestacarForaLargura(): number
        if typeof(Caixa.PopOutWidth) == "number" then
            return math.max(50, math.floor(Caixa.PopOutWidth + 0.5))
        end

        if typeof(Caixa.PopOutDockedWidth) == "number" then
            return math.max(50, math.floor(Caixa.PopOutDockedWidth + 0.5))
        end

        local Largura = Suporte.AbsoluteSize.X / Library.DPIScale
        if Largura < 50 then
            Largura = 200
        end

        return math.max(50, math.floor(Largura + 0.5))
    end

    local function AplicarDestacarForaLargura()
        if not (Caixa.PoppedOut and Flutuante) then
            return
        end

        Flutuante.Size = UDim2.fromOffset(ObterDestacarForaLargura(), Flutuante.Size.Y.Offset)
        if Caixa.Resize then
            Caixa:Resize()
        end
    end

    local function ElevarFlutuante()
        if not Flutuante or not Flutuantes then
            return
        end

        local MaxZ = Flutuante.ZIndex
        for _, Filho in Flutuantes:GetChildren() do
            if Filho:IsA("GuiObject") and Filho ~= Flutuante then
                MaxZ = math.max(MaxZ, Filho.ZIndex)
            end
        end

        Flutuante.ZIndex = MaxZ + 1
        if Flutuante.Parent == Flutuantes then
            Flutuante.Parent = Sobreposicao
        end
        Flutuante.Parent = Flutuantes
    end

    local function CriarMarcador()
        local Frame = Novo("Frame", {
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = "BackgroundColor",
            BackgroundTransparency = 0.12,
            ClipsDescendants = true,
            Size = UDim2.new(1, 0, 0, 0),
            Parent = CaixaSuporte,
        })
        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius),
                Parent = Frame,
            })
        )
        Library:AddOutline(Frame)

        MarcadorCabecalho = Cabecalho:Clone()
        MarcadorCabecalho.Parent = Frame
        EscurecerDestacarForaClonar(MarcadorCabecalho)

        if DestacarForaIcone then
            local MarcadorEncaixarIcone = Novo("ImageButton", {
                AutoButtonColor = false,
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundTransparency = 1,
                ImageColor3 = "WhiteColor",
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(22, 22),
                ZIndex = MarcadorCabecalho.ZIndex + 1,
                Parent = Frame,
            })
            Library:ApplyLucideIcon(MarcadorEncaixarIcone, DestacarForaIcone)
            MarcadorEncaixarIcone.MouseButton1Click:Connect(function()
                Caixa:SetPoppedOut(false)
            end)
        end

        return Frame
    end

    function Caixa:RefreshPopOutPlaceholder()
        if not Caixa.PoppedOut or not Marcador or not Cabecalho then
            return
        end

        if MarcadorCabecalho then
            MarcadorCabecalho:Destroy()
            MarcadorCabecalho = nil
        end

        MarcadorCabecalho = Cabecalho:Clone()
        MarcadorCabecalho.Parent = Marcador
        EscurecerDestacarForaClonar(MarcadorCabecalho)
    end

    function Caixa:SetPoppedOut(Valor: boolean, FlutuantePosicao: UDim2?)
        if not Caixa.PopOutEnabled or Caixa.Destroyed then
            return
        end

        Valor = Valor == true
        if Caixa.PoppedOut == Valor then
            if Valor and FlutuantePosicao and Flutuante then
                Flutuante.Position = FlutuantePosicao
            end
            return
        end

        if Valor then
            if Opcoes.Before then
                Opcoes.Before()
            end

            local CaixaFilhos = if Opcoes.Children then Opcoes.Children() else { Suporte }
            HandledFilhos = {}

            table.clear(OriginalParents)
            table.clear(OriginalLeiauteOrders)

            for _, Filho in CaixaFilhos do
                if not Filho or not Filho.Parent then
                    continue
                end

                table.insert(HandledFilhos, Filho)
                OriginalParents[Filho] = Filho.Parent
                OriginalLeiauteOrders[Filho] = Filho.LayoutOrder
            end

            if #HandledFilhos == 0 then
                return
            end

            local EncaixadoLargura = Suporte.AbsoluteSize.X / Library.DPIScale
            if EncaixadoLargura < 50 then
                EncaixadoLargura = 200
            end
            Caixa.PopOutDockedWidth = math.max(50, math.floor(EncaixadoLargura + 0.5))

            local Largura = ObterDestacarForaLargura()

            local AbsolutoPosicao = Suporte.AbsolutePosition
            Marcador = CriarMarcador()
            Caixa.PopOutPlaceholder = Marcador

            Flutuante = Novo("Frame", {
                Active = true,
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Position = FlutuantePosicao or UDim2.fromOffset(
                    AbsolutoPosicao.X / Library.DPIScale,
                    AbsolutoPosicao.Y / Library.DPIScale
                ),
                Size = UDim2.fromOffset(Largura, 0),
                ZIndex = 1,
                Parent = Flutuantes,
            })
            FlutuanteEscala = Novo("UIScale", {
                Parent = Flutuante,
            })
            table.insert(Library.Scales, FlutuanteEscala)
            FlutuanteEscala.Scale = Library.DPIScale - (tonumber(Library.ScalesOffset[FlutuanteEscala]) or 0)

            Novo("UIListLayout", {
                Padding = UDim.new(0, 6),
                Parent = Flutuante,
            })

            for _, Filho in HandledFilhos do
                Filho.Parent = Flutuante
            end

            if not table.find(Library.DraggableElements, Flutuante) then
                table.insert(Library.DraggableElements, Flutuante)
            end

            Caixa.PopOutFloat = Flutuante
            Caixa.PoppedOut = true
            SyncPopOutVisibility(Caixa)
            ElevarFlutuante()

            Flutuante:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
                Caixa:Resize()
            end)

            if Opcoes.After then
                Opcoes.After()
            end

            return
        end

        if Flutuante then
            local ArrastavelIndice = table.find(Library.DraggableElements, Flutuante)
            if ArrastavelIndice then
                table.remove(Library.DraggableElements, ArrastavelIndice)
            end
        end

        if FlutuanteEscala then
            local EscalaIndice = table.find(Library.Scales, FlutuanteEscala)
            if EscalaIndice then
                table.remove(Library.Scales, EscalaIndice)
            end

            FlutuanteEscala = nil
        end

        for _, Filho in HandledFilhos do
            if not Filho or not Filho.Parent then
                continue
            end

            Filho.Parent = OriginalParents[Filho] or CaixaSuporte
            Filho.LayoutOrder = OriginalLeiauteOrders[Filho] or 0
        end

        if Marcador then
            Marcador:Destroy()
            Marcador = nil
        end
        
        MarcadorCabecalho = nil

        if Flutuante then
            Flutuante:Destroy()
            Flutuante = nil
        end

        Caixa.PopOutFloat = nil
        Caixa.PopOutPlaceholder = nil
        Caixa.PopOutDockedWidth = nil
        Caixa.PoppedOut = false

        table.clear(HandledFilhos)
        table.clear(OriginalParents)
        table.clear(OriginalLeiauteOrders)

        if Opcoes.After then
            Opcoes.After()
        end
    end

    function Caixa:TogglePoppedOut()
        Caixa:SetPoppedOut(not Caixa.PoppedOut)
    end

    function Caixa:SetMaxPopOutHeight(Altura: number?)
        if Altura ~= nil then
            assert(typeof(Altura) == "number", "Height must be a number or nil")
            assert(Altura >= 0, "Height must be higher than 0")
        end

        Caixa.PopOutMaxHeight = Altura
        if Caixa.PoppedOut and Caixa.Resize then
            Caixa:Resize()
        end
    end

    function Caixa:SetPopOutWidth(Largura: number?)
        if Largura ~= nil then
            assert(typeof(Largura) == "number", "Width must be a number or nil")
            assert(Largura >= 0, "Width must be higher than 0")
        end

        Caixa.PopOutWidth = Largura
        AplicarDestacarForaLargura()
    end

    local function PararArrastar()
        if ArrastarEstado == "Idle" then
            return
        end

        local EstavaArrastando = ArrastarEstado == "Dragging"
        local FezMover = DragDidMove
        ArrastarEstado = "Idle"
        ArrastarEntrada = nil
        PressMouse = nil
        DragStartPos = nil
        DragDidMove = false

        if DragChanged and DragChanged.Connected then
            DragChanged:Disconnect()
            DragChanged = nil
        end

        if not EstavaArrastando or not Caixa.PoppedOut or not Flutuante then
            return
        end

        local FlutuanteCentro = Flutuante.AbsolutePosition + (Flutuante.AbsoluteSize * 0.5)
        local PertoMarcador = false
        if Library.Toggled and Marcador and Marcador.Parent then
            local MarcadorCentro = Marcador.AbsolutePosition + (Marcador.AbsoluteSize * 0.5)
            PertoMarcador = (FlutuanteCentro - MarcadorCentro).Magnitude <= Library.PopOutSnapDistance
        end

        if PertoMarcador or (FezMover and not EhTelaPontoForaPrincipal(FlutuanteCentro)) then
            Caixa:SetPoppedOut(false)
        end
    end

    local function IniciarArrastar(Entrada_2: InputObject)
        if ArrastarEstado ~= "Idle" or Caixa.Destroyed or not (ScreenGui and ScreenGui.Parent) then
            return
        end

        local Ponto = Vector2.new(Entrada_2.Position.X, Entrada_2.Position.Y)
        local Topo = ObterTopoFlutuanteEm(Ponto)
        if Caixa.PoppedOut then
            if not Flutuante or Topo ~= Flutuante then
                return
            end
        elseif Topo ~= nil and not Cabecalho:IsDescendantOf(Topo) then
            return
        end

        ArrastarEstado = "Holding"
        ArrastarEntrada = Entrada_2
        PressMouse = Vector2.new(Entrada_2.Position.X, Entrada_2.Position.Y)
        DragStartPos = nil
        DragDidMove = false

        if Caixa.PoppedOut and Flutuante then
            ElevarFlutuante()
        end

        DragChanged = Entrada_2.Changed:Connect(function()
            if Entrada_2.UserInputState == Enum.UserInputState.End then
                PararArrastar()
            end
        end)

        task.delay(Library.PopOutHoldTime, function()
            if (ArrastarEstado :: any) ~= "Holding" or ArrastarEntrada ~= Entrada_2 then
                return
            end

            ArrastarEstado = "Dragging"
            if Caixa.PoppedOut and Flutuante then
                ElevarFlutuante()
                DragStartPos = Flutuante.Position
            end
        end)
    end

    local function AtualizarArrastar(Entrada_2: InputObject)
        if ArrastarEstado ~= "Dragging" or not PressMouse then
            return
        end
        if not (ScreenGui and ScreenGui.Parent) then
            PararArrastar()
            return
        end

        local MousePosicao = Vector2.new(Entrada_2.Position.X, Entrada_2.Position.Y)
        local Delta = MousePosicao - PressMouse

        if not Caixa.PoppedOut then
            if Delta.Magnitude < Library.PopOutDragThreshold then
                return
            end

            Caixa:SetPoppedOut(true)
            if not Flutuante then
                return
            end

            ElevarFlutuante()
            DragStartPos = Flutuante.Position
            DragDidMove = true
        elseif Delta.Magnitude >= Library.PopOutDragThreshold then
            DragDidMove = true
        end

        if Flutuante and DragStartPos then
            Flutuante.Position = UDim2.new(
                DragStartPos.X.Scale,
                DragStartPos.X.Offset + Delta.X,
                DragStartPos.Y.Scale,
                DragStartPos.Y.Offset + Delta.Y
            )
        end
    end

    local function VincularArrastarOrigem(Gui: GuiObject)
        Library:GiveSignal(Gui.InputBegan:Connect(function(Entrada_2: InputObject)
            if EhCliqueEntrada(Entrada_2) then
                IniciarArrastar(Entrada_2)
            end
        end))
    end

    VincularArrastarOrigem(Cabecalho)
    for _, Descendente in Cabecalho:QueryDescendants("GuiObject:not(ImageButton)") do
        VincularArrastarOrigem(Descendente)
    end

    Library:GiveSignal(Cabecalho.DescendantAdded:Connect(function(Descendente)
        if Descendente:IsA("GuiObject") and not Descendente:IsA("ImageButton") then
            VincularArrastarOrigem(Descendente)
        end
    end))

    Library:GiveSignal(UserInputService.InputChanged:Connect(function(Entrada_2: InputObject)
        if EhPairarEntrada(Entrada_2) then
            AtualizarArrastar(Entrada_2)
        end
    end))
end

function Library:MakeOutline(Frame: GuiObject, Canto: number?, ZIndice: number?)
    warn("Resopaste:MakeOutline is deprecated, please use Resopaste:AddOutline instead.")
    local Suporte = Novo("Frame", {
        BackgroundColor3 = "DarkColor",
        Position = UDim2.fromOffset(-2, -2),
        Size = UDim2.new(1, 4, 1, 4),
        ZIndex = ZIndice,
        Parent = Frame,
    })

    local Contorno = Novo("Frame", {
        BackgroundColor3 = "OutlineColor",
        Position = UDim2.fromOffset(1, 1),
        Size = UDim2.new(1, -2, 1, -2),
        ZIndex = ZIndice,
        Parent = Suporte,
    })

    if Canto and Canto > 0 then
        Novo("UICorner", {
            CornerRadius = UDim.new(0, Canto + 1),
            Parent = Suporte,
        })
        Novo("UICorner", {
            CornerRadius = UDim.new(0, Canto),
            Parent = Contorno,
        })
    end

    return Suporte, Contorno
end

function Library:AddDraggableLabel(...)
    local Parametros = select(1, ...)
    local Texto_2
    local Icon
    local IconePosicao = "left"

    if typeof(Parametros) == "table" then
        Texto_2 = Parametros.Text
        Icon = Parametros.Icon
        IconePosicao = Parametros.IconPosition or "left"
    elseif typeof(Parametros) == "string" then
        Texto_2 = Parametros
        Icon = select(2, ...)
        IconePosicao = select(3, ...) or "left"
    end

    if typeof(IconePosicao) ~= "string" then
        IconePosicao = "left"
    end

    IconePosicao = string.lower(IconePosicao)
    assert(IconePosicao == "left" or IconePosicao == "right", "Icon Position needs to be either 'left' or 'right'.")

    local ArrastavelRotulo = {
        Connections = {},
        Destroyed = false
    }

    local IconeImagem
    local Rotulo = Novo("TextLabel", {
        AutomaticSize = Enum.AutomaticSize.XY,
        BackgroundColor3 = "BackgroundColor",
        Size = UDim2.fromOffset(0, 0),
        Position = UDim2.fromOffset(6, 6),
        Text = Texto_2,
        TextSize = 15,
        ZIndex = 1,
        Parent = Flutuantes,
    })

    table.insert(
        Library.Corners,
        Novo("UICorner", {
            CornerRadius = UDim.new(0, Library.CornerRadius),
            Parent = Rotulo,
        })
    )

    local PreenchimentoInterno = Novo("UIPadding", {
        PaddingBottom = UDim.new(0, 6),
        PaddingLeft = UDim.new(0, 12),
        PaddingRight = UDim.new(0, 12),
        PaddingTop = UDim.new(0, 6),
        Parent = Rotulo,
    })
    table.insert(
        Library.Scales,
        Novo("UIScale", {
            Parent = Rotulo,
        })
    )

    Library:AddOutline(Rotulo)
    Library:MakeDraggable(Rotulo, Rotulo, true)

    function ArrastavelRotulo:SetText(Texto_2: string)
        Rotulo.Text = Texto_2
    end

    function ArrastavelRotulo:SetIcon(NovoIcone: string)
        Icon = NovoIcone

        local EhNaoVazio = Icon and Aparar(tostring(Icon)) ~= ""
        if EhNaoVazio then
            local PersonalizadoIcone = Library:GetCustomIcon(Icon)
            assert(PersonalizadoIcone, "Icon must be a valid Roblox asset or a valid URL or a valid lucide icon.")

            IconeImagem = IconeImagem or Novo("ImageLabel", {
                BackgroundTransparency = 1,
                ImageColor3 = "FontColor",
                Size = UDim2.fromOffset(16, 16),
                ZIndex = 2,
                Parent = Rotulo,
            })

            Library:ApplyLucideIcon(IconeImagem, PersonalizadoIcone)
        end

        if IconeImagem then IconeImagem.Visible = EhNaoVazio end
        ArrastavelRotulo:SetIconPosition(IconePosicao)
    end

    function ArrastavelRotulo:SetIconPosition(NovoPosicao: string)
        IconePosicao = string.lower(NovoPosicao)
        assert(IconePosicao == "left" or IconePosicao == "right", "Icon Position needs to be either 'left' or 'right'.")

        local EhNaoVazio = Icon and Aparar(tostring(Icon)) ~= ""
        PreenchimentoInterno.PaddingLeft = UDim.new(0, (EhNaoVazio and IconePosicao == "left") and 34 or 12)
        PreenchimentoInterno.PaddingRight = UDim.new(0, (EhNaoVazio and IconePosicao == "right") and 34 or 12)

        if IconeImagem then
            if IconePosicao == "left" then
                IconeImagem.AnchorPoint = Vector2.new(0, 0.5)
                IconeImagem.Position = UDim2.new(0, -22, 0.5, 0)
            else
                IconeImagem.AnchorPoint = Vector2.new(1, 0.5)
                IconeImagem.Position = UDim2.new(1, 22, 0.5, 0)
            end
        end
    end

    function ArrastavelRotulo:SetVisible(Visivel: boolean)
        Rotulo.Visible = Visivel
    end

    ArrastavelRotulo:SetIcon(Icon)
    ArrastavelRotulo.Label = Rotulo

    if not table.find(Library.DraggableElements, Rotulo) then
        table.insert(Library.DraggableElements, Rotulo)
    end

    PositionDraggable(Rotulo, Rotulo.Position)

    function ArrastavelRotulo:Destroy()
        ArrastavelRotulo.Destroyed = true

        if ArrastavelRotulo.Connections then
            for _, conexao in ArrastavelRotulo.Connections do
                conexao:Disconnect()
            end
        end

        local ElemIndice = table.find(Library.DraggableElements, Rotulo)
        if ElemIndice then
            table.remove(Library.DraggableElements, ElemIndice)
        end

        if Rotulo then
            Rotulo:Destroy()
        end
    end

    return ArrastavelRotulo
end

function Library:AddDraggableButton(...)
    local Parametros = select(1, ...)

    local Texto_2
    local Funcao
    local ExcluirEscalonamento
    local ExcluirArrastando

    if typeof(Parametros) == "table" then
        Texto_2 = Parametros.Text
        Funcao = Parametros.Callback or Parametros.Func
        ExcluirEscalonamento = Parametros.ExcludeScaling
        ExcluirArrastando = Parametros.ExcludeDragging
    elseif typeof(Parametros) == "string" then
        Texto_2 = Parametros
        Funcao = select(2, ...)
        ExcluirEscalonamento = select(3, ...)
        ExcluirArrastando = select(4, ...)
    end

    local ArrastavelBotao = {
        Connections = {},
        Destroyed = false
    }

    local Botao = Novo("TextButton", {
        BackgroundColor3 = "BackgroundColor",
        Position = UDim2.fromOffset(6, 6),
        TextSize = 16,
        ZIndex = 1,
        Parent = Flutuantes,
    })
    table.insert(
        Library.Corners,
        Novo("UICorner", {
            CornerRadius = UDim.new(0, Library.CornerRadius),
            Parent = Botao,
        })
    )
    if not ExcluirEscalonamento then
        table.insert(
            Library.Scales,
            Novo("UIScale", {
                Parent = Botao,
            })
        )
    end
    Library:AddOutline(Botao)

    local MaxCliqueDistancia = ExcluirArrastando and 12 or math.huge
    Botao.InputBegan:Connect(function(Entrada_2: InputObject)
        if not EhCliqueEntrada(Entrada_2) then
            return
        end

        local InicioPos = Entrada_2.Position
        local Alterado
        Alterado = Entrada_2.Changed:Connect(function()
            if Entrada_2.UserInputState ~= Enum.UserInputState.End then
                return
            end

            if (Entrada_2.Position - InicioPos).Magnitude <= MaxCliqueDistancia then
                Library:SafeCallback(Funcao, ArrastavelBotao)
            end

            if Alterado and Alterado.Connected then
                Alterado:Disconnect()
                Alterado = nil
            end
        end)
    end)

    function ArrastavelBotao:SetText(Texto_2: string)
        local X, Y = Library:GetTextBounds(Texto_2, Library.Scheme.Font, 16)

        Botao.Text = Texto_2
        Botao.Size = UDim2.fromOffset(X * 2, Y * 2)
    end

    Library:MakeDraggable(Botao, Botao, true)
    ArrastavelBotao:SetText(Texto_2)
    ArrastavelBotao.Button = Botao

    if not table.find(Library.DraggableElements, Botao) then
        table.insert(Library.DraggableElements, Botao)
    end

    PositionDraggable(Botao, Botao.Position)

    function ArrastavelBotao:Destroy()
        ArrastavelBotao.Destroyed = true

        if ArrastavelBotao.Connections then
            for _, conexao in ArrastavelBotao.Connections do
                conexao:Disconnect()
            end
        end

        local ElemIndice = table.find(Library.DraggableElements, Botao)
        if ElemIndice then
            table.remove(Library.DraggableElements, ElemIndice)
        end

        if Botao then
            Botao:Destroy()
        end
    end

    return ArrastavelBotao
end

