        })
    )
    table.insert(
        Library.Scales,
        Novo("UIScale", {
            Parent = Suporte,
        })
    )
    Library:AddOutline(Suporte)

    Library:MakeLine(Suporte, {
        Position = UDim2.fromOffset(0, 34),
        Size = UDim2.new(1, 0, 0, 1),
    })

    local Rotulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
