local AtualMenu
function Library:AddContextMenu(
    Suporte: GuiObject,
    Tamanho: UDim2 | () -> (),
    Deslocamento: { [number]: number } | () -> {},
    List: number?,
    ActiveCallback: (Active: boolean) -> ()?,
    IgnoreCornerRadius: boolean?,
    SpecificCornersOnly: ("top" | "bottom" | "no_left" | "no_top_left")?, 
    AnimationType: ("Dropdown" | "KeyPicker" | "none")?
)
    local Menu
    local SuporteGui = Suporte:FindFirstAncestorOfClass("ScreenGui")
    local PaiGui = Sobreposicao
    if SuporteGui and SuporteGui ~= ScreenGui and Library.ActiveLoading and SuporteGui == Library.ActiveLoading.ScreenGui then
        PaiGui = SuporteGui
    end

    if List then
        Menu = Novo("ScrollingFrame", {
            AutomaticCanvasSize = Enum.AutomaticSize.None,
            AutomaticSize = List == 1 and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
            BackgroundColor3 = "BackgroundColor",
            BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
            CanvasSize = UDim2.fromOffset(0, 0),
            ScrollBarImageColor3 = "OutlineColor",
            ScrollBarThickness = List == 2 and 2 or 0,
            Size = typeof(Tamanho) == "function" and Tamanho() or Tamanho,
            TopImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
            Visible = false,
            ZIndex = 1,
            Parent = PaiGui,
        })
    else
        Menu = Novo("Frame", {
            BackgroundColor3 = "BackgroundColor",
            Size = typeof(Tamanho) == "function" and Tamanho() or Tamanho,
            Visible = false,
            ZIndex = 1,
            Parent = PaiGui,
        })
    end
    table.insert(
        Library.Scales,
        Novo("UIScale", {
            Parent = Menu,
        })
    )

    Novo("UIStroke", {
        Color = "OutlineColor",
        Parent = Menu,
    })

    local Canto;
    if IgnoreCornerRadius ~= true then
        if SpecificCornersOnly == "top" then
            Canto = Novo("UICorner", {
                TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomRightRadius = UDim.new(0, 0),
                BottomLeftRadius = UDim.new(0, 0),
                Parent = Menu,
            }); table.insert(Library.SpecificCorners, Canto)
        elseif SpecificCornersOnly == "bottom" then
            Canto = Novo("UICorner", {
                TopLeftRadius = UDim.new(0, 0),
                TopRightRadius = UDim.new(0, 0),
                BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Menu,
            }); table.insert(Library.SpecificCorners, Canto)
        elseif SpecificCornersOnly == "no_left" then
            Canto = Novo("UICorner", {
                TopLeftRadius = UDim.new(0, 0),
                TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomLeftRadius = UDim.new(0, 0),
                Parent = Menu,
            }); table.insert(Library.SpecificCorners, Canto)
        elseif SpecificCornersOnly == "no_top_left" then
            Canto = Novo("UICorner", {
                TopLeftRadius = UDim.new(0, 0),
                TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Menu,
            }); table.insert(Library.SpecificCorners, Canto)
        else
            Canto = Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Menu,
            }); table.insert(Library.Corners, Canto)
        end
    end

    local Tabela = {
        Connections = {},
        Destroyed = false,

        Active = false,
        ActiveCallback = ActiveCallback,

        Holder = Suporte,
        Menu = Menu,
        Corner = Canto,

        List = nil,
        Signal = nil,

        Size = Tamanho,
        AutoSizeY = List == 1,

        OpenCloseTween = nil,
        Animated = function()
            if not AnimationType or AnimationType == "none" then
                return false
            end

            if not (Library.Animations and Library.Animations[AnimationType] == true) then
                return false
            end

            return true, Library[string.format("%sTransitionInfo", AnimationType)] or TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        end
    }

    if List == 1 then
        Tabela.List = Novo("UIListLayout", {
            Parent = Menu,
        })
    end

    function Tabela:Open()
        if AtualMenu == Tabela then
            return
        elseif AtualMenu then
            AtualMenu:Close()
        end

        AtualMenu = Tabela
        Tabela.Active = true
        Menu.ZIndex = 1

        local AlvoPai = if PaiGui == Sobreposicao then Sobreposicao else PaiGui
        Menu.Parent = nil
        Menu.Parent = AlvoPai

        if typeof(Deslocamento) == "function" then
            Menu.Position = UDim2.fromOffset(
                math.floor(Suporte.AbsolutePosition.X + Deslocamento()[1]),
                math.floor(Suporte.AbsolutePosition.Y + Deslocamento()[2])
            )
        else
            Menu.Position = UDim2.fromOffset(
                math.floor(Suporte.AbsolutePosition.X + Deslocamento[1]),
                math.floor(Suporte.AbsolutePosition.Y + Deslocamento[2])
            )
        end

        local AlvoTamanho = typeof(Tabela.Size) == "function" and Tabela.Size() or Tabela.Size

        if typeof(ActiveCallback) == "function" then
            Library:SafeCallback(ActiveCallback, true)
        end

        if Tabela.OpenCloseTween then
            PararInterpolacao(Tabela.OpenCloseTween, true)
            Tabela.OpenCloseTween = nil
        end

        local EhAnimado, TweenInfo = Tabela.Animated()
        if EhAnimado == true then
            local AbrirTamanho = AlvoTamanho
            if Tabela.AutoSizeY then
                local CheioAltura = Menu.AbsoluteSize.Y

                Menu.AutomaticSize = Enum.AutomaticSize.None
                AbrirTamanho = UDim2.new(AlvoTamanho.X.Scale, AlvoTamanho.X.Offset, 0, CheioAltura)
            end

            Menu.Size = UDim2.new(AbrirTamanho.X.Scale, AbrirTamanho.X.Offset, 0, 0)
            Menu.Visible = true

            local Interpolacao = TweenService:Create(Menu, TweenInfo, { Size = AbrirTamanho })
            Tabela.OpenCloseTween = Interpolacao

            local Conexao; Conexao = Library:GiveSignal(Interpolacao.Completed:Once(function()
                if Conexao then
                    Conexao:Disconnect()
                end

                if Tabela.OpenCloseTween == Interpolacao then
                    PararInterpolacao(Tabela.OpenCloseTween, true)
                    Tabela.OpenCloseTween = nil

                    if Tabela.AutoSizeY then
                        Menu.AutomaticSize = Enum.AutomaticSize.Y
                    end
                end
            end))

            Interpolacao:Play()
        else
            Menu.Size = AlvoTamanho
            Menu.Visible = true
        end

        Tabela.Signal = Suporte:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
            if typeof(Deslocamento) == "function" then
                Menu.Position = UDim2.fromOffset(
                    math.floor(Suporte.AbsolutePosition.X + Deslocamento()[1]),
                    math.floor(Suporte.AbsolutePosition.Y + Deslocamento()[2])
                )
            else
                Menu.Position = UDim2.fromOffset(
                    math.floor(Suporte.AbsolutePosition.X + Deslocamento[1]),
                    math.floor(Suporte.AbsolutePosition.Y + Deslocamento[2])
                )
            end

            local SuportePermitido = Library:IsInsideFrame(Library.WindowContainer, Suporte)
            if not SuportePermitido then
                for _, Superficie in Library.DraggableElements do
                    if not (Superficie and Library:IsInsideFrame(Superficie, Suporte)) then
                        continue
                    end

                    SuportePermitido = true
                    break
                end
            end

            if not SuportePermitido and Tabela.Active then
                Tabela:Close()
            end
        end)
    end

    function Tabela:Close()
        if AtualMenu ~= Tabela then
            return
        end

        if Tabela.Signal then
            Tabela.Signal:Disconnect()
            Tabela.Signal = nil
        end

        Tabela.Active = false
        AtualMenu = nil

        if typeof(ActiveCallback) == "function" then
            Library:SafeCallback(ActiveCallback, false)
        end

        if Tabela.OpenCloseTween then
            PararInterpolacao(Tabela.OpenCloseTween, true)
            Tabela.OpenCloseTween = nil
        end

        local EhAnimado, TweenInfo = Tabela.Animated()
        if EhAnimado == true then
            if Tabela.AutoSizeY then
                Menu.AutomaticSize = Enum.AutomaticSize.None
            end

            local AtualTamanho = Menu.Size
            local RecolhidoTamanho = UDim2.new(AtualTamanho.X.Scale, AtualTamanho.X.Offset, 0, 0)

            local Interpolacao = TweenService:Create(Menu, TweenInfo, { Size = RecolhidoTamanho })
            Tabela.OpenCloseTween = Interpolacao

            local Conexao; Conexao = Library:GiveSignal(Interpolacao.Completed:Once(function(PlaybackEstado)
                if Conexao then
                    Conexao:Disconnect()
                end

                if Tabela.OpenCloseTween == Interpolacao then
                    PararInterpolacao(Tabela.OpenCloseTween, true)
                    Tabela.OpenCloseTween = nil

                    Menu.Visible = false
                    if Tabela.AutoSizeY then
                        Menu.AutomaticSize = Enum.AutomaticSize.Y
                    end
                end
            end))

            Interpolacao:Play()
        else
            Menu.Visible = false
        end
    end

    function Tabela:Toggle()
        if Tabela.Active then
            Tabela:Close()
        else
            Tabela:Open()
        end
    end

    function Tabela:SetSize(Tamanho)
        Tabela.Size = Tamanho
        Menu.Size = typeof(Tamanho) == "function" and Tamanho() or Tamanho
    end

    function Tabela:Destroy()
        Tabela.Destroyed = true

        if Tabela.Connections then
            for _, Conexao in Tabela.Connections do
                Conexao:Disconnect()
            end
        end

        if AtualMenu == Tabela then
            Tabela:Close()
        end

        if Tabela.OpenCloseTween then
            PararInterpolacao(Tabela.OpenCloseTween, true)
            Tabela.OpenCloseTween = nil
        end

        local MenuIndice = table.find(Library.ContextMenus, Tabela)
        if MenuIndice then
            table.remove(Library.ContextMenus, MenuIndice)
        end

        if Menu then
            Menu:Destroy()
        end
    end

    table.insert(Library.ContextMenus, Tabela)
    return Tabela
end

Library:GiveSignal(UserInputService.InputBegan:Connect(function(Entrada_2: InputObject)
    if Library.Unloaded then
        return
    end

    if EhCliqueEntrada(Entrada_2, true) then
        local Localizacao = Entrada_2.Position

        if
            AtualMenu
            and not (
                Library:MouseIsOverFrame(AtualMenu.Menu, Localizacao)
                or Library:MouseIsOverFrame(AtualMenu.Holder, Localizacao)
            )
        then
            AtualMenu:Close()
        end
    end
end))

