local DicaMedidaId = 0
local UltimoDicaTexto = ""
local UltimoDicaMaxLargura = 0

local function AtualizarDicaTamanho(Force: boolean?)
    if Library.Unloaded or not DicaRotulo.Visible then
        return
    end

    local MaxLargura = math.max(
        40,
        (workspace.CurrentCamera.ViewportSize.X - DicaRotulo.AbsolutePosition.X - 8) / Library.DPIScale
    )

    if
        not Force
        and DicaRotulo.Text == UltimoDicaTexto
        and math.abs(MaxLargura - UltimoDicaMaxLargura) < 1
        and DicaRotulo.Size.X.Offset > 0
    then
        return
    end

    DicaMedidaId += 1
    local MedidaId = DicaMedidaId
    local Texto_2 = DicaRotulo.Text

    local X, Y = Library:GetTextBounds(Texto_2, DicaRotulo.FontFace, DicaRotulo.TextSize, MaxLargura)
    if MedidaId ~= DicaMedidaId or DicaRotulo.Text ~= Texto_2 then
        return
    end

    UltimoDicaTexto = Texto_2
    UltimoDicaMaxLargura = MaxLargura
    DicaRotulo.Size = UDim2.fromOffset(X + 8, Y + 4)
end

DicaRotulo:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
    AtualizarDicaTamanho(false)
end)

local AtualPairarInstancia
function Library:AddTooltip(InfoTexto: string, DesativadoInfoTexto: string, PairarInstancia: GuiObject)
    local DicaTabela = {
        Disabled = false,
        Hovering = false,
        Signals = {},
    }

    local function ExecutarPairar()
        if
            AtualPairarInstancia == PairarInstancia
            or Library.ActiveDialog
            or (AtualMenu and Library:MouseIsOverFrame(AtualMenu.Menu, Mouse))
            or (DicaTabela.Disabled and typeof(DesativadoInfoTexto) ~= "string")
            or (not DicaTabela.Disabled and typeof(InfoTexto) ~= "string")
        then
            return
        end
        AtualPairarInstancia = PairarInstancia

        local SuporteGui = PairarInstancia:FindFirstAncestorOfClass("ScreenGui")
        if SuporteGui and SuporteGui ~= ScreenGui and Library.ActiveLoading and SuporteGui == Library.ActiveLoading.ScreenGui then
            DicaRotulo.Parent = SuporteGui
        else
            DicaRotulo.Parent = ScreenGui
        end

        DicaRotulo.Text = DicaTabela.Disabled and DesativadoInfoTexto or InfoTexto
        DicaRotulo.Position = UDim2.fromOffset(
            Mouse.X + (Library.ShowCustomCursor and 8 or 14),
            Mouse.Y + (Library.ShowCustomCursor and 8 or 12)
        )
        DicaRotulo.Visible = true
        AtualizarDicaTamanho(true)

        while
            (Library.Toggled or Library.ActiveLoading)
            and not Library.ActiveDialog
            and Library:MouseIsOverFrame(PairarInstancia, Mouse)
            and not (AtualMenu and Library:MouseIsOverFrame(AtualMenu.Menu, Mouse))
        do
            DicaRotulo.Position = UDim2.fromOffset(
                Mouse.X + (Library.ShowCustomCursor and 8 or 14),
                Mouse.Y + (Library.ShowCustomCursor and 8 or 12)
            )

            RunService.RenderStepped:Wait()
        end

        DicaRotulo.Visible = false
        AtualPairarInstancia = nil
    end

    local function RegistrarSinal(Conexao: RBXScriptConnection | RBXScriptSignal)
        local ConexaoTipo = typeof(Conexao)
        if Conexao and (ConexaoTipo == "RBXScriptConnection" or ConexaoTipo == "RBXScriptSignal") then
            table.insert(DicaTabela.Signals, Conexao)
        end

        return Conexao
    end

    RegistrarSinal(PairarInstancia.MouseEnter:Connect(ExecutarPairar))
    RegistrarSinal(PairarInstancia.MouseMoved:Connect(ExecutarPairar))
    RegistrarSinal(PairarInstancia.MouseLeave:Connect(function()
        if AtualPairarInstancia ~= PairarInstancia then
            return
        end

        DicaRotulo.Visible = false
        AtualPairarInstancia = nil
    end))

    function DicaTabela:Destroy()
        for Indice_2 = #DicaTabela.Signals, 1, -1 do
            local Conexao = table.remove(DicaTabela.Signals, Indice_2)
            if Conexao and Conexao.Connected then
                Conexao:Disconnect()
            end
        end

        if AtualPairarInstancia == PairarInstancia then
            if DicaRotulo then
                DicaRotulo.Visible = false
            end

            AtualPairarInstancia = nil
        end
    end

    table.insert(Dicas, DicaRotulo)
    return DicaTabela
end

function Library:OnUnload(Retorno)
    table.insert(Library.UnloadSignals, Retorno)
end

local BaseComplementos = {}
do
    local Funcoes = {}

    function Funcoes:AddKeyPicker(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.KeyPicker)

        local PaiObj = self
        local AlternadorRotulo = PaiObj.TextLabel

        if PaiObj.Type == "Button" or PaiObj.Type == "SubButton" then
            assert(Info.Mode == "Press", "KeyPicker on Buttons can only be applied with the 'Press' mode.")

            AlternadorRotulo = PaiObj.Base
        end

        local TeclaSeletorTecla = {
            Connections = {},

            Text = Info.Text,
            Value = Info.Default, 
            Modifiers = Info.DefaultModifiers, 
            DisplayValue = Info.Default, 

            Blacklisted = Info.Blacklisted,
            BlacklistedModifiers = Info.BlacklistedModifiers,
            Whitelisted = Info.Whitelisted,
            WhitelistedModifiers = Info.WhitelistedModifiers,

            Toggled = false,
            Mode = Info.Mode,
            SyncToggleState = Info.SyncToggleState,

            MenuVisible = Info.NoUI ~= true,

            Callback = Info.Callback,
            ChangedCallback = Info.ChangedCallback,
            Changed = Info.Changed,
            Clicked = Info.Clicked,

            Type = "KeyPicker",
        }

        if TeclaSeletorTecla.Mode == "Press" then
            assert(PaiObj.Type == "Label" or PaiObj.Type == "Button" or PaiObj.Type == "SubButton", "KeyPicker with the mode 'Press' can be only applied on Labels and Buttons.")

            TeclaSeletorTecla.SyncToggleState = false
            Info.Modes = { "Press" }
            Info.Mode = "Press"
        end

        if TeclaSeletorTecla.SyncToggleState then
            Info.Modes = { "Toggle", "Hold" }

            if not table.find(Info.Modes, Info.Mode) then
                Info.Mode = "Toggle"
            end
        end

        local Selecionando = false
        local EhParaBotao = PaiObj.Type == "Button" or PaiObj.Type == "SubButton"

        local EspecialTeclas = {
            ["MB1"] = Enum.UserInputType.MouseButton1,
            ["MB2"] = Enum.UserInputType.MouseButton2,
            ["MB3"] = Enum.UserInputType.MouseButton3,
        }

        local EspecialTeclasEntrada = {
            [Enum.UserInputType.MouseButton1] = "MB1",
            [Enum.UserInputType.MouseButton2] = "MB2",
            [Enum.UserInputType.MouseButton3] = "MB3",
        }

        local Modificadores = {
            ["LAlt"] = Enum.KeyCode.LeftAlt,
            ["RAlt"] = Enum.KeyCode.RightAlt,

            ["LCtrl"] = Enum.KeyCode.LeftControl,
            ["RCtrl"] = Enum.KeyCode.RightControl,

            ["LShift"] = Enum.KeyCode.LeftShift,
            ["RShift"] = Enum.KeyCode.RightShift,

            ["Tab"] = Enum.KeyCode.Tab,
            ["CapsLock"] = Enum.KeyCode.CapsLock,
        }

        local ModificadoresEntrada = {
            [Enum.KeyCode.LeftAlt] = "LAlt",
            [Enum.KeyCode.RightAlt] = "RAlt",

            [Enum.KeyCode.LeftControl] = "LCtrl",
            [Enum.KeyCode.RightControl] = "RCtrl",

            [Enum.KeyCode.LeftShift] = "LShift",
            [Enum.KeyCode.RightShift] = "RShift",

            [Enum.KeyCode.Tab] = "Tab",
            [Enum.KeyCode.CapsLock] = "CapsLock",
        }

        local EhModificadorEntrada = function(Entrada_2)
            return Entrada_2.UserInputType == Enum.UserInputType.Keyboard and ModificadoresEntrada[Entrada_2.KeyCode] ~= nil
        end

        local ObterAtivoModificadores = function()
            local AtivoModificadores = {}

            for Name, Entrada_2 in Modificadores do
                if table.find(AtivoModificadores, Name) then
                    continue
                end
                if not UserInputService:IsKeyDown(Entrada_2) then
                    continue
                end

                table.insert(AtivoModificadores, Name)
            end

            return AtivoModificadores
        end

        local EstaoModificadoresSegurado = function(Necessario)
            if not (typeof(Necessario) == "table" and ObterTabelaTamanho(Necessario) > 0) then
                return true
            end

            local AtivoModificadores = ObterAtivoModificadores()
            local Segurando = true

            for _, Name in Necessario do
                if table.find(AtivoModificadores, Name) then
                    continue
                end

                Segurando = false
                break
            end

            return Segurando
        end

        local EhEntradaBaixo = function(Entrada_2)
            if not Entrada_2 then
                return false
            end

            if EspecialTeclasEntrada[Entrada_2.UserInputType] ~= nil then
                return UserInputService:IsMouseButtonPressed(Entrada_2.UserInputType)
                    and not UserInputService:GetFocusedTextBox()
            elseif Entrada_2.UserInputType == Enum.UserInputType.Keyboard then
                return UserInputService:IsKeyDown(Entrada_2.KeyCode) and not UserInputService:GetFocusedTextBox()
            else
                return false
            end
        end

        local ConverterParaEntradaModificadores = function(AtualModificadores)
            local EntradaModificadores = {}

            for _, nome in AtualModificadores do
                table.insert(EntradaModificadores, Modificadores[nome])
            end

            return EntradaModificadores
        end

        local VerificarModificadores = function(AtualModificadores)
            if typeof(AtualModificadores) ~= "table" then
                return {}
            end

            local ValidoModificadores = {}

            for _, nome in AtualModificadores do
                if not Modificadores[nome] then
                    continue
                end

                table.insert(ValidoModificadores, nome)
            end

            return ValidoModificadores
        end

        TeclaSeletorTecla.Modifiers = VerificarModificadores(TeclaSeletorTecla.Modifiers)

        local DeslizarExcesso = true
        local UltimoExibicaoTexto = nil
        local MaxSeletorTeclaLargura = 85
        local DeslizandoRotulo

        local DeslizarAvancarInterpolacao
        local DeslizarVoltarInterpolacao
        local ManipularAvancarInterpolacao = function(Estado)
            if Estado ~= Enum.PlaybackState.Completed then
                return
            end

            task.wait(1.5)
            if DeslizarVoltarInterpolacao then
                DeslizarVoltarInterpolacao:Play()
            end
        end

        local ManipularVoltarInterpolacao = function(Estado)
            if Estado ~= Enum.PlaybackState.Completed then
                return
            end

            task.wait(1.5)
            if DeslizarAvancarInterpolacao then
                DeslizarAvancarInterpolacao:Play()
            end
        end

        local DeslizarAvancarConexao, DeslizarVoltarConexao
        local CancelarDeslizandoInterpolacoes = function()
            if DeslizarAvancarConexao then
                DeslizarAvancarConexao:Disconnect()
                DeslizarAvancarConexao = nil
            end

            if DeslizarVoltarConexao then
                DeslizarVoltarConexao:Disconnect()
                DeslizarVoltarConexao = nil
            end

            if DeslizarAvancarInterpolacao then
                PararInterpolacao(DeslizarAvancarInterpolacao, true)
                DeslizarAvancarInterpolacao = nil
            end

            if DeslizarVoltarInterpolacao then
                PararInterpolacao(DeslizarVoltarInterpolacao, true)
                DeslizarVoltarInterpolacao = nil
            end

            RunService.RenderStepped:Wait()
        end

        local SeletorTecla = Novo("TextButton", {
            BackgroundColor3 = "MainColor",
            Size = UDim2.fromOffset(18, 18),
            Text = (EhParaBotao and DeslizarExcesso) and "" or TeclaSeletorTecla.Value,
            TextSize = 14,
            TextTransparency = 0.4,
            Parent = AlternadorRotulo,
        })

        if EhParaBotao and DeslizarExcesso then
            SeletorTecla.ClipsDescendants = true

            DeslizandoRotulo = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 1, 0),
                Position = UDim2.new(0, 0, 0, 0),
                Text = TeclaSeletorTecla.Value,
                TextSize = 14,
                FontFace = SeletorTecla.FontFace,
                TextXAlignment = Enum.TextXAlignment.Center,
                Parent = SeletorTecla,
            })

            Library:AddToRegistry(DeslizandoRotulo, {
                TextColor3 = "FontColor",
            })
        end

        Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = SeletorTecla,
        })

        local SeletorTeclaCanto = Novo("UICorner", {
            TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            Parent = SeletorTecla,
        }); table.insert(Library.SpecificCorners, SeletorTeclaCanto)

        local SeletorTeclaPairarInterpolacao = nil

        local function AplicarSeletorTeclaTextoTransparencia(Transparencia: number)
            PararInterpolacao(SeletorTeclaPairarInterpolacao)
            SeletorTeclaPairarInterpolacao = nil

            SeletorTecla.TextTransparency = Transparencia
            if DeslizandoRotulo then
                DeslizandoRotulo.TextTransparency = Transparencia
            end
        end

        local function InterpolacaoSeletorTeclaTextoTransparencia(Transparencia: number)
            PararInterpolacao(SeletorTeclaPairarInterpolacao)

            SeletorTeclaPairarInterpolacao = TweenService:Create(SeletorTecla, Library.TweenInfo, {
                TextTransparency = Transparencia,
            })
            SeletorTeclaPairarInterpolacao:Play()

            if DeslizandoRotulo then
                TweenService:Create(DeslizandoRotulo, Library.TweenInfo, {
                    TextTransparency = Transparencia,
                }):Play()
            end
        end

        table.insert(TeclaSeletorTecla.Connections, SeletorTecla.MouseEnter:Connect(function()
            if PaiObj.Disabled then
                return
            end

            InterpolacaoSeletorTeclaTextoTransparencia(0)
        end))

        table.insert(TeclaSeletorTecla.Connections, SeletorTecla.MouseLeave:Connect(function()
            if PaiObj.Disabled then
                return
            end

            InterpolacaoSeletorTeclaTextoTransparencia(0.4)
        end))

        if EhParaBotao then
            local Suporte = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 21),
