            AlternadorRotulo.Parent = Suporte
            SeletorTecla.Parent = Suporte

            SeletorTecla.Size = UDim2.new(0, 18, 1, 0)
        end

        local AtalhosAlternador = { Normal = TeclaSeletorTecla.Mode ~= "Toggle" }
        do
