            AtalhosAlternador.Checkbox = CaixaSelecao
            AtalhosAlternador.Loaded = true
            table.insert(Library.KeybindToggles, AtalhosAlternador)
        end

        local ModoBotoes = {}
        local ModoCantos = {}
        local TotalModoBotoes = ObterTabelaTamanho(Info.Modes)
        local MenuCantosApenas = if TotalModoBotoes == 1 then "no_left" else "no_top_left"

        local MenuTabela
        MenuTabela = Library:AddContextMenu(SeletorTecla, UDim2.fromOffset(62, 0), function()
            return { SeletorTecla.AbsoluteSize.X + 1.5, 0.5 }
        end, 1, function(Active: boolean)
            local Metade = UDim.new(0, Library.CornerRadius / 2)
            local Zero = UDim.new(0, 0)

            SeletorTeclaCanto.TopLeftRadius = Metade
            SeletorTeclaCanto.BottomLeftRadius = Metade
            SeletorTeclaCanto.TopRightRadius = Active and Zero or Metade
            SeletorTeclaCanto.BottomRightRadius = Active and Zero or Metade

            local MenuCanto = MenuTabela and MenuTabela.Corner
            if MenuCanto then
                if MenuCantosApenas == "no_left" then
                    MenuCanto.TopLeftRadius = Zero
                    MenuCanto.BottomLeftRadius = Zero
                    MenuCanto.TopRightRadius = Metade
                    MenuCanto.BottomRightRadius = Metade
                else
