                    Canto.TopRightRadius = Metade
                    Canto.BottomLeftRadius = Zero
                    Canto.BottomRightRadius = Zero
                elseif Entrada.Style == "last" then
                    Canto.TopLeftRadius = Zero
                    Canto.TopRightRadius = Zero
                    Canto.BottomLeftRadius = Metade
                    Canto.BottomRightRadius = Metade
                end
            end
        end, false, MenuCantosApenas, "KeyPicker")
        TeclaSeletorTecla.Menu = MenuTabela

        for Indice_2, Modo in Info.Modes do
            local ModoBotao = {}

            local Botao = Novo("TextButton", {
                BackgroundColor3 = "MainColor",
