                    TopLeftRadius = UDim.new(0, 0),
                    TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomLeftRadius = UDim.new(0, 0),
                    BottomRightRadius = UDim.new(0, 0),
                    Parent = Botao,
                })
                table.insert(Library.SpecificCorners, Canto)
                table.insert(ModoCantos, { Corner = Canto, Style = "first" })
            elseif Indice_2 == TotalModoBotoes then
                local Canto = Novo("UICorner", {
                    TopLeftRadius = UDim.new(0, 0),
                    TopRightRadius = UDim.new(0, 0),
                    BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Botao,
                })
                table.insert(Library.SpecificCorners, Canto)
                table.insert(ModoCantos, { Corner = Canto, Style = "last" })
            end

            function ModoBotao:Select()
                for _, Botao in ModoBotoes do
                    Botao:Deselect()
                end

                TeclaSeletorTecla.Mode = Modo

                Botao.BackgroundTransparency = 0
                Botao.TextTransparency = 0

                MenuTabela:Close()
                if TeclaSeletorTecla.Update then
                    TeclaSeletorTecla:Update()
                end
            end

            function ModoBotao:Deselect()
                TeclaSeletorTecla.Mode = nil

                Botao.BackgroundTransparency = 1
                Botao.TextTransparency = 0.5
            end

            table.insert(TeclaSeletorTecla.Connections, Botao.MouseButton1Click:Connect(function()
                ModoBotao:Select()
            end))

            table.insert(TeclaSeletorTecla.Connections, Botao.MouseEnter:Connect(function()
                if TeclaSeletorTecla.Mode == Modo then
                    return
                end

                TweenService:Create(Botao, Library.TweenInfo, {
                    BackgroundTransparency = 0.7,
                    TextTransparency = 0.1,
                }):Play()
            end))

            table.insert(TeclaSeletorTecla.Connections, Botao.MouseLeave:Connect(function()
                if TeclaSeletorTecla.Mode == Modo then
                    return
                end

                TweenService:Create(Botao, Library.TweenInfo, {
                    BackgroundTransparency = 1,
                    TextTransparency = 0.5,
                }):Play()
            end))

            if TeclaSeletorTecla.Mode == Modo then
                ModoBotao:Select()
            end

            ModoBotoes[Modo] = ModoBotao
        end

        local DefinirSelecionandoEstado = function(Estado, PularAtualizar: boolean?)
            Selecionando = Estado
            Library.IsPicking = Estado

            if PaiObj then
                PaiObj.AnyKeyPickerPicking = Selecionando
            end

            if EhParaBotao then
                AlternadorRotulo.Visible = not Selecionando
                UltimoExibicaoTexto = nil
                RunService.RenderStepped:Wait()
            end

            if PularAtualizar ~= true then
                (TeclaSeletorTecla :: any):Update()
            end
        end

        function TeclaSeletorTecla:Display(SeletorTeclaTexto)
            if Library.Unloaded then
                return
            end

            local ExibicaoTexto = SeletorTeclaTexto or TeclaSeletorTecla.DisplayValue
            if EhParaBotao and DeslizarExcesso then
                local X, _Y = Library:GetTextBounds(
                    ExibicaoTexto,
                    SeletorTecla.FontFace,
                    SeletorTecla.TextSize,
                    10000
                )

                local DeslocamentoEscala = X + 9
                local TextoAlterado = UltimoExibicaoTexto ~= ExibicaoTexto
                local RotuloLargura

                DeslizandoRotulo.Text = ExibicaoTexto
                UltimoExibicaoTexto = ExibicaoTexto

                if Selecionando then
                    SeletorTecla.Size = UDim2.new(1, 0, 1, 0)
                    RunService.RenderStepped:Wait()
                    RotuloLargura = SeletorTecla.AbsoluteSize.X

                    if RotuloLargura <= 0 then
                        RotuloLargura = MaxSeletorTeclaLargura
                    end
                else
                    RotuloLargura = math.min(DeslocamentoEscala, MaxSeletorTeclaLargura)
                    SeletorTecla.Size = UDim2.new(0, RotuloLargura, 1, 0)
                end

                if DeslocamentoEscala > RotuloLargura then
                    DeslizandoRotulo.TextXAlignment = Enum.TextXAlignment.Left
                    DeslizandoRotulo.Size = UDim2.new(0, DeslocamentoEscala, 1, 0)

                    local ExcessoDistancia = DeslocamentoEscala - RotuloLargura - 4.5
                    if ExcessoDistancia > 0 then
                        if TextoAlterado or not DeslizarAvancarInterpolacao then
                            DeslizandoRotulo.Position = UDim2.fromOffset(4.5, 0)
                            CancelarDeslizandoInterpolacoes()

                            local Duracao = math.max(ExcessoDistancia / 25, 0.35)
                            local TweenInfo = TweenInfo.new(
                                Duracao,
                                Enum.EasingStyle.Linear,
                                Enum.EasingDirection.InOut
                            )

                            DeslizarAvancarInterpolacao = TweenService:Create(DeslizandoRotulo, TweenInfo, {
                                Position = UDim2.fromOffset(-ExcessoDistancia, 0),
                            })

                            DeslizarVoltarInterpolacao = TweenService:Create(DeslizandoRotulo, TweenInfo, {
                                Position = UDim2.fromOffset(4.5, 0),
                            })

                            DeslizarAvancarInterpolacao:Play()

                            if DeslizarAvancarConexao then
                                DeslizarAvancarConexao:Disconnect()
                            end

                            if DeslizarVoltarConexao then
                                DeslizarVoltarConexao:Disconnect()
                            end

                            DeslizarAvancarConexao = DeslizarAvancarInterpolacao.Completed:Connect(ManipularAvancarInterpolacao)
                            DeslizarVoltarConexao = DeslizarVoltarInterpolacao.Completed:Connect(ManipularVoltarInterpolacao)
                        end
                    else
                        CancelarDeslizandoInterpolacoes()

                        DeslizandoRotulo.TextXAlignment = Enum.TextXAlignment.Center
                        DeslizandoRotulo.Size = UDim2.new(1, 0, 1, 0)
                        DeslizandoRotulo.Position = UDim2.new(0, 0, 0, 0)
                    end
                else
                    CancelarDeslizandoInterpolacoes()

                    DeslizandoRotulo.TextXAlignment = Enum.TextXAlignment.Center
                    DeslizandoRotulo.Size = UDim2.new(1, 0, 1, 0)
                    DeslizandoRotulo.Position = UDim2.new(0, 0, 0, 0)
                end
            else
                local X, Y = Library:GetTextBounds(
                    ExibicaoTexto,
                    SeletorTecla.FontFace,
                    SeletorTecla.TextSize,
                    AlternadorRotulo.AbsoluteSize.X / Library.DPIScale
                )
                SeletorTecla.Text = ExibicaoTexto
                SeletorTecla.Size = EhParaBotao and UDim2.new(0, X + 9, 1, 0) or UDim2.fromOffset((X + 9), (Y + 4))
            end
        end

        function TeclaSeletorTecla:Update()
            local Desativado = PaiObj.Disabled == true

            if Desativado and Selecionando then
                DefinirSelecionandoEstado(false, true)
            end

            TeclaSeletorTecla:Display()

            SeletorTecla.Active = not Desativado
            AplicarSeletorTeclaTextoTransparencia(Desativado and 0.8 or 0.4)

            if Desativado then
                if MenuTabela.Active then
                    MenuTabela:Close()
                end
            end

            if TeclaSeletorTecla.Mode == "Toggle" and PaiObj.Type == "Toggle" and PaiObj.Disabled then
                AtalhosAlternador:SetVisibility(false)
                return
            end

            local Estado = TeclaSeletorTecla:GetState()
            local MostrarAlternador = Library.ShowToggleFrameInKeybinds and TeclaSeletorTecla.Mode == "Toggle"

            if TeclaSeletorTecla.SyncToggleState and PaiObj.Value ~= Estado then
                PaiObj:SetValue(Estado)
            end

            if Info.NoUI then
                return
            end

            if AtalhosAlternador.Loaded then
                if MostrarAlternador then
                    AtalhosAlternador:SetNormal(false)
                else
                    AtalhosAlternador:SetNormal(true)
                end

                AtalhosAlternador:SetText(("[%s] %s (%s)"):format(TeclaSeletorTecla.DisplayValue, TeclaSeletorTecla.Text, PTBR_MODOS_ATALHO[TeclaSeletorTecla.Mode] or TeclaSeletorTecla.Mode))
                AtalhosAlternador:SetVisibility(TeclaSeletorTecla.MenuVisible ~= false)
                AtalhosAlternador:Display(Estado)
            end
        end

        function TeclaSeletorTecla:GetState()
            if TeclaSeletorTecla.Mode == "Always" then
                return true
            elseif TeclaSeletorTecla.Mode == "Hold" then
                local Tecla = TeclaSeletorTecla.Value
                if Tecla == "None" then
                    return false
                end

                if not EstaoModificadoresSegurado(TeclaSeletorTecla.Modifiers) then
                    return false
                end

                if Selecionando then
                    return false
                end

                if EspecialTeclas[Tecla] ~= nil then
                    if Library.Toggled then
                        return false
                    end

                    return UserInputService:IsMouseButtonPressed(EspecialTeclas[Tecla])
                        and not UserInputService:GetFocusedTextBox()
                else
                    return UserInputService:IsKeyDown(Enum.KeyCode[Tecla] :: any) and not UserInputService:GetFocusedTextBox()
                end
            else
                return TeclaSeletorTecla.Toggled
            end
        end

        function TeclaSeletorTecla:OnChanged(Funcao)
            TeclaSeletorTecla.Changed = Funcao
        end

        function TeclaSeletorTecla:OnClick(Funcao)
            TeclaSeletorTecla.Clicked = Funcao
        end

        function TeclaSeletorTecla:DoClick()
            if Selecionando or PaiObj.Disabled then
                return
            end

            if TeclaSeletorTecla.Mode == "Press" then
                if TeclaSeletorTecla.Toggled and Info.WaitForCallback == true then
                    return
                end

                TeclaSeletorTecla.Toggled = true
            end

            Library:SafeCallback(TeclaSeletorTecla.Callback, TeclaSeletorTecla.Toggled)
            Library:SafeCallback(TeclaSeletorTecla.Clicked, TeclaSeletorTecla.Toggled)

            if EhParaBotao then
                Library:SafeCallback(PaiObj.Func, TeclaSeletorTecla.Toggled)
            end

            if Library.ToggleKeybind == TeclaSeletorTecla and Library.Toggle then
                Library:Toggle()
            end

            if TeclaSeletorTecla.Mode == "Press" then
                TeclaSeletorTecla.Toggled = false
            end
        end

        function TeclaSeletorTecla:RunChanged(EhTeclaValido, TeclaCode)
            if PaiObj.Disabled then
                return
            end

            if EhTeclaValido == nil or TeclaCode == nil then
                EhTeclaValido, TeclaCode = pcall(function()
                    if TeclaSeletorTecla.Value == "None" then
                        return nil
                    end

                    if EspecialTeclas[TeclaSeletorTecla.Value] == nil then
                        return Enum.KeyCode[TeclaSeletorTecla.Value]
                    end

                    return EspecialTeclas[TeclaSeletorTecla.Value]
                end)
            end

            local NovoModificadores = ConverterParaEntradaModificadores(TeclaSeletorTecla.Modifiers)
            Library:SafeCallback(TeclaSeletorTecla.ChangedCallback, TeclaCode, NovoModificadores)
            Library:SafeCallback(TeclaSeletorTecla.Changed, TeclaCode, NovoModificadores)
        end

        function TeclaSeletorTecla:SetValue(Dados)
            local Tecla, Modo, Modificadores = Dados[1], Dados[2], Dados[3]

            local EhTeclaValido, TeclaCode = pcall(function()
                if Tecla == "None" then
                    Tecla = nil
                    return nil
                end

                if EspecialTeclas[Tecla] == nil then
                    return Enum.KeyCode[Tecla]
                end

                return EspecialTeclas[Tecla]
            end)

            if Tecla == nil then
                TeclaSeletorTecla.Value = "None"
            elseif EhTeclaValido then
                TeclaSeletorTecla.Value = Tecla
            else
                TeclaSeletorTecla.Value = "Unknown"
            end

            TeclaSeletorTecla.Modifiers =
                VerificarModificadores(if typeof(Modificadores) == "table" then Modificadores else TeclaSeletorTecla.Modifiers)
            TeclaSeletorTecla.DisplayValue = if ObterTabelaTamanho(TeclaSeletorTecla.Modifiers) > 0
                then (table.concat(TeclaSeletorTecla.Modifiers, " + ") .. " + " .. TeclaSeletorTecla.Value)
                else TeclaSeletorTecla.Value

            if ModoBotoes[Modo] then
                ModoBotoes[Modo]:Select()
            end

            TeclaSeletorTecla:Update()
            TeclaSeletorTecla:RunChanged(EhTeclaValido, TeclaCode)
        end

        function TeclaSeletorTecla:SetText(Texto_2)
            AtalhosAlternador:SetText(Texto_2)
            TeclaSeletorTecla:Update()
        end

        function TeclaSeletorTecla:SetMenuVisibility(Visivel: boolean)
            assert(typeof(Visivel) == "boolean", "Visible must be a boolean")

            TeclaSeletorTecla.MenuVisible = Visivel
            TeclaSeletorTecla:Update()
        end

        table.insert(TeclaSeletorTecla.Connections, SeletorTecla.MouseButton1Click:Connect(function()
            if Selecionando or Library.IsPicking or PaiObj.Disabled then
                return
            end

            DefinirSelecionandoEstado(true)

            if EhParaBotao and DeslizarExcesso then
                TeclaSeletorTecla:Display("...")
            else
                SeletorTecla.Text = "..."
                SeletorTecla.Size = EhParaBotao and UDim2.new(0, 29, 1, 0) or UDim2.fromOffset(29, 18)
            end

            local AtivoModificadores = {}
            local AtualEntrada = nil

            local EhValidoEntrada = function(EntradaObj)
                if EntradaObj.KeyCode == Enum.KeyCode.Escape then
                    return true
                end

                local EhMod = EhModificadorEntrada(EntradaObj)
                local TeclaNome
                if EspecialTeclasEntrada[EntradaObj.UserInputType] ~= nil then
                    TeclaNome = EspecialTeclasEntrada[EntradaObj.UserInputType]
                elseif EntradaObj.UserInputType == Enum.UserInputType.Keyboard then
                    if EhMod then
                        TeclaNome = ModificadoresEntrada[EntradaObj.KeyCode]
                    else
                        TeclaNome = EntradaObj.KeyCode.Name
                    end
                end

                if TeclaNome then
                    if EhMod then
                        if TeclaSeletorTecla.WhitelistedModifiers and #TeclaSeletorTecla.WhitelistedModifiers > 0 and not table.find(TeclaSeletorTecla.WhitelistedModifiers, TeclaNome) then
                            return false
                        end

                        if TeclaSeletorTecla.BlacklistedModifiers and table.find(TeclaSeletorTecla.BlacklistedModifiers, TeclaNome) then
                            return false
                        end
                    else
                        if TeclaSeletorTecla.Whitelisted and #TeclaSeletorTecla.Whitelisted > 0 and not table.find(TeclaSeletorTecla.Whitelisted, TeclaNome) then
                            return false
                        end

                        if TeclaSeletorTecla.Blacklisted and table.find(TeclaSeletorTecla.Blacklisted, TeclaNome) then
                            return false
                        end
                    end
                end

                return true
            end

            while true do
                local EntradaObj = UserInputService.InputBegan:Wait()
                if UserInputService:GetFocusedTextBox() ~= nil then
                    DefinirSelecionandoEstado(false)
                    return
                end

                if EhValidoEntrada(EntradaObj) then
                    AtualEntrada = EntradaObj
                    break
                end
            end

            while EhModificadorEntrada(AtualEntrada) do
                if AtualEntrada.KeyCode == Enum.KeyCode.Escape then
                    break
                end

                local ModNome = ModificadoresEntrada[AtualEntrada.KeyCode]
                if ModNome then
                    local texto = if #AtivoModificadores > 0 then table.concat(AtivoModificadores, " + ") .. " + " .. ModNome .. " + ..." else ModNome .. " + ..."
                    TeclaSeletorTecla:Display(texto)
                end

                local ProximoEntrada = nil
                local Solto = false

                local IniciouConexao
                local FinalizadoConexao

                IniciouConexao = UserInputService.InputBegan:Connect(function(EntradaObj)
                    if UserInputService:GetFocusedTextBox() ~= nil then
                        return
                    end
                    if EhValidoEntrada(EntradaObj) then
                        ProximoEntrada = EntradaObj
                    end
                end)

                FinalizadoConexao = UserInputService.InputEnded:Connect(function(EntradaObj)
                    if EntradaObj.KeyCode == AtualEntrada.KeyCode then
                        Solto = true
                    end
                end)

                repeat
                    task.wait()
                until Solto or ProximoEntrada or UserInputService:GetFocusedTextBox() ~= nil or Library.Unloaded

                if IniciouConexao then IniciouConexao:Disconnect() end
                if FinalizadoConexao then FinalizadoConexao:Disconnect() end

                if UserInputService:GetFocusedTextBox() ~= nil or Library.Unloaded then
                    DefinirSelecionandoEstado(false)
                    return
                end

                if Solto then
                    break 
                elseif ProximoEntrada then
                    
                    local AntigoModNome = ModificadoresEntrada[AtualEntrada.KeyCode]
                    if AntigoModNome and not table.find(AtivoModificadores, AntigoModNome) then
                        AtivoModificadores[#AtivoModificadores + 1] = AntigoModNome
                    end

                    AtualEntrada = ProximoEntrada
                    if AtualEntrada.KeyCode == Enum.KeyCode.Escape then
                        break
                    end
                end
            end

            local Tecla = "Unknown"
            if EspecialTeclasEntrada[AtualEntrada.UserInputType] ~= nil then
                Tecla = EspecialTeclasEntrada[AtualEntrada.UserInputType]
            elseif AtualEntrada.UserInputType == Enum.UserInputType.Keyboard then
                Tecla = AtualEntrada.KeyCode == Enum.KeyCode.Escape and "None" or AtualEntrada.KeyCode.Name
            end

            AtivoModificadores = if AtualEntrada.KeyCode == Enum.KeyCode.Escape or Tecla == "Unknown" then {} else AtivoModificadores

            TeclaSeletorTecla.Toggled = if PaiObj.Type == "Toggle" then PaiObj.Value else false

            if Tecla ~= "None" and Tecla ~= "Unknown" then
                local ConflitoSeletorTecla = nil

                for _, Opcao in Library.Options do
                    if Opcao ~= TeclaSeletorTecla and Opcao.Type == "KeyPicker" and Opcao.Value == Tecla then
                        local MesmoModificadores = ObterTabelaTamanho(Opcao.Modifiers) == ObterTabelaTamanho(AtivoModificadores)

                        if MesmoModificadores then
                            for _, Mod in AtivoModificadores do
                                if not table.find(Opcao.Modifiers, Mod) then
                                    MesmoModificadores = false
                                    break
                                end
                            end
                        end

                        if MesmoModificadores then
                            ConflitoSeletorTecla = Opcao
                            break
                        end
                    end
                end

                if ConflitoSeletorTecla then
                    local ConflitoTexto = ConflitoSeletorTecla.Text or "outro atalho"

                    task.spawn(function()
                        local ConflitoDialogo = Library.Window and Library.Window:AddDialog("KeybindConflict", {
                            Title = "Conflito de Atalho",
                            Description = Tecla .. " já está vinculada a " .. ConflitoTexto .. ".",
                            AutoDismiss = false,
                            OutsideClickDismiss = false,
                            FooterButtons = {
                                KeepBoth = {
                                    Title = "Manter Ambos",
                                    Callback = function(Dialogo)
                                        TeclaSeletorTecla:SetValue({ Tecla, TeclaSeletorTecla.Mode, AtivoModificadores })
                                        Dialogo:Dismiss()
                                    end,
                                },
                                Replace = {
                                    Title = "Substituir",
                                    Callback = function(Dialogo)
                                        ConflitoSeletorTecla:SetValue({ "None", ConflitoSeletorTecla.Mode, {} })
                                        TeclaSeletorTecla:SetValue({ Tecla, TeclaSeletorTecla.Mode, AtivoModificadores })
                                        Dialogo:Dismiss()
                                    end,
                                },
                                Cancel = {
                                    Title = "Cancelar",
                                    Variant = "Destructive",
                                },
                            },
                        })
                    end)

                    DefinirSelecionandoEstado(false)
                    return
                end
            end

            TeclaSeletorTecla:SetValue({ Tecla, TeclaSeletorTecla.Mode, AtivoModificadores })

            repeat
                task.wait()
            until not EhEntradaBaixo(AtualEntrada) or UserInputService:GetFocusedTextBox()

            DefinirSelecionandoEstado(false)
        end))

        table.insert(TeclaSeletorTecla.Connections, SeletorTecla.MouseButton2Click:Connect(function()
            if PaiObj.Disabled then
                return
            end

            MenuTabela:Toggle()
        end))

        table.insert(TeclaSeletorTecla.Connections, UserInputService.InputBegan:Connect(function(Entrada_2: InputObject)
            if Library.Unloaded then
                return
            end

            local EhMouse = EhMouseCliqueEntrada(Entrada_2)
            if
                PaiObj.Disabled
                or TeclaSeletorTecla.Mode == "Always"
                or TeclaSeletorTecla.Value == "Unknown"
                or TeclaSeletorTecla.Value == "None"
                or Selecionando
                or Library.IsPicking
                or UserInputService:GetFocusedTextBox()
                or (EhMouse and Library.Toggled)
            then
                return
            end

            local Tecla = TeclaSeletorTecla.Value
            local SegurandoModificadores = EstaoModificadoresSegurado(TeclaSeletorTecla.Modifiers)
            local SegurandoTecla = false

            if
                Tecla
                and SegurandoModificadores == true
                and (
                    EspecialTeclasEntrada[Entrada_2.UserInputType] == Tecla
                    or (Entrada_2.UserInputType == Enum.UserInputType.Keyboard and Entrada_2.KeyCode.Name == Tecla)
                )
            then
                SegurandoTecla = true
            end

            if SegurandoTecla then
                if TeclaSeletorTecla.Mode == "Toggle" then
                    TeclaSeletorTecla.Toggled = not TeclaSeletorTecla.Toggled
                    TeclaSeletorTecla:DoClick()
                elseif TeclaSeletorTecla.Mode == "Press" then
                    TeclaSeletorTecla:DoClick()
                elseif TeclaSeletorTecla.Mode == "Hold" then
                    EntradaAlterado = Entrada_2.Changed:Connect(function()
                        if TeclaSeletorTecla:GetState() then
                            return
                        end

                        TeclaSeletorTecla:Update()
                        if EntradaAlterado and EntradaAlterado.Connected then
                            EntradaAlterado:Disconnect()
                            EntradaAlterado = nil
                        end
                    end)
                end

                TeclaSeletorTecla:Update()
            end
        end))

        TeclaSeletorTecla:Update()

        if not PaiObj.Addons then
            PaiObj.Addons = {}
        end

        table.insert(PaiObj.Addons, TeclaSeletorTecla)

        TeclaSeletorTecla.Default = TeclaSeletorTecla.Value
        TeclaSeletorTecla.DefaultModifiers = table.clone(TeclaSeletorTecla.Modifiers or {})

        function TeclaSeletorTecla:Destroy()
            TeclaSeletorTecla.Destroyed = true

            if DeslizarAvancarConexao then
                DeslizarAvancarConexao:Disconnect()
                DeslizarAvancarConexao = nil
            end

            if DeslizarVoltarConexao then
                DeslizarVoltarConexao:Disconnect()
                DeslizarVoltarConexao = nil
            end

            if TeclaSeletorTecla.Connections then
                for _, Conexao in TeclaSeletorTecla.Connections do
                    Conexao:Disconnect()
                end
            end

            if AtalhosAlternador and AtalhosAlternador.Loaded then
                if AtalhosAlternador.Holder then
                    AtalhosAlternador.Holder:Destroy()
                end
                local AtalhoIndice = table.find(Library.KeybindToggles, AtalhosAlternador)
                if AtalhoIndice then
                    table.remove(Library.KeybindToggles, AtalhoIndice)
                end
            end

            if MenuTabela then
                MenuTabela:Destroy()
            end

            if EhParaBotao and DeslizarExcesso then
                if DeslizarAvancarInterpolacao then
                    DeslizarAvancarInterpolacao:Destroy()
                end

                if DeslizarVoltarInterpolacao then
                    DeslizarVoltarInterpolacao:Destroy()
                end
            end

            if SeletorTecla then
                SeletorTecla:Destroy()
            end

            if PaiObj and PaiObj.Addons then
                local ComplementoIndice = table.find(PaiObj.Addons, TeclaSeletorTecla)

                if ComplementoIndice then
                    table.remove(PaiObj.Addons, ComplementoIndice)
                end
            end

            Opcoes[Indice] = nil
        end

        Opcoes[Indice] = TeclaSeletorTecla

        return self
    end

    local HueSequenciaTabela = {}
    for Hue = 0, 1, 0.1 do
        table.insert(HueSequenciaTabela, ColorSequenceKeypoint.new(Hue, Color3.fromHSV(Hue, 1, 1)))
    end
    function Funcoes:AddColorPicker(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.ColorPicker)

        local PaiObj = self
        local AlternadorRotulo = PaiObj.TextLabel

        local CorSeletorTecla = {
            Connections = {},
            Destroyed = false,

            Value = Info.Default,

            Transparency = Info.Transparency or 0,
            Title = Info.Title,

            Callback = Info.Callback,
            Changed = Info.Changed,

            Type = "ColorPicker",
        }
        CorSeletorTecla.Hue, CorSeletorTecla.Sat, CorSeletorTecla.Vib = CorSeletorTecla.Value:ToHSV()

        local Suporte = Novo("TextButton", {
            BackgroundColor3 = CorSeletorTecla.Value,
            Size = UDim2.fromOffset(18, 18),
            Text = "",
            Parent = AlternadorRotulo,
        })

        local SuporteBorda = Novo("UIStroke", {
