            Parent = Suporte,
        })

        local CorSeletorTeclaCanto = Novo("UICorner", {
            TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            Parent = Suporte,
        }); table.insert(Library.SpecificCorners, CorSeletorTeclaCanto)

        local SuporteTransparencia = Novo("ImageLabel", {
            Image = GerenciadorImagens.GetAsset("TransparencyTexture"),
            ImageTransparency = (1 - CorSeletorTecla.Transparency),
            ScaleType = Enum.ScaleType.Tile,
            Position = UDim2.new(0, -1, 0, -1),
            Size = UDim2.new(1, 2, 1, 2),
            TileSize = UDim2.fromOffset(9, 9),
            Parent = Suporte,
        })

        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = SuporteTransparencia,
            })
        )

        local MapaTamanho = Library.IsMobile and 140 or 200
        local BarraLargura = 16
        local MenuLargura = MapaTamanho + BarraLargura + 6 + 12
        if Info.Transparency then
            MenuLargura += BarraLargura + 6
        end

        local CorMenu
        local RodapeCanto
        CorMenu = Library:AddContextMenu(
            Suporte,
            UDim2.fromOffset(MenuLargura, 0),
            function()
                return { 0.5, Suporte.AbsoluteSize.Y + 1.5 }
            end,
            1, function(Active: boolean)
                local Metade = UDim.new(0, Library.CornerRadius / 2)
                local Zero = UDim.new(0, 0)

                CorSeletorTeclaCanto.TopLeftRadius = Metade
                CorSeletorTeclaCanto.TopRightRadius = Metade
                CorSeletorTeclaCanto.BottomRightRadius = Active and Zero or Metade
                CorSeletorTeclaCanto.BottomLeftRadius = Active and Zero or Metade

                local MenuCanto = CorMenu and CorMenu.Corner
                if MenuCanto then
                    MenuCanto.TopLeftRadius = Zero
                    MenuCanto.TopRightRadius = Metade
                    MenuCanto.BottomRightRadius = Metade
                    MenuCanto.BottomLeftRadius = Metade
                end

                if RodapeCanto then
                    RodapeCanto.TopLeftRadius = Zero
                    RodapeCanto.TopRightRadius = Zero
                    RodapeCanto.BottomLeftRadius = Metade
                    RodapeCanto.BottomRightRadius = Metade
                end
            end, false, "no_top_left")
        CorMenu.List.Padding = UDim.new(0, 0)
        CorSeletorTecla.ColorMenu = CorMenu

        local ConteudoSuporte = Novo("Frame", {
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 0),
            Parent = CorMenu.Menu,
        })
        Novo("UIListLayout", {
            Padding = UDim.new(0, 8),
            Parent = ConteudoSuporte,
        })
        Novo("UIPadding", {
            PaddingBottom = UDim.new(0, 6),
            PaddingLeft = UDim.new(0, 6),
            PaddingRight = UDim.new(0, 6),
            PaddingTop = UDim.new(0, 6),
            Parent = ConteudoSuporte,
        })

        local RodapeAltura = Library.IsMobile and 30 or 22

        local RodapeFundo = Novo("Frame", {
            BackgroundColor3 = function()
                return Library:GetBetterColor(Library.Scheme.BackgroundColor, 4)
            end,
            Size = UDim2.new(1, 0, 0, RodapeAltura),
            Parent = CorMenu.Menu,
        })
        RodapeCanto = Novo("UICorner", {
            TopLeftRadius = UDim.new(0, 0),
            TopRightRadius = UDim.new(0, 0),
            BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
            Parent = RodapeFundo,
        })
        table.insert(Library.SpecificCorners, RodapeCanto)
        Library:MakeLine(RodapeFundo, {
            Position = UDim2.fromScale(0, 0),
            Size = UDim2.new(1, 0, 0, 1),
        })

        local RodapeBarra = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Parent = RodapeFundo,
        })
        Novo("UIPadding", {
            PaddingLeft = UDim.new(0, 6),
            PaddingRight = UDim.new(0, Info.Resizable and (RodapeAltura + 4) or 6),
            Parent = RodapeBarra,
        })

        local RodapeInfoRotulo = Novo("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Text = "",
            TextSize = 14,
            TextTransparency = 0.5,
            TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Center,
            Parent = RodapeBarra,
        })

        local function AtualizarRodapeInfo()
            RodapeInfoRotulo.Text = string.format(
                "#%s • %d, %d, %d",
                CorSeletorTecla.Value:ToHex(),
                math.floor(CorSeletorTecla.Value.R * 255),
                math.floor(CorSeletorTecla.Value.G * 255),
                math.floor(CorSeletorTecla.Value.B * 255)
            )
        end
        AtualizarRodapeInfo()

        if typeof(CorSeletorTecla.Title) == "string" then
            Novo("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 8),
                Text = CorSeletorTecla.Title,
                TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = ConteudoSuporte,
            })
        end

        local CorSuporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, MapaTamanho),
            Parent = ConteudoSuporte,
        })
        Novo("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 6),
            Parent = CorSuporte,
        })

        local SatBrilhoCorMapa = Novo("ImageButton", {
            BackgroundColor3 = CorSeletorTecla.Value,
