        })
        Novo("UICorner", {
            CornerRadius = UDim.new(1, 0),
            Parent = SatBrilhoCorCursor,
        })
        Novo("UIStroke", {
            Color = "DarkColor",
            Parent = SatBrilhoCorCursor,
        })

        local HueSeletor = Novo("TextButton", {
            Size = UDim2.fromOffset(BarraLargura, MapaTamanho),
            Text = "",
            Parent = CorSuporte,
        })
        Novo("UIGradient", {
            Color = ColorSequence.new(HueSequenciaTabela),
            Rotation = 90,
            Parent = HueSeletor,
        })

        local HueCursor = Novo("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = "WhiteColor",
            BorderColor3 = "DarkColor",
            BorderSizePixel = 1,
            Position = UDim2.fromScale(0.5, CorSeletorTecla.Hue),
            Size = UDim2.new(1, 2, 0, 1),
            Parent = HueSeletor,
        })

        local TransparenciaSeletor, TransparenciaCor, TransparenciaCursor
        if Info.Transparency then
            TransparenciaSeletor = Novo("ImageButton", {
                Image = GerenciadorImagens.GetAsset("TransparencyTexture"),
                ScaleType = Enum.ScaleType.Tile,
                Size = UDim2.fromOffset(BarraLargura, MapaTamanho),
                TileSize = UDim2.fromOffset(8, 8),
                Parent = CorSuporte,
            })

            TransparenciaCor = Novo("Frame", {
                BackgroundColor3 = CorSeletorTecla.Value,
                Size = UDim2.fromScale(1, 1),
                Parent = TransparenciaSeletor,
            })
            Novo("UIGradient", {
                Rotation = 90,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = TransparenciaCor,
            })

            TransparenciaCursor = Novo("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                BorderColor3 = "DarkColor",
                BorderSizePixel = 1,
                Position = UDim2.fromScale(0.5, CorSeletorTecla.Transparency),
                Size = UDim2.new(1, 2, 0, 1),
                Parent = TransparenciaSeletor,
            })
        end

        local RedimensionarAlca
        if Info.Resizable then
            local BaseMapaTamanho = 200
            local BaseBarraLargura = BarraLargura
            local BasePreenchimentoInterno = 6
            local MinMapaTamanho = 140

            CorSeletorTecla.MapWidth = MapaTamanho
            CorSeletorTecla.MapHeight = MapaTamanho

            local function ObterBarraLargura(MapWidth)
                return math.clamp(math.floor((MapWidth / BaseMapaTamanho) * BaseBarraLargura + 0.5), 12, 24)
            end

            local function ObterConteudoLargura(MapWidth)
                local AtualBarraLargura = ObterBarraLargura(MapWidth)
                local Largura = MapWidth + AtualBarraLargura + BasePreenchimentoInterno
                if Info.Transparency then
                    Largura += (AtualBarraLargura + BasePreenchimentoInterno)
                end

                return Largura + 12
            end

            local FixoVerticalAcima = 6 + 6 + 8 + 20 + 8 + 20 + RodapeAltura
            if typeof(CorSeletorTecla.Title) == "string" then
                FixoVerticalAcima += 8 + 8
            end

            local function LimitarParaAreaVisao(NewWidth, NewHeight)
                local Camera = workspace.CurrentCamera
                if not Camera then
                    return NewWidth, NewHeight
                end

                local AreaVisaoTamanho = Camera.ViewportSize
                local TelaMargem = 12

                local MaxLargura = AreaVisaoTamanho.X - CorMenu.Menu.AbsolutePosition.X - TelaMargem
                local MaxAltura = AreaVisaoTamanho.Y - CorMenu.Menu.AbsolutePosition.Y - TelaMargem - FixoVerticalAcima

                while NewWidth > MinMapaTamanho and ObterConteudoLargura(NewWidth) > MaxLargura do
                    NewWidth -= 4
                end

                if NewHeight > MaxAltura then
                    NewHeight = math.max(MinMapaTamanho, math.floor(MaxAltura))
                end

                return NewWidth, NewHeight
            end

            local function AtualizarCorMenuTamanho(NewWidth, NewHeight)
                NewWidth = math.max(MinMapaTamanho, math.floor(NewWidth + 0.5))
                NewHeight = math.max(MinMapaTamanho, math.floor(NewHeight + 0.5))
                NewWidth, NewHeight = LimitarParaAreaVisao(NewWidth, NewHeight)

                if NewWidth == CorSeletorTecla.MapWidth and NewHeight == CorSeletorTecla.MapHeight then
                    return
                end

                local AtualBarraLargura = ObterBarraLargura(NewWidth)
                local CursorTamanho = math.clamp(math.floor((math.min(NewWidth, NewHeight) / BaseMapaTamanho) * 6 + 0.5), 4, 10)

                CorSuporte.Size = UDim2.new(1, 0, 0, NewHeight)
                SatBrilhoCorMapa.Size = UDim2.fromOffset(NewWidth, NewHeight)
                SatBrilhoCorCursor.Size = UDim2.fromOffset(CursorTamanho, CursorTamanho)
                HueSeletor.Size = UDim2.new(0, AtualBarraLargura, 0, NewHeight)

                if TransparenciaSeletor then
                    TransparenciaSeletor.Size = UDim2.new(0, AtualBarraLargura, 0, NewHeight)
                end

                CorSeletorTecla.MapWidth = NewWidth
                CorSeletorTecla.MapHeight = NewHeight
                CorMenu:SetSize(UDim2.new(0, ObterConteudoLargura(NewWidth), 0, 0))
            end

            RedimensionarAlca = Novo("TextButton", {
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Position = UDim2.new(1, -Library.CornerRadius / 4, 0, 0),
                Size = UDim2.fromScale(1, 1),
                SizeConstraint = Enum.SizeConstraint.RelativeYY,
                Text = "",
                Parent = RodapeFundo,
            })
            local RedimensionarAlcaIcone = Novo("ImageLabel", {
                ImageColor3 = "FontColor",
                ImageTransparency = 0.5,
                Position = UDim2.fromOffset(2, 2),
                Size = UDim2.new(1, -4, 1, -4),
                Parent = RedimensionarAlca,
            })
            if RedimensionarIcone then
                Library:ApplyLucideIcon(RedimensionarAlcaIcone, RedimensionarIcone)
            end

            table.insert(CorSeletorTecla.Connections, RedimensionarAlca.InputBegan:Connect(function(Entrada_2: InputObject)
                Library.CantDragForced = true
                local InicioMouse = Vector2.new(Mouse.X, Mouse.Y)
                local InicioLargura = CorSeletorTecla.MapWidth
                local InicioAltura = CorSeletorTecla.MapHeight

                while EhArrastarEntrada(Entrada_2) and not CorSeletorTecla.Destroyed do
                    local Delta = Vector2.new(Mouse.X, Mouse.Y) - InicioMouse
                    AtualizarCorMenuTamanho(InicioLargura + Delta.X, InicioAltura + Delta.Y)

                    RunService.RenderStepped:Wait()
                end

                Library.CantDragForced = false
            end))
        end

        local InfoSuporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 20),
            Parent = ConteudoSuporte,
        })
        Novo("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalFlex = Enum.UIFlexAlignment.Fill,
            Padding = UDim.new(0, 8),
            Parent = InfoSuporte,
        })

        local HueCaixa = Novo("TextBox", {
            BackgroundColor3 = "MainColor",
            ClearTextOnFocus = false,
            Size = UDim2.fromScale(1, 1),
            Text = "#??????",
            TextSize = 14,
            Parent = InfoSuporte,
        })

        local HueCaixaBorda = Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = HueCaixa,
        })

        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = HueCaixa,
            })
        )

        local RgbCaixa = Novo("TextBox", {
            BackgroundColor3 = "MainColor",
            ClearTextOnFocus = false,
            Size = UDim2.fromScale(1, 1),
            Text = "?, ?, ?",
            TextSize = 14,
            Parent = InfoSuporte,
        })

        local RgbCaixaBorda = Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = RgbCaixa,
        })

        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = RgbCaixa,
            })
        )

        local ContextoMenu
        ContextoMenu = Library:AddContextMenu(Suporte, UDim2.fromOffset(93, 0), function()
            return { Suporte.AbsoluteSize.X + 1.5, 0.5 }
        end, 1, function(Active: boolean)
            local Metade = UDim.new(0, Library.CornerRadius / 2)
            local Zero = UDim.new(0, 0)

            CorSeletorTeclaCanto.TopLeftRadius = Metade
            CorSeletorTeclaCanto.BottomLeftRadius = Metade
            CorSeletorTeclaCanto.TopRightRadius = Active and Zero or Metade
            CorSeletorTeclaCanto.BottomRightRadius = Active and Zero or Metade

            local MenuCanto = ContextoMenu and ContextoMenu.Corner
            if MenuCanto then
                MenuCanto.TopLeftRadius = Zero
                MenuCanto.TopRightRadius = Metade
                MenuCanto.BottomRightRadius = Metade
                MenuCanto.BottomLeftRadius = Metade
            end
        end, false, "no_top_left")
        CorSeletorTecla.ContextMenu = ContextoMenu
        ContextoMenu.List.Padding = UDim.new(0, 6)
        do
            local function CriarBotao(Texto_2, Funcao)
                local Botao = Novo("TextButton", {
                    BackgroundColor3 = "MainColor",
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 0, 21),
                    Text = Texto_2,
                    TextSize = 14,
                    Parent = ContextoMenu.Menu,
                })

                table.insert(CorSeletorTecla.Connections, Botao.MouseButton1Click:Connect(function()
                    Library:SafeCallback(Funcao)
                    ContextoMenu:Close()
                end))

                table.insert(CorSeletorTecla.Connections, Botao.MouseEnter:Connect(function()
                    TweenService:Create(Botao, Library.TweenInfo, {
                        BackgroundTransparency = 0.7,
                    }):Play()
                end))

                table.insert(CorSeletorTecla.Connections, Botao.MouseLeave:Connect(function()
                    TweenService:Create(Botao, Library.TweenInfo, {
                        BackgroundTransparency = 1,
                    }):Play()
                end))
            end

            CriarBotao("Copy color", function()
                Library.CopiedColor = { CorSeletorTecla.Value, CorSeletorTecla.Transparency }
            end)

            CorSeletorTecla.SetValueRGB = function(...) end 
            CriarBotao("Paste color", function()
                if not Library.CopiedColor then
                    return
                end

                CorSeletorTecla:SetValueRGB(Library.CopiedColor[1], Library.CopiedColor[2])
            end)

            if setclipboard then
                CriarBotao("Copy Hex", function()
                    setclipboard(tostring(CorSeletorTecla.Value:ToHex()))
                end)

                CriarBotao("Copy RGB", function()
                    setclipboard(table.concat({
                        math.floor(CorSeletorTecla.Value.R * 255),
                        math.floor(CorSeletorTecla.Value.G * 255),
                        math.floor(CorSeletorTecla.Value.B * 255),
                    }, ", "))
                end)
            end
        end

        local AcaoSuporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 20),
            Parent = ConteudoSuporte,
        })
        Novo("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalFlex = Enum.UIFlexAlignment.Fill,
            Padding = UDim.new(0, 8),
            Parent = AcaoSuporte,
        })

        local CopiaCorBotao = Novo("TextButton", {
            BackgroundColor3 = "MainColor",
            Size = UDim2.fromScale(1, 1),
            Text = "Copiar cor",
            TextSize = 14,
            Parent = AcaoSuporte,
        })
        Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = CopiaCorBotao,
        })
        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = CopiaCorBotao,
            })
        )

        local ColarCorBotao = Novo("TextButton", {
            BackgroundColor3 = "MainColor",
            Size = UDim2.fromScale(1, 1),
            Text = "Colar cor",
            TextSize = 14,
            Parent = AcaoSuporte,
        })
        Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = ColarCorBotao,
        })
        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = ColarCorBotao,
            })
        )

        local CopiaCorOriginalTexto = CopiaCorBotao.Text
        local ColarCorOriginalTexto = ColarCorBotao.Text
        local CopiaCorResetarId = 0
        local ColarCorResetarId = 0

        table.insert(CorSeletorTecla.Connections, CopiaCorBotao.MouseEnter:Connect(function()
            TweenService:Create(CopiaCorBotao, Library.TweenInfo, {
                BackgroundColor3 = Library:GetBetterColor(Library.Scheme.MainColor, 10),
            }):Play()
        end))

        table.insert(CorSeletorTecla.Connections, CopiaCorBotao.MouseLeave:Connect(function()
            TweenService:Create(CopiaCorBotao, Library.TweenInfo, {
                BackgroundColor3 = Library.Scheme.MainColor,
            }):Play()
        end))

        table.insert(CorSeletorTecla.Connections, ColarCorBotao.MouseEnter:Connect(function()
            TweenService:Create(ColarCorBotao, Library.TweenInfo, {
                BackgroundColor3 = Library:GetBetterColor(Library.Scheme.MainColor, 10),
            }):Play()
        end))

        table.insert(CorSeletorTecla.Connections, ColarCorBotao.MouseLeave:Connect(function()
            TweenService:Create(ColarCorBotao, Library.TweenInfo, {
                BackgroundColor3 = Library.Scheme.MainColor,
            }):Play()
        end))

        table.insert(CorSeletorTecla.Connections, CopiaCorBotao.MouseButton1Click:Connect(function()
            Library.CopiedColor = { CorSeletorTecla.Value, CorSeletorTecla.Transparency }

            CopiaCorResetarId += 1
            local EsteResetarId = CopiaCorResetarId
            CopiaCorBotao.Text = "Cor copiada"

            task.delay(1, function()
                if CorSeletorTecla.Destroyed or EsteResetarId ~= CopiaCorResetarId then
                    return
                end

                CopiaCorBotao.Text = CopiaCorOriginalTexto
            end)
        end))

        table.insert(CorSeletorTecla.Connections, ColarCorBotao.MouseButton1Click:Connect(function()
            ColarCorResetarId += 1
            local EsteResetarId = ColarCorResetarId

            if not Library.CopiedColor then
                ColarCorBotao.Text = "Nada para colar"
            else
                CorSeletorTecla:SetValueRGB(Library.CopiedColor[1], Library.CopiedColor[2])
                ColarCorBotao.Text = "Cor colada"
            end

            task.delay(1, function()
                if CorSeletorTecla.Destroyed or EsteResetarId ~= ColarCorResetarId then
                    return
                end

                ColarCorBotao.Text = ColarCorOriginalTexto
            end)
        end))

        function CorSeletorTecla:SetHSVFromRGB(Cor)
            CorSeletorTecla.Hue, CorSeletorTecla.Sat, CorSeletorTecla.Vib = Cor:ToHSV()
        end

        function CorSeletorTecla:Display()
            if Library.Unloaded then
                return
            end

            CorSeletorTecla.Value = Color3.fromHSV(CorSeletorTecla.Hue, CorSeletorTecla.Sat, CorSeletorTecla.Vib)

            SatBrilhoCorMapa.BackgroundColor3 = Color3.fromHSV(CorSeletorTecla.Hue, 1, 1)
            if TransparenciaCor then
                TransparenciaCor.BackgroundColor3 = CorSeletorTecla.Value
            end

            SatBrilhoCorCursor.Position = UDim2.fromScale(CorSeletorTecla.Sat, 1 - CorSeletorTecla.Vib)
            HueCursor.Position = UDim2.fromScale(0.5, CorSeletorTecla.Hue)
            if TransparenciaCursor then
                TransparenciaCursor.Position = UDim2.fromScale(0.5, CorSeletorTecla.Transparency)
            end

            HueCaixa.Text = "#" .. CorSeletorTecla.Value:ToHex()
            RgbCaixa.Text = table.concat({
                math.floor(CorSeletorTecla.Value.R * 255),
                math.floor(CorSeletorTecla.Value.G * 255),
                math.floor(CorSeletorTecla.Value.B * 255),
            }, ", ")

            AtualizarRodapeInfo()
        end

        local function AplicarSuporteVisual(Desativado: boolean)
            Suporte.Active = not Desativado
            SuporteBorda.Transparency = Desativado and 0.5 or 0
            Suporte.BackgroundTransparency = Desativado and 0.5 or 0

            if Desativado then
                Suporte.BackgroundColor3 = CorSeletorTecla.Value:Lerp(Library.Scheme.BackgroundColor, 0.5)
                SuporteTransparencia.ImageTransparency = math.clamp((1 - CorSeletorTecla.Transparency) + 0.5, 0, 1)
            else
                Suporte.BackgroundColor3 = CorSeletorTecla.Value
                SuporteBorda.Color = Library:GetDarkerColor(CorSeletorTecla.Value)
                SuporteTransparencia.ImageTransparency = (1 - CorSeletorTecla.Transparency)
            end
        end

        function CorSeletorTecla:RunChanged()
            if PaiObj.Disabled then
                return
            end

            Library:SafeCallback(CorSeletorTecla.Callback, CorSeletorTecla.Value)
            Library:SafeCallback(CorSeletorTecla.Changed, CorSeletorTecla.Value)
        end

        function CorSeletorTecla:Update()
            CorSeletorTecla:Display()

            local Desativado = PaiObj.Disabled == true
            AplicarSuporteVisual(Desativado)

            if Desativado then
                if CorMenu.Active then
                    CorMenu:Close()
                end

                if ContextoMenu.Active then
                    ContextoMenu:Close()
                end
            end

            CorSeletorTecla:RunChanged()
        end

        function CorSeletorTecla:OnChanged(Funcao)
            CorSeletorTecla.Changed = Funcao
        end

        function CorSeletorTecla:SetValue(HSV, Transparencia)
            if typeof(HSV) == "Color3" then
                CorSeletorTecla:SetValueRGB(HSV, Transparencia)
                return
            end

            local Cor = Color3.fromHSV(HSV[1], HSV[2], HSV[3])
            CorSeletorTecla.Transparency = Info.Transparency and Transparencia or 0
            CorSeletorTecla:SetHSVFromRGB(Cor)
            CorSeletorTecla:Update()
        end

        function CorSeletorTecla:SetValueRGB(Cor, Transparencia)
            CorSeletorTecla.Transparency = Info.Transparency and Transparencia or 0
            CorSeletorTecla:SetHSVFromRGB(Cor)
            CorSeletorTecla:Update()
        end

        table.insert(CorSeletorTecla.Connections, Suporte.MouseButton1Click:Connect(function()
            if PaiObj.Disabled then
                return
            end

            CorMenu:Toggle()
        end))

        table.insert(CorSeletorTecla.Connections, Suporte.MouseButton2Click:Connect(function()
            if PaiObj.Disabled then
                return
            end

            ContextoMenu:Toggle()
        end))

        table.insert(CorSeletorTecla.Connections, SatBrilhoCorMapa.InputBegan:Connect(function(Entrada_2: InputObject)
            while EhArrastarEntrada(Entrada_2) and not CorSeletorTecla.Destroyed do
                local MinX = SatBrilhoCorMapa.AbsolutePosition.X
                local MaxX = MinX + SatBrilhoCorMapa.AbsoluteSize.X
                local LocalizacaoX = math.clamp(Mouse.X, MinX, MaxX)

                local MinY = SatBrilhoCorMapa.AbsolutePosition.Y
                local MaxY = MinY + SatBrilhoCorMapa.AbsoluteSize.Y
                local LocalizacaoY = math.clamp(Mouse.Y, MinY, MaxY)

                local AntigoSat = CorSeletorTecla.Sat
                local AntigoBrilhoCor = CorSeletorTecla.Vib
                CorSeletorTecla.Sat = (LocalizacaoX - MinX) / (MaxX - MinX)
                CorSeletorTecla.Vib = 1 - ((LocalizacaoY - MinY) / (MaxY - MinY))

                if CorSeletorTecla.Sat ~= AntigoSat or CorSeletorTecla.Vib ~= AntigoBrilhoCor then
                    CorSeletorTecla:Update()
                end

                RunService.RenderStepped:Wait()
            end
        end))

        table.insert(CorSeletorTecla.Connections, HueSeletor.InputBegan:Connect(function(Entrada_2: InputObject)
            while EhArrastarEntrada(Entrada_2) and not CorSeletorTecla.Destroyed do
                local Min = HueSeletor.AbsolutePosition.Y
                local Max = Min + HueSeletor.AbsoluteSize.Y
                local Localizacao = math.clamp(Mouse.Y, Min, Max)

                local AntigoHue = CorSeletorTecla.Hue
                CorSeletorTecla.Hue = (Localizacao - Min) / (Max - Min)

                if CorSeletorTecla.Hue ~= AntigoHue then
                    CorSeletorTecla:Update()
                end

                RunService.RenderStepped:Wait()
            end
        end))

        if TransparenciaSeletor then
            table.insert(CorSeletorTecla.Connections, TransparenciaSeletor.InputBegan:Connect(function(Entrada_2: InputObject)
                while EhArrastarEntrada(Entrada_2) and not CorSeletorTecla.Destroyed do
                    local Min = TransparenciaSeletor.AbsolutePosition.Y
                    local Max = TransparenciaSeletor.AbsolutePosition.Y + TransparenciaSeletor.AbsoluteSize.Y
                    local Localizacao = math.clamp(Mouse.Y, Min, Max)

                    local AntigoTransparencia = CorSeletorTecla.Transparency
                    CorSeletorTecla.Transparency = (Localizacao - Min) / (Max - Min)

                    if CorSeletorTecla.Transparency ~= AntigoTransparencia then
                        CorSeletorTecla:Update()
                    end

                    RunService.RenderStepped:Wait()
                end
            end))
        end

        table.insert(CorSeletorTecla.Connections, HueCaixa.FocusLost:Connect(function(Enter)
            if not Enter then
                return
            end

            local Sucesso, Cor = pcall(Color3.fromHex, HueCaixa.Text)
            if Sucesso and typeof(Cor) == "Color3" then
                CorSeletorTecla.Hue, CorSeletorTecla.Sat, CorSeletorTecla.Vib = Cor:ToHSV()
            end

            CorSeletorTecla:Update()
        end))

        table.insert(CorSeletorTecla.Connections, RgbCaixa.FocusLost:Connect(function(Enter)
            if not Enter then
                return
            end

            local R, G, B = RgbCaixa.Text:match("(%d+),%s*(%d+),%s*(%d+)")
            if R and G and B then
                CorSeletorTecla:SetHSVFromRGB(Color3.fromRGB(R, G, B))
            end

            CorSeletorTecla:Update()
        end))

        for _, CaixaPar in {
            { HueCaixa, HueCaixaBorda },
            { RgbCaixa, RgbCaixaBorda }
        } do
            local TextoCaixaInstancia, Borda = CaixaPar[1], CaixaPar[2]

            table.insert(CorSeletorTecla.Connections, TextoCaixaInstancia.Focused:Connect(function()
                Library.Registry[Borda].Color = "AccentColor"
                TweenService:Create(Borda, Library.TweenInfo, {
                    Color = Library.Scheme.AccentColor,
                }):Play()
            end))

            table.insert(CorSeletorTecla.Connections, TextoCaixaInstancia.FocusLost:Connect(function()
                Library.Registry[Borda].Color = "OutlineColor"
                TweenService:Create(Borda, Library.TweenInfo, {
                    Color = Library.Scheme.OutlineColor,
                }):Play()
            end))
        end

        CorSeletorTecla:Update()

        if not PaiObj.Addons then
            PaiObj.Addons = {}
        end

        table.insert(PaiObj.Addons, CorSeletorTecla)

        CorSeletorTecla.Default = CorSeletorTecla.Value

        function CorSeletorTecla:Destroy()
            CorSeletorTecla.Destroyed = true

            if CorSeletorTecla.Connections then
                for _, Conexao in CorSeletorTecla.Connections do
                    Conexao:Disconnect()
                end
            end

            if CorMenu then
                CorMenu:Destroy()
            end

            if RedimensionarAlca then
                RedimensionarAlca:Destroy()
            end

            if ContextoMenu then
                ContextoMenu:Destroy()
            end

            if Suporte then
                Suporte:Destroy()
            end

            if PaiObj and PaiObj.Addons then
                local ComplementoIndice = table.find(PaiObj.Addons, CorSeletorTecla)

                if ComplementoIndice then
                    table.remove(PaiObj.Addons, ComplementoIndice)
                end
            end

            Opcoes[Indice] = nil
        end

        Opcoes[Indice] = CorSeletorTecla

        return self
    end

    BaseComplementos.__index = Funcoes
    BaseComplementos.__namecall = function(_, Tecla, ...)
        return Funcoes[Tecla](...)
    end
end

local BaseCaixaGrupo = {}
do
    local Funcoes = {}

    function Funcoes:AddDivider(...)
        if self.Destroyed then return nil end

        local Parametros = select(1, ...)
        local Texto_2
        local MargemTopo = 0
        local MargemInferior = 0

        if typeof(Parametros) == "table" then
            Texto_2 = Parametros.Text
            MargemTopo = Parametros.MarginTop or Parametros.Margin or 0
            MargemInferior = Parametros.MarginBottom or Parametros.Margin or 0
        elseif typeof(Parametros) == "string" then
            Texto_2 = Parametros
        end

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local Suporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 6 + MargemTopo + MargemInferior),
            Parent = Conteiner,
        })

        local InternoSuporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 1, 0),
            Parent = Suporte,
        })

        Novo("UIPadding", {
            PaddingTop = UDim.new(0, MargemTopo),
            PaddingBottom = UDim.new(0, MargemInferior),
            Parent = Suporte,
        })

        if Texto_2 then
            local TextLabel = Novo("TextLabel", {
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 0),
                Text = Texto_2,
                TextSize = 14,
                TextTransparency = 0.5,
                TextXAlignment = Enum.TextXAlignment.Center,
                Parent = InternoSuporte,
            })

            local X, _ = Library:GetTextBounds(Texto_2, TextLabel.FontFace, TextLabel.TextSize, TextLabel.AbsoluteSize.X / Library.DPIScale)
            local TamanhoX = X // 2 + 10

            Novo("Frame", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = "MainColor",
                BorderColor3 = "OutlineColor",
                BorderSizePixel = 1,
                Position = UDim2.fromScale(0, 0.5),
                Size = UDim2.new(0.5, -TamanhoX, 0, 2),
                Parent = InternoSuporte,
            })
            Novo("Frame", {
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = "MainColor",
                BorderColor3 = "OutlineColor",
                BorderSizePixel = 1,
                Position = UDim2.fromScale(1, 0.5),
                Size = UDim2.new(0.5, -TamanhoX, 0, 2),
                Parent = InternoSuporte,
            })
        else
            Novo("Frame", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = "MainColor",
                BorderColor3 = "OutlineColor",
                BorderSizePixel = 1,
                Position = UDim2.fromScale(0, 0.5),
                Size = UDim2.new(1, 0, 0, 2),
                Parent = InternoSuporte,
            })
        end

        CaixaGrupo:Resize()

        local Divisor = {
            Connections = {},
            Destroyed = false,

            Holder = Suporte,
            Text = Texto_2,
            MarginTop = MargemTopo,
            MarginBottom = MargemInferior,
            Type = "Divider",

            Parent = CaixaGrupo,
        }

        function Divisor:SetVisible(Valor)
            Suporte.Visible = Valor == true
            CaixaGrupo:Resize()
        end

        function Divisor:Destroy()
            Divisor.Destroyed = true

            if Divisor.Connections then
                for _, Conexao in Divisor.Connections do
                    Conexao:Disconnect()
                end
            end

            if Suporte then
                Suporte:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, Divisor)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
        end

        table.insert(CaixaGrupo.Elements, Divisor)
        return Divisor
    end

    function Funcoes:AddLabel(...)
        if self.Destroyed then return nil end

        local Dados = {}
        local Complementos = {}

        local Primeiro = select(1, ...)
        local Segundo = select(2, ...)

        if typeof(Primeiro) == "table" or typeof(Segundo) == "table" then
            local Parametros = typeof(Primeiro) == "table" and Primeiro or Segundo

            Dados.Text = Parametros.Text or ""
            Dados.DoesWrap = Parametros.DoesWrap or false
            Dados.Size = Parametros.Size or 14
            Dados.Visible = if typeof(Parametros.Visible) == "boolean" then Parametros.Visible else true
            Dados.Idx = typeof(Segundo) == "table" and Primeiro or nil
        else
            Dados.Text = Primeiro or ""
            Dados.DoesWrap = Segundo or false
            Dados.Size = 14
            Dados.Visible = true
            Dados.Idx = select(3, ...) or nil
        end

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local Rotulo = {
            Connections = {},
            Destroyed = false,

            Text = Dados.Text,
            DoesWrap = Dados.DoesWrap,

            Addons = Complementos,

            Visible = Dados.Visible,
            Type = "Label",

            Parent = CaixaGrupo,
        }

        local TextLabel = Novo("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 18),
            Text = Rotulo.Text,
            TextSize = Dados.Size,
            TextWrapped = Rotulo.DoesWrap,
            TextXAlignment = CaixaGrupo.IsKeyTab and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left,
            Visible = Rotulo.Visible,
            Parent = Conteiner,
        })

        function Rotulo:Display()
            if not Rotulo.DoesWrap then
                return
            end

            local Largura = TextLabel.AbsoluteSize.X / Library.DPIScale
            if Largura <= 0 then return end

            local _, Y = Library:GetTextBounds(Rotulo.Text, TextLabel.FontFace, TextLabel.TextSize, Largura)
            TextLabel.Size = UDim2.new(1, 0, 0, Y + 4)
        end

        function Rotulo:SetVisible(Visivel: boolean)
            Rotulo.Visible = Visivel

            TextLabel.Visible = Rotulo.Visible
            CaixaGrupo:Resize()
        end

        function Rotulo:SetText(Texto_2: string)
            Rotulo.Text = Texto_2
            TextLabel.Text = Texto_2

            Rotulo:Display()
            CaixaGrupo:Resize()
        end

        if Rotulo.DoesWrap then
            Rotulo:Display()

            local Ultimo = TextLabel.AbsoluteSize
            table.insert(Rotulo.Connections, TextLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                if TextLabel.AbsoluteSize == Ultimo then
                    return
                end

                Rotulo:Display()
                Ultimo = TextLabel.AbsoluteSize

                CaixaGrupo:Resize()
            end))
        else
            Novo("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Right,
                Padding = UDim.new(0, 6),
                Parent = TextLabel,
            })
        end

        CaixaGrupo:Resize()

        Rotulo.TextLabel = TextLabel
        Rotulo.Container = Conteiner
        if not Dados.DoesWrap then
            setmetatable(Rotulo, BaseComplementos)
        end

        Rotulo.Holder = TextLabel
        table.insert(CaixaGrupo.Elements, Rotulo)

        if Dados.Idx then
            Rotulos[Dados.Idx] = Rotulo
        else
            table.insert(Rotulos, Rotulo)
        end

        function Rotulo:Destroy()
            Rotulo.Destroyed = true

            if Rotulo.Connections then
                for _, Conexao in Rotulo.Connections do
                    Conexao:Disconnect()
                end
            end

            if Rotulo.Addons then
                for Indice_2 = #Rotulo.Addons, 1, -1 do
                    local Complemento = table.remove(Rotulo.Addons, Indice_2)
                    if Complemento and Complemento.Destroy then
                        Complemento:Destroy()
                    end
                end
            end

            if TextLabel then
                TextLabel:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, Rotulo)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()

            if Dados.Idx then
                Rotulos[Dados.Idx] = nil
            else
                local RotuloIndice = table.find(Rotulos, Rotulo)

                if RotuloIndice then
                    table.remove(Rotulos, RotuloIndice)
                end
            end
        end

        return Rotulo
    end

    function Funcoes:AddButton(...)
        if self.Destroyed then return nil end

        local function ObterInfo(...)
            local Info = {}

            local Primeiro = select(1, ...)
            local Segundo = select(2, ...)

            if typeof(Primeiro) == "table" or typeof(Segundo) == "table" then
                local Parametros = typeof(Primeiro) == "table" and Primeiro or Segundo

                Info.Text = Parametros.Text or ""
                Info.Func = Parametros.Func or Parametros.Callback or function() end
                Info.DoubleClick = Parametros.DoubleClick
                Info.Icon = Parametros.Icon or Parametros.IconName

                Info.Tooltip = Parametros.Tooltip
                Info.DisabledTooltip = Parametros.DisabledTooltip

                Info.Risky = Parametros.Risky or false
                Info.Disabled = Parametros.Disabled or false
                Info.Half = Parametros.Half
                Info.Visible = if typeof(Parametros.Visible) == "boolean" then Parametros.Visible else true
                Info.Idx = typeof(Segundo) == "table" and Primeiro or nil
            else
                Info.Text = Primeiro or ""
                Info.Func = Segundo or function() end
                Info.DoubleClick = false
                Info.Icon = nil

                Info.Tooltip = nil
                Info.DisabledTooltip = nil

                Info.Risky = false
                Info.Disabled = false
                Info.Visible = true
                Info.Idx = select(3, ...) or nil
            end

            return Info
        end
        local Info = ObterInfo(...)

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local Botao = {
            Connections = {},
            Destroyed = false,

            Text = Info.Text,
            Func = Info.Func,
            DoubleClick = Info.DoubleClick,
            Icon = Info.Icon,

            Tooltip = Info.Tooltip,
            DisabledTooltip = Info.DisabledTooltip,
            TooltipTable = nil,

            Risky = Info.Risky,
            Disabled = Info.Disabled,
            Visible = Info.Visible,
            Locked = false,

            Base = nil,
            Stroke = nil,
            Content = nil,
            Label = nil,
            IconImage = nil,

            Tween = nil,
            Type = "Button",

            Parent = CaixaGrupo,
        }

        local BotaoPai = Conteiner

        if Info.Half == "Left" then
            local Linha_2 = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 21),
                Parent = Conteiner,
            })

            Novo("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                Padding = UDim.new(0, 4),
                Parent = Linha_2,
            })

            CaixaGrupo.HalfButtonRow = Linha_2
            BotaoPai = Linha_2
        elseif Info.Half == "Right" then
            BotaoPai = CaixaGrupo.HalfButtonRow or Conteiner
        end

        local Suporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = if BotaoPai ~= Conteiner then UDim2.new(0.5, -2, 0, 21) else UDim2.new(1, 0, 0, 21),
            Parent = BotaoPai,
        })

        Novo("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalFlex = Enum.UIFlexAlignment.Fill,
            Padding = UDim.new(0, 9),
            Parent = Suporte,
        })

        local function AplicarBotaoIcone(Botao, IconName)
            local Conteudo = Botao.Content
            if not Conteudo then
                return
            end

            local AnalisadoIcone = Library:GetCustomIcon(IconName)
            if AnalisadoIcone then
                local CorTecla = Botao.Risky and "RedColor" or (AnalisadoIcone.Custom and "WhiteColor" or "FontColor")

                if not Botao.IconImage then
                    Botao.IconImage = Novo("ImageLabel", {
                        BackgroundTransparency = 1,
                        ImageColor3 = CorTecla,
                        LayoutOrder = 0,
                        Size = UDim2.fromOffset(14, 14),
                        Parent = Conteudo,
                    })
                else
                    Botao.IconImage.ImageColor3 = Library.Scheme[CorTecla]
                    Library.Registry[Botao.IconImage].ImageColor3 = CorTecla
                end

                Botao.IconImage.ImageTransparency = Botao.Disabled and 0.8 or 0.4
                Botao.IconImage.Visible = true
                Library:ApplyLucideIcon(Botao.IconImage, AnalisadoIcone)
            elseif Botao.IconImage then
                Botao.IconImage.Visible = false
            end
        end

        local function CriarBotao(Botao)
            local Base = Novo("TextButton", {
                Active = not Botao.Disabled,
                BackgroundColor3 = Botao.Disabled and "BackgroundColor" or "MainColor",
                Size = UDim2.fromScale(1, 1),
                Text = "",
                Visible = Botao.Visible,
                Parent = Suporte,
            })

            local Borda = Novo("UIStroke", {
                Color = "OutlineColor",
                Transparency = Botao.Disabled and 0.5 or 0,
                Parent = Base,
            })

            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Base,
                })
            )

            local Conteudo = Novo("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(0, 16),
                Parent = Base,
            })
            Novo("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Center,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                Padding = UDim.new(0, 6),
                Parent = Conteudo,
            })
            Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 8),
                Parent = Conteudo,
            })

            Botao.Content = Conteudo
            Botao.Label = Novo("TextLabel", {
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                LayoutOrder = 1,
                Size = UDim2.fromOffset(0, 16),
                Text = Botao.Text,
                TextSize = 14,
                TextTransparency = Botao.Disabled and 0.8 or 0.4,
                Parent = Conteudo,
            })

            if Botao.Risky then
                Botao.Label.TextColor3 = Library.Scheme.RedColor
                Library.Registry[Botao.Label].TextColor3 = "RedColor"
            end

            AplicarBotaoIcone(Botao, Botao.Icon)

            return Base, Borda
        end

        local function IniciarEventos(Botao)
            table.insert(Botao.Connections, Botao.Base.MouseEnter:Connect(function()
                if Botao.Disabled then
                    return
                end

                Botao.Tween = TweenService:Create(Botao.Label, Library.TweenInfo, {
                    TextTransparency = 0,
                })
                Botao.Tween:Play()

                if Botao.IconImage and Botao.IconImage.Visible then
                    TweenService:Create(Botao.IconImage, Library.TweenInfo, {
                        ImageTransparency = 0,
                    }):Play()
                end
            end))
            table.insert(Botao.Connections, Botao.Base.MouseLeave:Connect(function()
                if Botao.Disabled then
                    return
                end

                Botao.Tween = TweenService:Create(Botao.Label, Library.TweenInfo, {
                    TextTransparency = 0.4,
                })
                Botao.Tween:Play()

                if Botao.IconImage and Botao.IconImage.Visible then
                    TweenService:Create(Botao.IconImage, Library.TweenInfo, {
                        ImageTransparency = 0.4,
                    }):Play()
                end
            end))

            table.insert(Botao.Connections, Botao.Base.MouseButton1Click:Connect(function()
                if Botao.Disabled or Botao.Locked then
                    return
                end

                if Botao.DoubleClick then
                    Botao.Locked = true

                    local IconeEstavaVisivel = false
                    if Botao.IconImage then
                        IconeEstavaVisivel = Botao.IconImage.Visible
                        Botao.IconImage.Visible = false
                    end

                    Botao.Label.Text = "Tem certeza?"
                    Botao.Label.TextColor3 = Library.Scheme.AccentColor
                    Library.Registry[Botao.Label].TextColor3 = "AccentColor"

                    local Clicado = AguardarParaEvento(Botao.Base.MouseButton1Click, 0.5)

                    Botao.Label.Text = Botao.Text
                    Botao.Label.TextColor3 = Botao.Risky and Library.Scheme.RedColor or Library.Scheme.FontColor
                    Library.Registry[Botao.Label].TextColor3 = Botao.Risky and "RedColor" or "FontColor"

                    if Botao.IconImage then
                        Botao.IconImage.Visible = IconeEstavaVisivel
                    end

                    if Clicado then
                        Library:SafeCallback(Botao.Func)
                    end

                    RunService.RenderStepped:Wait()
                    Botao.Locked = false
                    return
                end

                Library:SafeCallback(Botao.Func)
            end))
        end

        Botao.Base, Botao.Stroke = CriarBotao(Botao)
        IniciarEventos(Botao)

        function Botao:AddButton(...)
            local Info = ObterInfo(...)

            local SubBotao = {
                Connections = {},
                Destroyed = false,

                Text = Info.Text,
                Func = Info.Func,
                DoubleClick = Info.DoubleClick,
                Icon = Info.Icon,

                Tooltip = Info.Tooltip,
                DisabledTooltip = Info.DisabledTooltip,
                TooltipTable = nil,

                Risky = Info.Risky,
                Disabled = Info.Disabled,
                Visible = Info.Visible,
                Locked = false,

                Base = nil,
                Stroke = nil,
                Content = nil,
                Label = nil,
                IconImage = nil,

                Tween = nil,
                Type = "SubButton",
            }

            Botao.SubButton = SubBotao
            SubBotao.Base, SubBotao.Stroke = CriarBotao(SubBotao)
            IniciarEventos(SubBotao)

            function SubBotao:UpdateColors()
                if Library.Unloaded then
                    return
                end

                PararInterpolacao(SubBotao.Tween)

                SubBotao.Base.BackgroundColor3 = SubBotao.Disabled and Library.Scheme.BackgroundColor or Library.Scheme.MainColor
                SubBotao.Label.TextTransparency = SubBotao.Disabled and 0.8 or 0.4
                SubBotao.Stroke.Transparency = SubBotao.Disabled and 0.5 or 0

                if SubBotao.IconImage and SubBotao.IconImage.Visible then
                    SubBotao.IconImage.ImageTransparency = SubBotao.Disabled and 0.8 or 0.4
                end

                Library.Registry[SubBotao.Base].BackgroundColor3 = SubBotao.Disabled and "BackgroundColor"
                    or "MainColor"
            end

            function SubBotao:SetDisabled(Desativado: boolean)
                SubBotao.Disabled = Desativado

                if SubBotao.TooltipTable then
                    SubBotao.TooltipTable.Disabled = SubBotao.Disabled
                end

                SubBotao.Base.Active = not SubBotao.Disabled
                SubBotao:UpdateColors()
                Library:UpdateAddons(SubBotao)
            end

            function SubBotao:SetVisible(Visivel: boolean)
                SubBotao.Visible = Visivel

                SubBotao.Base.Visible = SubBotao.Visible
                CaixaGrupo:Resize()
            end

            function SubBotao:SetText(Texto_2: string)
                SubBotao.Text = Texto_2
                SubBotao.Label.Text = Texto_2
            end

            function SubBotao:SetIcon(Icon: string?)
                SubBotao.Icon = Icon
                AplicarBotaoIcone(SubBotao, Icon)
            end

            if typeof(SubBotao.Tooltip) == "string" or typeof(SubBotao.DisabledTooltip) == "string" then
                SubBotao.TooltipTable =
                    Library:AddTooltip(SubBotao.Tooltip, SubBotao.DisabledTooltip, SubBotao.Base)
                SubBotao.TooltipTable.Disabled = SubBotao.Disabled
            end

            SubBotao:UpdateColors()

            if Info.Idx then
                Botoes[Info.Idx] = SubBotao
            else
                table.insert(Botoes, SubBotao)
            end

            SubBotao.AddKeyPicker = BaseComplementos.__index.AddKeyPicker

            function SubBotao:Destroy()
                SubBotao.Destroyed = true

                if SubBotao.Connections then
                    for _, Conexao in SubBotao.Connections do
                        Conexao:Disconnect()
                    end
                end

                if SubBotao.TooltipTable then
                    SubBotao.TooltipTable:Destroy()
                end

                if SubBotao.Tween then
                    SubBotao.Tween:Destroy()
                end

                if SubBotao.Base then
                    SubBotao.Base:Destroy()
                end

                if Info.Idx then
                    Botoes[Info.Idx] = nil
                else
                    local BIndice = table.find(Botoes, SubBotao)

                    if BIndice then
                        table.remove(Botoes, BIndice)
                    end
                end
            end

            return SubBotao
        end

