    function Funcoes:AddCheckbox(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.Toggle)

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local Alternador = {
            Connections = {},
            Destroyed = false,

            Text = Info.Text,
            Value = Info.Default,

            Tooltip = Info.Tooltip,
            DisabledTooltip = Info.DisabledTooltip,
            TooltipTable = nil,

            Callback = Info.Callback,
            Changed = Info.Changed,

            Risky = Info.Risky,
            Disabled = Info.Disabled,
            Visible = Info.Visible,

            Addons = {},
            AnyKeyPickerPicking = false,

            Variant = "Checkbox",
            Type = "Toggle",

            Parent = CaixaGrupo,
        }

        local Botao = Novo("TextButton", {
            Active = not Alternador.Disabled,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 18),
            Text = "",
            Visible = Alternador.Visible,
            Parent = Conteiner,
        })

        local Rotulo = Novo("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(26, 0),
            Size = UDim2.new(1, -26, 1, 0),
            Text = Alternador.Text,
            TextSize = 14,
            TextTransparency = 0.4,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = Botao,
        })

        Novo("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalAlignment = Enum.HorizontalAlignment.Right,
            Padding = UDim.new(0, 6),
            Parent = Rotulo,
        })

        local CaixaSelecao = Novo("Frame", {
            BackgroundColor3 = "MainColor",
            Size = UDim2.fromScale(1, 1),
            SizeConstraint = Enum.SizeConstraint.RelativeYY,
            Parent = Botao,
        })
        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = CaixaSelecao,
            })
        )

        local CaixaSelecaoBorda = Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = CaixaSelecao,
        })

        local VerificarImagem = Novo("ImageLabel", {
            ImageColor3 = "FontColor",
            ImageTransparency = 1,
            Position = UDim2.fromOffset(2, 2),
            Size = UDim2.new(1, -4, 1, -4),
            Parent = CaixaSelecao,
        })
        if VerificarIcone then
            Library:ApplyLucideIcon(VerificarImagem, VerificarIcone)
        end

        function Alternador:UpdateColors()
            Alternador:Display()
        end

        function Alternador:Display()
            if Library.Unloaded then
                return
            end

            CaixaSelecaoBorda.Transparency = Alternador.Disabled and 0.5 or 0

            if Alternador.Disabled then
                Rotulo.TextTransparency = 0.8
                VerificarImagem.ImageTransparency = Alternador.Value and 0.8 or 1

                CaixaSelecao.BackgroundColor3 = Library.Scheme.BackgroundColor
                Library.Registry[CaixaSelecao].BackgroundColor3 = "BackgroundColor"

                return
            end

            TweenService:Create(Rotulo, Library.TweenInfo, {
                TextTransparency = Alternador.Value and 0 or 0.4,
            }):Play()
            TweenService:Create(VerificarImagem, Library.TweenInfo, {
                ImageTransparency = Alternador.Value and 0 or 1,
            }):Play()

            CaixaSelecao.BackgroundColor3 = Library.Scheme.MainColor
            Library.Registry[CaixaSelecao].BackgroundColor3 = "MainColor"
        end

        function Alternador:OnChanged(Funcao)
            Alternador.Changed = Funcao
        end

        function Alternador:RunChanged()
            if Alternador.Disabled then
                return
            end

            Library:SafeCallback(Alternador.Callback, Alternador.Value)
            Library:SafeCallback(Alternador.Changed, Alternador.Value)
        end

        function Alternador:SetValue(Valor)
            Alternador.Value = Valor
            Alternador:Display()

            for _, Complemento in Alternador.Addons do
                if Complemento.Type == "KeyPicker" and Complemento.SyncToggleState then
                    Complemento.Toggled = Alternador.Value
                    Complemento:Update()
                end
            end

            if not Alternador.Disabled then
                Library:UpdateDependencyBoxes()
            end

            if not Alternador.AnyKeyPickerPicking then
                Alternador:RunChanged()
            end
        end

        function Alternador:SetDisabled(Desativado: boolean)
            Alternador.Disabled = Desativado

            if Alternador.TooltipTable then
                Alternador.TooltipTable.Disabled = Alternador.Disabled
            end

            Library:UpdateAddons(Alternador)

            Botao.Active = not Alternador.Disabled
            Alternador:Display()

            Library:UpdateDependencyBoxes()
        end

        function Alternador:SetVisible(Visivel: boolean)
            Alternador.Visible = Visivel

            Botao.Visible = Alternador.Visible
            CaixaGrupo:Resize()
        end

        function Alternador:SetText(Texto_2: string)
            Alternador.Text = Texto_2
            Rotulo.Text = Texto_2
        end

        table.insert(Alternador.Connections, Botao.MouseButton1Click:Connect(function()
            if Alternador.Disabled then
                return
            end

            Alternador:SetValue(not Alternador.Value)
        end))

        if typeof(Alternador.Tooltip) == "string" or typeof(Alternador.DisabledTooltip) == "string" then
            Alternador.TooltipTable = Library:AddTooltip(Alternador.Tooltip, Alternador.DisabledTooltip, Botao)
            Alternador.TooltipTable.Disabled = Alternador.Disabled
        end

        if Alternador.Risky then
            Rotulo.TextColor3 = Library.Scheme.RedColor
            Library.Registry[Rotulo].TextColor3 = "RedColor"
        end

        Alternador:Display()
        CaixaGrupo:Resize()

        Alternador.TextLabel = Rotulo
        Alternador.Container = Conteiner
        setmetatable(Alternador, BaseComplementos)

        Alternador.Holder = Botao
        table.insert(CaixaGrupo.Elements, Alternador)

        Alternador.Default = Alternador.Value

        Alternadores[Indice] = Alternador

        function Alternador:Destroy()
            Alternador.Destroyed = true

            if Alternador.Connections then
                for _, Conexao in Alternador.Connections do
                    Conexao:Disconnect()
                end
            end

            if Alternador.TooltipTable then
                Alternador.TooltipTable:Destroy()
            end

            if Botao then
                Botao:Destroy()
            end

            if Alternador.Addons then
                for Indice_2 = #Alternador.Addons, 1, -1 do
                    local Complemento = table.remove(Alternador.Addons, Indice_2)
                    if Complemento and Complemento.Destroy then
                        Complemento:Destroy()
                    end
                end
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, Alternador)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
            Alternadores[Indice] = nil
        end

        return Alternador
    end

