            Parent = Suporte,
        })

        local Caixa = Novo("TextBox", {
            AnchorPoint = Vector2.new(0, 1),
            BackgroundColor3 = "MainColor",
            ClearTextOnFocus = not Entrada_2.Disabled and Entrada_2.ClearTextOnFocus,
            PlaceholderText = Entrada_2.Placeholder,
            Position = UDim2.fromScale(0, 1),
            Size = UDim2.new(1, 0, 0, 21),
            Text = Entrada_2.Value,
            TextEditable = not Entrada_2.Disabled,
            TextScaled = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = Suporte,
        })

        Novo("UIPadding", {
            PaddingBottom = UDim.new(0, 3),
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 8),
            PaddingTop = UDim.new(0, 4),
            Parent = Caixa,
        })

        local CaixaBorda = Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = Caixa,
        })

        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Caixa,
            })
        )

        function Entrada_2:UpdateColors()
            if Library.Unloaded then
                return
            end

            Rotulo.TextTransparency = Entrada_2.Disabled and 0.8 or 0
            Caixa.TextTransparency = Entrada_2.Disabled and 0.8 or 0
            CaixaBorda.Transparency = Entrada_2.Disabled and 0.5 or 0

            Caixa.BackgroundColor3 = Entrada_2.Disabled and Library.Scheme.BackgroundColor or Library.Scheme.MainColor
            Library.Registry[Caixa].BackgroundColor3 = Entrada_2.Disabled and "BackgroundColor" or "MainColor"
        end

        function Entrada_2:OnChanged(Funcao)
            Entrada_2.Changed = Funcao
        end

        function Entrada_2:RunChanged()
            if Entrada_2.Disabled then
                return
            end

            Library:SafeCallback(Entrada_2.Callback, Entrada_2.Value)
            Library:SafeCallback(Entrada_2.Changed, Entrada_2.Value)
        end

        function Entrada_2:SetValue(Texto_2)
            if not Entrada_2.AllowEmpty and Aparar(Texto_2) == "" then
                Texto_2 = Entrada_2.EmptyReset
            end

            if Info.MaxLength and #Texto_2 > Info.MaxLength then
                Texto_2 = Texto_2:sub(1, Info.MaxLength)
            end

            if Entrada_2.Numeric then
                if #tostring(Texto_2) > 0 and not tonumber(Texto_2) then
                    Texto_2 = Entrada_2.Value
                end
            end

            if typeof(Info.VerifyValue) == "function" and (Texto_2 ~= Entrada_2.EmptyReset and Info.VerifyValue(Texto_2) ~= true) then
                Texto_2 = Entrada_2.EmptyReset
            end

            Entrada_2.Value = Texto_2
            Caixa.Text = Texto_2

            Entrada_2:RunChanged()
        end

        function Entrada_2:SetDisabled(Desativado: boolean)
            Entrada_2.Disabled = Desativado

            if Entrada_2.TooltipTable then
                Entrada_2.TooltipTable.Disabled = Entrada_2.Disabled
            end

            Caixa.ClearTextOnFocus = not Entrada_2.Disabled and Entrada_2.ClearTextOnFocus
            Caixa.TextEditable = not Entrada_2.Disabled
            Entrada_2:UpdateColors()
        end

        function Entrada_2:SetVisible(Visivel: boolean)
            Entrada_2.Visible = Visivel

            Suporte.Visible = Entrada_2.Visible
            CaixaGrupo:Resize()
        end

        function Entrada_2:SetText(Texto_2: string)
            Entrada_2.Text = Texto_2
            Rotulo.Text = Texto_2
        end

        if Entrada_2.Finished then
            table.insert(Entrada_2.Connections, Caixa.FocusLost:Connect(function(Enter)
                if not Enter then
                    if Entrada_2.ClearTextOnBlur then
                        Caixa.Text = Entrada_2.Value
                    end

                    return
                end

                Entrada_2:SetValue(Caixa.Text)
            end))
        else
            table.insert(Entrada_2.Connections, Caixa:GetPropertyChangedSignal("Text"):Connect(function()
                if Caixa.Text == Entrada_2.Value then return end

                Entrada_2:SetValue(Caixa.Text)
            end))
        end

        table.insert(Entrada_2.Connections, Caixa.Focused:Connect(function()
            if Entrada_2.Disabled then
                return
            end

            Library.Registry[CaixaBorda].Color = "AccentColor"
            TweenService:Create(CaixaBorda, Library.TweenInfo, {
                Color = Library.Scheme.AccentColor,
            }):Play()
        end))

        table.insert(Entrada_2.Connections, Caixa.FocusLost:Connect(function()
            if Entrada_2.Disabled then
                return
            end

            Library.Registry[CaixaBorda].Color = "OutlineColor"
            TweenService:Create(CaixaBorda, Library.TweenInfo, {
                Color = Library.Scheme.OutlineColor,
            }):Play()
        end))

        if typeof(Entrada_2.Tooltip) == "string" or typeof(Entrada_2.DisabledTooltip) == "string" then
            Entrada_2.TooltipTable = Library:AddTooltip(Entrada_2.Tooltip, Entrada_2.DisabledTooltip, Caixa)
            Entrada_2.TooltipTable.Disabled = Entrada_2.Disabled
        end

        CaixaGrupo:Resize()

        Entrada_2.Holder = Suporte
        table.insert(CaixaGrupo.Elements, Entrada_2)

        Entrada_2.Default = Entrada_2.Value
        if typeof(Info.VerifyValue) == "function" and (Entrada_2.Default ~= Entrada_2.EmptyReset and Info.VerifyValue(Entrada_2.Default) ~= true) then
            Entrada_2:SetValue(Entrada_2.EmptyReset)
            Entrada_2.Default = Entrada_2.EmptyReset
        end

        Entrada_2:UpdateColors()
        Opcoes[Indice] = Entrada_2

        function Entrada_2:Destroy()
            Entrada_2.Destroyed = true

            if Entrada_2.Connections then
                for _, Conexao in Entrada_2.Connections do
                    Conexao:Disconnect()
                end
            end

            if Entrada_2.TooltipTable then
                Entrada_2.TooltipTable:Destroy()
            end

            if Suporte then
                Suporte:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, Entrada_2)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
            Opcoes[Indice] = nil
        end

        return Entrada_2
    end

    function Funcoes:AddSlider(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.Slider)

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local ControleDeslizante = {
            Connections = {},
            Destroyed = false,

            Text = Info.Text,
            Value = Info.Default,

            Min = Info.Min,
            Max = Info.Max,

            Prefix = Info.Prefix,
            Suffix = Info.Suffix,
            Compact = Info.Compact,
            Rounding = Info.Rounding,
            HideMax = Info.HideMax,

            Tooltip = Info.Tooltip,
            DisabledTooltip = Info.DisabledTooltip,
            TooltipTable = nil,

            Callback = Info.Callback,
            Changed = Info.Changed,

            Disabled = Info.Disabled,
            Visible = Info.Visible,

            AllowRightClickInput = Info.AllowRightClickInput,

            Type = "Slider",
        }

        local Suporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, Info.Compact and 15 or 33),
            Visible = ControleDeslizante.Visible,
            Parent = Conteiner,
        })

        local ControleDeslizanteRotulo
        if not Info.Compact then
            ControleDeslizanteRotulo = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 14),
                Text = ControleDeslizante.Text,
                TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Suporte,
            })
        end

        local Barra = Novo("TextButton", {
            Active = not ControleDeslizante.Disabled,
            AnchorPoint = Vector2.new(0, 1),
            BackgroundColor3 = "MainColor",
            Position = UDim2.fromScale(0, 1),
            Size = UDim2.new(1, 0, 0, 15),
            Text = "",
            Parent = Suporte,
        })

        Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = Barra,
        })

        local ExibicaoRotulo = Novo("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Text = "",
            TextSize = 14,
            ZIndex = Barra.ZIndex + 2,
            Parent = Barra,
        })
        Novo("UIStroke", {
            ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
            Color = "DarkColor",
            LineJoinMode = Enum.LineJoinMode.Miter,
            Parent = ExibicaoRotulo,
        })

        local EntradaTextoCaixa
        local EntradaTextoCaixaBorda
        if Info.AllowRightClickInput then
            EntradaTextoCaixa = Novo("TextBox", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                TextSize = 14,
                ZIndex = Barra.ZIndex + 3,
                Visible = false,
                ClearTextOnFocus = false,
                Parent = Barra,
            })
            EntradaTextoCaixaBorda = Novo("UIStroke", {
                ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
                Color = "DarkColor",
                LineJoinMode = Enum.LineJoinMode.Miter,
                Parent = EntradaTextoCaixa,
            })
        end

        local Preenchimento = Novo("Frame", {
            BackgroundColor3 = "AccentColor",
            Size = UDim2.fromScale(0.5, 1),
            ZIndex = Barra.ZIndex + 1,
            Parent = Barra,
        })

        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Barra,
            })
        )

        table.insert(
            Library.Corners,
            Novo("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Preenchimento,
            })
        )

        function ControleDeslizante:UpdateColors()
            if Library.Unloaded then
                return
            end

            if ControleDeslizanteRotulo then
                ControleDeslizanteRotulo.TextTransparency = ControleDeslizante.Disabled and 0.8 or 0
            end
            ExibicaoRotulo.TextTransparency = ControleDeslizante.Disabled and 0.8 or 0

            if Info.AllowRightClickInput then
                EntradaTextoCaixa.TextTransparency = ControleDeslizante.Disabled and 0.8 or 0
            end

            Preenchimento.BackgroundColor3 = ControleDeslizante.Disabled and Library.Scheme.OutlineColor or Library.Scheme.AccentColor
            Library.Registry[Preenchimento].BackgroundColor3 = ControleDeslizante.Disabled and "OutlineColor" or "AccentColor"
        end

        function ControleDeslizante:Display()
            if Library.Unloaded then
                return
            end

            local PersonalizadoExibicaoTexto = nil
            if Info.FormatDisplayValue then
                PersonalizadoExibicaoTexto = Info.FormatDisplayValue(ControleDeslizante, ControleDeslizante.Value)
            end

            if PersonalizadoExibicaoTexto then
                ExibicaoRotulo.Text = tostring(PersonalizadoExibicaoTexto)
            else
                if Info.Compact then
                    ExibicaoRotulo.Text =
                        string.format("%s: %s%s%s", ControleDeslizante.Text, ControleDeslizante.Prefix, ControleDeslizante.Value, ControleDeslizante.Suffix)
                elseif Info.HideMax then
                    ExibicaoRotulo.Text = string.format("%s%s%s", ControleDeslizante.Prefix, ControleDeslizante.Value, ControleDeslizante.Suffix)
                else
                    ExibicaoRotulo.Text = string.format(
                        "%s%s%s/%s%s%s",
                        ControleDeslizante.Prefix,
                        ControleDeslizante.Value,
                        ControleDeslizante.Suffix,
                        ControleDeslizante.Prefix,
                        ControleDeslizante.Max,
                        ControleDeslizante.Suffix
                    )
                end
            end

            local X = (ControleDeslizante.Value - ControleDeslizante.Min) / (ControleDeslizante.Max - ControleDeslizante.Min)
            Preenchimento.Size = UDim2.fromScale(X, 1)
        end

        function ControleDeslizante:OnChanged(Funcao)
            ControleDeslizante.Changed = Funcao
        end

        function ControleDeslizante:SetMax(Valor)
            assert(Valor > ControleDeslizante.Min, "Max value cannot be less than the current min value.")

            ControleDeslizante:SetValue(math.clamp(ControleDeslizante.Value, ControleDeslizante.Min, Valor))
            ControleDeslizante.Max = Valor
            ControleDeslizante:Display()
        end

        function ControleDeslizante:SetMin(Valor)
            assert(Valor < ControleDeslizante.Max, "Min value cannot be greater than the current max value.")

            ControleDeslizante:SetValue(math.clamp(ControleDeslizante.Value, Valor, ControleDeslizante.Max))
            ControleDeslizante.Min = Valor
            ControleDeslizante:Display()
        end

        function ControleDeslizante:RunChanged()
            if ControleDeslizante.Disabled then
                return
            end

            Library:SafeCallback(ControleDeslizante.Callback, ControleDeslizante.Value)
            Library:SafeCallback(ControleDeslizante.Changed, ControleDeslizante.Value)
        end

        function ControleDeslizante:SetValue(Texto)
            local Numero = tonumber(Texto)
            if not Numero or Numero == ControleDeslizante.Value then
                return
            end

            Numero = math.clamp(Numero, ControleDeslizante.Min, ControleDeslizante.Max)

            ControleDeslizante.Value = Numero
            ControleDeslizante:Display()

            ControleDeslizante:RunChanged()
        end

        function ControleDeslizante:SetDisabled(Desativado: boolean)
            ControleDeslizante.Disabled = Desativado

            if ControleDeslizante.TooltipTable then
                ControleDeslizante.TooltipTable.Disabled = ControleDeslizante.Disabled
            end

            Barra.Active = not ControleDeslizante.Disabled
            ControleDeslizante:UpdateColors()
        end

        function ControleDeslizante:SetVisible(Visivel: boolean)
            ControleDeslizante.Visible = Visivel

            Suporte.Visible = ControleDeslizante.Visible
            CaixaGrupo:Resize()
        end

        function ControleDeslizante:SetText(Texto_2: string)
            ControleDeslizante.Text = Texto_2
            if ControleDeslizanteRotulo then
                ControleDeslizanteRotulo.Text = Texto_2
                return
            end
            ControleDeslizante:Display()
        end

        function ControleDeslizante:SetPrefix(Prefixo: string)
            ControleDeslizante.Prefix = Prefixo
            ControleDeslizante:Display()
        end

        function ControleDeslizante:SetSuffix(Sufixo: string)
            ControleDeslizante.Suffix = Sufixo
            ControleDeslizante:Display()
        end

        if Info.AllowRightClickInput then
            local UltimoValidoTexto = ""
            table.insert(ControleDeslizante.Connections, EntradaTextoCaixa:GetPropertyChangedSignal("Text"):Connect(function()
                local Texto_2 = EntradaTextoCaixa.Text
                local ComoNumero = tonumber(Texto_2)

                if #tostring(Texto_2) > 0 and not ComoNumero and Texto_2 ~= "-" then
                    EntradaTextoCaixa.Text = UltimoValidoTexto
                else
                    if ControleDeslizante.Rounding == 0 and Texto_2:find("%.") then
                        EntradaTextoCaixa.Text = UltimoValidoTexto
                        return
                    end

                    local DecimalPos = Texto_2:find("%.")
                    if DecimalPos and ControleDeslizante.Rounding > 0 then
                        local Decimais = #Texto_2 - DecimalPos
                        if Decimais > ControleDeslizante.Rounding then
                            EntradaTextoCaixa.Text = UltimoValidoTexto
                            return
                        end
                    end

                    UltimoValidoTexto = Texto_2

                    if ComoNumero then
                        if ComoNumero > ControleDeslizante.Max then
                            EntradaTextoCaixa.Text = tostring(ControleDeslizante.Max)
                        elseif ComoNumero < ControleDeslizante.Min then
                            EntradaTextoCaixa.Text = tostring(ControleDeslizante.Min)
                        end
                    end
                end
            end))

            table.insert(ControleDeslizante.Connections, EntradaTextoCaixa.FocusLost:Connect(function()
                EntradaTextoCaixa.Visible = false
                ExibicaoRotulo.Visible = true

                local Numero = tonumber(EntradaTextoCaixa.Text)
                if not Numero then
                    return
                end

                Numero = Arredondar(Numero, ControleDeslizante.Rounding)
                ControleDeslizante:SetValue(Numero)
            end))

            table.insert(ControleDeslizante.Connections, EntradaTextoCaixa.Focused:Connect(function()
                if ControleDeslizante.Disabled then
                    return
                end

                Library.Registry[EntradaTextoCaixaBorda].Color = "AccentColor"
                TweenService:Create(EntradaTextoCaixaBorda, Library.TweenInfo, {
                    Color = Library.Scheme.AccentColor,
                }):Play()
            end))

            table.insert(ControleDeslizante.Connections, EntradaTextoCaixa.FocusLost:Connect(function()
                if ControleDeslizante.Disabled then
                    return
                end

                Library.Registry[EntradaTextoCaixaBorda].Color = "DarkColor"
                TweenService:Create(EntradaTextoCaixaBorda, Library.TweenInfo, {
                    Color = Library.Scheme.DarkColor,
                }):Play()
            end))
        end

        local UltimoToque = 0
        table.insert(ControleDeslizante.Connections, Barra.InputBegan:Connect(function(Entrada_2: InputObject)
            local ValidoEntrada = EhCliqueEntrada(Entrada_2) or Entrada_2.UserInputType == Enum.UserInputType.MouseButton2
            if not ValidoEntrada or ControleDeslizante.Disabled then
                return
            end

            if Info.AllowRightClickInput then
                local EhDireitaClique = Entrada_2.UserInputType == Enum.UserInputType.MouseButton2
                local EhDuploToque = false

                if Library.IsMobile and Entrada_2.UserInputType == Enum.UserInputType.Touch then
                    if tick() - UltimoToque < 0.3 then
                        EhDuploToque = true
                    end

                    UltimoToque = tick()
                end

                if EhDireitaClique or EhDuploToque then
                    EntradaTextoCaixa.Text = tostring(ControleDeslizante.Value)
                    EntradaTextoCaixa.Visible = true
                    ExibicaoRotulo.Visible = false

                    task.spawn(EntradaTextoCaixa.CaptureFocus, EntradaTextoCaixa)
                    return
                end
            end

            if not EhCliqueEntrada(Entrada_2) then
                return
            end

            if Library.ActiveTab then
                for _, Lado in Library.ActiveTab.Sides do
                    Lado.ScrollingEnabled = false
                end
            end

            if Library.ActiveLoading and Library.ActiveLoading.Sidebar then
                Library.ActiveLoading.Sidebar.Container.ScrollingEnabled = false
            end

            while EhArrastarEntrada(Entrada_2) and not ControleDeslizante.Destroyed do
                local Localizacao = Mouse.X
                local Escala = math.clamp((Localizacao - Barra.AbsolutePosition.X) / Barra.AbsoluteSize.X, 0, 1)

                local AntigoValor = ControleDeslizante.Value
                ControleDeslizante.Value = Arredondar(ControleDeslizante.Min + ((ControleDeslizante.Max - ControleDeslizante.Min) * Escala), ControleDeslizante.Rounding)

                ControleDeslizante:Display()
                if ControleDeslizante.Value ~= AntigoValor then
                    ControleDeslizante:RunChanged()
                end

                RunService.RenderStepped:Wait()
            end

            if Library.ActiveTab then
                for _, Lado in Library.ActiveTab.Sides do
                    Lado.ScrollingEnabled = true
                end
            end

            if Library.ActiveLoading and Library.ActiveLoading.Sidebar then
                Library.ActiveLoading.Sidebar.Container.ScrollingEnabled = true
            end
        end))

        if typeof(ControleDeslizante.Tooltip) == "string" or typeof(ControleDeslizante.DisabledTooltip) == "string" then
            ControleDeslizante.TooltipTable = Library:AddTooltip(ControleDeslizante.Tooltip, ControleDeslizante.DisabledTooltip, Barra)
            ControleDeslizante.TooltipTable.Disabled = ControleDeslizante.Disabled
        end

        ControleDeslizante:UpdateColors()
        ControleDeslizante:Display()
        CaixaGrupo:Resize()

        ControleDeslizante.Holder = Suporte
        table.insert(CaixaGrupo.Elements, ControleDeslizante)

        ControleDeslizante.Default = ControleDeslizante.Value

        Opcoes[Indice] = ControleDeslizante

        function ControleDeslizante:Destroy()
            ControleDeslizante.Destroyed = true

            if ControleDeslizante.Connections then
                for _, Conexao in ControleDeslizante.Connections do
                    Conexao:Disconnect()
                end
            end

            if ControleDeslizante.TooltipTable then
                ControleDeslizante.TooltipTable:Destroy()
            end

            if Suporte then
                Suporte:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, ControleDeslizante)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
            Opcoes[Indice] = nil
        end

        return ControleDeslizante
    end

    function Funcoes:AddDropdown(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.Dropdown)
        do
            local fmtExibicaoOrig = Info.FormatDisplayValue
            Info.FormatDisplayValue = function(v)
                local r = fmtExibicaoOrig and fmtExibicaoOrig(v) or v
                return PTBR_OPCOES_DROPDOWN[tostring(r)] or r
            end
            local fmtListaOrig = Info.FormatListValue
            Info.FormatListValue = function(v)
                local r = fmtListaOrig and fmtListaOrig(v) or v
                return PTBR_OPCOES_DROPDOWN[tostring(r)] or r
            end
        end

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        if Info.SpecialType == "Player" then
            Info.Values = ObterJogadores(Info.ExcludeLocalPlayer)
            Info.AllowNull = true
        elseif Info.SpecialType == "Team" then
            Info.Values = ObterEquipes()
            Info.AllowNull = true
        end

        local Seletor = {
            Connections = {},
            Destroyed = false,

            Text = typeof(Info.Text) == "string" and Info.Text or nil,

            Value = Info.Multi and {} or nil,
            Values = Info.Values,
            DisabledValues = Info.DisabledValues,
            ValueImages = Info.ValueImages,

            Multi = Info.Multi,
            DragSelect = Info.Multi and not Library.IsMobile and Info.DragSelect == true,
            KeepDisabledValuePosition = Info.KeepDisabledValuePosition == true,

            SpecialType = Info.SpecialType,
            ExcludeLocalPlayer = Info.ExcludeLocalPlayer,
            EnablePlayerImages = Info.EnablePlayerImages,

            Tooltip = Info.Tooltip,
            DisabledTooltip = Info.DisabledTooltip,
            TooltipTable = nil,

            Callback = Info.Callback,
            Changed = Info.Changed,

            Disabled = Info.Disabled,
            Visible = Info.Visible,

            Type = "Dropdown",
        }

        local Suporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, Seletor.Text and 39 or 21),
            Visible = Seletor.Visible,
            Parent = Conteiner,
        })

        local Rotulo = Novo("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 14),
            Text = Seletor.Text,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            Visible = not not Info.Text,
            ZIndex = 3,
            Parent = Suporte,
        })

        local ExibicaoConteiner = Novo("TextButton", {
            AnchorPoint = Vector2.new(0, 1),
            BackgroundColor3 = "MainColor",
            Position = UDim2.fromScale(0, 1),
            Size = UDim2.new(1, 0, 0, 21),
            Text = "",
            TextTransparency = 1,
            ZIndex = 2,
            Parent = Suporte,
        })

        Novo("UIPadding", {
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 4),
            Parent = ExibicaoConteiner,
        })

        local ExibicaoBorda = Novo("UIStroke", {
            Color = "OutlineColor",
            Parent = ExibicaoConteiner,
        })

        local SeletorCanto = Novo("UICorner", {
            TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
            BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
            Parent = ExibicaoConteiner,
        }); table.insert(Library.SpecificCorners, SeletorCanto)

        local ExibicaoImagem = Novo("ImageLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(-4, 3),
            Size = UDim2.fromOffset(16, 16),
            Image = "",
            ImageTransparency = 1,
            ZIndex = 2,
            Parent = ExibicaoConteiner,
        })

        local ExibicaoBotao = Novo("TextButton", {
            Active = not Seletor.Disabled,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 21),
            Text = "---",
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 2,
            Parent = ExibicaoConteiner,
        })

        local SetaImagem = Novo("ImageLabel", {
            AnchorPoint = Vector2.new(1, 0.5),
            ImageColor3 = "FontColor",
            ImageTransparency = 0.5,
            Position = UDim2.fromScale(1, 0.5),
            Size = UDim2.fromOffset(16, 16),
            Parent = ExibicaoConteiner,
        })
        if SetaIcone then
            Library:ApplyLucideIcon(SetaImagem, SetaIcone)
        end

        local PesquisaCaixa
        if Info.Searchable then
            PesquisaCaixa = Novo("TextBox", {
                BackgroundTransparency = 1,
                PlaceholderText = "Pesquisar...",
                Position = UDim2.fromOffset(-8, 0),
                Size = UDim2.new(1, -12, 1, 0),
                TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left,
                Visible = false,
                Parent = ExibicaoBotao,
            })
            Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                Parent = PesquisaCaixa,
            })

            table.insert(Seletor.Connections, PesquisaCaixa.Focused:Connect(function()
                Library.Registry[ExibicaoBorda].Color = "AccentColor"
                TweenService:Create(ExibicaoBorda, Library.TweenInfo, {
                    Color = Library.Scheme.AccentColor,
                }):Play()
            end))

            table.insert(Seletor.Connections, PesquisaCaixa.FocusLost:Connect(function()
                Library.Registry[ExibicaoBorda].Color = "OutlineColor"
                TweenService:Create(ExibicaoBorda, Library.TweenInfo, {
                    Color = Library.Scheme.OutlineColor,
                }):Play()
            end))
        end

        local ObterValorImagem = function(Valor, BrutoValor)
            if not Valor then
                return nil
            end

            local ValorImagem = nil
            if Seletor.SpecialType == "Player" and Seletor.EnablePlayerImages == true then
                local JogadorValor = Valor
                if typeof(JogadorValor) ~= "Instance" and BrutoValor ~= nil then
                    JogadorValor = BrutoValor
                end

                if typeof(JogadorValor) == "Instance" and JogadorValor:IsA("Player") then
                    ValorImagem = { Url = string.format("rbxthumb://type=AvatarHeadShot&id=%s&w=48&h=48", tostring(JogadorValor.UserId)) }
                end
            end

            if Seletor.ValueImages then
                local IconeRef = Seletor.ValueImages[Valor]
                if IconeRef == nil and BrutoValor ~= nil then
                    IconeRef = Seletor.ValueImages[BrutoValor]
                end

                if IconeRef then
                    ValorImagem = Library:GetCustomIcon(IconeRef)
                end
            end

            return ValorImagem
        end

        local MenuTabela
        MenuTabela = Library:AddContextMenu(
            ExibicaoConteiner,
            function()
                return UDim2.fromOffset((ExibicaoConteiner.AbsoluteSize.X / Library.DPIScale), 0)
            end,
            function()
                return { 0.5, ExibicaoConteiner.AbsoluteSize.Y + 1.5 }
            end,
            2,
            function(Active: boolean)
                ExibicaoBotao.TextTransparency = (Active and PesquisaCaixa) and 1 or 0

                SetaImagem.ImageTransparency = Active and 0 or 0.5
                SetaImagem.Rotation = Active and 180 or 0

                if PesquisaCaixa then
                    PesquisaCaixa.Text = ""
                    PesquisaCaixa.Visible = Active
                end

                local Metade = UDim.new(0, Library.CornerRadius / 2)
                local Zero = UDim.new(0, 0)

                SeletorCanto.TopLeftRadius = Metade
                SeletorCanto.TopRightRadius = Metade
                SeletorCanto.BottomRightRadius = Active and Zero or Metade
                SeletorCanto.BottomLeftRadius = Active and Zero or Metade

                local MenuCanto = MenuTabela and MenuTabela.Corner
                if MenuCanto then
                    MenuCanto.TopLeftRadius = Zero
                    MenuCanto.TopRightRadius = Zero
                    MenuCanto.BottomRightRadius = Metade
                    MenuCanto.BottomLeftRadius = Metade
                end
            end,
            false,
            "bottom",
            "Dropdown"
        )
        Seletor.Menu = MenuTabela

        local ItemAltura = 21
        local PoolTamanho = math.max(1, Info.MaxVisibleDropdownItems + 2)
        local Pool = {}
        local FiltradoEntradas = {}

        function Seletor:RecalculateListSize(Contagem)
            local ItemContagem = Contagem or #FiltradoEntradas
            local Y = math.clamp(ItemContagem * ItemAltura, 0, Info.MaxVisibleDropdownItems * ItemAltura)

            MenuTabela.Menu.CanvasSize = UDim2.fromOffset(0, ItemContagem * ItemAltura)

            MenuTabela:SetSize(function()
                return UDim2.fromOffset((ExibicaoConteiner.AbsoluteSize.X / Library.DPIScale), Y)
            end)
        end

        function Seletor:UpdateColors()
            if Library.Unloaded then
                return
            end

            Rotulo.TextTransparency = Seletor.Disabled and 0.8 or 0
            ExibicaoBotao.TextTransparency = Seletor.Disabled and 0.8 or 0
            ExibicaoImagem.ImageTransparency = Seletor.Disabled and 0.8 or 0
            SetaImagem.ImageTransparency = Seletor.Disabled and 0.8 or MenuTabela.Active and 0 or 0.5
        end

        function Seletor:Display()
            if Library.Unloaded then
                return
            end

            local Texto = ""
            local ValorImagem = nil
            local EhDicionario = not EhSequencialVetor(Seletor.Values)

            if Info.Multi then
                for Tecla, BrutoValor in Seletor.Values do
                    local Valor = EhDicionario and Tecla or BrutoValor

                    if Seletor.Value[Valor] then
                        if not ValorImagem then
                            ValorImagem = ObterValorImagem(Valor, BrutoValor)
                        end

                        Texto = Texto
                            .. (Info.FormatDisplayValue and tostring(Info.FormatDisplayValue(BrutoValor)) or tostring(BrutoValor))
                            .. ", "
                    end
                end

                Texto = Texto:sub(1, #Texto - 2)
            else
                local ExibicaoValor = Seletor.Value
                if EhDicionario and Seletor.Value ~= nil then
                    ExibicaoValor = Seletor.Values[Seletor.Value]
                end

                ValorImagem = ObterValorImagem(Seletor.Value, ExibicaoValor)
                Texto = ExibicaoValor and tostring(ExibicaoValor) or ""

                if Texto ~= "" and Info.FormatDisplayValue then
                    Texto = tostring(Info.FormatDisplayValue(Texto))
                end
            end

            if #Texto > 25 then
                Texto = Texto:sub(1, 22) .. "..."
            end

            ExibicaoBotao.Text = (Texto == "" and "---" or Texto)

            if ValorImagem then
                Library:ApplyLucideIcon(ExibicaoImagem, ValorImagem)
                ExibicaoImagem.ImageTransparency = 0
            else
                ExibicaoImagem.Image = ""
                ExibicaoImagem.ImageTransparency = 1
            end

            ExibicaoBotao.Size = ValorImagem and UDim2.new(1, -8, 0, 21) or UDim2.new(1, 0, 0, 21)
            ExibicaoBotao.Position = ValorImagem and UDim2.fromOffset(14, 0) or UDim2.fromOffset(0, 0)
        end

        function Seletor:OnChanged(Funcao)
            Seletor.Changed = Funcao
        end

        function Seletor:GetActiveValues(RetornoContagem)
            local Tabela = {}

            if Info.Multi then
                for Valor, _ in Seletor.Value do
                    table.insert(Tabela, Valor)
                end
            else
                if Seletor.Value then
                    table.insert(Tabela, Seletor.Value)
                end
            end

            return RetornoContagem == true and ObterTabelaTamanho(Tabela) or Tabela
        end

        local ArrastarSelecionando = false
        local ArrastarInicioIndice = nil
        local ArrastarAnteriorMin = nil
        local ArrastarAnteriorMax = nil
        local ArrastarUltimoIndice = nil
        local ArrastarInicialValores = {}
        local ArrastarEntradaFinalizadoConexao = nil
        local ArrastarEntradaAlteradoConexao = nil

        local function RecalcularFiltradoEntradas()
            local Valores = Seletor.Values
            local DesativadoValores = Seletor.DisabledValues
            local EhDicionario = not EhSequencialVetor(Valores)

            local PesquisaConsulta = PesquisaCaixa and NormalizarPesquisa(PesquisaCaixa.Text:lower()) or ""
            local EhPesquisando = PesquisaConsulta ~= ""

            local AtivadoLista, DesativadoLista = {}, {}
            local Pendente = {}

            for Tecla, BrutoValor in Valores do
                local Valor = EhDicionario and Tecla or BrutoValor

                local FormatadoValor = tostring(Info.FormatListValue and Info.FormatListValue(BrutoValor) or BrutoValor)

                local CorrespondenciaPontuacao = 0
                if EhPesquisando then
                    local Correspondeu, Pontuacao = AproximadoPontuacao(FormatadoValor:lower(), PesquisaConsulta)
                    if not Correspondeu then
                        continue
                    end
                    CorrespondenciaPontuacao = Pontuacao
                end

                local EhDesativado = table.find(DesativadoValores, Valor) ~= nil
                    or (BrutoValor ~= nil and BrutoValor ~= Valor and table.find(DesativadoValores, BrutoValor) ~= nil)

                local Entrada = {
                    Value = Valor,
                    RawValue = BrutoValor,
                    FormattedValue = FormatadoValor,
                    IsDisabled = EhDesativado,
                    ValueImage = ObterValorImagem(Valor, BrutoValor),
                    SortKey = Tecla,
                    MatchScore = CorrespondenciaPontuacao,
                    Order = #Pendente + 1,
                }

                table.insert(Pendente, Entrada)
            end

            if EhPesquisando then
                
                table.sort(Pendente, function(A, B)
                    if A.MatchScore ~= B.MatchScore then
                        return A.MatchScore > B.MatchScore
                    end
                    return A.Order < B.Order
                end)
            elseif not EhDicionario then
                table.sort(Pendente, function(A, B)
                    return A.SortKey < B.SortKey
                end)
            end

            table.clear(FiltradoEntradas)

            if Seletor.KeepDisabledValuePosition then
                for _, Entrada in Pendente do
                    table.insert(FiltradoEntradas, Entrada)
                end
                return
            end

            for _, Entrada in Pendente do
                if Entrada.IsDisabled then
                    table.insert(DesativadoLista, Entrada)
                else
                    table.insert(AtivadoLista, Entrada)
                end
            end

            for _, Entrada in AtivadoLista do
                table.insert(FiltradoEntradas, Entrada)
            end
            for _, Entrada in DesativadoLista do
                table.insert(FiltradoEntradas, Entrada)
            end
        end

        local function ObterPrimeiroVisivelIndice()
            local Total = #FiltradoEntradas
            if Total <= PoolTamanho then
                return 1
            end

            local MaxPrimeiro = Total - PoolTamanho + 1
            local RolagemY = MenuTabela.Menu.CanvasPosition.Y / Library.DPIScale
            local Indice_2 = math.floor(RolagemY / ItemAltura) + 1
            return math.clamp(Indice_2, 1, MaxPrimeiro)
        end

        function Seletor:RefreshPool()
            local Total = #FiltradoEntradas
            local Primeiro = ObterPrimeiroVisivelIndice()

            for VagaIndice, Linha_2 in Pool do
                local DadosIndice = Primeiro + VagaIndice - 1
                local Entrada = FiltradoEntradas[DadosIndice]

                Linha_2.Entry = Entrada
                Linha_2.Index = Entrada and DadosIndice or nil

                if not Entrada then
                    Linha_2.Container.Visible = false
                    continue
                end

                Linha_2.Container.Visible = true
                Linha_2.Container.Position = UDim2.fromOffset(0, (DadosIndice - 1) * ItemAltura)

                local EhUltimo = DadosIndice == Total
                Linha_2.Corner.BottomRightRadius = EhUltimo and UDim.new(0, Library.CornerRadius / 2) or UDim.new(0, 0)
                Linha_2.Corner.BottomLeftRadius = EhUltimo and UDim.new(0, Library.CornerRadius / 2) or UDim.new(0, 0)

                Linha_2.Button.Text = Entrada.FormattedValue

                if Entrada.ValueImage then
                    Linha_2.Image.Visible = true
                    Library:ApplyLucideIcon(Linha_2.Image, Entrada.ValueImage)
                    Linha_2.Button.Size = UDim2.new(1, -18, 0, ItemAltura)
                    Linha_2.Button.Position = UDim2.fromOffset(18, 0)
                else
                    Linha_2.Image.Visible = false
                    Linha_2.Button.Size = UDim2.new(1, 0, 0, ItemAltura)
                    Linha_2.Button.Position = UDim2.fromOffset(0, 0)
                end

                Linha_2:UpdateButton()
            end
        end

        function Seletor:RunChanged()
            if Seletor.Disabled then
                return
            end

            Library:SafeCallback(Seletor.Callback, Seletor.Value)
            Library:SafeCallback(Seletor.Changed, Seletor.Value)
        end

        local function PararArrastarSelecionar()
            ArrastarSelecionando = false
            ArrastarInicioIndice = nil
            ArrastarAnteriorMin = nil
            ArrastarAnteriorMax = nil
            ArrastarUltimoIndice = nil
            table.clear(ArrastarInicialValores)

            if ArrastarEntradaFinalizadoConexao then
                ArrastarEntradaFinalizadoConexao:Disconnect()
                ArrastarEntradaFinalizadoConexao = nil
            end

            if ArrastarEntradaAlteradoConexao then
                ArrastarEntradaAlteradoConexao:Disconnect()
                ArrastarEntradaAlteradoConexao = nil
            end
        end

        local ArrastarAtivoContagem = 0

        local function AplicarArrastarIndice(Indice_2, InRange)
            local Entrada = FiltradoEntradas[Indice_2]
            if not Entrada or Entrada.IsDisabled then
                return
            end

            local Tentar = ArrastarInicialValores[Entrada.Value]
            if InRange then
                Tentar = not Tentar
            end

            local QuerAtivo = Tentar and true or false
            local EhAtivo = Seletor.Value[Entrada.Value] and true or false
            if QuerAtivo == EhAtivo then
                return
            end

            if not QuerAtivo and ArrastarAtivoContagem == 1 and not Info.AllowNull then
                return
            end

            Seletor.Value[Entrada.Value] = QuerAtivo and true or nil
            ArrastarAtivoContagem += QuerAtivo and 1 or -1
        end

        local function AplicarArrastarAlcance(From, To, InRange)
            for Indice_2 = From, To do
                AplicarArrastarIndice(Indice_2, InRange)
            end
        end

        local function AtualizarArrastar(CurrentIndex)
            if CurrentIndex == nil or CurrentIndex == ArrastarUltimoIndice then
                return
            end

            ArrastarUltimoIndice = CurrentIndex

            local Min = math.min(ArrastarInicioIndice, CurrentIndex)
            local Max = math.max(ArrastarInicioIndice, CurrentIndex)
            ArrastarAtivoContagem = Seletor:GetActiveValues(true)

            if ArrastarAnteriorMin == nil then
                AplicarArrastarAlcance(Min, Max, true)
            else
                if ArrastarAnteriorMin < Min then
                    AplicarArrastarAlcance(ArrastarAnteriorMin, Min - 1, false)
                end
                if ArrastarAnteriorMax > Max then
                    AplicarArrastarAlcance(Max + 1, ArrastarAnteriorMax, false)
                end
                if Min < ArrastarAnteriorMin then
                    AplicarArrastarAlcance(Min, ArrastarAnteriorMin - 1, true)
                end
                if Max > ArrastarAnteriorMax then
                    AplicarArrastarAlcance(ArrastarAnteriorMax + 1, Max, true)
                end
            end

            ArrastarAnteriorMin = Min
            ArrastarAnteriorMax = Max

            for _, OutroLinha in Pool do
                OutroLinha:UpdateButton()
            end
        end

        local function CriarPoolLinha()
            local Linha_2 = {
                Entry = nil,
                Index = nil
            }

            local Conteiner = Novo("Frame", {
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, ItemAltura),
                Visible = false,
                Parent = MenuTabela.Menu,
            })

            local Canto = Novo("UICorner", {
                TopLeftRadius = UDim.new(0, 0),
                TopRightRadius = UDim.new(0, 0),
                BottomRightRadius = UDim.new(0, 0),
                BottomLeftRadius = UDim.new(0, 0),
                Parent = Conteiner,
            }); table.insert(Library.SpecificCorners, Canto)

            local Imagem = Novo("ImageLabel", {
                BackgroundTransparency = 1,
                Image = "",
                ImageTransparency = 0.5,
                Size = UDim2.fromOffset(16, 16),
                Position = UDim2.fromOffset(4, 3),
                Visible = false,
                Parent = Conteiner,
            })

            local Botao = Novo("TextButton", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, ItemAltura),
                Text = "",
                TextSize = 14,
                TextTransparency = 0.5,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Conteiner,
            })
            Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 7),
                PaddingRight = UDim.new(0, 7),
                Parent = Botao,
            })

            Linha_2.Container = Conteiner
            Linha_2.Corner = Canto
            Linha_2.Image = Imagem
            Linha_2.Button = Botao

            function Linha_2:UpdateButton()
                local Entrada = Linha_2.Entry
                if not Entrada then
                    return
                end

                local Selecionado
                if Info.Multi then
                    Selecionado = Seletor.Value[Entrada.Value]
                else
                    Selecionado = Seletor.Value == Entrada.Value
                end

                Linha_2.Selected = Selecionado and true or false

                Conteiner.BackgroundTransparency = Selecionado and 0 or 1
                Botao.TextTransparency = Entrada.IsDisabled and 0.8 or Selecionado and 0 or 0.5

                if Entrada.ValueImage then
                    Imagem.ImageTransparency = Entrada.IsDisabled and 0.8 or Selecionado and 0 or 0.5
                end
            end

            table.insert(Seletor.Connections, Botao.MouseButton1Click:Connect(function()
                local Entrada = Linha_2.Entry
                if not Entrada or Entrada.IsDisabled or ArrastarSelecionando then
                    return
                end

                local Selecionado
                if Info.Multi then
                    Selecionado = Seletor.Value[Entrada.Value]
                else
                    Selecionado = Seletor.Value == Entrada.Value
                end

                local Tentar = not Selecionado
                if not (Seletor:GetActiveValues(true) == 1 and not Tentar and not Info.AllowNull) then
                    Selecionado = Tentar
                    if Info.Multi then
                        Seletor.Value[Entrada.Value] = Selecionado and true or nil
                    else
                        Seletor.Value = Selecionado and Entrada.Value or nil
                    end

                    for _, OutroLinha in Pool do
                        OutroLinha:UpdateButton()
                    end
                end

                Linha_2:UpdateButton()
                Seletor:Display()

                Library:UpdateDependencyBoxes()
                Seletor:RunChanged()
            end))

            table.insert(Seletor.Connections, Botao.MouseEnter:Connect(function()
                local Entrada = Linha_2.Entry
                if not Entrada or Entrada.IsDisabled then
                    return
                end

                if Linha_2.Selected then
                    return
                end

                TweenService:Create(Conteiner, Library.TweenInfo, {
                    BackgroundTransparency = 0.85,
                }):Play()
                TweenService:Create(Botao, Library.TweenInfo, {
                    TextTransparency = 0.25,
                }):Play()

                if Imagem then
                    TweenService:Create(Imagem, Library.TweenInfo, {
                        ImageTransparency = 0.25,
                    }):Play()
                end
            end))

            table.insert(Seletor.Connections, Botao.MouseLeave:Connect(function()
                local Entrada = Linha_2.Entry
                if not Entrada or Entrada.IsDisabled then
                    return
                end

                if Linha_2.Selected then
                    return
                end

                TweenService:Create(Conteiner, Library.TweenInfo, {
                    BackgroundTransparency = 1,
                }):Play()
                TweenService:Create(Botao, Library.TweenInfo, {
                    TextTransparency = 0.5,
                }):Play()

                if Imagem then
                    TweenService:Create(Imagem, Library.TweenInfo, {
                        ImageTransparency = 0.5,
                    }):Play()
                end
            end))

            table.insert(Seletor.Connections, Botao.InputBegan:Connect(function(InicioEntrada)
                if not (Info.Multi and Seletor.DragSelect and not Library.IsMobile) then
                    return
                end

                local Entrada = Linha_2.Entry
                if not Entrada or Entrada.IsDisabled then
                    return
                end

                if not EhMouseEntrada(InicioEntrada) then
                    return
                end

                ArrastarSelecionando = true
                ArrastarInicioIndice = Linha_2.Index
                table.clear(ArrastarInicialValores)

                for _, FiltradoEntrada in FiltradoEntradas do
                    ArrastarInicialValores[FiltradoEntrada.Value] = Seletor.Value[FiltradoEntrada.Value]
                end

                AtualizarArrastar(Linha_2.Index)

                if ArrastarEntradaFinalizadoConexao then ArrastarEntradaFinalizadoConexao:Disconnect() end
                if ArrastarEntradaAlteradoConexao then ArrastarEntradaAlteradoConexao:Disconnect() end

                ArrastarEntradaAlteradoConexao = Library:GiveSignal(UserInputService.InputChanged:Connect(function(AlterarEntrada)
                    if not EhMovimentoEntrada(AlterarEntrada) and AlterarEntrada ~= InicioEntrada then
                        return
                    end

                    local Pos = AlterarEntrada.Position
                    for _, OutroLinha in Pool do
                        if OutroLinha.Entry and Library:MouseIsOverFrame(OutroLinha.Button, Pos) then
                            AtualizarArrastar(OutroLinha.Index)
                            break
                        end
                    end
                end))

                ArrastarEntradaFinalizadoConexao = Library:GiveSignal(UserInputService.InputEnded:Connect(function(FimEntrada)
                    if FimEntrada ~= InicioEntrada and not (EhMouseEntrada(FimEntrada) and FimEntrada.UserInputType == InicioEntrada.UserInputType) then
                        return
                    end

                    Seletor:Display()
                    Library:UpdateDependencyBoxes()
                    Seletor:RunChanged()

                    PararArrastarSelecionar()
                end))

                table.insert(Seletor.Connections, ArrastarEntradaFinalizadoConexao)
                table.insert(Seletor.Connections, ArrastarEntradaAlteradoConexao)
            end))

            return Linha_2
        end

        function Seletor:BuildDropdownList()
            PararArrastarSelecionar()

            RecalcularFiltradoEntradas()

            MenuTabela.Menu.CanvasPosition = Vector2.new(0, 0)

            Seletor:RefreshPool()
            Seletor:RecalculateListSize(#FiltradoEntradas)
        end

        for _ = 1, PoolTamanho do
            table.insert(Pool, CriarPoolLinha())
        end

        table.insert(Seletor.Connections, MenuTabela.Menu:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
            Seletor:RefreshPool()
        end))

        local function ValorExiste(Val)
            if EhSequencialVetor(Seletor.Values) then
                for _, Existente in Seletor.Values do
                    if Existente == Val then
                        return true
                    end
                end

                return false
            end

            return Seletor.Values[Val] ~= nil
        end

        function Seletor:SetValue(Valor)
            if Info.Multi then
                if typeof(Valor) == "string" then
                    Valor = if Valor == "" then {} else { [Valor] = true }
                end

                local Tabela = {}

                for Val, Active in Valor or {} do
                    if typeof(Active) ~= "boolean" then
                        Tabela[Active] = true
                    elseif Active and ValorExiste(Val) then
                        Tabela[Val] = true
                    end
                end

                Seletor.Value = Tabela
            else
                if ValorExiste(Valor) then
                    Seletor.Value = Valor
                elseif not Valor then
                    Seletor.Value = nil
                end
            end

            Seletor:Display()
            for _, Linha_2 in Pool do
                Linha_2:UpdateButton()
            end

            if not Seletor.Disabled then
                Library:UpdateDependencyBoxes()
            end

            Seletor:RunChanged()
        end

        function Seletor:SetValues(Valores)
            Seletor.Values = Valores

            local Alterado = false
            if Info.Multi then
                for Val in Seletor.Value do
                    if not ValorExiste(Val) then
                        Seletor.Value[Val] = nil
                        Alterado = true
                    end
                end

            elseif Seletor.Value ~= nil and not ValorExiste(Seletor.Value) then
                Seletor.Value = nil
                Alterado = true
            end

            Seletor:BuildDropdownList()
            Seletor:Display()

            if Alterado and not Seletor.Disabled then
                Library:UpdateDependencyBoxes()
            end

            if Alterado then
                Seletor:RunChanged()
            end
        end

        function Seletor:AddValues(Valores)
            if typeof(Valores) ~= "table" and typeof(Valores) ~= "string" then
                return
            end

            local EhDicionario = not EhSequencialVetor(Seletor.Values)
            if EhDicionario then
                if typeof(Valores) == "string" then
                    Seletor.Values[Valores] = Valores

                elseif EhSequencialVetor(Valores) then
                    for _, Val in Valores do
                        Seletor.Values[Val] = Val
                    end

                else
                    for Tecla, Val in Valores do
                        Seletor.Values[Tecla] = Val
                    end
                end
            else
                if typeof(Valores) == "table" then
                    for _, Val in Valores do
                        table.insert(Seletor.Values, Val)
                    end
                else
                    table.insert(Seletor.Values, Valores)
                end
            end

            Seletor:BuildDropdownList()
        end

        function Seletor:SetDisabledValues(DesativadoValores)
            Seletor.DisabledValues = DesativadoValores
            Seletor:BuildDropdownList()
        end

        function Seletor:AddDisabledValues(DesativadoValores)
            if typeof(DesativadoValores) == "table" then
                for _, val in DesativadoValores do
                    table.insert(Seletor.DisabledValues, val)
                end
            elseif typeof(DesativadoValores) == "string" then
                table.insert(Seletor.DisabledValues, DesativadoValores)
            else
                return
            end

            Seletor:BuildDropdownList()
        end

        function Seletor:SetValueImages(ValorImagens)
            if typeof(ValorImagens) ~= "table" then
                return
            end

            Seletor.ValueImages = ValorImagens
            Seletor:BuildDropdownList()
        end

        function Seletor:AddValueImages(ValorImagens)
            if typeof(ValorImagens) ~= "table" then
                return
            end

            for tecla, val in ValorImagens do
                Seletor.ValueImages[tecla] = val
            end

            Seletor:BuildDropdownList()
        end

        function Seletor:SetDisabled(Desativado: boolean)
            Seletor.Disabled = Desativado

            if Seletor.TooltipTable then
                Seletor.TooltipTable.Disabled = Seletor.Disabled
            end

            MenuTabela:Close()
            ExibicaoBotao.Active = not Seletor.Disabled
            Seletor:UpdateColors()

            Library:UpdateDependencyBoxes()
        end

        function Seletor:SetVisible(Visivel: boolean)
            Seletor.Visible = Visivel

            Suporte.Visible = Seletor.Visible
            CaixaGrupo:Resize()
        end

        function Seletor:SetText(Texto_2: string)
            Seletor.Text = Texto_2
            Suporte.Size = UDim2.new(1, 0, 0, Texto_2 and 39 or 21)

            Rotulo.Text = Texto_2 and Texto_2 or ""
            Rotulo.Visible = not not Texto_2
        end

        function Seletor:SetDragSelect(Valor: boolean)
            if not Info.Multi or Library.IsMobile then
                Valor = false
            end

            Seletor.DragSelect = Valor == true
            Seletor:BuildDropdownList()
        end

        local AlternadorSeletor = function()
            if Seletor.Disabled then
                return
            end

            MenuTabela:Toggle()
        end

        table.insert(Seletor.Connections, ExibicaoConteiner.MouseButton1Click:Connect(AlternadorSeletor))
        table.insert(Seletor.Connections, ExibicaoBotao.MouseButton1Click:Connect(AlternadorSeletor))

        if PesquisaCaixa then
            table.insert(Seletor.Connections, PesquisaCaixa:GetPropertyChangedSignal("Text"):Connect(Seletor.BuildDropdownList))
        end

        local Padroes = (function()
            local Resolvido = {}
            local Padrao = Info.Default
            if Padrao == nil then
                return Resolvido
            end

            local EhDicionario = not EhSequencialVetor(Seletor.Values)
            local function ResolverUm(Candidato)
                if EhDicionario then
                    return Seletor.Values[Candidato] ~= nil and Candidato or nil
                end

                for _, Existente in Seletor.Values do
                    if Existente == Candidato then
                        return Existente
                    end
                end

                return nil
            end

            local PadraoTipo = typeof(Padrao)
            if PadraoTipo == "string" then
                local Valor = ResolverUm(Padrao)
                if Valor ~= nil then
                    table.insert(Resolvido, Valor)
                end

            elseif PadraoTipo == "table" then
                for _, Candidato in Padrao do
                    local Valor = ResolverUm(Candidato)
                    if Valor ~= nil then
                        table.insert(Resolvido, Valor)
                    end
                end

            elseif Seletor.Values[Padrao] ~= nil then
                table.insert(Resolvido, EhDicionario and Padrao or Seletor.Values[Padrao])
            end

            return Resolvido
        end)()

        for _, SelecionarValor in Padroes do
            if Info.Multi then
                Seletor.Value[SelecionarValor] = true
            else
                Seletor.Value = SelecionarValor
                break
            end
        end

        if typeof(Seletor.Tooltip) == "string" or typeof(Seletor.DisabledTooltip) == "string" then
            Seletor.TooltipTable = Library:AddTooltip(Seletor.Tooltip, Seletor.DisabledTooltip, ExibicaoConteiner)
            Seletor.TooltipTable.Disabled = Seletor.Disabled
        end

        Seletor:UpdateColors()
        Seletor:Display()
        Seletor:BuildDropdownList()
        CaixaGrupo:Resize()

        Seletor.Holder = Suporte
        table.insert(CaixaGrupo.Elements, Seletor)

        Seletor.Default = Padroes
        Seletor.DefaultValues = Seletor.Values

        Opcoes[Indice] = Seletor

        function Seletor:Destroy()
            Seletor.Destroyed = true

            PararArrastarSelecionar()

            if Seletor.Connections then
                for _, Conexao in Seletor.Connections do
                    Conexao:Disconnect()
                end
            end

            if Seletor.TooltipTable then
                Seletor.TooltipTable:Destroy()
            end

            if MenuTabela then
                MenuTabela:Destroy()
            end

            if Suporte then
                Suporte:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, Seletor)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
            Opcoes[Indice] = nil
        end

        return Seletor
    end

    function Funcoes:AddViewport(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.Viewport)

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local Arrastando, Pincando = false, false
        local UltimoMousePos, UltimoPincaDist = nil, 0

        local AreaVisaoObjeto = Info.Object
        if Info.Clone and typeof(Info.Object) == "Instance" then
            if Info.Object.Archivable then
                AreaVisaoObjeto = AreaVisaoObjeto:Clone()
            else
                Info.Object.Archivable = true
                AreaVisaoObjeto = AreaVisaoObjeto:Clone()
                Info.Object.Archivable = false
            end
        end

        local AreaVisao = {
            Connections = {},
            Destroyed = false,

            Object = AreaVisaoObjeto :: PVInstance,
            Camera = if not Info.Camera then Instance.new("Camera") else Info.Camera,
            Interactive = Info.Interactive,
            AutoFocus = Info.AutoFocus,
            Visible = Info.Visible,
            Type = "Viewport",
        }

        assert(
            typeof(AreaVisao.Object) == "Instance" and (AreaVisao.Object:IsA("BasePart") or AreaVisao.Object:IsA("Model")),
            "Instance must be a BasePart or Model."
        )

        assert(
            typeof(AreaVisao.Camera) == "Instance" and AreaVisao.Camera:IsA("Camera"),
            "Camera must be a valid Camera instance."
        )

        local function ObterModeloTamanho(model)
            if model:IsA("BasePart") then
                return model.Size
            end

            return select(2, model:GetBoundingBox())
        end

        local function FocoCamera()
            local ModeloTamanho = ObterModeloTamanho(AreaVisao.Object)
            local MaxExtensao = math.max(ModeloTamanho.X, ModeloTamanho.Y, ModeloTamanho.Z)
            local CameraDistancia = MaxExtensao * 2
            local ModeloPosicao = (AreaVisao.Object :: PVInstance):GetPivot().Position

            AreaVisao.Camera.CFrame = CFrame.new(ModeloPosicao + Vector3.new(0, MaxExtensao / 2, CameraDistancia), ModeloPosicao)
        end

        local Suporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, Info.Height),
            Visible = AreaVisao.Visible,
            Parent = Conteiner,
        })

        local Caixa = Novo("Frame", {
            AnchorPoint = Vector2.new(0, 1),
            BackgroundColor3 = "MainColor",
            BorderColor3 = "OutlineColor",
            BorderSizePixel = 1,
            Position = UDim2.fromScale(0, 1),
            Size = UDim2.fromScale(1, 1),
            Parent = Suporte,
        })

        Novo("UIPadding", {
            PaddingBottom = UDim.new(0, 3),
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 8),
            PaddingTop = UDim.new(0, 4),
            Parent = Caixa,
        })

        local ViewportFrame = Novo("ViewportFrame", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Parent = Caixa,
            CurrentCamera = AreaVisao.Camera,
            Active = AreaVisao.Interactive,
        })

        table.insert(AreaVisao.Connections, ViewportFrame.MouseEnter:Connect(function()
            if not AreaVisao.Interactive then
                return
            end

            for _, Lado in CaixaGrupo.Tab.Sides do
                Lado.ScrollingEnabled = false
            end
        end))

        table.insert(AreaVisao.Connections, ViewportFrame.MouseLeave:Connect(function()
            if not AreaVisao.Interactive then
                return
            end

            for _, Lado in CaixaGrupo.Tab.Sides do
                Lado.ScrollingEnabled = true
            end
        end))

        table.insert(AreaVisao.Connections, ViewportFrame.InputBegan:Connect(function(entrada)
            if not AreaVisao.Interactive then
                return
            end

            if entrada.UserInputType == Enum.UserInputType.MouseButton2 or (entrada.UserInputType == Enum.UserInputType.Touch and not Pincando) then
                Arrastando = true
                UltimoMousePos = entrada.Position
            end
        end))

        table.insert(AreaVisao.Connections, UserInputService.InputEnded:Connect(function(entrada)
            if Library.Unloaded then
                return
            end

            if not AreaVisao.Interactive then
                return
            end

            if entrada.UserInputType == Enum.UserInputType.MouseButton2 or entrada.UserInputType == Enum.UserInputType.Touch then
                Arrastando = false
            end
        end))

        table.insert(AreaVisao.Connections, UserInputService.InputChanged:Connect(function(entrada)
            if Library.Unloaded then
                return
            end

            if not AreaVisao.Interactive or not Arrastando or Pincando then
                return
            end

            if
                entrada.UserInputType == Enum.UserInputType.MouseMovement
                or entrada.UserInputType == Enum.UserInputType.Touch
            then
                local MouseDelta = entrada.Position - UltimoMousePos
                UltimoMousePos = entrada.Position

                local Posicao = (AreaVisao.Object :: PVInstance):GetPivot().Position
                local Camera = AreaVisao.Camera

                local RotacaoY = CFrame.fromAxisAngle(Vector3.new(0, 1, 0), -MouseDelta.X * 0.01)
                Camera.CFrame = CFrame.new(Posicao) * RotacaoY * CFrame.new(-Posicao) * Camera.CFrame

                local RotacaoX = CFrame.fromAxisAngle(Camera.CFrame.RightVector, -MouseDelta.Y * 0.01)
                local InclinadoCQuadro = CFrame.new(Posicao) * RotacaoX * CFrame.new(-Posicao) * Camera.CFrame

                if InclinadoCQuadro.UpVector.Y > 0.1 then
                    Camera.CFrame = InclinadoCQuadro
                end
            end
        end))

        table.insert(AreaVisao.Connections, ViewportFrame.InputChanged:Connect(function(entrada)
            if not AreaVisao.Interactive then
                return
            end

            if entrada.UserInputType == Enum.UserInputType.MouseWheel then
                local ZoomQuantidade = entrada.Position.Z * 2
                AreaVisao.Camera.CFrame += AreaVisao.Camera.CFrame.LookVector * ZoomQuantidade
            end
        end))

        table.insert(AreaVisao.Connections, UserInputService.TouchPinch:Connect(function(toquePosicoes, _, _, estado)
            if Library.Unloaded then
                return
            end

            if not AreaVisao.Interactive or not Library:MouseIsOverFrame(ViewportFrame, toquePosicoes[1]) then
                return
            end

            if estado == Enum.UserInputState.Begin then
                Pincando = true
                Arrastando = false
                UltimoPincaDist = (toquePosicoes[1] - toquePosicoes[2]).Magnitude
            elseif estado == Enum.UserInputState.Change then
                local atualDist = (toquePosicoes[1] - toquePosicoes[2]).Magnitude
                local delta = (atualDist - UltimoPincaDist) * 0.1
                UltimoPincaDist = atualDist
                AreaVisao.Camera.CFrame += AreaVisao.Camera.CFrame.LookVector * delta
            elseif estado == Enum.UserInputState.End or estado == Enum.UserInputState.Cancel then
                Pincando = false
            end
        end))

        ;(AreaVisao.Object :: PVInstance).Parent = ViewportFrame
        if AreaVisao.AutoFocus then
            FocoCamera()
        end

        function AreaVisao:SetObject(Objeto: Instance, Clonar: boolean?)
            assert(Objeto, "Object cannot be nil.")

            if Clonar then
                Objeto = Objeto:Clone()
            end

            if AreaVisao.Object then
                AreaVisao.Object:Destroy()
            end

            AreaVisao.Object = Objeto
            ;(AreaVisao.Object :: PVInstance).Parent = ViewportFrame

            CaixaGrupo:Resize()
        end

        function AreaVisao:SetHeight(Altura: number)
            assert(Altura > 0, "Height must be greater than 0.")

            Suporte.Size = UDim2.new(1, 0, 0, Altura)
            CaixaGrupo:Resize()
        end

        function AreaVisao:Focus()
            if not AreaVisao.Object then
                return
            end

            FocoCamera()
        end

        function AreaVisao:SetCamera(Camera: Instance)
            assert(
                Camera and typeof(Camera) == "Instance" and Camera:IsA("Camera"),
                "Camera must be a valid Camera instance."
            )

            AreaVisao.Camera = Camera
            ViewportFrame.CurrentCamera = Camera
        end

        function AreaVisao:SetInteractive(Interativo: boolean)
            AreaVisao.Interactive = Interativo
            ViewportFrame.Active = Interativo
        end

        function AreaVisao:SetVisible(Visivel: boolean)
            AreaVisao.Visible = Visivel

            Suporte.Visible = AreaVisao.Visible
            CaixaGrupo:Resize()
        end

        CaixaGrupo:Resize()

        AreaVisao.Holder = Suporte
        table.insert(CaixaGrupo.Elements, AreaVisao)

        Opcoes[Indice] = AreaVisao

        function AreaVisao:Destroy()
            AreaVisao.Destroyed = true

            if AreaVisao.Connections then
                for _, Conexao in AreaVisao.Connections do
                    Conexao:Disconnect()
                end
            end

            if Suporte then
                Suporte:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, AreaVisao)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
            Opcoes[Indice] = nil
        end

        return AreaVisao
    end

    function Funcoes:AddImage(Indice, Info)
        if self.Destroyed then return nil end

        Info = Library:Validate(Info, Modelos.Image)

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local Imagem = {
            Connections = {},
            Destroyed = false,

            Image = Info.Image,
            Color = Info.Color,
            RectOffset = Info.RectOffset,
            RectSize = Info.RectSize,
            Height = Info.Height,
            ScaleType = Info.ScaleType,
            Transparency = Info.Transparency,
            BackgroundTransparency = Info.BackgroundTransparency,

            Visible = Info.Visible,
            Type = "Image",
        }

        local Suporte = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, Info.Height),
            Visible = Imagem.Visible,
            Parent = Conteiner,
        })

        local Caixa = Novo("Frame", {
            AnchorPoint = Vector2.new(0, 1),
            BackgroundColor3 = "MainColor",
            BorderColor3 = "OutlineColor",
            BorderSizePixel = 1,
            BackgroundTransparency = Imagem.BackgroundTransparency,
            Position = UDim2.fromScale(0, 1),
            Size = UDim2.fromScale(1, 1),
            Parent = Suporte,
        })

        Novo("UIPadding", {
            PaddingBottom = UDim.new(0, 3),
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 8),
            PaddingTop = UDim.new(0, 4),
            Parent = Caixa,
        })

        local ImagemPropriedades = {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            ImageTransparency = Imagem.Transparency,
            ImageColor3 = Imagem.Color,
            ScaleType = Imagem.ScaleType,
            Parent = Caixa,
        }

        local Icon = Library:GetCustomIcon(Imagem.Image)
        assert(Icon, "Image must be a valid Roblox asset or a valid URL or a valid lucide icon.")

        ImagemPropriedades.Image = Icon.Url
        ImagemPropriedades.ImageRectOffset = Icon.ImageRectOffset
        ImagemPropriedades.ImageRectSize = Icon.ImageRectSize

        local ImageLabel = Novo("ImageLabel", ImagemPropriedades)

        function Imagem:SetHeight(Altura: number)
            assert(Altura > 0, "Height must be greater than 0.")

            Imagem.Height = Altura
            Suporte.Size = UDim2.new(1, 0, 0, Altura)
            CaixaGrupo:Resize()
        end

        function Imagem:SetImage(NovoImagem: string)
            assert(typeof(NovoImagem) == "string", "Image must be a string.")

            local Icon = Library:GetCustomIcon(NovoImagem)
            assert(Icon, "Image must be a valid Roblox asset or a valid URL or a valid lucide icon.")

            Imagem.RectOffset = Icon.ImageRectOffset
            Imagem.RectSize = Icon.ImageRectSize

            Library:ApplyLucideIcon(ImageLabel, Icon)
            Imagem.Image = Icon.Url
        end

        function Imagem:SetColor(Cor: Color3)
            assert(typeof(Cor) == "Color3", "Color must be a Color3 value.")

            ImageLabel.ImageColor3 = Cor
            Imagem.Color = Cor
        end

        function Imagem:SetRectOffset(RetanguloDeslocamento: Vector2)
            assert(typeof(RetanguloDeslocamento) == "Vector2", "RectOffset must be a Vector2 value.")

            ImageLabel.ImageRectOffset = RetanguloDeslocamento
            Imagem.RectOffset = RetanguloDeslocamento
        end

        function Imagem:SetRectSize(RetanguloTamanho: Vector2)
            assert(typeof(RetanguloTamanho) == "Vector2", "RectSize must be a Vector2 value.")

            ImageLabel.ImageRectSize = RetanguloTamanho
            Imagem.RectSize = RetanguloTamanho
        end

        function Imagem:SetScaleType(EscalaTipo: Enum.ScaleType)
            assert(
                typeof(EscalaTipo) == "EnumItem" and EscalaTipo:IsA("ScaleType"),
                "ScaleType must be a valid Enum.ScaleType."
            )

            ImageLabel.ScaleType = EscalaTipo
            Imagem.ScaleType = EscalaTipo
        end

        function Imagem:SetTransparency(Transparencia: number)
            assert(typeof(Transparencia) == "number", "Transparency must be a number between 0 and 1.")
            assert(Transparencia >= 0 and Transparencia <= 1, "Transparency must be between 0 and 1.")

            ImageLabel.ImageTransparency = Transparencia
            Imagem.Transparency = Transparencia
        end

        function Imagem:SetVisible(Visivel: boolean)
            Imagem.Visible = Visivel

            Suporte.Visible = Imagem.Visible
            CaixaGrupo:Resize()
        end

        CaixaGrupo:Resize()

        Imagem.Holder = Suporte
        table.insert(CaixaGrupo.Elements, Imagem)

        Opcoes[Indice] = Imagem

        function Imagem:Destroy()
            Imagem.Destroyed = true

            if Suporte then
                Suporte:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.Elements, Imagem)
            if ElemIndice then
                table.remove(CaixaGrupo.Elements, ElemIndice)
            end

            CaixaGrupo:Resize()
            Opcoes[Indice] = nil
        end

        return Imagem
    end

