    function Funcoes:AddDependencyBox()
        if self.Destroyed then return nil end

        local CaixaGrupo = self
        local Conteiner = CaixaGrupo.Container

        local CaixaDepConteiner
        local CaixaDepLista

        do
            CaixaDepConteiner = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Visible = false,
                Parent = Conteiner,
            })

            CaixaDepLista = Novo("UIListLayout", {
                Padding = UDim.new(0, 8),
                Parent = CaixaDepConteiner,
            })
        end

        local CaixaDep = {
            Connections = {},
            Destroyed = false,

            Visible = false,
            Dependencies = {},

            Holder = CaixaDepConteiner,
            Container = CaixaDepConteiner,

            Elements = {},
            DependencyBoxes = {}
        }

        function CaixaDep:Resize()
            CaixaDepConteiner.Size = UDim2.new(1, 0, 0, CaixaDepLista.AbsoluteContentSize.Y / Library.DPIScale)
            CaixaGrupo:Resize()
        end

        function CaixaDep:Update(CancelarPesquisa)
            for _, Dependencia in CaixaDep.Dependencies do
                local Elemento = Dependencia[1]
                local Valor = Dependencia[2]

                if Elemento.Disabled then
                    CaixaDepConteiner.Visible = false
                    CaixaDep.Visible = false
                    return
                end

                if Elemento.Type == "Toggle" and Elemento.Value ~= Valor then
                    CaixaDepConteiner.Visible = false
                    CaixaDep.Visible = false
                    return
                elseif Elemento.Type == "Dropdown" then
                    local correspondeu = false

                    if typeof(Elemento.Value) == "table" then
                        if typeof(Valor) == "table" then
                            for _, Esperado in Valor do
                                if Elemento.Value[Esperado] then
                                    correspondeu = true
                                    break
                                end
                            end
                        elseif Elemento.Value[Valor] then
                            correspondeu = true
                        end
                    elseif Elemento.Value == Valor then
                        correspondeu = true
                    end

                    if not correspondeu then
                        CaixaDepConteiner.Visible = false
                        CaixaDep.Visible = false
                        return
                    end
                end
            end

            CaixaDep.Visible = true
            CaixaDepConteiner.Visible = true
            if not Library.Searching then
                task.defer(function()
                    CaixaDep:Resize()
                end)
            elseif not CancelarPesquisa then
                Library:UpdateSearch(Library.SearchText)
            end
        end

        table.insert(CaixaDep.Connections, CaixaDepLista:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            if not CaixaDep.Visible then
                return
            end

            CaixaDep:Resize()
        end))

        function CaixaDep:SetupDependencies(Dependencias)
            for _, Dependencia in Dependencias do
                assert(typeof(Dependencia) == "table", "Dependency should be a table.")
                assert(Dependencia[1] ~= nil, "Dependency is missing element.")
                assert(Dependencia[2] ~= nil, "Dependency is missing expected value.")
            end

            CaixaDep.Dependencies = Dependencias
            CaixaDep:Update()
        end

        table.insert(CaixaDep.Connections, CaixaDepConteiner:GetPropertyChangedSignal("Visible"):Connect(function()
            CaixaDep:Resize()
        end))

        setmetatable(CaixaDep, BaseCaixaGrupo)

        table.insert(CaixaGrupo.DependencyBoxes, CaixaDep)
        table.insert(Library.DependencyBoxes, CaixaDep)

        function CaixaDep:Destroy()
            CaixaDep.Destroyed = true

            if CaixaDep.Connections then
                for _, Conexao in CaixaDep.Connections do
                    Conexao:Disconnect()
                end
            end

            for _, Elemento in CaixaDep.Elements do
                if Elemento.Destroy then
                    Elemento:Destroy()
                end
            end

            for _, SubCaixaDep in CaixaDep.DependencyBoxes do
                if SubCaixaDep.Destroy then
                    SubCaixaDep:Destroy()
                end
            end

            if CaixaDepConteiner then
                CaixaDepConteiner:Destroy()
            end

            local ElemIndice = table.find(CaixaGrupo.DependencyBoxes, CaixaDep)
            if ElemIndice then
                table.remove(CaixaGrupo.DependencyBoxes, ElemIndice)
            end

            local BibIndice = table.find(Library.DependencyBoxes, CaixaDep)
            if BibIndice then
                table.remove(Library.DependencyBoxes, BibIndice)
            end
        end

        return CaixaDep
    end

    function Funcoes:AddDependencyGroupbox()
        if self.Destroyed then return nil end

        local CaixaGrupo = self
        local Aba = CaixaGrupo.Tab
        local CaixaSuporte = CaixaGrupo.BoxHolder

        local DepCaixaGrupoConteiner
        local DepCaixaGrupoLista

        do
            DepCaixaGrupoConteiner = Novo("Frame", {
                BackgroundColor3 = "BackgroundColor",
                Size = UDim2.fromScale(1, 0),
                Visible = false,
                Parent = CaixaSuporte,
            })
            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius),
                    Parent = DepCaixaGrupoConteiner,
                })
            )
            Library:AddOutline(DepCaixaGrupoConteiner)

            DepCaixaGrupoLista = Novo("UIListLayout", {
                Padding = UDim.new(0, 8),
                Parent = DepCaixaGrupoConteiner,
            })
            Novo("UIPadding", {
                PaddingBottom = UDim.new(0, 7),
                PaddingLeft = UDim.new(0, 7),
                PaddingRight = UDim.new(0, 7),
                PaddingTop = UDim.new(0, 7),
                Parent = DepCaixaGrupoConteiner,
            })
        end

        local DepCaixaGrupo = {
            Connections = {},
            Destroyed = false,

            Visible = false,
            Dependencies = {},

            BoxHolder = CaixaSuporte,
            Holder = DepCaixaGrupoConteiner,
            Container = DepCaixaGrupoConteiner,

            Tab = Aba,
            Elements = {},
            DependencyBoxes = {},
        }

        function DepCaixaGrupo:Resize()
            DepCaixaGrupoConteiner.Size = UDim2.new(1, 0, 0, (DepCaixaGrupoLista.AbsoluteContentSize.Y / Library.DPIScale) + 18)
        end

        function DepCaixaGrupo:Update(CancelarPesquisa)
            for _, Dependencia in DepCaixaGrupo.Dependencies do
                local Elemento = Dependencia[1]
                local Valor = Dependencia[2]

                if Elemento.Disabled then
                    DepCaixaGrupoConteiner.Visible = false
                    DepCaixaGrupo.Visible = false
                    return
                end

                if Elemento.Type == "Toggle" and Elemento.Value ~= Valor then
                    DepCaixaGrupoConteiner.Visible = false
                    DepCaixaGrupo.Visible = false
                    return
                elseif Elemento.Type == "Dropdown" then
                    if typeof(Elemento.Value) == "table" then
                        if not Elemento.Value[Valor] then
                            DepCaixaGrupoConteiner.Visible = false
                            DepCaixaGrupo.Visible = false
                            return
                        end
                    else
                        if Elemento.Value ~= Valor then
                            DepCaixaGrupoConteiner.Visible = false
                            DepCaixaGrupo.Visible = false
                            return
                        end
                    end
                end
            end

            DepCaixaGrupo.Visible = true
            if not Library.Searching then
                DepCaixaGrupoConteiner.Visible = true
                DepCaixaGrupo:Resize()
            elseif not CancelarPesquisa then
                Library:UpdateSearch(Library.SearchText)
            end
        end

        function DepCaixaGrupo:SetupDependencies(Dependencias)
            for _, Dependencia in Dependencias do
                assert(typeof(Dependencia) == "table", "Dependency should be a table.")
                assert(Dependencia[1] ~= nil, "Dependency is missing element.")
                assert(Dependencia[2] ~= nil, "Dependency is missing expected value.")
            end

            DepCaixaGrupo.Dependencies = Dependencias
            DepCaixaGrupo:Update()
        end

        setmetatable(DepCaixaGrupo, BaseCaixaGrupo)

        table.insert(Aba.DependencyGroupboxes, DepCaixaGrupo)
        table.insert(Library.DependencyBoxes, DepCaixaGrupo :: any)

        function DepCaixaGrupo:Destroy()
            DepCaixaGrupo.Destroyed = true

            if DepCaixaGrupo.Connections then
                for _, Conexao in DepCaixaGrupo.Connections do
                    Conexao:Disconnect()
                end
            end

            for _, Elemento in DepCaixaGrupo.Elements do
                if Elemento.Destroy then
                    Elemento:Destroy()
                end
            end

            for _, SubCaixaDep in DepCaixaGrupo.DependencyBoxes do
                if SubCaixaDep.Destroy then
                    SubCaixaDep:Destroy()
                end
            end

            if DepCaixaGrupoConteiner then
                DepCaixaGrupoConteiner:Destroy()
            end

            local ElemIndice = table.find(Aba.DependencyGroupboxes, DepCaixaGrupo)
            if ElemIndice then
                table.remove(Aba.DependencyGroupboxes, ElemIndice)
            end

            local BibIndice = table.find(Library.DependencyBoxes, DepCaixaGrupo)
            if BibIndice then
                table.remove(Library.DependencyBoxes, BibIndice)
            end
        end

        return DepCaixaGrupo
    end

    BaseCaixaGrupo.__index = Funcoes
    BaseCaixaGrupo.__namecall = function(_, Tecla, ...)
        return Funcoes[Tecla](...)
    end
end

function Library:SetFont(FonteFace)
    if typeof(FonteFace) == "EnumItem" then
        FonteFace = Font.fromEnum(FonteFace :: any)
    end

    Library.Scheme.Font = FonteFace
    Library:UpdateColorsUsingRegistry()
end

function Library:SetBackgroundImage(Imagem: string | number)
    assert(typeof(Imagem) == "string" or typeof(Imagem) == "number", "Expected string/number got " .. typeof(Imagem))

    Library.Scheme.BackgroundImage = Imagem
    if Library.Window then
        Library.Window:SetBackgroundImage(Imagem)
    end

    Library:UpdateColorsUsingRegistry()
end

function Library:UpdateNotificationPositions(Encaixe: boolean?)
    local EhEsquerda = Library.NotifySide:lower() == "left"
    local XEscala = EhEsquerda and 0 or 1
    local ExecutandoY = 0

    for _, FalsoFundo in NotificarOrdem do
        local Dados = Library.Notifications[FalsoFundo]
        if not (Dados and FalsoFundo.Parent) then continue end

        local Alvo = UDim2.new(XEscala, 0, 0, ExecutandoY)
        if Encaixe or not Dados.PositionInitialized then
            FalsoFundo.Position = Alvo
            Dados.PositionInitialized = true

        elseif FalsoFundo.Position ~= Alvo then
            TweenService:Create(FalsoFundo, Library.NotifyTweenInfo, {
                Position = Alvo,
            }):Play()
        end

        ExecutandoY = ExecutandoY + FalsoFundo.AbsoluteSize.Y / Library.DPIScale + 8
    end
end

function Library:SetNotifySide(Lado: string)
    Library.NotifySide = Lado

    local EhEsquerda = Lado:lower() == "left"
    if EhEsquerda then
        NotificacaoArea.AnchorPoint = Vector2.new(0, 0)
        NotificacaoArea.Position = UDim2.fromOffset(6, 6)
    else
        NotificacaoArea.AnchorPoint = Vector2.new(1, 0)
        NotificacaoArea.Position = UDim2.new(1, -6, 0, 6)
    end

    for FalsoFundo in Library.Notifications do
        if not (FalsoFundo and FalsoFundo.Parent) then continue end
        FalsoFundo.AnchorPoint = if EhEsquerda then Vector2.new(0, 0) else Vector2.new(1, 0)
    end

    if Library.UpdateNotificationPositions then
        Library:UpdateNotificationPositions(true)
    end
end

function Library:Notify(...)
    local Dados = {}
    local Info = select(1, ...)

    if typeof(Info) == "table" then
        Dados.Title = tostring(Info.Title)
        Dados.TitleColor = Info.TitleColor

        Dados.Description = tostring(Info.Description)
        Dados.DescriptionColor = Info.DescriptionColor

        Dados.Time = Info.Time or 5
        Dados.SoundId = Info.SoundId
        Dados.Steps = Info.Steps
        Dados.Persist = Info.Persist

        Dados.Callback = typeof(Info.Callback) == "function" and Info.Callback or nil
        Dados.Closable = Info.Closable == true

        Dados.Icon = Info.Icon
        Dados.BigIcon = Info.BigIcon
        Dados.IconColor = Info.IconColor

        Dados.Volume = tonumber(Info.Volume) or 3
    else
        Dados.Description = tostring(Info)
        Dados.Time = select(2, ...) or 5
        Dados.SoundId = select(3, ...)
        Dados.Volume = select(4, ...) or 3
    end
    Dados.Destroyed = false

    local ExcluidoInstancia = false
    local ExcluirConexao = nil
    if typeof(Dados.Time) == "Instance" then
        ExcluirConexao = Dados.Time.Destroying:Connect(function()
            ExcluidoInstancia = true

            ExcluirConexao:Disconnect()
            ExcluirConexao = nil
        end)
    end

    local FalsoFundo = Novo("Frame", {
        AnchorPoint = Library.NotifySide:lower() == "left" and Vector2.new(0, 0) or Vector2.new(1, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(0, 0),
        Visible = false,
        Parent = NotificacaoArea,
    })

    local Suporte = Novo("Frame", {
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = "MainColor",
        Position = Library.NotifySide:lower() == "left" and UDim2.new(-1, -8, 0, 0) or UDim2.new(1, 8, 0, 0),
        Size = UDim2.new(1, 0, 0, 0),
        ZIndex = 5,
        Parent = FalsoFundo,
    })
    table.insert(
        Library.Corners,
        Novo("UICorner", {
            CornerRadius = UDim.new(0, Library.CornerRadius),
            Parent = Suporte,
        })
    )
    Library:AddOutline(Suporte)

    local ConteudoSuporte = Novo("Frame", {
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 0),
        Parent = Suporte,
    })
    Novo("UIListLayout", {
        Padding = UDim.new(0, 4),
        Parent = ConteudoSuporte,
    })
    Novo("UIPadding", {
        PaddingBottom = UDim.new(0, 8),
        PaddingLeft = UDim.new(0, 8),
        PaddingRight = UDim.new(0, 8),
        PaddingTop = UDim.new(0, 8),
        Parent = ConteudoSuporte,
    })

    local FecharBotao
    if Dados.Closable then
        FecharBotao = Novo("ImageButton", {
            AnchorPoint = Vector2.new(1, 0),
            BackgroundTransparency = 1,
            Image = FecharIcone and FecharIcone.Url or "",
            ImageColor3 = "FontColor",
            ImageRectOffset = FecharIcone and FecharIcone.ImageRectOffset or Vector2.zero,
            ImageRectSize = FecharIcone and FecharIcone.ImageRectSize or Vector2.zero,
            ImageTransparency = 0.5,
            Position = UDim2.new(1, -8, 0, 8),
            Size = UDim2.fromOffset(14, 14),
            ZIndex = 6,
            Parent = Suporte,
        })

        FecharBotao.MouseEnter:Connect(function()
            TweenService:Create(FecharBotao, Library.TweenInfo, {
                ImageTransparency = 0,
            }):Play()
        end)
        FecharBotao.MouseLeave:Connect(function()
            TweenService:Create(FecharBotao, Library.TweenInfo, {
                ImageTransparency = 0.5,
            }):Play()
        end)
        FecharBotao.MouseButton1Click:Connect(function()
            Dados:Destroy("user")
        end)
    end

    local ConteudoConteiner = Novo("Frame", {
        BackgroundTransparency = 1,
        AutomaticSize = Enum.AutomaticSize.XY,
        Size = UDim2.fromOffset(0, 0),
        Parent = ConteudoSuporte,
    })

    if Dados.BigIcon then
        Novo("UIListLayout", {
            Padding = UDim.new(0, 8),
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Parent = ConteudoConteiner,
        })
    end

    local GrandeIconeRotulo
    if Dados.BigIcon then
        local AnalisadoIcone = Library:GetCustomIcon(Dados.BigIcon)
        if AnalisadoIcone then
            GrandeIconeRotulo = Novo("ImageLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(24, 24),
                ImageColor3 = Dados.IconColor or "AccentColor",
                Parent = ConteudoConteiner,
            })
            Library:ApplyLucideIcon(GrandeIconeRotulo, AnalisadoIcone)
        end
    end

    local TextoConteiner = Novo("Frame", {
        BackgroundTransparency = 1,
        AutomaticSize = Enum.AutomaticSize.XY,
        Size = UDim2.fromOffset(0, 0),
        Parent = ConteudoConteiner,
    })
    Novo("UIListLayout", {
        Padding = UDim.new(0, 4),
        Parent = TextoConteiner,
    })

    local TituloConteiner
    if Dados.Title then
        TituloConteiner = Novo("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(0, 0),
            Parent = TextoConteiner,
        })
    end

    local IconeRotulo
    if Dados.Icon and TituloConteiner then
        local AnalisadoIcone = Library:GetCustomIcon(Dados.Icon)
        if AnalisadoIcone then
            IconeRotulo = Novo("ImageLabel", {
                BackgroundTransparency = 1,
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 0, 0.5, 1),
                Size = UDim2.fromOffset(15, 15),
                ImageColor3 = Dados.IconColor or "FontColor",
                Parent = TituloConteiner,
            })
            Library:ApplyLucideIcon(IconeRotulo, AnalisadoIcone)
        end
    end

    local Titulo
    local Desc
    local TituloX = 0
    local DescX = 0

    local TemporizadorPreenchimento

    if Dados.Title then
        Titulo = Novo("TextLabel", {
            AutomaticSize = Enum.AutomaticSize.None,
            BackgroundTransparency = 1,
            AnchorPoint = Vector2.new(0, 0.5),
            Position = UDim2.new(0, (IconeRotulo and 21 or 0), 0.5, 0),
            Size = UDim2.fromScale(0, 0),
            Text = Dados.Title,
            TextColor3 = Dados.TitleColor or "FontColor",
            TextSize = 15,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Center,
            TextWrapped = true,
            Parent = TituloConteiner,
        })
    end

    if Dados.Description then
        Desc = Novo("TextLabel", {
            AutomaticSize = Enum.AutomaticSize.None,
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(0, 0),
            Text = Dados.Description,
            TextColor3 = Dados.DescriptionColor or "FontColor",
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            Parent = TextoConteiner,
        })
    end

    function Dados:Resize()
        local ExtraLargura = GrandeIconeRotulo and 32 or 0
        local IconeLargura = IconeRotulo and 21 or 0
        local FecharLargura = Dados.Closable and 20 or 0
        local MaxTextoLargura = math.max(
            40,
            (NotificacaoArea.AbsoluteSize.X / Library.DPIScale) - 24 - ExtraLargura - FecharLargura
        )

        if Titulo then
            local X, Y = Library:GetTextBounds(Titulo.Text, Titulo.FontFace, Titulo.TextSize, MaxTextoLargura - IconeLargura)
            Titulo.Size = UDim2.fromOffset(X, Y)
            TituloX = X + IconeLargura
            TituloConteiner.Size = UDim2.fromOffset(TituloX, math.max(Y, IconeRotulo and 16 or 0))
        end

        if Desc then
            local X, Y = Library:GetTextBounds(Desc.Text, Desc.FontFace, Desc.TextSize, MaxTextoLargura)
            Desc.Size = UDim2.fromOffset(X, Y)
            DescX = X
        end

        FalsoFundo.Size = UDim2.fromOffset(math.max(TituloX, DescX) + 24 + ExtraLargura + FecharLargura, 0)

        if Library.Notifications[FalsoFundo] then
            task.defer(function()
                if Dados.Destroyed or not FalsoFundo.Parent then
                    return
                end

                if FalsoFundo.AbsoluteSize.Y <= 0 then
                    task.defer(function()
                        if Dados.Destroyed or not FalsoFundo.Parent then
                            return
                        end

                        Library:UpdateNotificationPositions(true)
                    end)
                    return
                end

                Library:UpdateNotificationPositions(true)
            end)
        end
    end

    function Dados:ChangeTitle(Texto_2)
        if Titulo then
            Dados.Title = tostring(Texto_2)
            Titulo.Text = Dados.Title
            Dados:Resize()
        end
    end

    function Dados:ChangeDescription(Texto_2)
        if Desc then
            Dados.Description = tostring(Texto_2)
            Desc.Text = Dados.Description
            Dados:Resize()
        end
    end

    function Dados:ChangeStep(NovoPasso)
        if TemporizadorPreenchimento and Dados.Steps then
            NovoPasso = math.clamp(NovoPasso or 0, 0, Dados.Steps)
            TemporizadorPreenchimento.Size = UDim2.fromScale(NovoPasso / Dados.Steps, 1)
        end
    end

    function Dados:Destroy(Motivo)
        if Dados.Destroyed then
            return
        end

        Motivo = Motivo or "script"
        Dados.Destroyed = true

        if Dados.Callback then
            pcall(Dados.Callback, Motivo)
        end

        if typeof(Dados.Time) == "Instance" then
            pcall(Dados.Time.Destroy, Dados.Time)
        end

        if ExcluirConexao then
            ExcluirConexao:Disconnect()
        end

        if FalsoFundo then
            local Indice = table.find(NotificarOrdem, FalsoFundo)
            if Indice then
                table.remove(NotificarOrdem, Indice)
            end
        end

        Library:UpdateNotificationPositions()

        TweenService
            :Create(Suporte, Library.NotifyTweenInfo, {
                Position = Library.NotifySide:lower() == "left" and UDim2.new(-1, -8, 0, -2) or UDim2.new(1, 8, 0, -2),
            })
            :Play()

        task.delay(Library.NotifyTweenInfo.Time, function()
            Library.Notifications[FalsoFundo] = nil
            FalsoFundo:Destroy()
        end)
    end

    local TemporizadorSuporte = Novo("Frame", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 7),
        Visible = (Dados.Persist ~= true and typeof(Dados.Time) ~= "Instance") or typeof(Dados.Steps) == "number",
        Parent = ConteudoSuporte,
    })
    local TemporizadorBarra = Novo("Frame", {
        BackgroundColor3 = "BackgroundColor",
        BorderColor3 = "OutlineColor",
        BorderSizePixel = 1,
        Position = UDim2.fromOffset(0, 3),
        Size = UDim2.new(1, 0, 0, 2),
        Parent = TemporizadorSuporte,
    })
    TemporizadorPreenchimento = Novo("Frame", {
        BackgroundColor3 = "AccentColor",
        Size = UDim2.fromScale(1, 1),
        Parent = TemporizadorBarra,
    })

    if typeof(Dados.Time) == "Instance" then
        TemporizadorPreenchimento.Size = UDim2.fromScale(0, 1)
    end
    if Dados.SoundId then
        local SomId = Dados.SoundId
        if typeof(SomId) == "number" then
            SomId = string.format("rbxassetid://%d", SomId)
        end

        Novo("Sound", {
            SoundId = SomId,
            Volume = tonumber(Dados.Volume) or 3,
            PlayOnRemove = true,
            Parent = SoundService,
        }):Destroy()
    end

    Dados.Holder = Suporte

    table.insert(NotificarOrdem, FalsoFundo)
    Library.Notifications[FalsoFundo] = Dados

    Dados:Resize()

    FalsoFundo.Visible = true
    TweenService:Create(Suporte, Library.NotifyTweenInfo, {
        Position = UDim2.fromOffset(0, 0),
    }):Play()

    task.defer(function()
        if not Dados.Destroyed then
            Library:UpdateNotificationPositions(true)
        end
    end)

    task.delay(Library.NotifyTweenInfo.Time, function()
        if Dados.Persist then
            return
        elseif typeof(Dados.Time) == "Instance" then
            repeat
                task.wait()
            until ExcluidoInstancia or Dados.Destroyed
        else
            TweenService
                :Create(TemporizadorPreenchimento, TweenInfo.new(Dados.Time, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut), {
                    Size = UDim2.fromScale(0, 1),
                })
                :Play()
            task.wait(Dados.Time)
        end

        Dados:Destroy("timer")
    end)

    return Dados
end

function Library:CreateWindow(JanelaInfo)
    JanelaInfo = Library:Validate(JanelaInfo, Modelos.Window)
    local AreaVisaoTamanho: Vector2 = workspace.CurrentCamera.ViewportSize
    if RunService:IsStudio() and AreaVisaoTamanho.X <= 5 and AreaVisaoTamanho.Y <= 5 then
        repeat
            AreaVisaoTamanho = workspace.CurrentCamera.ViewportSize
            task.wait()
        until AreaVisaoTamanho.X > 5 and AreaVisaoTamanho.Y > 5
    end

    local MaxX = AreaVisaoTamanho.X - 64
    local MaxY = AreaVisaoTamanho.Y - 64

    Library.OriginalMinSize =
        Vector2.new(math.min(Library.OriginalMinSize.X, MaxX), math.min(Library.OriginalMinSize.Y, MaxY))
    Library.MinSize = Vector2.new(math.min(JanelaInfo.MinContainerWidth, MaxX), Library.OriginalMinSize.Y)

    JanelaInfo.Size = UDim2.fromOffset(
        math.clamp(JanelaInfo.Size.X.Offset, Library.MinSize.X, MaxX),
        math.clamp(JanelaInfo.Size.Y.Offset, Library.MinSize.Y, MaxY)
    )
    if typeof(JanelaInfo.Font) == "EnumItem" then
        JanelaInfo.Font = Font.fromEnum(JanelaInfo.Font :: any)
    end
    JanelaInfo.CornerRadius = math.min(JanelaInfo.CornerRadius, 20)

