    local function DefinirUICanto(UICorner, Canto, HalfValue)
        local Atual = UICorner[Canto]
        if Atual.Offset == 0 and Atual.Scale == 0 then
            return
        end

        UICorner[Canto] = HalfValue
    end

    function Janela:ChangeTitle(titulo)
        assert(typeof(titulo) == "string", "Expected string for title got: " .. typeof(titulo))

        JanelaTitulo.Text = titulo
        JanelaInfo.Title = titulo
    end

    function Janela:SetBackgroundImage(Imagem: string)
        local ValidoIcone = false

        if typeof(Imagem) == "string" then
            local FundoIcone = Library:GetCustomIcon(Imagem)

            if FundoIcone then
                ValidoIcone = true

                Library:ApplyLucideIcon(FundoImagem, FundoIcone)
            elseif Imagem:match("http://") or Imagem:match("https://") then
                local BrutoArquivoNome = Imagem:match("(.+)%..+$")
                local _, Dominio = Imagem:match("^(https?://)([^/]+)");

                if BrutoArquivoNome and Dominio then
                    local Extensao = string.sub(Imagem, #BrutoArquivoNome + 1, #Imagem)
                    local ArquivoNomePos = BrutoArquivoNome:gsub("\\", "/"):find("/[^/]*$")
                    local ArquivoNome = ArquivoNomePos and Imagem:sub(ArquivoNomePos + 1) or nil

                    if ArquivoNome then
                        ValidoIcone = true

                        local RecursoNome = Dominio .. ArquivoNome
                        if #RecursoNome > 255 then
                            local NovoComprimento = 255 - #Dominio - #Extensao
                            if NovoComprimento < 0 then
                                RecursoNome = Dominio .. Extensao
                            else
                                RecursoNome = Dominio .. string.sub(ArquivoNome:sub(1, #ArquivoNome - #Extensao), 1, NovoComprimento) .. Extensao
                            end
                        end

                        if RecursosGerenciadorImagens[ArquivoNome] == nil then
                            GerenciadorImagens.AddAsset(ArquivoNome, 0, Imagem)
                        else
                            GerenciadorImagens.DownloadAsset(ArquivoNome, true)
                        end

                        FundoImagem.Image = GerenciadorImagens.GetAsset(ArquivoNome)
                        FundoImagem.ImageRectOffset = Vector2.zero
                        FundoImagem.ImageRectSize = Vector2.zero
                    end
                end
            end
        end

        if not ValidoIcone then
            FundoImagem.Image = ""
            FundoImagem.ImageRectOffset = Vector2.zero
            FundoImagem.ImageRectSize = Vector2.zero
        end

        TemFundoImagem = ValidoIcone
        JanelaInfo.BackgroundImage = Imagem
    end

    function Janela:SetFooter(Rodape: string)
        assert(typeof(Rodape) == "string", "Expected string for footer got: " .. typeof(Rodape))

        RodapeRotulo.Text = Rodape
        JanelaInfo.Footer = Rodape
    end

    function Janela:SetAlwaysOnTop(Ativado: boolean)
        JanelaInfo.AlwaysOnTop = Ativado == true
        DefinirSempreAoTopo(Library.ScreenGui, JanelaInfo.AlwaysOnTop)
    end

    function Janela:SetSnapping(Ativado: boolean, Distancia: number?, Margem: number?, EvitarNucleoGui: boolean?)
        JanelaInfo.Snapping = Ativado == true
        JanelaEncaixeConfig.Enabled = JanelaInfo.Snapping

        if Distancia then
            JanelaInfo.SnapDistance = math.max(0, Distancia)
            JanelaEncaixeConfig.Distance = JanelaInfo.SnapDistance
        end

        if Margem then
            JanelaInfo.SnapMargin = math.max(0, Margem)
            JanelaEncaixeConfig.Margin = JanelaInfo.SnapMargin
        end

        if EvitarNucleoGui ~= nil then
            JanelaInfo.SnapAvoidCoreGui = EvitarNucleoGui == true
            JanelaEncaixeConfig.AvoidCoreGui = JanelaInfo.SnapAvoidCoreGui
        end
    end

    function Janela:SetCornerRadius(Raio: number)
        assert(typeof(Raio) == "number", "Expected number for Radius got: " .. typeof(Raio))
        Raio = math.min(Raio, 20)

        local RaioMetade = UDim.new(0, Raio / 2)
        local RaioUEscurecer = UDim.new(0, Raio)
        local MetadeAtual = Library.CornerRadius / 2

        for _, UICorner in Library.Corners do
            if math.abs(UICorner.CornerRadius.Offset - MetadeAtual) < 0.001 then
                UICorner.CornerRadius = RaioMetade
            else
                UICorner.CornerRadius = RaioUEscurecer
            end
        end

        for _, UICorner in Library.SpecificCorners do
            DefinirUICanto(UICorner, "TopRightRadius", RaioMetade)
            DefinirUICanto(UICorner, "TopLeftRadius", RaioMetade)
            DefinirUICanto(UICorner, "BottomRightRadius", RaioMetade)
            DefinirUICanto(UICorner, "BottomLeftRadius", RaioMetade)
        end

        Library.CornerRadius = Raio
        JanelaInfo.CornerRadius = Raio

        if RedimensionarBotao then
            RedimensionarBotao.Position = UDim2.new(1, -Raio / 4, 0, 0)
        end
        if InferiorFundoCanto then
            InferiorFundoCanto.BottomLeftRadius = RaioUEscurecer
            InferiorFundoCanto.BottomRightRadius = RaioUEscurecer
        end

        for _, Menu in Library.ContextMenus do
            if Menu.Destroyed then
                continue
            end

            if typeof(Menu.ActiveCallback) ~= "function" then
                continue
            end

            if not Menu.Active then
                local SuporteAtivo = false
                for _, Outro in Library.ContextMenus do
                    if Outro == Menu then 
                        continue
                    end
   
                    if Outro.Active and Outro.Holder == Menu.Holder then
                        SuporteAtivo = true
                        break
                    end
                end

                if SuporteAtivo then
                    continue
                end

                Menu.ActiveCallback(false)
                continue
            end

            Menu.ActiveCallback(true)
        end

        for _, Opcao in Opcoes do
            if Opcao.Type == "Dropdown" and Opcao.RefreshPool then
                Opcao:RefreshPool()
            end
        end

        for _, Aba in Library.Tabs do
            if Aba.IsKeyTab then
                continue
            end

            for _, CaixaAbas in Aba.Tabboxes do
                CaixaAbas:UpdateCorners()
            end
        end
    end

    function Janela:SetAnimations(Animacoes: { [string]: boolean }?, AbaTransicaoTempo: number?, AbaDeslizeDeslocamento: number?, AbaDeslizeDe: ("left" | "right" | "top" | "bottom" | string)?)
        if typeof(Animacoes) == "table" then
            JanelaInfo.Animations = Animacoes
            Library.Animations = Animacoes
        end

        if typeof(AbaTransicaoTempo) == "number" then
            local TweenInfo = TweenInfo.new(
                math.max(0, AbaTransicaoTempo or 0.22),
                Enum.EasingStyle.Quad,
                Enum.EasingDirection.Out
            )

            JanelaInfo.TabTransitionInfo = TweenInfo
            Library.TabTransitionInfo = TweenInfo
        end

        if typeof(AbaDeslizeDeslocamento) == "number" then
            AbaDeslizeDeslocamento = math.max(1, AbaDeslizeDeslocamento)

            JanelaInfo.TabSwipeOffset = AbaDeslizeDeslocamento
            Library.TabSwipeOffset = AbaDeslizeDeslocamento
        end

        if typeof(AbaDeslizeDe) == "string" then
            AbaDeslizeDe = string.lower(AbaDeslizeDe)

            JanelaInfo.TabSwipeFrom = AbaDeslizeDe
            Library.TabSwipeFrom = AbaDeslizeDe
        end
    end

    local function AplicarCompacto()
        EhCompacto = Janela:GetSidebarWidth() == JanelaInfo.SidebarCompactWidth
        if JanelaInfo.DisableCompactingSnap then
            EhCompacto = Janela:GetSidebarWidth() <= JanelaInfo.CompactWidthActivation
        end

        JanelaTitulo.Visible = not EhCompacto
        if not JanelaInfo.Icon then
            JanelaIcone.Visible = EhCompacto
        end

        for _, Botao in Library.TabButtons do
            if not Botao.Icon then
                continue
            end

            Botao.Label.Visible = not EhCompacto
            Botao.Padding.PaddingBottom = UDim.new(0, EhCompacto and 6 or 11)
            Botao.Padding.PaddingLeft = UDim.new(0, EhCompacto and 6 or 12)
            Botao.Padding.PaddingRight = UDim.new(0, EhCompacto and 6 or 12)
            Botao.Padding.PaddingTop = UDim.new(0, EhCompacto and 6 or 11)
            Botao.Icon.SizeConstraint = EhCompacto and Enum.SizeConstraint.RelativeXY or Enum.SizeConstraint.RelativeYY
        end
    end

    function Janela:IsSidebarCompacted()
        return EhCompacto
    end

    function Janela:SetCompact(Estado)
        Janela:SetSidebarWidth(Estado and JanelaInfo.SidebarCompactWidth or UltimoExpandidoLargura)
    end

    function Janela:GetSidebarWidth()
        return Abas.Size.X.Offset
    end

    function Janela:SetSidebarWidth(Largura)
        Largura = math.clamp(Largura, 48, PrincipalQuadro.Size.X.Offset - JanelaInfo.MinContainerWidth - 1)

        DivisorLinha.Position = UDim2.fromOffset(Largura, 0)

        TituloSuporte.Size = UDim2.new(0, Largura, 1, 0)
        DireitaEnvoltorio.Size = UDim2.new(1, -Largura - 57 - 1, 1, -16)
        Abas.Size = UDim2.new(0, Largura, 1, -70)
        Conteiner.Size = UDim2.new(1, -Largura - 1, 1, -70)

        if JanelaInfo.EnableCompacting then
            AplicarCompacto()
        end
        if not EhCompacto then
            UltimoExpandidoLargura = Largura
        end
    end

    function Janela:ShowTabInfo(Name, Descricao)
        AtualAbaRotulo.Text = Name
        AtualAbaDescricao.Text = Descricao

        if EhPadraoBarraPesquisaTamanho then
            PesquisaCaixa.Size = UDim2.fromScale(0.5, 1)
        end
        AtualAbaInfo.Visible = true
    end

    function Janela:HideTabInfo()
        AtualAbaInfo.Visible = false
        if EhPadraoBarraPesquisaTamanho then
            PesquisaCaixa.Size = UDim2.fromScale(1, 1)
        end
    end

    function Janela:AddTab(...)
        local Name = nil
        local Icon = nil
        local Descricao = nil
        local Dica = nil
        local Ordem = nil

        if select("#", ...) == 1 and typeof(...) == "table" then
            local Info = select(1, ...)
            Name = Info.Name or "Tab"
            Icon = Info.Icon
            Descricao = Info.Description
            Dica = Info.Tooltip
            Ordem = Info.Order
        else
            Name = select(1, ...)
            Icon = select(2, ...)
            Descricao = select(3, ...)
            Ordem = select(4, ...)
        end

        if not tonumber(Ordem) then
            Ordem = #Abas:GetChildren()
        end

        local AbaBotao: TextButton
        local TabIndicator
        local TabLabel
        local TabIcon

        local AbaConteiner
        local TabLeft
        local TabRight

        Icon = Library:GetCustomIcon(Icon)
        do
            AbaBotao = Novo("TextButton", {
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 40),
                Text = "",
                LayoutOrder = Ordem,
                Parent = Abas,
            })
            Novo("UICorner", {
                CornerRadius = UDim.new(0, AbaBotoesEstilo.CornerRadius),
                Parent = AbaBotao,
            })

            if AbaBotoesEstilo.Indicator then
                TabIndicator = Novo("Frame", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundColor3 = "AccentColor",
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, -2, 0.5, 0),
                    Size = UDim2.fromOffset(AbaBotoesEstilo.IndicatorWidth, AbaBotoesEstilo.IndicatorHeight),
                    Parent = AbaBotao,
                })

                Novo("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = TabIndicator,
                })
            end

            local BotaoSuporte = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Parent = AbaBotao,
            })
            local BotaoPreenchimentoInterno = Novo("UIPadding", {
                PaddingBottom = UDim.new(0, EhCompacto and 6 or 11),
                PaddingLeft = UDim.new(0, EhCompacto and 6 or 12),
                PaddingRight = UDim.new(0, EhCompacto and 6 or 12),
                PaddingTop = UDim.new(0, EhCompacto and 6 or 11),
                Parent = BotaoSuporte,
            })
            TabLabel = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(30, 0),
                Size = UDim2.new(1, -30, 1, 0),
                Text = Name,
                TextSize = 16,
                TextTransparency = 0.5,
                TextXAlignment = Enum.TextXAlignment.Left,
                Visible = not EhCompacto,
                Parent = BotaoSuporte,
            })

            if Icon then
                TabIcon = Novo("ImageLabel", {
                    ImageColor3 = Icon.Custom and "WhiteColor" or "AccentColor",
                    ImageTransparency = 0.5,
                    ScaleType = Enum.ScaleType.Fit,
                    Size = UDim2.fromScale(1, 1),
                    SizeConstraint = EhCompacto and Enum.SizeConstraint.RelativeXY or Enum.SizeConstraint.RelativeYY,
                    Parent = BotaoSuporte,
                })
                Library:ApplyLucideIcon(TabIcon, Icon)
            end

            table.insert(Library.TabButtons, {
                Label = TabLabel,
                Padding = BotaoPreenchimentoInterno,
                Icon = TabIcon,
            })

            AbaConteiner = Novo("Frame", {
                BackgroundTransparency = 1,
                Position = UDim2.fromScale(0, 0),
                Size = UDim2.fromScale(1, 1),
                Visible = false,
                Parent = Conteiner,
            })

            TabLeft = Novo("ScrollingFrame", {
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                CanvasSize = UDim2.fromScale(0, 0),
                ScrollBarImageTransparency = 1,
                ScrollBarThickness = 0,
                Size = UDim2.new(0.5, -3, 1, 0),
                Parent = AbaConteiner,
            })
            Novo("UIListLayout", {
                Padding = UDim.new(0, 2),
                Parent = TabLeft,
            })
            Novo("UIPadding", {
                PaddingBottom = UDim.new(0, 2),
                PaddingLeft = UDim.new(0, 2),
                PaddingRight = UDim.new(0, 2),
                PaddingTop = UDim.new(0, 2),
                Parent = TabLeft,
            })
            do
                Novo("Frame", {
                    BackgroundTransparency = 1,
                    LayoutOrder = -1,
                    Parent = TabLeft,
                })
                Novo("Frame", {
                    BackgroundTransparency = 1,
                    LayoutOrder = 1,
                    Parent = TabLeft,
                })
            end

            TabRight = Novo("ScrollingFrame", {
                AnchorPoint = Vector2.new(1, 0),
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                CanvasSize = UDim2.fromScale(0, 0),
                Position = UDim2.fromScale(1, 0),
                ScrollBarImageTransparency = 1,
                ScrollBarThickness = 0,
                Size = UDim2.new(0.5, -3, 1, 0),
                Parent = AbaConteiner,
            })
            Novo("UIListLayout", {
                Padding = UDim.new(0, 2),
                Parent = TabRight,
            })
            Novo("UIPadding", {
                PaddingBottom = UDim.new(0, 2),
                PaddingLeft = UDim.new(0, 2),
                PaddingRight = UDim.new(0, 2),
                PaddingTop = UDim.new(0, 2),
                Parent = TabRight,
            })
            do
                Novo("Frame", {
                    BackgroundTransparency = 1,
                    LayoutOrder = -1,
                    Parent = TabRight,
                })
                Novo("Frame", {
                    BackgroundTransparency = 1,
                    LayoutOrder = 1,
                    Parent = TabRight,
                })
            end
        end

        local Aba = {
            Name = Name,
            Description = Descricao,

            Tooltip = Dica,
            TooltipTable = nil,

            Connections = {},
            Destroyed = false,

            Window = Janela,
            Button = AbaBotao,
            Container = AbaConteiner,
            Sides = {
                TabLeft,
                TabRight,
            },
            WarningBox = {
                IsNormal = false,
                LockSize = false,
                Visible = false,
                Title = "AVISO",
                Text = "",
            },

            Groupboxes = {},
            Tabboxes = {},
            DependencyGroupboxes = {},
        }

        local AvisoCaixaSuporte = Novo("Frame", {
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(0, 7),
            Size = UDim2.fromScale(1, 0),
            Visible = false,
            Parent = AbaConteiner,
        })

        local AvisoCaixa
        local AvisoCaixaContorno
        local AvisoCaixaSombraContorno
        local AvisoCaixaRolagemQuadro
        local AvisoTitulo
        local AvisoBorda
        local AvisoTexto
        do
            AvisoCaixa = Novo("Frame", {
                BackgroundColor3 = Color3.fromRGB(127, 0, 0),
                Position = UDim2.fromOffset(2, 0),
                Size = UDim2.new(1, -5, 0, 0),
                Parent = AvisoCaixaSuporte,
            })
            Library:AddToRegistry(AvisoCaixa, {
                BackgroundColor3 = function()
                    return Aba.WarningBox.IsNormal == true and Library.Scheme.BackgroundColor or Color3.fromRGB(127, 0, 0)
                end
            })
            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, JanelaInfo.CornerRadius),
                    Parent = AvisoCaixa,
                })
            )
            AvisoCaixaContorno, AvisoCaixaSombraContorno = Library:AddOutline(AvisoCaixa)
            Library:AddToRegistry(AvisoCaixaContorno, {
                Color = function()
                    return Aba.WarningBox.IsNormal == true and Library.Scheme.OutlineColor or Color3.fromRGB(255, 50, 50)
                end
            })
            Library:AddToRegistry(AvisoCaixaSombraContorno, {
                Color = function()
                    return Aba.WarningBox.IsNormal == true and Library.Scheme.DarkColor or Color3.fromRGB(85, 0, 0)
                end
            })

            AvisoCaixaRolagemQuadro = Novo("ScrollingFrame", {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Size = UDim2.fromScale(1, 1),
                CanvasSize = UDim2.new(0, 0, 0, 0),
                ScrollBarThickness = 3,
                ScrollingDirection = Enum.ScrollingDirection.Y,
                Parent = AvisoCaixa,
            })
            Novo("UIPadding", {
                PaddingBottom = UDim.new(0, 4),
                PaddingLeft = UDim.new(0, 6),
                PaddingRight = UDim.new(0, 6),
                PaddingTop = UDim.new(0, 4),
                Parent = AvisoCaixaRolagemQuadro,
            })

            AvisoTitulo = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, -4, 0, 14),
                Text = "",
                TextColor3 = Color3.fromRGB(255, 50, 50),
                TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = AvisoCaixaRolagemQuadro,
            })
            Library:AddToRegistry(AvisoTitulo, {
                TextColor3 = function()
                    return Aba.WarningBox.IsNormal == true and Library.Scheme.FontColor or Color3.fromRGB(255, 50, 50)
                end
            })

            AvisoBorda = Novo("UIStroke", {
                ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
                Color = Color3.fromRGB(169, 0, 0),
                LineJoinMode = Enum.LineJoinMode.Miter,
                Parent = AvisoTitulo,
            })
            Library:AddToRegistry(AvisoBorda, {
                Color = function()
                    return Aba.WarningBox.IsNormal == true and Library.Scheme.OutlineColor or Color3.fromRGB(169, 0, 0)
                end
            })

            AvisoTexto = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, 16),
                Size = UDim2.new(1, -4, 0, 0),
                Text = "",
                TextSize = 14,
                TextWrapped = true,
                Parent = AvisoCaixaRolagemQuadro,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Top,
            })

            Novo("UIStroke", {
                ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
                Color = "DarkColor",
                LineJoinMode = Enum.LineJoinMode.Miter,
                Parent = AvisoTexto,
            })
        end

        function Aba:UpdateWarningBox(Info)
            if typeof(Info.IsNormal) == "boolean" then
                Aba.WarningBox.IsNormal = Info.IsNormal
            end
            if typeof(Info.LockSize) == "boolean" then
                Aba.WarningBox.LockSize = Info.LockSize
            end
            if typeof(Info.Visible) == "boolean" then
                Aba.WarningBox.Visible = Info.Visible
            end
            if typeof(Info.Title) == "string" then
                Aba.WarningBox.Title = Info.Title
            end
            if typeof(Info.Text) == "string" then
                Aba.WarningBox.Text = Info.Text
            end

            AvisoCaixaSuporte.Visible = Aba.WarningBox.Visible
            AvisoTitulo.Text = Aba.WarningBox.Title
            AvisoTexto.Text = Aba.WarningBox.Text
            Aba:Resize(true)

            AvisoCaixa.BackgroundColor3 = Library.Registry[AvisoCaixa].BackgroundColor3()
            AvisoCaixaSombraContorno.Color = Library.Registry[AvisoCaixaSombraContorno].Color()
            AvisoCaixaContorno.Color = Library.Registry[AvisoCaixaContorno].Color()
            AvisoTitulo.TextColor3 = Library.Registry[AvisoTitulo].TextColor3()
            AvisoBorda.Color = Library.Registry[AvisoBorda].Color()
        end

        function Aba:RefreshSides()
            local Deslocamento = AvisoCaixaSuporte.Visible and AvisoCaixa.Size.Y.Offset + 8 or 0
            for _, Lado in Aba.Sides do
                Lado.Position = UDim2.new(Lado.Position.X.Scale, 0, 0, Deslocamento)
                Lado.Size = UDim2.new(0.5, -3, 1, -Deslocamento)
            end
        end

        function Aba:Resize(RedimensionarAvisoCaixa: boolean?)
            if RedimensionarAvisoCaixa then
                local MaximoTamanho = math.floor((AbaConteiner.AbsoluteSize.Y / Library.DPIScale) / 3.25)
                local _, YTexto = Library:GetTextBounds(
                    AvisoTexto.Text,
                    Library.Scheme.Font,
                    AvisoTexto.TextSize,
                    AvisoTexto.AbsoluteSize.X / Library.DPIScale
                )

                local YCaixa = 24 + YTexto
                if Aba.WarningBox.LockSize == true and YCaixa >= MaximoTamanho then
                    AvisoCaixaRolagemQuadro.CanvasSize = UDim2.fromOffset(0, YCaixa)
                    YCaixa = MaximoTamanho
                else
                    AvisoCaixaRolagemQuadro.CanvasSize = UDim2.fromOffset(0, 0)
                end

                AvisoTexto.Size = UDim2.new(1, -4, 0, YTexto)
                AvisoCaixa.Size = UDim2.new(1, -5, 0, YCaixa + 4)
            end

            Aba:RefreshSides()
        end

        local function AdicionarCaixaAbas(self, Info)
            Info = Library:Validate(Info, Modelos.Tabbox)
            local PaiObj = self
            local EhAninhado = PaiObj.Type == "Groupbox" or PaiObj.Type == "SubTab"

            if typeof(Info.Side) == "string" then
                local minusculoLado = string.lower(Info.Side)
                if not LadoIndice[minusculoLado] then
                    error(string.format("Invalid side: %s", Info.Side))
                end

                Info.Side = LadoIndice[minusculoLado]
            end

            local CaixaSuporte = Novo("Frame", {
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 0),
                Parent = if EhAninhado then PaiObj.Container else (Info.Side == 1 and TabLeft or TabRight),
            })
            Novo("UIListLayout", {
                Padding = UDim.new(0, 6),
                Parent = CaixaSuporte,
            })
            Novo("UIPadding", {
                PaddingBottom = UDim.new(0, 4),
                PaddingTop = UDim.new(0, 4),
                Parent = CaixaSuporte,
            })

            local CaixaAbasSuporte
            local CaixaAbasBotoes
            local AbaFaixaDeslocamento

            do
                CaixaAbasSuporte = Novo("Frame", {
                    BackgroundColor3 = "BackgroundColor",
                    Size = UDim2.fromScale(1, 0),
                    Parent = CaixaSuporte,
                })
                table.insert(
                    Library.Corners,
                    Novo("UICorner", {
                        CornerRadius = UDim.new(0, JanelaInfo.CornerRadius),
                        Parent = CaixaAbasSuporte,
                    })
                )
                Library:AddOutline(CaixaAbasSuporte)

                local TituloIcone = Library:GetCustomIcon(Info.IconName)
                AbaFaixaDeslocamento = 35

                if Info.Name ~= nil or TituloIcone then
                    local CaixaAbasTitulo = Novo("Frame", {
                        BackgroundTransparency = 1,
                        Size = UDim2.new(1, 0, 0, 32),
                        Parent = CaixaAbasSuporte,
                    })
                    Novo("UIPadding", {
                        PaddingBottom = UDim.new(0, 6),
                        PaddingLeft = UDim.new(0, 6),
                        PaddingRight = UDim.new(0, 6),
                        PaddingTop = UDim.new(0, 6),
                        Parent = CaixaAbasTitulo,
                    })

                    if TituloIcone then
                        local CaixaAbasTituloIcone = Novo("ImageLabel", {
                            AnchorPoint = Vector2.new(0, 0.5),
                            ImageColor3 = TituloIcone.Custom and "WhiteColor" or "AccentColor",
                            Position = UDim2.fromScale(0, 0.5),
                            Size = UDim2.fromOffset(22, 22),
                            Parent = CaixaAbasTitulo,
                        })
                        Library:ApplyLucideIcon(CaixaAbasTituloIcone, TituloIcone)
                    end

                    local CaixaAbasTituloRotulo = Novo("TextLabel", {
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(TituloIcone and 26 or 0, 0),
                        Size = UDim2.new(1, TituloIcone and -26 or 0, 1, 0),
                        Text = Info.Name or "",
                        TextSize = 15,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Center,
                        Parent = CaixaAbasTitulo,
                    })

                    Library:MakeLine(CaixaAbasSuporte, {
                        Position = UDim2.fromOffset(0, 32),
                        Size = UDim2.new(1, 0, 0, 1),
                    })

                    AbaFaixaDeslocamento = 68
                end

                CaixaAbasBotoes = Novo("Frame", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(0, AbaFaixaDeslocamento - 35),
                    Size = UDim2.new(1, 0, 0, 34),
                    Parent = CaixaAbasSuporte,
                })
                Novo("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalFlex = Enum.UIFlexAlignment.Fill,
                    Parent = CaixaAbasBotoes,
                })
            end

            local TotalAbas = 0
            local PrimeiroAba
            local UltimoAba

            local CaixaAbas: any = {
                Type = "Tabbox",

                Connections = {},
                Destroyed = false,

                Visible = true,
                ActiveTab = nil,

                BoxHolder = CaixaSuporte,
                Holder = CaixaAbasSuporte,
                Tabs = {},

                ParentBox = if EhAninhado then PaiObj else nil,
            }

            function CaixaAbas:UpdateCorners()
                for _, Aba in CaixaAbas.Tabs do
                    Aba:UpdateCorners()
                end
            end

            function CaixaAbas:Resize()
                if CaixaAbas.ActiveTab then
                    CaixaAbas.ActiveTab:Resize()
                end
            end

            function CaixaAbas:AddTab(Name, IconName)
                TotalAbas = TotalAbas + 1
                local AbaIndice = TotalAbas

                UltimoAba = AbaIndice
                if not PrimeiroAba then
                    PrimeiroAba = AbaIndice
                end

                local EhNomeVazio = Name == nil or Aparar(tostring(Name)) == ""
                local AbaArmazenandoIndice = EhNomeVazio and tostring(AbaIndice) or Name

                local Botao = Novo("TextButton", {
                    BackgroundColor3 = "MainColor",
                    BackgroundTransparency = 0,
                    Size = UDim2.fromOffset(0, 34),
                    Text = "",
                    Parent = CaixaAbasBotoes,
                })

                local BotaoCanto = Novo("UICorner", {
                    TopLeftRadius = UDim.new(0, JanelaInfo.CornerRadius),
                    TopRightRadius = UDim.new(0, JanelaInfo.CornerRadius),
                    BottomRightRadius = UDim.new(0, 0),
                    BottomLeftRadius = UDim.new(0, 0),
                    Parent = Botao,
                }); table.insert(Library.SpecificCorners, BotaoCanto)

                local BotaoConteudo = Novo("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(0, 16),
                    Parent = Botao,
                })
                Novo("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalAlignment = Enum.HorizontalAlignment.Center,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    Padding = UDim.new(0, 8),
                    Parent = BotaoConteudo,
                })

                local BotaoIcone
                local CaixaIcone = Library:GetCustomIcon(IconName)
                if CaixaIcone then
                    BotaoIcone = Novo("ImageLabel", {
                        ImageColor3 = CaixaIcone.Custom and "WhiteColor" or "AccentColor",
                        ImageTransparency = 0.5,
                        Size = EhNomeVazio and UDim2.fromOffset(16, 16) or UDim2.fromOffset(18, 18),
                        Parent = BotaoConteudo,
                    })
                    Library:ApplyLucideIcon(BotaoIcone, CaixaIcone)
                end

                local BotaoRotulo_2
                if not EhNomeVazio then
                    BotaoRotulo_2 = Novo("TextLabel", {
                        AutomaticSize = Enum.AutomaticSize.X,
                        BackgroundTransparency = 1,
                        Size = UDim2.fromOffset(0, 16),
                        Text = Name,
                        TextSize = 15,
                        TextTransparency = 0.5,
                        Parent = BotaoConteudo,
                    })
                end

                local Linha = Library:MakeLine(Botao, {
                    AnchorPoint = Vector2.new(0, 1),
                    Position = UDim2.new(0, 0, 1, 1),
                    Size = UDim2.new(1, 0, 0, 1),
                })

                local Conteiner = Novo("ScrollingFrame", {
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    CanvasSize = UDim2.fromScale(0, 0),
                    Position = UDim2.fromOffset(0, AbaFaixaDeslocamento),
                    ScrollBarThickness = 0,
                    Size = UDim2.new(1, 0, 1, -AbaFaixaDeslocamento),
                    Visible = false,
                    Parent = CaixaAbasSuporte,
                })
                local List = Novo("UIListLayout", {
                    Padding = UDim.new(0, 8),
                    Parent = Conteiner,
                })
                Novo("UIPadding", {
                    PaddingBottom = UDim.new(0, 7),
                    PaddingLeft = UDim.new(0, 7),
                    PaddingRight = UDim.new(0, 7),
                    PaddingTop = UDim.new(0, 7),
                    Parent = Conteiner,
                })

                local Aba = {
                    Type = "SubTab",
                    Name = Name,

                    Connections = {},
                    Destroyed = false,

                    ButtonHolder = Botao,
                    Container = Conteiner,
                    ButtonCorner = BotaoCanto,

                    Tab = Aba,
                    Tabbox = CaixaAbas,

                    Elements = {},
                    DependencyBoxes = {},
                }

                function Aba:Show()
                    if CaixaAbas.ActiveTab then
                        CaixaAbas.ActiveTab:Hide()
                    end

                    Botao.BackgroundTransparency = 1

                    if BotaoRotulo_2 then
                        BotaoRotulo_2.TextTransparency = 0
                    end
                    if BotaoIcone then
                        BotaoIcone.ImageTransparency = 0
                    end

                    Linha.Visible = false

                    Conteiner.Visible = true

                    CaixaAbas.ActiveTab = Aba
                    Aba:Resize()
                    CaixaAbas:RefreshPopOutPlaceholder()
                end

                function Aba:Hide()
                    Botao.BackgroundTransparency = 0

                    if BotaoRotulo_2 then
                        BotaoRotulo_2.TextTransparency = 0.5
                    end
                    if BotaoIcone then
                        BotaoIcone.ImageTransparency = 0.5
                    end
                    Linha.Visible = true
                    Conteiner.Visible = false

                    CaixaAbas.ActiveTab = nil
                end

                function Aba:Resize()
                    if CaixaAbas.ActiveTab ~= Aba then
                        return
                    end

                    local ConteudoTamanho = (List.AbsoluteContentSize.Y / Library.DPIScale) + 14
                    if CaixaAbas.PoppedOut then
                        ConteudoTamanho = math.min(ConteudoTamanho, ObterDestacarForaCorpoMaxAltura(CaixaAbas, 35))
                    end

                    CaixaAbasSuporte.Size = UDim2.new(1, 0, 0, ConteudoTamanho + 35)
                    if EhAninhado then
                        PaiObj:Resize()
                    end
                end

                function Aba:UpdateCorners()
                    local Raio = JanelaInfo.CornerRadius

                    BotaoCanto.TopLeftRadius = UDim.new(0, AbaIndice == PrimeiroAba and Raio or 0)
                    BotaoCanto.TopRightRadius = UDim.new(0, AbaIndice == UltimoAba and Raio or 0)
                end

                function Aba:Destroy()
                    Aba.Destroyed = true

                    if Aba.Connections then
                        for _, Conexao in Aba.Connections do
                            Conexao:Disconnect()
                        end
                    end

                    for _, Elemento in Aba.Elements do
                        if Elemento.Destroy then
                            Elemento:Destroy()
                        end
                    end

                    for _, SubCaixaDep in Aba.DependencyBoxes do
                        if SubCaixaDep.Destroy then
                            SubCaixaDep:Destroy()
                        end
                    end

                    if Conteiner then
                        Conteiner:Destroy()
                    end

                    if Botao then
                        Botao:Destroy()
                    end
                end

                if not CaixaAbas.ActiveTab then
                    Aba:Show()
                end

                Botao.MouseButton1Click:Connect(Aba.Show)

                Aba.AddTabbox = AdicionarCaixaAbas
                setmetatable(Aba, BaseCaixaGrupo)

                CaixaAbas.Tabs[AbaArmazenandoIndice] = Aba
                CaixaAbas:UpdateCorners()

                return Aba, AbaArmazenandoIndice
            end

            Library:MakeBoxPopOut(CaixaAbas, {
                Enabled = Info.PopOut ~= false,
                MaxPopOutHeight = Info.MaxPopOutHeight,
                PopOutWidth = Info.PopOutWidth,

                Header = CaixaAbasBotoes,
                Children = function()
                    return { CaixaAbasSuporte }
                end,

                After = function()
                    if CaixaAbas.ActiveTab then
                        CaixaAbas.ActiveTab:Resize()
                    end
                    if EhAninhado then
                        PaiObj:Resize()
                    end
                end,
            })

            function CaixaAbas:Destroy()
                if CaixaAbas.PoppedOut then
                    CaixaAbas:SetPoppedOut(false)
                end

                CaixaAbas.Destroyed = true

                if CaixaAbas.Connections then
                    for _, Conexao in CaixaAbas.Connections do
                        Conexao:Disconnect()
                    end
                end

                for _, Aba in CaixaAbas.Tabs do
                    if Aba.Destroy then
                        Aba:Destroy()
                    end
                end

                if CaixaAbasSuporte then
                    CaixaAbasSuporte:Destroy()
                end

                if CaixaSuporte then
                    CaixaSuporte:Destroy()
                end
            end

            if Info.Name then
                Aba.Tabboxes[Info.Name] = CaixaAbas
            else
                table.insert(Aba.Tabboxes, CaixaAbas)
            end

            return CaixaAbas
        end

        Aba.AddTabbox = AdicionarCaixaAbas

        function Aba:AddLeftTabbox(Name, IconName)
            return Aba:AddTabbox({ Side = 1, Name = Name, IconName = IconName })
        end

        function Aba:AddRightTabbox(Name, IconName)
            return Aba:AddTabbox({ Side = 2, Name = Name, IconName = IconName })
        end

        function Aba:AddGroupbox(Info)
            Info = Library:Validate(Info, Modelos.Groupbox)

            if typeof(Info.Side) == "string" then
                local minusculoLado = string.lower(Info.Side)
                if not LadoIndice[minusculoLado] then
                    error(string.format("Invalid side: %s", Info.Side))
                end

                Info.Side = LadoIndice[minusculoLado]
            end

            local CaixaSuporte = Novo("Frame", {
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 0),
                Parent = (Info.Side == 1) and TabLeft or TabRight,
            })
            Novo("UIListLayout", {
                Padding = UDim.new(0, 6),
                Parent = CaixaSuporte,
            })
            Novo("UIPadding", {
                PaddingBottom = UDim.new(0, 4),
                PaddingTop = UDim.new(0, 4),
                Parent = CaixaSuporte,
            })

            local CaixaGrupoSuporte

            local CaixaGrupoTopo
            local CaixaGrupoRotulo
            local CaixaGrupoDescricao

            local CaixaGrupoConteiner
            local CaixaGrupoLista

            local CaixaGrupoRecolherSeta
            local CaixaGrupoLinha

            do
                CaixaGrupoSuporte = Novo("Frame", {
                    BackgroundColor3 = "BackgroundColor",
                    Size = UDim2.fromScale(1, 0),
                    Parent = CaixaSuporte,
                })
                table.insert(
                    Library.Corners,
                    Novo("UICorner", {
                        CornerRadius = UDim.new(0, JanelaInfo.CornerRadius),
                        Parent = CaixaGrupoSuporte,
                    })
                )
                Novo("UIListLayout", {
                    Parent = CaixaGrupoSuporte,
                })
                Library:AddOutline(CaixaGrupoSuporte)

                CaixaGrupoTopo = Novo("Frame", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 0),
                    Parent = CaixaGrupoSuporte,
                })
                Novo("UIPadding", {
                    PaddingBottom = UDim.new(0, 6),
                    PaddingLeft = UDim.new(0, 6),
                    PaddingRight = UDim.new(0, 6),
                    PaddingTop = UDim.new(0, 6),
                    Parent = CaixaGrupoTopo,
                })

                local CaixaIcone = Library:GetCustomIcon(Info.IconName)
                if CaixaIcone then
                    local CaixaGrupoCabecalhoIcone = Novo("ImageLabel", {
                        AnchorPoint = Vector2.new(0, 0.5),
                        ImageColor3 = CaixaIcone.Custom and "WhiteColor" or "AccentColor",
                        Position = UDim2.fromScale(0, 0.5),
                        Size = UDim2.fromOffset(22, 22),
                        Parent = CaixaGrupoTopo,
                    })
                    Library:ApplyLucideIcon(CaixaGrupoCabecalhoIcone, CaixaIcone)
                end

                local DireitaMargemInterna = if Info.DisableCollapsing ~= true then 22 else 0
                local TextosQuadro = Novo("Frame", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(CaixaIcone and 24 or 0, 0),
                    Size = UDim2.new(1, -DireitaMargemInterna - (CaixaIcone and 24 or 0), 0, 0),
                    Parent = CaixaGrupoTopo,
                })
                Novo("UIListLayout", {
                    Parent = TextosQuadro,
                })
                Novo("UIPadding", {
                    PaddingBottom = UDim.new(0, 3),
                    PaddingLeft = UDim.new(0, 6),
                    PaddingRight = UDim.new(0, 6),
                    PaddingTop = UDim.new(0, 3),
                    Parent = TextosQuadro,
                })

                CaixaGrupoRotulo = Novo("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 0),
                    Text = Info.Name,
                    TextSize = 15,
                    TextWrapped = true,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Parent = TextosQuadro,
                })
                Novo("UIPadding", {
                    PaddingBottom = UDim.new(0, 1),
                    Parent = CaixaGrupoRotulo,
                })

                CaixaGrupoDescricao = Novo("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 0),
                    Text = Info.Description or "",
                    TextSize = 14,
                    TextTransparency = 0.5,
                    TextWrapped = true,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Visible = (Info.Description ~= nil),
                    Parent = TextosQuadro,
                })

                CaixaGrupoRecolherSeta = Novo("ImageButton", {
                    Visible = Info.DisableCollapsing ~= true,
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundTransparency = 1,
                    ImageColor3 = "WhiteColor",
                    Position = UDim2.fromScale(1, 0.5),
                    Size = UDim2.fromOffset(22, 22),
                    Parent = CaixaGrupoTopo,
                })
                if SetaIcone then
                    Library:ApplyLucideIcon(CaixaGrupoRecolherSeta, SetaIcone, 180)
                end

                CaixaGrupoLinha = Library:MakeLine(CaixaGrupoSuporte, {
                    LayoutOrder = 1,
                    Size = UDim2.new(1, 0, 0, 1),
                })

                CaixaGrupoConteiner = Novo("ScrollingFrame", {
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    CanvasSize = UDim2.fromScale(0, 0),
                    LayoutOrder = 2,
                    ScrollBarThickness = 0,
                    Size = UDim2.fromScale(1, 0),
                    Parent = CaixaGrupoSuporte,
                })

                CaixaGrupoLista = Novo("UIListLayout", {
                    Padding = UDim.new(0, 8),
                    Parent = CaixaGrupoConteiner,
                })
                Novo("UIPadding", {
                    PaddingBottom = UDim.new(0, 7),
                    PaddingLeft = UDim.new(0, 7),
                    PaddingRight = UDim.new(0, 7),
                    PaddingTop = UDim.new(0, 7),
                    Parent = CaixaGrupoConteiner,
                })
            end

            local CaixaGrupo: any = {
                Type = "Groupbox",

                Name = Info.Name,
                Description = Info.Description,

                Connections = {},
                Destroyed = false,

                Visible = true,
                Collapsed = false,

                BoxHolder = CaixaSuporte,
                Holder = CaixaGrupoSuporte,
                Container = CaixaGrupoConteiner,

                Tab = Aba,
                DependencyBoxes = {},
                Elements = {}
            }

            local RedimensionarInterpolacao
            local RecolherSetaInterpolacao

            function CaixaGrupo:Resize()
                if RedimensionarInterpolacao then
                    PararInterpolacao(RedimensionarInterpolacao, true)
                    RedimensionarInterpolacao = nil
                end

                local TopoTamanho = (CaixaGrupoTopo.AbsoluteSize.Y / Library.DPIScale)
                local ConteinerTamanho = (CaixaGrupoLista.AbsoluteContentSize.Y / Library.DPIScale) + 14
                if CaixaGrupo.PoppedOut then
                    ConteinerTamanho = math.min(ConteinerTamanho, ObterDestacarForaCorpoMaxAltura(CaixaGrupo, TopoTamanho + 1))
                end

                local AlvoTamanho = UDim2.new(1, 0, 0, if CaixaGrupo.Collapsed then TopoTamanho else (TopoTamanho + 1 + ConteinerTamanho))
                CaixaGrupoConteiner.Size = UDim2.new(1, 0, 0, ConteinerTamanho)
                CaixaGrupoLinha.Visible = not CaixaGrupo.Collapsed

                if Library.Animations and Library.Animations.Groupbox then
                    local TweenInfo = Library.GroupboxTweenInfo or TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                    local Interpolacao = TweenService:Create(CaixaGrupoSuporte, TweenInfo, { Size = AlvoTamanho })
                    RedimensionarInterpolacao = Interpolacao

                    local Conexao; Conexao = Library:GiveSignal(Interpolacao.Completed:Once(function()
                        if Conexao then
                            Conexao:Disconnect()
                        end

                        if RedimensionarInterpolacao == Interpolacao then
                            PararInterpolacao(RedimensionarInterpolacao, true)
                            RedimensionarInterpolacao = nil
                        end
                    end))

                    Interpolacao:Play()
                else
                    CaixaGrupoSuporte.Size = AlvoTamanho
                end
            end

            table.insert(CaixaGrupo.Connections, CaixaGrupoLista:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                if CaixaGrupo.Visible == false or CaixaGrupo.Destroyed then
                    return
                end

                CaixaGrupo:Resize()
            end))

            function CaixaGrupo:SetDescription(Descricao: string | nil)
                CaixaGrupoDescricao.Text = Descricao or ""
                CaixaGrupoDescricao.Visible = (Descricao ~= nil)

                CaixaGrupo:Resize()
            end

            function CaixaGrupo:SetCollapsed(Recolhido: boolean)
                if Info.DisableCollapsing == true then return end
                CaixaGrupo.Collapsed = Recolhido

                if RecolherSetaInterpolacao then
                    PararInterpolacao(RecolherSetaInterpolacao, true)
                    RecolherSetaInterpolacao = nil
                end

                local AlvoRotacao = if Recolhido then 0 else 180

                CaixaGrupoConteiner.Visible = not Recolhido
                if Library.Animations and Library.Animations.Groupbox then
                    local TweenInfo = Library.GroupboxTweenInfo or TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                    local Interpolacao = TweenService:Create(CaixaGrupoRecolherSeta, TweenInfo, { Rotation = AlvoRotacao })
                    RecolherSetaInterpolacao = Interpolacao

                    local Conexao; Conexao = Library:GiveSignal(Interpolacao.Completed:Connect(function()
                        if Conexao then
                            Conexao:Disconnect()
                        end

                        if RecolherSetaInterpolacao == Interpolacao then
                            PararInterpolacao(RecolherSetaInterpolacao, true)
                            RecolherSetaInterpolacao = nil
                        end
                    end))

                    Interpolacao:Play()
                else
                    CaixaGrupoRecolherSeta.Rotation = AlvoRotacao
                end

                CaixaGrupo:Resize()
            end

            function CaixaGrupo:ToggleCollapsed()
                if Info.DisableCollapsing == true then return end
                CaixaGrupo:SetCollapsed(not CaixaGrupo.Collapsed)
            end

            Library:MakeBoxPopOut(CaixaGrupo, {
                Enabled = Info.PopOut ~= false,
                MaxPopOutHeight = Info.MaxPopOutHeight,
                PopOutWidth = Info.PopOutWidth,

                Header = CaixaGrupoTopo,
                Children = function()
                    local Filhos = {}
                    for _, Filho in CaixaSuporte:GetChildren() do
                        if Filho:IsA("GuiObject") and Filho ~= CaixaGrupo.PopOutPlaceholder then
                            table.insert(Filhos, Filho)
                        end
                    end
                    return Filhos
                end,

                Before = function()
                    CaixaGrupoRecolherSeta.Visible = false
                end,
                After = function()
                    CaixaGrupoRecolherSeta.Visible = Info.DisableCollapsing ~= true
                    CaixaGrupo:Resize()
                end
            })

            function CaixaGrupo:Destroy()
                if CaixaGrupo.PoppedOut then
                    CaixaGrupo:SetPoppedOut(false)
                end

                CaixaGrupo.Destroyed = true

                if RedimensionarInterpolacao then
                    PararInterpolacao(RedimensionarInterpolacao, true)
                    RedimensionarInterpolacao = nil
                end

                if RecolherSetaInterpolacao then
                    PararInterpolacao(RecolherSetaInterpolacao, true)
                    RecolherSetaInterpolacao = nil
                end

                if CaixaGrupo.Connections then
                    for _, Conexao in CaixaGrupo.Connections do
                        Conexao:Disconnect()
                    end
                end

                for _, Elemento in CaixaGrupo.Elements do
                    if Elemento.Destroy then
                        Elemento:Destroy()
                    end
                end
                table.clear(CaixaGrupo.Elements)

                for _, SubCaixaDep in CaixaGrupo.DependencyBoxes do
                    if SubCaixaDep.Destroy then
                        SubCaixaDep:Destroy()
                    end
                end
                table.clear(CaixaGrupo.DependencyBoxes)

                if CaixaGrupoSuporte then
                    CaixaGrupoSuporte:Destroy()
                end

                if CaixaSuporte then
                    CaixaSuporte:Destroy()
                end
            end

            function CaixaGrupo:SetVisible(Visivel: boolean)
                CaixaGrupo.Visible = Visivel
                CaixaSuporte.Visible = Visivel
                SyncPopOutVisibility(CaixaGrupo)

                if Visivel == true and Library.Searching then
                    Library:UpdateSearch(Library.SearchText)
                end
            end

            function CaixaGrupo:Show()
                CaixaGrupo:SetVisible(true)
            end

            function CaixaGrupo:Hide()
                CaixaGrupo:SetVisible(false)
            end

            if Info.DisableCollapsing ~= true then
                CaixaGrupoRecolherSeta.MouseButton1Click:Connect(function()
                    CaixaGrupo:ToggleCollapsed()
                end)
            end

            CaixaGrupo.AddTabbox = AdicionarCaixaAbas
            setmetatable(CaixaGrupo, BaseCaixaGrupo)

            CaixaGrupo:Resize()
            Aba.Groupboxes[Info.Name] = CaixaGrupo

            if Info.Visible == false then
                CaixaGrupo:Hide()
            end

            if Info.DisableCollapsing ~= true and Info.Collapsed == true then
                CaixaGrupo:SetCollapsed(true)
            end

            return CaixaGrupo
        end

        function Aba:AddLeftGroupbox(Name, IconName, Visivel, Recolhido, DesativarRecolhimento)
            return Aba:AddGroupbox({ Side = 1, Name = Name, IconName = IconName, Visible = Visivel, Collapsed = Recolhido, DisableCollapsing = DesativarRecolhimento })
        end

        function Aba:AddRightGroupbox(Name, IconName, Visivel, Recolhido, DesativarRecolhimento)
            return Aba:AddGroupbox({ Side = 2, Name = Name, IconName = IconName, Visible = Visivel, Collapsed = Recolhido, DisableCollapsing = DesativarRecolhimento })
        end

        function Aba:Hover(Pairando)
            if Library.ActiveTab == Aba then
                return
            end

            TweenService:Create(TabLabel, Library.TweenInfo, {
                TextTransparency = Pairando and 0.25 or 0.5,
            }):Play()
            if TabIcon then
                TweenService:Create(TabIcon, Library.TweenInfo, {
                    ImageTransparency = Pairando and 0.25 or 0.5,
                }):Play()
            end
        end

        function Aba:Show()
            if Library.ActiveTab == Aba then
                return
            end

            if Library.ActiveTab then
                Library.ActiveTab:Hide()
            end

            TweenService:Create(AbaBotao, Library.TweenInfo, {
                BackgroundTransparency = 0,
            }):Play()
            if TabIndicator then
                TweenService:Create(TabIndicator, Library.TweenInfo, {
                    BackgroundTransparency = 0,
                }):Play()
            end
            TweenService:Create(TabLabel, Library.TweenInfo, {
                TextTransparency = 0,
            }):Play()
            if TabIcon then
                TweenService:Create(TabIcon, Library.TweenInfo, {
                    ImageTransparency = 0,
                }):Play()
            end

            if Descricao then
                Janela:ShowTabInfo(Name, Descricao)
            end

            Library:PlayTabAnimation(Aba, true)
            Aba:RefreshSides()

            Library.ActiveTab = Aba

            if Library.Searching then
                Library:UpdateSearch(Library.SearchText)
            end
        end

        function Aba:Hide()
            TweenService:Create(AbaBotao, Library.TweenInfo, {
                BackgroundTransparency = 1,
            }):Play()

            if TabIndicator then
                TweenService:Create(TabIndicator, Library.TweenInfo, {
                    BackgroundTransparency = 1,
                }):Play()
            end

            TweenService:Create(TabLabel, Library.TweenInfo, {
                TextTransparency = 0.5,
            }):Play()

            if TabIcon then
                TweenService:Create(TabIcon, Library.TweenInfo, {
                    ImageTransparency = 0.5,
                }):Play()
            end

            Library:PlayTabAnimation(Aba, false)
            Janela:HideTabInfo()

            Library.PreviousTab = Aba
            Library.ActiveTab = nil
        end

        function Aba:SetVisible(Visivel: boolean)
            AbaBotao.Visible = Visivel

            if not Visivel and Library.ActiveTab == Aba then
                Aba:Hide()
            end
        end

        function Aba:SetOrder(NovoOrdem: number)
            Ordem = NovoOrdem
            AbaBotao.LayoutOrder = Ordem
        end

        function Aba:SetTooltip(Texto_2: string?)
            Aba.Tooltip = Texto_2

            if Aba.TooltipTable then
                Aba.TooltipTable:Destroy()
                Aba.TooltipTable = nil
            end

            if typeof(Texto_2) == "string" then
                Aba.TooltipTable = Library:AddTooltip(Texto_2, nil, AbaBotao)
            end
        end

        function Aba:Destroy()
            Aba.Destroyed = true

            if Aba.Connections then
                for _, Conexao in Aba.Connections do
                    Conexao:Disconnect()
                end
            end

            if Aba.TooltipTable then
                Aba.TooltipTable:Destroy()
                Aba.TooltipTable = nil
            end

            for _, CaixaGrupo in Aba.Groupboxes do
                if CaixaGrupo.Destroy then
                    CaixaGrupo:Destroy()
                end
            end
            table.clear(Aba.Groupboxes)

            for _, CaixaAbas in Aba.Tabboxes do
                if CaixaAbas.Destroy then
                    CaixaAbas:Destroy()
                end
            end
            table.clear(Aba.Tabboxes)

            for _, DepCaixaGrupo in Aba.DependencyGroupboxes do
                if DepCaixaGrupo.Destroy then
                    DepCaixaGrupo:Destroy()
                end
            end

            if AbaConteiner then
                AbaConteiner:Destroy()
            end

            if AbaBotao then
                for Indice_2, Entrada in Library.TabButtons do
                    if typeof(Entrada) == "table" and Entrada.Button == AbaBotao then
                        table.remove(Library.TabButtons, Indice_2)
                        break
                    end
                end

                AbaBotao:Destroy()
            end

            Library.Tabs[Name] = nil
        end

        if typeof(Dica) == "string" then
            Aba.TooltipTable = Library:AddTooltip(Dica, nil, AbaBotao)
        end

        if not Library.ActiveTab then
            Aba:Show()
        end

        AbaBotao.MouseEnter:Connect(function()
            Aba:Hover(true)
        end)
        AbaBotao.MouseLeave:Connect(function()
            Aba:Hover(false)
        end)
        AbaBotao.MouseButton1Click:Connect(Aba.Show)

        Library.Tabs[Name] = Aba

        return Aba
    end

    function Janela:AddKeyTab(...)
        local Name = nil
        local Icon = nil
        local Descricao = nil
        local Dica = nil
        local Ordem = nil

        if select("#", ...) == 1 and typeof(...) == "table" then
            local Info = select(1, ...)
            Name = Info.Name or "Tab"
            Icon = Info.Icon
            Descricao = Info.Description
            Dica = Info.Tooltip
            Ordem = Info.Order
        else
            Name = select(1, ...) or "Tab"
            Icon = select(2, ...)
            Descricao = select(3, ...)
            Ordem = select(4, ...)
        end

        if not tonumber(Ordem) then
            Ordem = #Abas:GetChildren()
        end

        Icon = Icon or "key"

        local AbaBotao: TextButton
        local TabIndicator
        local TabLabel
        local TabIcon

        local AbaConteiner

        Icon = if Icon == "key" then TeclaIcone else Library:GetCustomIcon(Icon)
        do
            AbaBotao = Novo("TextButton", {
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 40),
                Text = "",
                LayoutOrder = Ordem,
                Parent = Abas,
            })
            Novo("UICorner", {
                CornerRadius = UDim.new(0, AbaBotoesEstilo.CornerRadius),
                Parent = AbaBotao,
            })

            if AbaBotoesEstilo.Indicator then
                TabIndicator = Novo("Frame", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundColor3 = "AccentColor",
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, -2, 0.5, 0),
                    Size = UDim2.fromOffset(AbaBotoesEstilo.IndicatorWidth, AbaBotoesEstilo.IndicatorHeight),
                    Parent = AbaBotao,
                })

                Novo("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = TabIndicator,
                })
            end

            local BotaoSuporte = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Parent = AbaBotao,
            })
            local BotaoPreenchimentoInterno = Novo("UIPadding", {
                PaddingBottom = UDim.new(0, EhCompacto and 6 or 11),
                PaddingLeft = UDim.new(0, EhCompacto and 6 or 12),
                PaddingRight = UDim.new(0, EhCompacto and 6 or 12),
                PaddingTop = UDim.new(0, EhCompacto and 6 or 11),
                Parent = BotaoSuporte,
            })

            TabLabel = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(30, 0),
                Size = UDim2.new(1, -30, 1, 0),
                Text = Name,
                TextSize = 16,
                TextTransparency = 0.5,
                TextXAlignment = Enum.TextXAlignment.Left,
                Visible = not EhCompacto,
                Parent = BotaoSuporte,
            })

            if Icon then
                TabIcon = Novo("ImageLabel", {
                    ImageColor3 = Icon.Custom and "WhiteColor" or "AccentColor",
                    ImageTransparency = 0.5,
                    ScaleType = Enum.ScaleType.Fit,
                    Size = UDim2.fromScale(1, 1),
                    SizeConstraint = EhCompacto and Enum.SizeConstraint.RelativeXY or Enum.SizeConstraint.RelativeYY,
                    Parent = BotaoSuporte,
                })
                Library:ApplyLucideIcon(TabIcon, Icon)
            end

            table.insert(Library.TabButtons, {
                Label = TabLabel,
                Padding = BotaoPreenchimentoInterno,
                Icon = TabIcon,
            })

            AbaConteiner = Novo("ScrollingFrame", {
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                CanvasSize = UDim2.fromScale(0, 0),
                ScrollBarThickness = 0,
                Position = UDim2.fromScale(0, 0),
                Size = UDim2.fromScale(1, 1),
                Visible = false,
                Parent = Conteiner,
            })
            Novo("UIListLayout", {
                HorizontalAlignment = Enum.HorizontalAlignment.Center,
                Padding = UDim.new(0, 8),
                VerticalAlignment = Enum.VerticalAlignment.Center,
                Parent = AbaConteiner,
            })
            Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 1),
                PaddingRight = UDim.new(0, 1),
                Parent = AbaConteiner,
            })
        end

        local Aba = {
            Description = Descricao,
            IsKeyTab = true,

            Tooltip = Dica,
            TooltipTable = nil,

            Elements = {},

            Window = Janela,
            Button = AbaBotao,
            Container = AbaConteiner
        }

        function Aba:AddKeyBox(Retorno)
            assert(typeof(Retorno) == "function", "Callback must be a function")

            local Suporte = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(0.75, 0, 0, 21),
                Parent = AbaConteiner,
            })

            local Caixa = Novo("TextBox", {
                BackgroundColor3 = "MainColor",
                PlaceholderText = "Chave",
                Size = UDim2.new(1, -71, 1, 0),
                TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Suporte,
            })
            Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 8),
                Parent = Caixa,
            })
            local CaixaBorda = Novo("UIStroke", {
                Color = "OutlineColor",
                Parent = Caixa,
            })
            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Caixa,
                })
            )

            Caixa.Focused:Connect(function()
                Library.Registry[CaixaBorda].Color = "AccentColor"
                TweenService:Create(CaixaBorda, Library.TweenInfo, {
                    Color = Library.Scheme.AccentColor,
                }):Play()
            end)

            Caixa.FocusLost:Connect(function()
                Library.Registry[CaixaBorda].Color = "OutlineColor"
                TweenService:Create(CaixaBorda, Library.TweenInfo, {
                    Color = Library.Scheme.OutlineColor,
                }):Play()
            end)

            local Botao = Novo("TextButton", {
                AnchorPoint = Vector2.new(1, 0),
                BackgroundColor3 = "MainColor",
                Position = UDim2.fromScale(1, 0),
                Size = UDim2.new(0, 63, 1, 0),
                Text = "Executar",
                TextSize = 14,
                TextTransparency = 0.4,
                Parent = Suporte,
            })
            Novo("UIStroke", {
                Color = "OutlineColor",
                Parent = Botao,
            })
            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Botao,
                })
            )

            Botao.MouseEnter:Connect(function()
                TweenService:Create(Botao, Library.TweenInfo, {
                    TextTransparency = 0,
                }):Play()
            end)

            Botao.MouseLeave:Connect(function()
                TweenService:Create(Botao, Library.TweenInfo, {
                    TextTransparency = 0.4,
                }):Play()
            end)

            Botao.InputBegan:Connect(function(Entrada_2)
                if not EhCliqueEntrada(Entrada_2) then
                    return
                end

                if not Library:MouseIsOverFrame(Botao, Entrada_2.Position) then
                    return
                end

                Retorno(Caixa.Text)
            end)
        end

        function Aba:Destroy()
            if AbaConteiner then
                AbaConteiner:Destroy()
            end

            if AbaBotao then
                for Indice_2, Entrada in Library.TabButtons do
                    if typeof(Entrada) == "table" and Entrada.Button == AbaBotao then
                        table.remove(Library.TabButtons, Indice_2)
                        break
                    end
                end

                AbaBotao:Destroy()
            end

            Library.Tabs[Name] = nil
        end

        function Aba:SetOrder(NovoOrdem: number)
            Ordem = NovoOrdem
            AbaBotao.LayoutOrder = Ordem
        end

        function Aba:RefreshSides() end
        function Aba:Resize() end
        function Aba:UpdateCorners() end

        function Aba:Hover(Pairando)
            if Library.ActiveTab == Aba then
                return
            end

            TweenService:Create(TabLabel, Library.TweenInfo, {
                TextTransparency = Pairando and 0.25 or 0.5,
            }):Play()
            if TabIcon then
                TweenService:Create(TabIcon, Library.TweenInfo, {
                    ImageTransparency = Pairando and 0.25 or 0.5,
                }):Play()
            end
        end

        function Aba:Show()
            if Library.ActiveTab == Aba then
                return
            end

            if Library.ActiveTab then
                Library.ActiveTab:Hide()
            end

            TweenService:Create(AbaBotao, Library.TweenInfo, {
                BackgroundTransparency = 0,
            }):Play()

            if TabIndicator then
                TweenService:Create(TabIndicator, Library.TweenInfo, {
                    BackgroundTransparency = 0,
                }):Play()
            end

            TweenService:Create(TabLabel, Library.TweenInfo, {
                TextTransparency = 0,
            }):Play()

            if TabIcon then
                TweenService:Create(TabIcon, Library.TweenInfo, {
                    ImageTransparency = 0,
                }):Play()
            end

            Library:PlayTabAnimation(Aba, true)

            if Descricao then
                Janela:ShowTabInfo(Name, Descricao)
            end

            Aba:RefreshSides()

            Library.ActiveTab = Aba

            if Library.Searching then
                Library:UpdateSearch(Library.SearchText)
            end
        end

        function Aba:Hide()
            TweenService:Create(AbaBotao, Library.TweenInfo, {
                BackgroundTransparency = 1,
            }):Play()

            if TabIndicator then
                TweenService:Create(TabIndicator, Library.TweenInfo, {
                    BackgroundTransparency = 1,
                }):Play()
            end

            TweenService:Create(TabLabel, Library.TweenInfo, {
                TextTransparency = 0.5,
            }):Play()

            if TabIcon then
                TweenService:Create(TabIcon, Library.TweenInfo, {
                    ImageTransparency = 0.5,
                }):Play()
            end

            Library:PlayTabAnimation(Aba, false)
            Janela:HideTabInfo()

            Library.PreviousTab = Aba
            Library.ActiveTab = nil
        end

        function Aba:SetVisible(Visivel: boolean)
            AbaBotao.Visible = Visivel

            if not Visivel and Library.ActiveTab == Aba then
                Aba:Hide()
            end
        end

        function Aba:SetTooltip(Texto_2: string?)
            Aba.Tooltip = Texto_2

            if Aba.TooltipTable then
                Aba.TooltipTable:Destroy()
                Aba.TooltipTable = nil
            end

            if typeof(Texto_2) == "string" then
                Aba.TooltipTable = Library:AddTooltip(Texto_2, nil, AbaBotao)
            end
        end

        if typeof(Dica) == "string" then
            Aba.TooltipTable = Library:AddTooltip(Dica, nil, AbaBotao)
        end

        if not Library.ActiveTab then
            Aba:Show()
        end

        AbaBotao.MouseEnter:Connect(function()
            Aba:Hover(true)
        end)
        AbaBotao.MouseLeave:Connect(function()
            Aba:Hover(false)
        end)
        AbaBotao.MouseButton1Click:Connect(Aba.Show)

        Aba.Container = AbaConteiner
        setmetatable(Aba, BaseCaixaGrupo)

        Library.Tabs[Name] = Aba

        return Aba
    end

