        })

        local Dialogo = {
            Destroyed = false,
            Elements = {},
            Container = DialogoConteiner,
            OutsideClickDismiss = Info.OutsideClickDismiss,
        }

        function Dialogo:Resize()
            local MaxLargura = (PrincipalQuadro.AbsoluteSize.X / Library.DPIScale) * 0.75
            local MinLargura = 400

            local TotalBotaoLargura = 0
            local BotaoContagem = 0
            local TemBotoes = false

            for _, BotaoEnvolver in RodapeBotoesLista do
                TemBotoes = true
                BotaoContagem = BotaoContagem + 1
                TotalBotaoLargura = TotalBotaoLargura + BotaoEnvolver.Container.Size.X.Offset
            end

            local AlvoLargura = MinLargura
            if TemBotoes then
                local NecessarioLargura = TotalBotaoLargura + ((BotaoContagem - 1) * 8) + 30
                AlvoLargura = math.max(MinLargura, math.min(NecessarioLargura, MaxLargura))
            end

            DialogoQuadro.Size = UDim2.fromOffset(AlvoLargura, 0)

            local _DescX, DescY = Library:GetTextBounds(DescricaoRotulo.Text, Library.Scheme.Font, 14, AlvoLargura - 30)
            DescricaoRotulo.Size = UDim2.new(1, 0, 0, DescY)

            local TemElementos = false
            for _, v in DialogoConteiner:GetChildren() do
                if not v:IsA("UIListLayout") and not v:IsA("UIPadding") then
                    TemElementos = true
                    break
                end
            end
            DialogoConteiner.Visible = TemElementos

            BotoesSuporte.Visible = TemBotoes
            _Sep2.Visible = TemBotoes
        end

        function Dialogo:SetTitle(Titulo)
            TituloRotulo.Text = Titulo
            Dialogo:Resize()
        end

        function Dialogo:SetDescription(Descricao)
            DescricaoRotulo.Text = Descricao
            Dialogo:Resize()
        end

        function Dialogo:Dismiss()
            if Dialogo.Destroyed then
                return
            end

            Dialogo.Destroyed = true

            if Library.ActiveDialog == Dialogo then
                Library.ActiveDialog = nil
            end

            for Indice_2 = #Dialogo.Elements, 1, -1 do
                local Elemento = Dialogo.Elements[Indice_2]
                if Elemento and Elemento.Destroy then
                    Elemento:Destroy()
                end
            end
            table.clear(Dialogo.Elements)

            local FecharInterpolacao = TweenService:Create(DialogoEscala, Library.TweenInfo, { Scale = 0.95 })
            TweenService:Create(DialogoSobreposicao, Library.TweenInfo, { BackgroundTransparency = 1 }):Play()
            FecharInterpolacao:Play()

            task.delay(Library.TweenInfo.Time, function()
                DialogoSobreposicao:Destroy()
            end)
            Library.Dialogues[Indice] = nil
        end

        DialogoSobreposicao.MouseButton1Click:Connect(function()
            if Info.OutsideClickDismiss then
                Dialogo:Dismiss()
            end
        end)

        function Dialogo:RemoveFooterButton(BotaoIndice)
            if RodapeBotoesLista[BotaoIndice] then
                RodapeBotoesLista[BotaoIndice].Container:Destroy()
                RodapeBotoesLista[BotaoIndice] = nil
            end
        end

        function Dialogo:SetButtonDisabled(BotaoIndice, Desativado)
            if RodapeBotoesLista[BotaoIndice] and type(RodapeBotoesLista[BotaoIndice].SetDisabled) == "function" then
                RodapeBotoesLista[BotaoIndice]:SetDisabled(Desativado)
            end
        end

        function Dialogo:SetButtonOrder(BotaoIndice, Ordem)
            if RodapeBotoesLista[BotaoIndice] and RodapeBotoesLista[BotaoIndice].Container then
                RodapeBotoesLista[BotaoIndice].Container.LayoutOrder = Ordem
            end
        end

        function Dialogo:AddFooterButton(BotaoIndice, BotaoInfo)
            Dialogo:RemoveFooterButton(BotaoIndice)

            local AguardarTempo = BotaoInfo.WaitTime or 0

            local BotaoConteiner = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(0, 26),
                LayoutOrder = BotaoInfo.Order or 0,
                ZIndex = 2,
                Parent = BotoesSuporte,
            })

            local BotaoCor = "MainColor"
            local BotaoContorno = "OutlineColor"
            local Variante = BotaoInfo.Variant or "Primary"

            if Variante == "Primary" then
                BotaoCor = "FontColor"
                BotaoContorno = "FontColor"
            elseif Variante == "Secondary" then
                BotaoCor = "MainColor"
                BotaoContorno = "OutlineColor"
            elseif Variante == "Destructive" then
                BotaoCor = "DestructiveColor"
                BotaoContorno = "DestructiveColor"
            elseif Variante == "Ghost" then
                BotaoCor = "BackgroundColor"
                BotaoContorno = "BackgroundColor"
            end

            local TextoBotao = Novo("TextButton", {
                BackgroundColor3 = BotaoCor,
                BorderColor3 = BotaoContorno,
                BackgroundTransparency = AguardarTempo > 0 and 0.5 or 0,
                Size = UDim2.fromOffset(0, 26),
                Text = "",
                AutoButtonColor = false,
                ZIndex = 2,
                Parent = BotaoConteiner,
            })
            Library:AddOutline(TextoBotao)
            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius),
                    Parent = TextoBotao
                })
            )

            local _BotaoPreenchimentoInterno = Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 15),
                PaddingRight = UDim.new(0, 15),
                Parent = TextoBotao,
            })

            local TextoCor = Library.Scheme.FontColor
            if Variante == "Primary" then
                TextoCor = Library.Scheme.BackgroundColor
            elseif Variante == "Destructive" then
                TextoCor = Color3.new(1, 1, 1)
            end

            local BotaoRotulo = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Text = BotaoInfo.Title or BotaoIndice,
                TextColor3 = TextoCor,
                TextTransparency = AguardarTempo > 0 and 0.5 or 0,
                TextSize = 14,
                ZIndex = 2,
                Parent = TextoBotao,
            })

            local RotuloX, _ = Library:GetTextBounds(BotaoRotulo.Text, Library.Scheme.Font, 14, 250)
            BotaoConteiner.Size = UDim2.fromOffset(RotuloX + 30, 26)
            TextoBotao.Size = UDim2.fromOffset(RotuloX + 30, 26)

            local ProgressoBarra
            if AguardarTempo > 0 then
                ProgressoBarra = Novo("Frame", {
                    BackgroundColor3 = "AccentColor",
                    BorderSizePixel = 0,
                    Position = UDim2.new(0, 0, 1, -2),
                    Size = UDim2.new(0, 0, 0, 2),
                    ZIndex = 2,
                    Parent = TextoBotao,
                })
                table.insert(
                    Library.Corners,
                    Novo("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius),
                        Parent = ProgressoBarra
                    })
                )
            end

            local EhAtivo = AguardarTempo <= 0

            local BotaoEnvolver_2 = {
                Container = BotaoConteiner,
                SetDisabled = function(self, Desativado)
                    EhAtivo = not Desativado
                    if Desativado then
                        TweenService:Create(TextoBotao, Library.TweenInfo, { BackgroundTransparency = 0.5 }):Play()
                        TweenService:Create(BotaoRotulo, Library.TweenInfo, { TextTransparency = 0.5 }):Play()
                    else
                        TweenService:Create(TextoBotao, Library.TweenInfo, { BackgroundTransparency = 0 }):Play()
                        TweenService:Create(BotaoRotulo, Library.TweenInfo, { TextTransparency = 0 }):Play()
                    end
                end
            }

            local AtivoCor = typeof(BotaoCor) == "Color3" and BotaoCor or Library.Scheme[BotaoCor]
            local PairarCor = Variante == "Ghost" and Library.Scheme.MainColor or Library:GetBetterColor(AtivoCor, 10)

            TextoBotao.MouseEnter:Connect(function()
                if not EhAtivo then return end
                TweenService:Create(TextoBotao, Library.TweenInfo, {
                    BackgroundColor3 = PairarCor
                }):Play()
            end)
            TextoBotao.MouseLeave:Connect(function()
                if not EhAtivo then return end
                TweenService:Create(TextoBotao, Library.TweenInfo, {
                    BackgroundColor3 = AtivoCor
                }):Play()
            end)

            TextoBotao.MouseButton1Click:Connect(function()
                if not EhAtivo then return end
                if BotaoInfo.Callback then
                    BotaoInfo.Callback(Dialogo)
                end
                if Info.AutoDismiss then
                    Dialogo:Dismiss()
                end
            end)

            if AguardarTempo > 0 then
                TweenService:Create(ProgressoBarra, TweenInfo.new(AguardarTempo, Enum.EasingStyle.Linear), {
                    Size = UDim2.new(1, 0, 0, 2)
                }):Play()

                task.delay(AguardarTempo, function()
                    BotaoEnvolver_2:SetDisabled(false)
                    if ProgressoBarra then
                        TweenService:Create(ProgressoBarra, Library.TweenInfo, {
                            BackgroundTransparency = 1
                        }):Play()
                    end
                end)
            end

            RodapeBotoesLista[BotaoIndice] = BotaoEnvolver_2
        end

        for BIndice, BInfo in Info.FooterButtons do
            if type(BIndice) == "number" and BInfo.Id then BIndice = BInfo.Id end
            Dialogo:AddFooterButton(BIndice, BInfo)
        end

        setmetatable(Dialogo, BaseCaixaGrupo)
        Library.Dialogues[Indice] = Dialogo

        Dialogo:Resize()

        Library.ActiveDialog = Dialogo
        return Dialogo
    end

    local GuiPropriedades = { "BackgroundTransparency" }
    local ImagemPropriedades = { "BackgroundTransparency", "ImageTransparency" }
    local TextoPropriedades = { "BackgroundTransparency", "TextTransparency" }
    local BordaPropriedades = { "Transparency" }

    local function TransicaoInstancia(Desc, Propriedades)
        local Cache = TransparenciaCache[Desc]
        if not Cache then
            Cache = {}
            TransparenciaCache[Desc] = Cache
        end

        for _, Prop in Propriedades do
            if not Library.Toggled then
                Cache[Prop] = Desc[Prop]
            end

            if Cache[Prop] ~= nil and Cache[Prop] ~= 1 then
                TweenService:Create(Desc, Library.WindowAnimationInfo, {
                    [Prop] = Library.Toggled and Cache[Prop] or 1,
                }):Play()
            end
        end
    end

    function Janela:Toggle(Valor: boolean?)
        if Desvanecendo then
            return
        end

        if Library.ActiveLoading then
            if Valor == true then
                return
            end

            if not Library.Toggled then
                return
            end
        end

        if typeof(Valor) == "boolean" then
            Library.Toggled = Valor
        else
            Library.Toggled = not Library.Toggled
        end

        if Library.Animations and Library.Animations.ToggleWindow == true then
            local TransicaoTempo = Library.WindowAnimationInfo.Time
            Desvanecendo = true

            if Library.Toggled then
                PrincipalQuadro.Visible = true
            end

            if Library.Toggled then
                TransicaoInstancia(PrincipalQuadro, { "BackgroundTransparency" })
                task.wait(TransicaoTempo / 2)
            else
                task.delay(TransicaoTempo / 2, TransicaoInstancia, PrincipalQuadro, { "BackgroundTransparency" })
            end

            for _, Instance in PrincipalQuadro:GetDescendants() do
                if Instance == TopoBarra then
                    continue
                end

                if Instance:IsA("GuiObject") then
                    local ClasseNome = Instance.ClassName
                    if ClasseNome == "ImageLabel" or ClasseNome == "ImageButton" then
                        TransicaoInstancia(Instance, ImagemPropriedades)
                    elseif ClasseNome == "TextLabel" or ClasseNome == "TextBox" or ClasseNome == "TextButton" then
                        TransicaoInstancia(Instance, TextoPropriedades)
                    else
                        TransicaoInstancia(Instance, GuiPropriedades)
                    end
                elseif Instance.ClassName == "UIStroke" then
                    TransicaoInstancia(Instance, BordaPropriedades)
                end
            end

            task.delay(TransicaoTempo, function()
                PrincipalQuadro.Visible = Library.Toggled
                Desvanecendo = false
            end)
        else
            PrincipalQuadro.Visible = Library.Toggled
        end

        if JanelaInfo.UnlockMouseWhileOpen then
            ModalElemento.Modal = Library.Toggled
        end

        if Library.Toggled and not Library.IsMobile then
            local MostrarCursorVinculo = Library.ShowCursorBinding
            Library.OriginalMouseIconEnabled = UserInputService.MouseIconEnabled

            pcall(function() RunService:UnbindFromRenderStep(MostrarCursorVinculo) end)
            RunService:BindToRenderStep(MostrarCursorVinculo, Enum.RenderPriority.Last.Value, function()
                UserInputService.MouseIconEnabled = not Library.ShowCustomCursor

                Cursor.Position = UDim2.fromOffset(Mouse.X, Mouse.Y)
                Cursor.Visible = Library.ShowCustomCursor

                if Library.Unloaded == true or not (Library.Toggled and ScreenGui and ScreenGui.Parent) then
                    RestaurarMouseIcone()
                end
            end)
        elseif not Library.Toggled then
            RestaurarMouseIcone()
            DicaRotulo.Visible = false

            for _, Opcao in Library.Options do
                if Opcao.Type == "ColorPicker" then
                    Opcao.ColorMenu:Close()
                    Opcao.ContextMenu:Close()
                elseif Opcao.Type == "Dropdown" or Opcao.Type == "KeyPicker" then
                    Opcao.Menu:Close()
                end
            end
        end
    end

    function Library:Toggle(Valor: boolean?)
        return Janela:Toggle(Valor)
    end

    if JanelaInfo.EnableSidebarResize then
        local Limite = (JanelaInfo.MinSidebarWidth + JanelaInfo.SidebarCompactWidth) * JanelaInfo.SidebarCollapseThreshold
        local InicioPos, InicioLargura
        local Arrastando = false
        local Alterado

        local BarraLateralAlca = Novo("TextButton", {
            AnchorPoint = Vector2.new(0.5, 0),
            BackgroundTransparency = 1,
            Position = UDim2.fromScale(0.5, 0),
            Size = UDim2.new(0, 8, 1, 0),
            Text = "",
            Parent = DivisorLinha,
        })
        BarraLateralAlca.MouseEnter:Connect(function()
            TweenService:Create(DivisorLinha, Library.TweenInfo, {
                BackgroundColor3 = Library:GetLighterColor(Library.Scheme.OutlineColor),
            }):Play()
        end)
        BarraLateralAlca.MouseLeave:Connect(function()
            if Arrastando then
                return
            end
            TweenService:Create(DivisorLinha, Library.TweenInfo, {
                BackgroundColor3 = Library.Scheme.OutlineColor,
            }):Play()
        end)

        BarraLateralAlca.InputBegan:Connect(function(Entrada_2: InputObject)
            if not EhCliqueEntrada(Entrada_2) then
                return
            end

            Library.CantDragForced = true

            InicioPos = Entrada_2.Position
            InicioLargura = Janela:GetSidebarWidth()
            Arrastando = true

            Alterado = Entrada_2.Changed:Connect(function()
                if Entrada_2.UserInputState ~= Enum.UserInputState.End then
                    return
                end

                Library.CantDragForced = false
                TweenService:Create(DivisorLinha, Library.TweenInfo, {
                    BackgroundColor3 = Library.Scheme.OutlineColor,
                }):Play()

                Arrastando = false
                if Alterado and Alterado.Connected then
                    Alterado:Disconnect()
                    Alterado = nil
                end
            end)
        end)

        Library:GiveSignal(UserInputService.InputChanged:Connect(function(Entrada_2: InputObject)
            if not Library.Toggled or not (ScreenGui and ScreenGui.Parent) then
                Arrastando = false
                if Alterado and Alterado.Connected then
                    Alterado:Disconnect()
                    Alterado = nil
                end

                return
            end

            if Arrastando and EhPairarEntrada(Entrada_2) then
                local Delta = Entrada_2.Position - InicioPos
                local Largura = InicioLargura + Delta.X

                if JanelaInfo.DisableCompactingSnap then
                    Janela:SetSidebarWidth(Largura)
                    return
                end

                if Largura > Limite then
                    Janela:SetSidebarWidth(math.max(Largura, JanelaInfo.MinSidebarWidth))
                else
                    Janela:SetSidebarWidth(JanelaInfo.SidebarCompactWidth)
                end
            end
        end))
    end

    Janela:SetAlwaysOnTop(JanelaInfo.AlwaysOnTop)
    if JanelaInfo.EnableCompacting and JanelaInfo.SidebarCompacted then
        Janela:SetSidebarWidth(JanelaInfo.SidebarCompactWidth)
    end
    if JanelaInfo.AutoShow and not Library.ActiveLoading then
        task.spawn(Library.Toggle)
    end

    if Library.IsMobile then
        local AlternadorBotao = Library:AddDraggableButton("Toggle", function()
            Library:Toggle()
        end, true, true)

        local TravarBotao = Library:AddDraggableButton("Lock", function(self)
            Library.CantDragForced = not Library.CantDragForced
            self:SetText(Library.CantDragForced and "Destravar" or "Travar")
        end, true, true)

        if JanelaInfo.MobileButtonsSide == "Right" then
            AlternadorBotao.Button.AnchorPoint = Vector2.new(1, 0)
            AlternadorBotao.Button.Position = UDim2.new(1, -6, 0, 6)

            TravarBotao.Button.AnchorPoint = Vector2.new(1, 0)
            TravarBotao.Button.Position = UDim2.new(1, -(AlternadorBotao.Button.Size.X.Offset + 12), 0, 6)
        else
            AlternadorBotao.Button.AnchorPoint = Vector2.new(0, 0)
            AlternadorBotao.Button.Position = UDim2.fromOffset(6, 6)

            TravarBotao.Button.AnchorPoint = Vector2.new(0, 0)
            TravarBotao.Button.Position = UDim2.fromOffset(AlternadorBotao.Button.Size.X.Offset + 12, 6)
        end

        if JanelaInfo.ShowMobileButtons == false then
            AlternadorBotao.Button.Visible = false
            TravarBotao.Button.Visible = false
        end
    end

    Library:GiveSignal(PesquisaCaixa:GetPropertyChangedSignal("Text"):Connect(function()
        Library:UpdateSearch(PesquisaCaixa.Text)
    end))

    Library:GiveSignal(UserInputService.InputBegan:Connect(function(Entrada_2: InputObject)
        if Library.Unloaded then
            return
        end

        if Entrada_2.KeyCode == Enum.KeyCode.Escape then
            
            local FocadoCaixa = UserInputService:GetFocusedTextBox()
            if FocadoCaixa then
                FocadoCaixa:ReleaseFocus()
                return
            end

            if Library.ActiveDialog and Library.ActiveDialog.OutsideClickDismiss ~= false then
                Library.ActiveDialog:Dismiss()
                return
            end

            if AtualMenu then
                AtualMenu:Close()
                return
            end

            return
        end

        if UserInputService:GetFocusedTextBox() then
            return
        end

        if Entrada_2.KeyCode == Library.ToggleKeybind then
            Library:Toggle()
        end
    end))

    Library:GiveSignal(UserInputService.WindowFocused:Connect(function()
        Library.IsRobloxFocused = true
    end))
    Library:GiveSignal(UserInputService.WindowFocusReleased:Connect(function()
        Library.IsRobloxFocused = false
    end))

    Janela.MainFrame = PrincipalQuadro
    Library.Window = Janela

    return Janela
end

function Library:CreateLoading(CarregandoInfo)
    if Library.ActiveLoading then
        warn("Loading GUI already exists, you cannot create multiple Loading GUIs.")
        return Library.ActiveLoading
    end

    CarregandoInfo = Library:Validate(CarregandoInfo, Modelos.Loading)

    local Carregando = {
        CurrentStep = CarregandoInfo.CurrentStep,
        TotalSteps = CarregandoInfo.TotalSteps,

        ShowSidebar = CarregandoInfo.ShowSidebar,
        AutoResizeHeight = CarregandoInfo.AutoResizeHeight,
        AlwaysOnTop = CarregandoInfo.AlwaysOnTop,

        IsError = false,
        Destroyed = false,

        WindowWidth = CarregandoInfo.WindowWidth,
        WindowHeight = CarregandoInfo.WindowHeight,
        BaseWindowHeight = CarregandoInfo.WindowHeight,
        WindowErrorHeight = CarregandoInfo.WindowHeight,

        ContentWidth = CarregandoInfo.ContentWidth,
        SidebarWidth = CarregandoInfo.SidebarWidth,
    }

    local ScreenGui = Novo("ScreenGui", {
        Name = "ResonanceLoading",
        DisplayOrder = 999,
        ResetOnSpawn = false
    })
    PaiUI(ScreenGui)
    Carregando.ScreenGui = ScreenGui
    DefinirSempreAoTopo(ScreenGui, CarregandoInfo.AlwaysOnTop)

    ScreenGui.DescendantRemoving:Connect(function(Instance)
        task.defer(function()
            if Instance.Parent and Instance:IsDescendantOf(ScreenGui) then
                return
            end

            Library:RemoveFromRegistry(Instance)
        end)
    end)

    local PrincipalQuadro = Novo("TextButton", {
        Name = "Main",
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = function()
            return Library:GetBetterColor(Library.Scheme.BackgroundColor, -1)
        end,
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(Carregando.ShowSidebar and (Carregando.ContentWidth + Carregando.SidebarWidth) or Carregando.WindowWidth, Carregando.WindowHeight),
        ClipsDescendants = true,
        Text = "",
        AutoButtonColor = false,
        Parent = ScreenGui,
    })
    Library:AddOutline(PrincipalQuadro)
    table.insert(Library.Corners, Novo("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius), Parent = PrincipalQuadro }))

    local PrincipalEscala = Novo("UIScale", {
        Scale = Library.IsMobile and 0.8 or 1,
        Parent = PrincipalQuadro
    })
    table.insert(Library.Scales, PrincipalEscala)
    Library.ScalesOffset[PrincipalEscala] = Library.IsMobile and 0.2 or 0

    local Conteiner = Novo("Frame", {
        Name = "Content",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(0, 0),
        Size = UDim2.new(0, Carregando.ContentWidth, 1, 0),
        Parent = PrincipalQuadro,
    })

    local LadoBarra = Novo("Frame", {
        Name = "SideBar",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(Carregando.ContentWidth, 0),
        Size = UDim2.new(0, Carregando.ShowSidebar and Carregando.SidebarWidth or 0, 1, 0),
        ClipsDescendants = true,
        Visible = Carregando.ShowSidebar,
        Parent = PrincipalQuadro,
    })
    local BarraLateralCanto = Novo("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius), Parent = LadoBarra })
    table.insert(Library.Corners, BarraLateralCanto)

    Library:AddOutline(LadoBarra)

    local BarraLateralDivisor = Novo("Frame", {
        BackgroundColor3 = "OutlineColor",
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(0, 0),
        Size = UDim2.new(0, 1, 1, 0),
        Visible = Carregando.ShowSidebar,
        Parent = LadoBarra,
    })

    local TopoBarra = Novo("Frame", {
        Name = "TopBar",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 48),
        ZIndex = 2,
        Parent = Conteiner,
    })
    Library:MakeDraggable(PrincipalQuadro, TopoBarra, true, true)

    local TituloSuporte = Novo("Frame", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        Parent = TopoBarra,
    })
    Novo("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 6),
        Parent = TituloSuporte,
    })
    Novo("UIPadding", {
        PaddingLeft = UDim.new(0, 12),
        Parent = TituloSuporte,
    })

    if CarregandoInfo.Icon then
        local Icon = Library:GetCustomIcon(CarregandoInfo.Icon)
        local _JanelaIcone = Novo("ImageLabel", {
            Size = CarregandoInfo.IconSize,
            Parent = TituloSuporte,
        })
        if Icon then
            Library:ApplyLucideIcon(_JanelaIcone, Icon)
        end
    else
        local _JanelaIcone = Novo("TextLabel", {
            BackgroundTransparency = 1,
            Size = CarregandoInfo.IconSize,
            Text = CarregandoInfo.Title:sub(1, 1),
            TextScaled = true,
            Visible = false,
            Parent = TituloSuporte,
        })
    end

    local TituloX = Library:GetTextBounds(
        CarregandoInfo.Title,
        Library.Scheme.Font,
        20,
        (TituloSuporte.AbsoluteSize.X / Library.DPIScale) - (CarregandoInfo.Icon and (CarregandoInfo.IconSize.X.Offset + 6) or 0) - 12
    )
    local _JanelaTitulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
        Size = UDim2.new(0, TituloX, 1, 0),
        Text = CarregandoInfo.Title,
        TextSize = 20,
        Parent = TituloSuporte,
    })

    Library:MakeLine(Conteiner, {
        Position = UDim2.fromOffset(0, 48),
        Size = UDim2.new(1, 0, 0, 1),
    })

    local InternoConteudo = Novo("Frame", {
        Name = "InnerContent",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(0, 49),
        Size = UDim2.new(1, 0, 1, -49),
        Parent = Conteiner,
    })

    Novo("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 12),
        Parent = InternoConteudo,
    })

    local IconeSuporte = Novo("Frame", {
        Name = "IconHolder",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(64, 64),
        Parent = InternoConteudo,
    })

    local CarregadorIcone = Library:GetCustomIcon(CarregandoInfo.LoadingIcon)
    local CarregandoIcone = Novo("ImageLabel", {
        Name = "LoaderIcon",
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromScale(1, 1),
        ImageColor3 = CarregandoInfo.LoadingIconColor or ((CarregandoInfo.LoadingIcon == Modelos.Loading.LoadingIcon) and "AccentColor" or "WhiteColor"),
        Parent = IconeSuporte,
    })
    if CarregadorIcone then
        Library:ApplyLucideIcon(CarregandoIcone, CarregadorIcone)
    end

    local RotacaoInterpolacao
    if CarregandoInfo.LoadingIconTweenTime > 0 then
        RotacaoInterpolacao = TweenService:Create(
            CarregandoIcone,
            TweenInfo.new(CarregandoInfo.LoadingIconTweenTime, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, -1),
            { Rotation = 360 }
        )
        RotacaoInterpolacao:Play()
    end

    local MensagemRotulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
        AutomaticSize = Carregando.AutoResizeHeight and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
        Size = Carregando.AutoResizeHeight and UDim2.new(1, -60, 0, 0) or UDim2.fromOffset(0, 0),
        Text = "",
        TextSize = 18,
        TextWrapped = Carregando.AutoResizeHeight,
        Parent = InternoConteudo,
    })

    local DescricaoRotulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
        AutomaticSize = Carregando.AutoResizeHeight and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
        Size = Carregando.AutoResizeHeight and UDim2.new(1, -60, 0, 0) or UDim2.fromOffset(0, 0),
        Text = "",
        TextSize = 14,
        TextTransparency = 0.5,
        TextWrapped = Carregando.AutoResizeHeight,
        Parent = InternoConteudo,
    })

    local ControleDeslizanteBarra = Novo("Frame", {
        BackgroundColor3 = "MainColor",
        Size = UDim2.new(0.7, 0, 0, 15),
        Parent = InternoConteudo,
    })
    Library:AddOutline(ControleDeslizanteBarra)
    table.insert(Library.Corners, Novo("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius / 2), Parent = ControleDeslizanteBarra }))

    local ControleDeslizantePreenchimento = Novo("Frame", {
        BackgroundColor3 = "AccentColor",
        BorderSizePixel = 0,
        Size = UDim2.fromScale(0, 1),
        Parent = ControleDeslizanteBarra,
    })
    table.insert(Library.Corners, Novo("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius / 2), Parent = ControleDeslizantePreenchimento }))

    local ProgressoRotulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        Text = "",
        TextSize = 14,
        ZIndex = 2,
        Parent = ControleDeslizanteBarra,
    })
    Novo("UIStroke", {
        ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
        Color = "DarkColor",
        LineJoinMode = Enum.LineJoinMode.Miter,
        Parent = ProgressoRotulo,
    })

    local BarraLateralRolagem = Novo("ScrollingFrame", {
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        Size = UDim2.fromScale(1, 1),
        ScrollBarThickness = 2,
        ScrollBarImageColor3 = "OutlineColor",
        Parent = LadoBarra,
    })
    local BarraLateralLista = Novo("UIListLayout", {
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = BarraLateralRolagem,
    })
    Novo("UIPadding", {
        PaddingBottom = UDim.new(0, 12),
        PaddingLeft = UDim.new(0, 12),
        PaddingRight = UDim.new(0, 12),
        PaddingTop = UDim.new(0, 12),
        Parent = BarraLateralRolagem,
    })

    local BarraLateralObjeto = {
        Elements = {},
        DependencyBoxes = {},
        Tabboxes = {},

        BoxHolder = BarraLateralRolagem,
        Container = BarraLateralRolagem,

        Resize = function(self)
            BarraLateralRolagem.CanvasSize = UDim2.fromOffset(0, BarraLateralLista.AbsoluteContentSize.Y + 24)
        end,
        Tab = {
            Elements = {},
            DependencyBoxes = {},
            DependencyGroupboxes = {},
            Tabboxes = {},
        },
    }

    BarraLateralLista:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        BarraLateralObjeto:Resize()
    end)

    setmetatable(BarraLateralObjeto, BaseCaixaGrupo)
    Carregando.Sidebar = BarraLateralObjeto

    local ErroQuadro = Novo("Frame", {
        Name = "Error",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(0, 49),
        Size = UDim2.new(1, 0, 1, -49),
        ClipsDescendants = true,
        Visible = false,
        Parent = Conteiner,
    })

    local _ErroTitulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(15, 15),
        Size = UDim2.new(1, -30, 0, 18),
        Text = "Erro",
        TextColor3 = "RedColor",
        TextSize = 18,
        TextXAlignment = Enum.TextXAlignment.Left,
        Parent = ErroQuadro,
    })

    local ErroRotulo = Novo("TextLabel", {
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(15, 39),
        Size = UDim2.new(1, -30, 1, -90),
        Text = "Mensagem de Erro",
        TextSize = 14,
        TextTransparency = 0.2,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        Parent = ErroQuadro,
    })

    local ErroBotoesDivisor = Novo("Frame", {
        BackgroundColor3 = "OutlineColor",
        BackgroundTransparency = 0,
        BorderSizePixel = 0,
        AnchorPoint = Vector2.new(0.5, 0),
        Position = UDim2.new(0.5, 0, 1, -48),
        Size = UDim2.new(1, -30, 0, 1),
        Visible = false,
        Parent = ErroQuadro,
    })

    local ErroBotoesSuporte = Novo("Frame", {
        AnchorPoint = Vector2.new(0.5, 1),
        BackgroundTransparency = 1,
        Position = UDim2.new(0.5, 0, 1, 0),
        Size = UDim2.new(1, 0, 0, 42),
        Visible = false,
        Parent = ErroQuadro,
    })
    Novo("UIListLayout", {
        Padding = UDim.new(0, 8),
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalAlignment = Enum.HorizontalAlignment.Right,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = ErroBotoesSuporte,
    })
    Novo("UIPadding", {
        PaddingTop = UDim.new(0, 5),
        PaddingBottom = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),
        Parent = ErroBotoesSuporte,
    })

    function Carregando:UpdateLayout()
        if Carregando.IsError then
            Carregando:RecalculateErrorHeight()
        end

        local MostrarBarraLateral = Carregando.ShowSidebar
        local FinalLargura = MostrarBarraLateral and (Carregando.ContentWidth + Carregando.SidebarWidth) or Carregando.WindowWidth
        local FinalAltura = Carregando.IsError and Carregando.WindowErrorHeight or Carregando.WindowHeight

        if MostrarBarraLateral then
            LadoBarra.Visible = true
            BarraLateralDivisor.Visible = true
        end

        TweenService:Create(PrincipalQuadro, Library.TweenInfo, { Size = UDim2.fromOffset(FinalLargura, FinalAltura) }):Play()
        TweenService:Create(LadoBarra, Library.TweenInfo, { Position = UDim2.fromOffset(Carregando.ContentWidth, 0), Size = UDim2.new(0, MostrarBarraLateral and Carregando.SidebarWidth or 0, 1, 0) }):Play()
        TweenService:Create(Conteiner, Library.TweenInfo, { Size = UDim2.new(0, MostrarBarraLateral and Carregando.ContentWidth or Carregando.WindowWidth, 1, 0) }):Play()

        if not MostrarBarraLateral then
            task.delay(Library.TweenInfo.Time, function()
                if not Carregando.ShowSidebar then
                    LadoBarra.Visible = false
                    BarraLateralDivisor.Visible = false
                end
            end)
        end
    end

    function Carregando:RecalculateLoadingHeight()
        if not Carregando.AutoResizeHeight then
            return
        end

        local NecessarioAltura =
              49 
            + 48 
            + InternoConteudo.UIListLayout.AbsoluteContentSize.Y

        Carregando.WindowHeight = math.max(Carregando.BaseWindowHeight, NecessarioAltura)
    end

    function Carregando:SetMessage(Texto_2)
        MensagemRotulo.Text = Texto_2

        if Carregando.AutoResizeHeight then
            Carregando:RecalculateLoadingHeight()
            Carregando:UpdateLayout()
        end
    end

    function Carregando:SetDescription(Texto_2)
        DescricaoRotulo.Text = Texto_2

        if Carregando.AutoResizeHeight then
            Carregando:RecalculateLoadingHeight()
            Carregando:UpdateLayout()
        end
    end

    function Carregando:SetLoadingIcon(Icon)
        local IconeDados = Library:GetCustomIcon(Icon)
        assert(IconeDados, "Image must be a valid Roblox asset or a valid URL or a valid lucide icon.")

        Library:ApplyLucideIcon(CarregandoIcone, IconeDados)
    end

    function Carregando:SetLoadingIconTweenTime(InterpolacaoTempo)
        if RotacaoInterpolacao then
            PararInterpolacao(RotacaoInterpolacao, true)
            RotacaoInterpolacao = nil
        end

        if InterpolacaoTempo > 0 then
            RotacaoInterpolacao = TweenService:Create(
                CarregandoIcone,
                TweenInfo.new(InterpolacaoTempo, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, -1),
                { Rotation = 360 }
            )
            RotacaoInterpolacao:Play()
        else
            CarregandoIcone.Rotation = 0
        end
    end

    function Carregando:SetLoadingIconColor(Cor)
        CarregandoIcone.ImageColor3 = Cor
    end

    function Carregando:SetCurrentStep(Passo)
        Carregando.CurrentStep = math.clamp(Passo, 0, Carregando.TotalSteps)

        local Progresso = Carregando.CurrentStep / Carregando.TotalSteps
        TweenService:Create(ControleDeslizantePreenchimento, Library.TweenInfo, { Size = UDim2.fromScale(Progresso, 1) }):Play()

        ProgressoRotulo.Text = string.format("%d/%d", Carregando.CurrentStep, Carregando.TotalSteps)
    end

    function Carregando:SetTotalSteps(Passos)
        Carregando.TotalSteps = Passos
        Carregando:SetCurrentStep(Carregando.CurrentStep)
    end

    function Carregando:SetWindowHeight(Altura)
        Carregando.WindowHeight = Altura
        Carregando:UpdateLayout()
    end

    function Carregando:SetWindowWidth(Largura)
        Carregando.WindowWidth = Largura
        Carregando:UpdateLayout()
    end

    function Carregando:SetContentWidth(Largura)
        Carregando.ContentWidth = Largura
        Carregando:UpdateLayout()
    end

    function Carregando:SetSidebarWidth(Largura)
        Carregando.SidebarWidth = Largura
        Carregando:UpdateLayout()
    end

    function Carregando:ShowSidebarPage(Booleano)
        Carregando.ShowSidebar = Booleano
        Carregando:UpdateLayout()
    end

    function Carregando:ShowErrorPage(Ativado)
        Carregando.IsError = Ativado
        InternoConteudo.Visible = not Ativado
        ErroQuadro.Visible = Ativado

        if Carregando.ShowSidebar then
            Carregando:ShowSidebarPage(not Ativado)
        else
            Carregando:UpdateLayout()
        end
    end

    function Carregando:RecalculateErrorHeight()
        local AlvoLargura = (Carregando.ShowSidebar and Carregando.ContentWidth or Carregando.WindowWidth) - 30
        local _, ErroY = Library:GetTextBounds(ErroRotulo.Text, Library.Scheme.Font, 14, AlvoLargura)

        ErroRotulo.Size = UDim2.new(1, -30, 0, ErroY)

        local TemBotoes = ErroBotoesSuporte.Visible
        local NecessarioAltura =
              49                        
            + 15                        
            + 18                        
            + 6                         
            + ErroY                    
            + 15                        
            + (TemBotoes and 48 or 0)  

        Carregando.WindowErrorHeight = NecessarioAltura 
    end

    function Carregando:SetErrorMessage(Texto_2)
        ErroRotulo.Text = Texto_2
        Carregando:UpdateLayout()
    end

    function Carregando:SetErrorButtons(Botoes)
        assert(typeof(Botoes) == "table", "Buttons must be a table")

        for _, botao in ErroBotoesSuporte:GetChildren() do
            if botao:IsA("Frame") then
                botao:Destroy()
            end
        end

        local TemBotoes = ObterTabelaTamanho(Botoes) > 0
        ErroBotoesSuporte.Visible = TemBotoes
        ErroBotoesDivisor.Visible = TemBotoes

        for Indice, BotaoInfo in Botoes do
            local BotaoConteiner = Novo("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(0, 26),
                Parent = ErroBotoesSuporte,
            })

            local BotaoCor = "MainColor"
            local BotaoContorno = "OutlineColor"
            local Variante = BotaoInfo.Variant or "Primary"

            if Variante == "Primary" then
                BotaoCor = "FontColor"
                BotaoContorno = "FontColor"
            elseif Variante == "Secondary" then
                BotaoCor = "MainColor"
                BotaoContorno = "OutlineColor"
            elseif Variante == "Destructive" then
                BotaoCor = "DestructiveColor"
                BotaoContorno = "DestructiveColor"
            elseif Variante == "Ghost" then
                BotaoCor = "BackgroundColor"
                BotaoContorno = "BackgroundColor"
            end

            local TextoBotao = Novo("TextButton", {
                BackgroundColor3 = BotaoCor,
                BorderColor3 = BotaoContorno,
                Size = UDim2.fromOffset(0, 26),
                Text = "",
                AutoButtonColor = false,
                Parent = BotaoConteiner,
            })
            Library:AddOutline(TextoBotao)
            table.insert(
                Library.Corners,
                Novo("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius),
                    Parent = TextoBotao
                })
            )

            Novo("UIPadding", {
                PaddingLeft = UDim.new(0, 15),
                PaddingRight = UDim.new(0, 15),
                Parent = TextoBotao,
            })

            local TextoCor = Library.Scheme.FontColor
            if Variante == "Primary" then
                TextoCor = Library.Scheme.BackgroundColor
            elseif Variante == "Destructive" then
                TextoCor = Color3.new(1, 1, 1)
            end

            local BotaoRotulo = Novo("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Text = BotaoInfo.Title or Indice,
                TextColor3 = TextoCor,
                TextSize = 14,
                Parent = TextoBotao,
            })

            local RotuloX, _ = Library:GetTextBounds(BotaoRotulo.Text, Library.Scheme.Font, 14, 250)
            BotaoConteiner.Size = UDim2.fromOffset(RotuloX + 30, 26)
            TextoBotao.Size = UDim2.fromOffset(RotuloX + 30, 26)

            local AtivoCor = typeof(BotaoCor) == "Color3" and BotaoCor or Library.Scheme[BotaoCor]
            local PairarCor = Variante == "Ghost" and Library.Scheme.MainColor or Library:GetBetterColor(AtivoCor, 10)

            TextoBotao.MouseEnter:Connect(function()
                TweenService:Create(TextoBotao, Library.TweenInfo, {
                    BackgroundColor3 = PairarCor
                }):Play()
            end)
            TextoBotao.MouseLeave:Connect(function()
                TweenService:Create(TextoBotao, Library.TweenInfo, {
                    BackgroundColor3 = AtivoCor
                }):Play()
            end)

            TextoBotao.MouseButton1Click:Connect(function()
                if BotaoInfo.Callback then
                    BotaoInfo.Callback(Carregando)
                end
            end)
        end

        Carregando:UpdateLayout()
    end

    function Carregando:Destroy()
        if RotacaoInterpolacao then
            PararInterpolacao(RotacaoInterpolacao, true)
            RotacaoInterpolacao = nil
        end

        ScreenGui:Destroy()
        Carregando.Destroyed = true
        Library.ActiveLoading = nil

        if Library.Toggle and Library.Toggled == false and Library.Unloaded ~= true then
            Library:Toggle(true)
        end
    end

    Carregando.Continue = Carregando.Destroy;

    if Library.Toggle and Library.Toggled and Library.Unloaded ~= true then
        Library:Toggle(false)
    end

    Carregando:SetCurrentStep(Carregando.CurrentStep)

    Library.ActiveLoading = Carregando
    return Carregando
end

local function AoJogadorAlterar()
    if Library.Unloaded then
        return
    end

    local JogadorLista, ExcluidoJogadorLista = ObterJogadores(), ObterJogadores(true)
    for _, Seletor in Opcoes do
        if Seletor.Type == "Dropdown" and Seletor.SpecialType == "Player" then
            Seletor:SetValues(Seletor.ExcludeLocalPlayer and ExcluidoJogadorLista or JogadorLista)
        end
    end
end

local function AoEquipeAlterar()
    if Library.Unloaded then
        return
    end

    local EquipeLista = ObterEquipes()
    for _, Seletor in Opcoes do
        if Seletor.Type == "Dropdown" and Seletor.SpecialType == "Team" then
            Seletor:SetValues(EquipeLista)
        end
    end
end

Library:GiveSignal(Players.PlayerAdded:Connect(AoJogadorAlterar))
Library:GiveSignal(Players.PlayerRemoving:Connect(AoJogadorAlterar))

Library:GiveSignal(Teams.ChildAdded:Connect(AoEquipeAlterar))
Library:GiveSignal(Teams.ChildRemoved:Connect(AoEquipeAlterar))

function Library:Unload()
    Library.Unloaded = true

    for Indice_2 = #Library.Signals, 1, -1 do
        local Conexao = table.remove(Library.Signals, Indice_2)

        if Conexao and Conexao.Connected then
            Conexao:Disconnect()
        end
    end

    for _ = 1, #Library.UnloadSignals do
        local Retorno = table.remove(Library.UnloadSignals, 1)

        if Retorno then
            Library:SafeCallback(Retorno)
        end
    end

    for Indice_2 = #Library.Tabs, 1, -1 do
        local Aba = table.remove(Library.Tabs, Indice_2)

        if Aba and Aba.Destroy then
            Library:SafeCallback(Aba.Destroy, Aba)
        end
    end

    for Indice_2 = #Dicas, 1, -1 do
        local Dica = table.remove(Dicas, Indice_2)

        if Dica and Dica.Destroy then
            Library:SafeCallback(Dica.Destroy, Dica)
        end
    end

    if Library.ActiveLoading then
        Library.ActiveLoading:Destroy()
    end

    if ScreenGui then
        ScreenGui:Destroy()
    end

    table.clear(Library.Registry)

    table.clear(Opcoes)
    table.clear(Alternadores)
    table.clear(Botoes)
    table.clear(Rotulos)
    table.clear(Dicas)

    table.clear(Library.Tabs)
    table.clear(Library.TabButtons)

    table.clear(Library.Scales)
    table.clear(Library.ScalesOffset)

    table.clear(Library.Corners)
    table.clear(Library.SpecificCorners)
    table.clear(Library.ContextMenus)

    table.clear(Library.Notifications)
    table.clear(Library.Dialogues)
    table.clear(Library.DraggableElements)
    table.clear(Library.KeybindToggles)
    table.clear(Library.DependencyBoxes)

    table.clear(TransparenciaCache)
    table.clear(AtivoAbaInterpolacoes)

    Library.Toggle = function(...) end
    Library.ScreenGui = nil
    Library.Floats = nil
    Library.Overlay = nil
    Library.WindowContainer = nil
    Library.KeybindFrame = nil
    Library.KeybindContainer = nil

    getgenv().Library = nil
end

getgenv().Library = Library
return Library
]]
