local isfolder, isfile, listfiles = isfolder, isfile, listfiles
local isfolder_copia, isfile_copia, listfiles_copia = clonefunction(isfolder), clonefunction(isfile), clonefunction(listfiles)
local isfolder_sucesso, isfolder_erro = pcall(function() return isfolder_copia("test" .. tostring(math.random(1000000, 9999999))) end)

if isfolder_sucesso == false or typeof(isfolder_erro) ~= "boolean" then
    isfolder = function(pasta)
        local sucesso, dados = pcall(isfolder_copia, pasta)
