function ThemeManager:SetLibrary(Library)
    ThemeManager.Library = Library
end

local function Aparar(Text: string)
    return Text:match("^%s*(.-)%s*$")
end

local function EhTextoVazio(String: string): boolean
    return if typeof(String) == "string" then Aparar(String) == "" else true
end

local function EhValidoPastaCaminho(Nome: string): boolean
    return typeof(Nome) == "string" and (
        Aparar(Nome) ~= "" and 
        not Nome:match("^%s*$") and 
        not Nome:find('[<>:"|%?%*%z]')
    )
end

local function LinearizarCanal(Channel: number): number
    if Channel <= SrgbLinearLimite then
        return Channel / SrgbLinearDivisor
    end

    return ((Channel + SrgbGamaDeslocamento) / SrgbGamaEscala) ^ SrgbGamaExpoente
end

local function ObterRelativoLuminancia(Cor: Color3): number
    local R = LinearizarCanal(Cor.R)
    local G = LinearizarCanal(Cor.G)
    local B = LinearizarCanal(Cor.B)

    return LuminanciaVermelhoPeso * R + LuminanciaGreenPeso * G + LuminanciaBluePeso * B
end

local function ObterContrasteProporcao(ColorA: Color3, ColorB: Color3): number
    local LuminanciaA = ObterRelativoLuminancia(ColorA)
    local LuminanciaB = ObterRelativoLuminancia(ColorB)

    local MaisClaro = math.max(LuminanciaA, LuminanciaB)
    local MaisEscuro = math.min(LuminanciaA, LuminanciaB)

    return (MaisClaro + ContrasteProporcaoDeslocamento) / (MaisEscuro + ContrasteProporcaoDeslocamento)
end

local function EhValidoTemaDados(Dados: any): boolean
    if typeof(Dados) ~= "table" then
        return false
    end

    for _, EsquemaIndice in EsquemaIndices do
        if typeof(Dados[EsquemaIndice]) ~= "string" then
            return false
        end
    end

    return true
end

local function DividirCaminho(Caminho: string): {string}
	local Resultado = {}
	local Atual = ""

	for Part in string.gmatch(Caminho, "[^/]+") do
		Atual = if Atual == "" then Part else (Atual .. "/" .. Part)
		table.insert(Resultado, Atual)
	end

	return Resultado
end

local function ObterPastaCaminho(): false | string
    if EhTextoVazio(ThemeManager.Folder) then
        return false
    end

    return string.format("%s/themes", ThemeManager.Folder)
end

local ObterAtualTemasCaminho = ObterPastaCaminho

local function ObterTemaCaminho(TemaNome: string): false | string
    local AtualTemasCaminho = ObterAtualTemasCaminho()
    return if AtualTemasCaminho == false then false else string.format("%s/%s.json", AtualTemasCaminho, TemaNome)
end

local function FazTemaExistir(TemaNome: string, IncludeBuiltIn: boolean): boolean
    if ThemeManager.BuiltInThemes[TemaNome] then
        return true
    end

    local TemaCaminho = ObterTemaCaminho(TemaNome)
    return if TemaCaminho == false then false else isfile(TemaCaminho)
end

local function ObterPadraoTemaCaminho(): false | string
    local AtualTemasCaminho = ObterAtualTemasCaminho()
    return if AtualTemasCaminho == false then false else string.format("%s/default.txt", AtualTemasCaminho)
end

function ThemeManager:GetPaths(): {string}
    local PastaCaminho = ObterPastaCaminho()
    return if PastaCaminho == false then {} else DividirCaminho(PastaCaminho)
end

function ThemeManager:BuildFolderTree(PularWhenCriado: boolean?)
    local Caminhos = ThemeManager:GetPaths()
    if #Caminhos == 0 then
        return false
    end

    if PularWhenCriado == true then
        if isfolder(Caminhos[1]) then
            return true
        end
    end

    for _, Caminho in Caminhos do
        if isfolder(Caminho) then continue end
        
        makefolder(Caminho)
    end

    return true
end

function ThemeManager:CheckFolderTree()
    return ThemeManager:BuildFolderTree(true)
end

function ThemeManager:SetFolder(Folder: string)
    assert(EhValidoPastaCaminho(Folder), "Invalid path provided")

    ThemeManager.Folder = Folder
    ThemeManager:BuildFolderTree()
end

function ThemeManager:ReloadCustomThemes()
    local ConfiguracoesCaminho = ObterAtualTemasCaminho()
    if ConfiguracoesCaminho == false then
        return {}
    end

    pcall(makefolder, ConfiguracoesCaminho)
    local SucessoLista, Arquivos = pcall(listfiles, ConfiguracoesCaminho)
    if not (SucessoLista and typeof(Arquivos) == "table") then
        ThemeManager.Library:Notify(string.format("Falha ao carregar lista de temas: %s", tostring(Arquivos)))
        return {}
    end

    local ArquivoNomes = {}
    for _, ArquivoCaminho in Arquivos do
        local BrutoArquivoNome = ArquivoCaminho:match("(.+)%..+$")
        if not BrutoArquivoNome then continue end

        local Posicao = BrutoArquivoNome:gsub("\\", "/"):find("/[^/]*$")
        local ArquivoNome = Posicao and BrutoArquivoNome:sub(Posicao + 1) or BrutoArquivoNome
        if not ArquivoNome or ArquivoNome == "default" then continue end

        table.insert(ArquivoNomes, ArquivoNome)
    end

    return ArquivoNomes
end

function ThemeManager:GetCustomTheme(TemaNome: string): any
    if EhTextoVazio(TemaNome) then
        return nil
    end

    local TemaCaminho = ObterTemaCaminho(TemaNome)
    if TemaCaminho == false or not isfile(TemaCaminho) then
        return nil
    end

    local SucessoLer, Conteudo = pcall(readfile, TemaCaminho)
    if not SucessoLer then
        return nil
    end

    local SucessoDecodificar, Decodificado = pcall(HttpService.JSONDecode, HttpService, Conteudo)
    if not SucessoDecodificar or typeof(Decodificado) ~= "table" then
        return nil
    end

    return Decodificado
end

local function ConstruirAtualTemaDados(): {[string]: any}
    local Library = ThemeManager.Library
    local TemaDados = {
        FontFace = Library.Options.FontFace.Value,
        BackgroundImage = Library.Options.BackgroundImage.Value
    }

    for _, EsquemaIndice in EsquemaIndices do
        TemaDados[EsquemaIndice] = Library.Options[EsquemaIndice].Value:ToHex()
    end

    return TemaDados
end

function ThemeManager:SaveCustomTheme(TemaNome: string): any
    if EhTextoVazio(TemaNome) then
        return false, "Invalid theme name provided"
    end

    if string.lower(TemaNome) == "default" then
        return false, "Invalid theme name provided"
    end

    local TemaCaminho = ObterTemaCaminho(TemaNome)
    if TemaCaminho == false then
        return false, "Invalid theme name provided"
    end

    ThemeManager:CheckFolderTree()

    local CodificadoDados, SucessoCodificar, CodificarErroMensagem = ThemeManager:SaveJSON()
    if not SucessoCodificar then
        return false, CodificarErroMensagem
    end

    local SucessoEscrever, ErroMensagem = pcall(writefile, TemaCaminho, CodificadoDados)
    if not SucessoEscrever then
        return false, "Failed to write theme file: " .. tostring(ErroMensagem)
    end

    return true
end

function ThemeManager:Delete(TemaNome: string): (boolean | string?)
    if EhTextoVazio(TemaNome) then
        return false, "Nenhum tema selecionado"
    end

    local TemaCaminho = ObterTemaCaminho(TemaNome)
    if TemaCaminho == false or not isfile(TemaCaminho) then
        return false, "Theme file does not exist"
    end

    local SucessoExcluir, ErroMensagem = pcall(delfile, TemaCaminho)
    if not SucessoExcluir then
        return false, "Failed to delete theme file: " .. tostring(ErroMensagem)
    end

    if TemaNome == ThemeManager.DefaultThemeName then
        ThemeManager:DeleteDefaultTheme()
    end

    return true
end

function ThemeManager:GetDefaultTheme(): (string, boolean, string?)
    ThemeManager:CheckFolderTree()

    local PadraoTemaCaminho = ObterPadraoTemaCaminho()
    if PadraoTemaCaminho == false then
        return "none", false, "Invalid path provided"
    end

    if not isfile(PadraoTemaCaminho) then
        return "none", false, "Default theme is not set"
    end

    local SucessoLer, PadraoTemaNome = pcall(readfile, PadraoTemaCaminho)
    if not (SucessoLer and typeof(PadraoTemaNome) == "string") then
        return "none", false, PadraoTemaNome
    end

    local ConfigExiste = FazTemaExistir(PadraoTemaNome, true)
    if not ConfigExiste then
        return "none", false, "Theme file not found"
    end

    ThemeManager.DefaultThemeName = PadraoTemaNome
    return PadraoTemaNome, true
end

function ThemeManager:SetDefaultTheme(Tema: any)
    assert(ThemeManager.Library, "Library is not set, call ThemeManager:SetLibrary(Library) first.")
    assert(not ThemeManager.AppliedToTab, "Cannot set default theme after applying ThemeManager to a tab!")

    local Library = ThemeManager.Library
    local PadraoTemaDados = ThemeManager.BuiltInThemes["Default"][2]

    local BibliotecaEsquema = {}
    local FinalTema = {}

    for _, EsquemaIndice in EsquemaIndices do
        local IndiceDados = Tema[EsquemaIndice]
        local IndiceTipo = typeof(IndiceDados)
        
        if IndiceTipo == "Color3" then
            BibliotecaEsquema[EsquemaIndice] = IndiceDados
            FinalTema[EsquemaIndice] = string.format("#%s", IndiceDados:ToHex())

        elseif IndiceTipo == "string" then
            BibliotecaEsquema[EsquemaIndice] = Color3.fromHex(IndiceDados)
            FinalTema[EsquemaIndice] = if IndiceDados:sub(1, 1) == "#" then IndiceDados else string.format("#%s", IndiceDados)
        
        else
            local Valor = PadraoTemaDados[EsquemaIndice]
            BibliotecaEsquema[EsquemaIndice] = Color3.fromHex(Valor)
            FinalTema[EsquemaIndice] = Valor
        end
    end

    local FonteFace = Tema["FontFace"]
    local FonteFaceTipo = typeof(FonteFace)
    
    if FonteFaceTipo == "EnumItem" then
        BibliotecaEsquema.Font = Font.fromEnum(FonteFace)
        FinalTema.FontFace = FonteFace.Name

    elseif FonteFaceTipo == "string" then
        BibliotecaEsquema.Font = Font.fromEnum(Enum.Font[FonteFace] :: Enum.Font)
        FinalTema.FontFace = FonteFace
    
    else
        BibliotecaEsquema.Font = Font.fromEnum(Enum.Font.Gotham)
        FinalTema.FontFace = "Gotham"
    end

    for _, PadraoEsquemaCor in { "RedColor", "DestructiveColor", "DarkColor", "WhiteColor" } do
        BibliotecaEsquema[PadraoEsquemaCor] = Library.Scheme[PadraoEsquemaCor]
    end

    Library.Scheme = BibliotecaEsquema
    ThemeManager.BuiltInThemes["Default"] = { 1, FinalTema }

    Library:UpdateColorsUsingRegistry()
end

function ThemeManager:SaveDefault(TemaNome: string): (boolean, string?)
    if EhTextoVazio(TemaNome) then
        return false, "Nenhum tema selecionado"
    end

    ThemeManager:CheckFolderTree()

    local PadraoTemaCaminho = ObterPadraoTemaCaminho()
    if PadraoTemaCaminho == false then
        return false, "Invalid path provided"
    end

    if not FazTemaExistir(TemaNome, true) then
        return false, "Theme does not exist"
    end

    local SucessoEscrever, ErroMensagem = pcall(writefile, PadraoTemaCaminho, TemaNome)
    if not SucessoEscrever then
        return false, ErroMensagem
    end

    ThemeManager.DefaultThemeName = TemaNome
    return true
end

function ThemeManager:LoadDefault()
    local TemaNome, Sucesso, BuscarErroMensagem = ThemeManager:GetDefaultTheme()
    if not Sucesso or BuscarErroMensagem then
        if BuscarErroMensagem ~= "Default theme is not set" then
            ThemeManager.Library:Notify(string.format("Falha ao aplicar tema padrão: %s", BuscarErroMensagem))
        end

        return
    end

    if not ThemeManager:GetCustomTheme(TemaNome) then
        ThemeManager.Library.Options.ThemeManager_ThemeList:SetValue(TemaNome)
        return
    end

    local SucessoCarregar, CarregarErroMensagem = ThemeManager:ApplyTheme(TemaNome)
    if not SucessoCarregar then
        ThemeManager.Library:Notify(string.format("Falha ao aplicar tema padrão: %s", CarregarErroMensagem))
        return
    end

    ThemeManager.Library:Notify(string.format("Tema padrão %q aplicado com sucesso", TemaNome))
end

function ThemeManager:DeleteDefaultTheme(): (boolean, string?)
    ThemeManager:CheckFolderTree()

    local PadraoTemaCaminho = ObterPadraoTemaCaminho()
    if PadraoTemaCaminho == false then
        return false, "Invalid path provided"
    end

    if not isfile(PadraoTemaCaminho) then
        return false, "Default theme is not set"
    end

    local SucessoExcluir, ErroMensagem = pcall(delfile, PadraoTemaCaminho)
    if not SucessoExcluir then
        return false, ErroMensagem
    end

    ThemeManager.DefaultThemeName = nil
    return true
end

function ThemeManager:GetContrastReport(): { Ratio: number, PairName: string, Passes: boolean }
    local Library = ThemeManager.Library
    local FonteCorOpcao = Library.Options.FontColor
    local FundoCorOpcao = Library.Options.BackgroundColor
    local PrincipalCorOpcao = Library.Options.MainColor

    if not (FonteCorOpcao and FundoCorOpcao and PrincipalCorOpcao) then
        return { Ratio = math.huge, PairName = "", Passes = true }
    end

    local FonteCor = FonteCorOpcao.Value
    local Superficies = {
        { Name = "font color vs. background color", Color = FundoCorOpcao.Value },
        { Name = "font color vs. main color", Color = PrincipalCorOpcao.Value },
    }

    local PiorProporcao, PiorNome = math.huge, ""
    for _, Superficie in Superficies do
        local Ratio = ObterContrasteProporcao(FonteCor, Superficie.Color)
        if Ratio < PiorProporcao then
            PiorProporcao = Ratio
            PiorNome = Superficie.Name
        end
    end

    return {
        Ratio = PiorProporcao,
        PairName = PiorNome,
        Passes = PiorProporcao >= ContrasteAvisoLimite,
    }
end

function ThemeManager:UpdateContrastWarning()
    local ContrasteRotulo = ThemeManager.ContrastLabel
    if not ContrasteRotulo or ContrasteRotulo.Destroyed then
        return
    end

    local Library = ThemeManager.Library
    local Relatorio = ThemeManager:GetContrastReport()
    local TextLabel = ContrasteRotulo.TextLabel

    if not Library.Registry[TextLabel] then
        Library:AddToRegistry(TextLabel, {})
    end

    if Relatorio.Passes then
        ContrasteRotulo:SetText(string.format("Contraste: bom (%.1f:1)", Relatorio.Ratio))

        TextLabel.TextColor3 = Library.Scheme.FontColor
        Library.Registry[TextLabel].TextColor3 = "FontColor"
    else
        ContrasteRotulo:SetText(string.format(
            "Low contrast (%.1f:1) between %s. Aim for at least %.1f:1 so text stays readable.",
            Relatorio.Ratio, Relatorio.PairName, ContrasteAvisoLimite
        ))

        TextLabel.TextColor3 = Library.Scheme.RedColor
        Library.Registry[TextLabel].TextColor3 = "RedColor"

        if not ThemeManager.ContrastWasPoor then
            Library:Notify({
                Title = "Tema com baixo contraste",
                Description = string.format(
                    "Your %s has a contrast ratio of %.1f:1, below the recommended %.1f:1. Text may be hard to read.",
                    Relatorio.PairName, Relatorio.Ratio, ContrasteAvisoLimite
                ),
                Time = 10,
            })
        end
    end

    ThemeManager.ContrastWasPoor = not Relatorio.Passes
end

function ThemeManager:ThemeUpdate()
    local Library = ThemeManager.Library

    for _, EsquemaIndice in EsquemaIndices do
        local Elemento = Library.Options[EsquemaIndice]
        if not Elemento then continue end

        Library.Scheme[EsquemaIndice] = Elemento.Value
    end

    Library:UpdateColorsUsingRegistry()
    ThemeManager:UpdateContrastWarning()
end

function ThemeManager:ApplyThemeData(TemaDados: any): (boolean, string?)
    if typeof(TemaDados) ~= "table" then
        return false, "Invalid theme data"
    end

    local Library = ThemeManager.Library

    for Indice, Valor in TemaDados do
        if Indice == "VideoLink" then
            continue
        end

        local Elemento = Library.Options[Indice]
        local FinalValor = Valor

        if Indice == "FontFace" then
            if typeof(Valor) ~= "string" or not Enum.Font[Valor] then continue end
            ThemeManager.Library:SetFont(Enum.Font[Valor])

        elseif Indice == "BackgroundImage" then
            if typeof(Valor) ~= "string" then continue end
            ThemeManager.Library:SetBackgroundImage(Valor)

        elseif table.find(EsquemaIndices, Indice) then
            local SucessoCor, Cor = pcall(Color3.fromHex, Valor)
            if not SucessoCor then continue end

            FinalValor = Cor
            Library.Scheme[Indice] = FinalValor

        else
            continue 
        end

        if Elemento then
            Elemento:SetValue(FinalValor)
        end
    end

    ThemeManager:ThemeUpdate()
    return true
end

function ThemeManager:ApplyTheme(TemaNome: string)
    if EhTextoVazio(TemaNome) then
        return false, "Nenhum tema selecionado"
    end

    local PersonalizadoTemaDados = ThemeManager:GetCustomTheme(TemaNome)
    local Dados = PersonalizadoTemaDados or ThemeManager.BuiltInThemes[TemaNome]
    
    if not Dados then
        return false, "Tema não encontrado"
    end
    
    local TemaDados = PersonalizadoTemaDados or Dados[2]
    return ThemeManager:ApplyThemeData(TemaDados)
end

function ThemeManager:SaveJSON(): (string, boolean, string?)
    local TemaDados = ConstruirAtualTemaDados()

    local SucessoCodificar, CodificadoDados = pcall(HttpService.JSONEncode, HttpService, TemaDados)
    if not SucessoCodificar then
        return "", false, "Falha ao codificar dados"
    end

    return CodificadoDados, true
end

function ThemeManager:LoadJSON(Conteudo: string): (boolean, string?)
    if EhTextoVazio(Conteudo) then
        return false, "Nenhum JSON informado"
    end

    local SucessoDecodificar, Decodificado = pcall(HttpService.JSONDecode, HttpService, Conteudo)
    if not SucessoDecodificar or not EhValidoTemaDados(Decodificado) then
        return false, "Falha ao decodificar dados do tema"
    end

    return ThemeManager:ApplyThemeData(Decodificado)
end

local function MostrarDialogo(
    Condition: () -> boolean,

    Indice: string, 
    Title: string, 
    Description: string,

    DestructiveText: string,
    DestructiveAction: () -> nil
)
    if Condition() == false then
        return DestructiveAction()
    end

    return ThemeManager.Library.Window:AddDialog(Indice, {
        Title = Title,
        Description = Description,
        AutoDismiss = false,

        FooterButtons = {
            Cancel = {
                Title = "Cancelar",
                Variant = "Ghost",
                Order = 1,
                Callback = function(Dialogo)
                    Dialogo:Dismiss()
                end
            },

            DestructiveAction = {
                Title = DestructiveText,
                Variant = "Destructive",
                Order = 2,
                Callback = function(Dialogo)
                    Dialogo:Dismiss()
                    DestructiveAction()
                end
            }
        }
    })
end

function ThemeManager:CreateThemeManager(CaixaTemas: any)
    assert(ThemeManager.Library, "Library is not set, call ThemeManager:SetLibrary(Library) first.")

    local NativoEmTemasNomes = {}
    for Nome, _TemaDados in ThemeManager.BuiltInThemes do
        table.insert(NativoEmTemasNomes, Nome)
    end

    local PersonalizadoTemaLista, PersonalizadoTemaNome, TemaLista, FonteFace, FundoImagem, PadraoTemaRotulo, TemaJSONEntrada
    local function AtualizarLista()
        PersonalizadoTemaLista:SetValues(ThemeManager:ReloadCustomThemes())
        PersonalizadoTemaLista:SetValue(nil)

        TemaLista:SetValues(NativoEmTemasNomes)
    end

    local function AtualizarPadraoTemaRotulo()
        local PadraoTemaNome, _Sucesso, _ErroMensagem = ThemeManager:GetDefaultTheme()

        PadraoTemaRotulo:SetText(string.format("Tema padrão atual: %s", PadraoTemaNome))
        if PersonalizadoTemaLista then AtualizarLista() end
    end

    table.sort(NativoEmTemasNomes, function(IndiceA, IndiceB)
        return ThemeManager.BuiltInThemes[IndiceA][1] < ThemeManager.BuiltInThemes[IndiceB][1]
    end)

    local function CriarCorOpcao(Text, EsquemaIndice)
        CaixaTemas:AddLabel(Text):AddColorPicker(EsquemaIndice, {
            Default = ThemeManager.Library.Scheme[EsquemaIndice]
        })

        return ThemeManager.Library.Options[EsquemaIndice]
    end

    local FundoCor = CriarCorOpcao("Cor de fundo", "BackgroundColor")
    local PrincipalCor = CriarCorOpcao("Cor principal", "MainColor")
    local DestaqueCor = CriarCorOpcao("Cor de destaque", "AccentColor")
    local ContornoCor = CriarCorOpcao("Cor do contorno", "OutlineColor")
    local FonteCor = CriarCorOpcao("Cor da fonte", "FontColor")

    ThemeManager.ContrastLabel = CaixaTemas:AddLabel({
        Text = "Contraste: n/d",
        DoesWrap = true,
    })

    CaixaTemas:AddDropdown("FontFace", {
        Text = "Fonte",
        Default = "Gotham",
        
        Values = { "BuilderSans", "Code", "Fantasy", "Gotham", "Jura", "Roboto", "RobotoMono", "SourceSans" },
        AllowNull = false,
        Multi = false
    })
    
    CaixaTemas:AddInput("BackgroundImage", { 
        Text = "Imagem de Fundo",

        Default = "",
        Finished = true,
        ClearTextOnFocus = false,
        ClearTextOnBlur = false
    })

    CaixaTemas:AddDivider()

    CaixaTemas:AddDropdown("ThemeManager_ThemeList", { 
        Text = "Lista de temas", 

        Values = NativoEmTemasNomes,
        AllowNull = true,
        Multi = false,

        FormatDisplayValue = function(Valor: any)
            if Valor ~= "Default" and Valor == ThemeManager.DefaultThemeName then
                return string.format("%s (padrão)", Valor)
            end

            return Valor
        end,
        FormatListValue = function(Valor: any)
            if Valor ~= "Default" and Valor == ThemeManager.DefaultThemeName then
                return string.format("%s (padrão)", Valor)
            end

            return Valor
        end
    })

    CaixaTemas:AddButton("Definir como padrão", function()
        local TemaNome = TemaLista.Value
        ThemeManager:SaveDefault(TemaNome)

        ThemeManager.Library:Notify(string.format("Tema padrão definido para %q", TemaNome))
        AtualizarPadraoTemaRotulo()
    end)

    CaixaTemas:AddDivider()

    PersonalizadoTemaNome = CaixaTemas:AddInput("ThemeManager_CustomThemeName", { 
        Text = "Nome do tema personalizado" 
    })

    local function SalvarTemaComContrasteVerificar(Nome: string, SuccessMessage: string, OnSaved: (() -> nil)?)
        local function ExecutarSalvar()
            local Sucesso, ErroMensagem = ThemeManager:SaveCustomTheme(Nome)
            if not Sucesso then
                ThemeManager.Library:Notify(string.format("Falha ao salvar o tema %q: %s", Nome, ErroMensagem))
                return
            end

            ThemeManager.Library:Notify(string.format(SuccessMessage, Nome))
            if OnSaved then OnSaved() end
        end

        local Relatorio = ThemeManager:GetContrastReport()
        if Relatorio.Passes then
            ExecutarSalvar()
            return
        end

        MostrarDialogo(
            function(): boolean
                return true
            end,

            "ThemeManager_LowContrastSave",
            "Tema com baixo contraste",
            string.format(
                "Este tema tem taxa de contraste de %.1f:1 entre %s, abaixo do recomendado de %.1f:1. O texto pode ficar difícil de ler. Salvar mesmo assim?",
                Relatorio.Ratio, Relatorio.PairName, ContrasteAvisoLimite
            ),

            "Salvar Mesmo Assim",
            ExecutarSalvar
        )
    end

    CaixaTemas:AddButton("Criar tema", function()
        local Nome = PersonalizadoTemaNome.Value
        if EhTextoVazio(Nome) then
            ThemeManager.Library:Notify("O nome do tema não pode estar vazio.")
            return
        end

        if string.lower(Nome) == "default" then
            ThemeManager.Library:Notify("Nome de tema inválido.")
            return
        end

        MostrarDialogo(
            function(): boolean
                return ThemeManager:GetCustomTheme(Nome) ~= nil
            end,

            "ThemeManager_CreateTheme",
            "Tema já existe",
            string.format("Já existe um tema personalizado chamado %q. Sobrescrevê-lo substituirá pelas suas cores atuais.", Nome),

            "Sobrescrever",
            function()
                SalvarTemaComContrasteVerificar(Nome, "Tema %q criado com sucesso", AtualizarLista)
            end
        )
    end)

    CaixaTemas:AddDivider()

    PersonalizadoTemaLista = CaixaTemas:AddDropdown("ThemeManager_CustomThemeList", { 
        Text = "Temas personalizados",

        Values = ThemeManager:ReloadCustomThemes(), 
        AllowNull = true,
        Multi = false,

        FormatDisplayValue = function(Valor: any)
            if Valor == ThemeManager.DefaultThemeName then
                return string.format("%s (padrão)", Valor)
            end

            return Valor
        end,
        FormatListValue = function(Valor: any)
            if Valor == ThemeManager.DefaultThemeName then
                return string.format("%s (padrão)", Valor)
            end

            return Valor
        end
    })

    CaixaTemas:AddButton("Carregar tema", function()
        local Nome = PersonalizadoTemaLista.Value
        if EhTextoVazio(Nome) then
            ThemeManager.Library:Notify("Selecione um tema primeiro.")
            return
        end

        ThemeManager:ApplyTheme(Nome)
        ThemeManager.Library:Notify(string.format("Tema %q carregado com sucesso", Nome))
    end)

    CaixaTemas:AddButton("Sobrescrever tema", function()
        local Nome = PersonalizadoTemaLista.Value
        if EhTextoVazio(Nome) then
            ThemeManager.Library:Notify("Selecione um tema primeiro.")
            return
        end

        MostrarDialogo(
            function(): boolean
                return true
            end,

            "ThemeManager_OverwriteTheme",
            "Sobrescrever tema",
            string.format("Tem certeza que deseja sobrescrever %q com suas cores atuais? Isso não pode ser desfeito.", Nome),

            "Sobrescrever",
            function()
                SalvarTemaComContrasteVerificar(Nome, "Tema %q sobrescrito com sucesso")
            end
        )
    end)

    CaixaTemas:AddButton("Excluir tema", function()
        local Nome = PersonalizadoTemaLista.Value
        if EhTextoVazio(Nome) then
            ThemeManager.Library:Notify("Selecione um tema primeiro.")
            return
        end

        MostrarDialogo(
            function(): boolean
                return true
            end,

            "ThemeManager_DeleteTheme",
            "Excluir tema",
            string.format("Tem certeza que deseja excluir %q? Isso não pode ser desfeito.", Nome),
            
            "Excluir",
            function()
                local Sucesso, ErroMensagem = ThemeManager:Delete(Nome)
                if not Sucesso then
                    ThemeManager.Library:Notify(string.format("Falha ao excluir tema: %s", ErroMensagem))
                    return
                end

                ThemeManager.Library:Notify(string.format("Tema %q excluído com sucesso", Nome))
                AtualizarPadraoTemaRotulo()
            end
        )
    end)

    CaixaTemas:AddButton("Atualizar lista", AtualizarLista)

    CaixaTemas:AddButton("Definir como padrão", function()
        local Nome = PersonalizadoTemaLista.Value
        if EhTextoVazio(Nome) then
            ThemeManager.Library:Notify("Selecione um tema primeiro.")
            return
        end

        ThemeManager:SaveDefault(Nome)
        ThemeManager.Library:Notify(string.format("Tema padrão definido para %q", Nome))
        AtualizarPadraoTemaRotulo()
    end)

    CaixaTemas:AddButton("Restaurar padrão", function()
        MostrarDialogo(
            function(): boolean
                return true
            end,

            "ThemeManager_ResetDefault",
            "Restaurar tema padrão",
            "Tem certeza que deseja limpar o tema padrão? O tema nativo será usado na próxima inicialização.",
            
            "Resetar",
            function()
                local Sucesso, ErroMensagem = ThemeManager:DeleteDefaultTheme()
                if not Sucesso then
                    ThemeManager.Library:Notify(string.format("Falha ao restaurar tema padrão: %s", ErroMensagem))
                    return
                end

                ThemeManager.Library:Notify("Tema padrão restaurado com sucesso.")
                AtualizarPadraoTemaRotulo()
            end
        )
    end)

    PadraoTemaRotulo = CaixaTemas:AddLabel("Tema padrão atual: ...", true);

    CaixaTemas:AddDivider()

    CaixaTemas:AddInput("ThemeManager_ThemeJSON", {
        Text = "JSON do Tema"
    })

    CaixaTemas:AddButton("Importar tema", function()
        local TemaJSON = TemaJSONEntrada.Value
        if EhTextoVazio(TemaJSON) then
            ThemeManager.Library:Notify("O JSON do tema não pode estar vazio.")
            return
        end

        MostrarDialogo(
            function(): boolean
                return true
            end,

            "ThemeManager_ImportTheme",
            "Importar tema",
            "Tem certeza que deseja importar este tema? Suas cores atuais serão substituídas.",

            "Importar",
            function()
                local Sucesso, ErroMensagem = ThemeManager:LoadJSON(TemaJSON)
                if not Sucesso then
                    ThemeManager.Library:Notify(string.format("Falha ao importar tema: %s", ErroMensagem))
                    return
                end

                ThemeManager.Library:Notify("Tema importado com sucesso")
            end
        )
    end)

    CaixaTemas:AddButton("Exportar tema atual", function()
        local CodificadoDados, Sucesso, ErroMensagem = ThemeManager:SaveJSON()
        if not Sucesso then
            ThemeManager.Library:Notify(ErroMensagem)
            return
        end

        TemaJSONEntrada:SetValue(CodificadoDados)
        if setclipboard then
            setclipboard(CodificadoDados)
            ThemeManager.Library:Notify("Tema copiado para a área de transferência")
        end
    end)

    PersonalizadoTemaLista, PersonalizadoTemaNome, TemaLista, FonteFace, FundoImagem, TemaJSONEntrada =
        ThemeManager.Library.Options.ThemeManager_CustomThemeList,
        ThemeManager.Library.Options.ThemeManager_CustomThemeName,
        ThemeManager.Library.Options.ThemeManager_ThemeList,
        ThemeManager.Library.Options.FontFace,
        ThemeManager.Library.Options.BackgroundImage,
        ThemeManager.Library.Options.ThemeManager_ThemeJSON;

    TemaLista:OnChanged(function()
        ThemeManager:ApplyTheme(TemaLista.Value)
    end)

    local function AtualizarTema()
        ThemeManager:ThemeUpdate()
    end

    FundoCor:OnChanged(AtualizarTema)
    PrincipalCor:OnChanged(AtualizarTema)
    DestaqueCor:OnChanged(AtualizarTema)
    ContornoCor:OnChanged(AtualizarTema)
    FonteCor:OnChanged(AtualizarTema)
    FonteFace:OnChanged(function(Valor) ThemeManager.Library:SetFont(Enum.Font[Valor]) end)
    FundoImagem:OnChanged(function(Valor) ThemeManager.Library:SetBackgroundImage(Valor) end)

    ThemeManager:LoadDefault()
    ThemeManager:UpdateContrastWarning()
    ThemeManager.AppliedToTab = true
    AtualizarPadraoTemaRotulo()

    return CaixaTemas
end

function ThemeManager:CreateGroupBox(Aba: any, IconeNome: string)
    return Aba:AddGroupbox({
        Side = "Left",
        Name = "Temas",
        IconName = IconeNome or "paintbrush",
    })
end

function ThemeManager:ApplyToTab(Aba: any, IconeNome: string)
    local CaixaGrupo = ThemeManager:CreateGroupBox(Aba, IconeNome)
    return ThemeManager:CreateThemeManager(CaixaGrupo)
end

function ThemeManager:ApplyToGroupbox(CaixaGrupo: any)
    return ThemeManager:CreateThemeManager(CaixaGrupo)
end

getgenv().ResonanceThemeManager = ThemeManager
return ThemeManager
]]
bundle["Configs"] = [[
local cloneref = (cloneref or clonereference or function(instancia: any)
    return instancia
end)
local clonefunction = (clonefunction or copyfunction or function(funcao) 
    return funcao 
end)

local HttpService: HttpService = cloneref(game:GetService("HttpService"))

local isfolder, isfile, listfiles = isfolder, isfile, listfiles
local isfolder_copia, isfile_copia, listfiles_copia = clonefunction(isfolder), clonefunction(isfile), clonefunction(listfiles)
local isfolder_sucesso, isfolder_erro = pcall(function() return isfolder_copia("test" .. tostring(math.random(1000000, 9999999))) end)

if isfolder_sucesso == false or typeof(isfolder_erro) ~= "boolean" then
    isfolder = function(pasta)
        local sucesso, dados = pcall(isfolder_copia, pasta)
        return (if sucesso then dados else false)
    end

    isfile = function(arquivo)
        local sucesso, dados = pcall(isfile_copia, arquivo)
        return (if sucesso then dados else false)
    end

    listfiles = function(pasta)
        local sucesso, dados = pcall(listfiles_copia, pasta)
        return (if sucesso then dados else {})
    end
end

local SaveManager = {
    Library = nil,

    Folder = "ResonanceLibSettings",
    SubFolder = "",

    Ignore = {},
    LoadingOrder = {},
    UseLoadingOrder = false,

    AutoloadConfig = nil
}

function SaveManager:SetLibrary(Library)
    SaveManager.Library = Library
end

local EspecialValorAnalisador = {
    UDim2 = {
        Encode = function(Valor: UDim2)
            return {
                X = { Scale = Valor.X.Scale, Offset = Valor.X.Offset },
                Y = { Scale = Valor.Y.Scale, Offset = Valor.Y.Offset }
            }
        end,

        Decode = function(Dados: any)
            local DadosTipo = typeof(Dados)
            if DadosTipo == "table" then
                return UDim2.new(Dados.X.Scale, Dados.X.Offset, Dados.Y.Scale, Dados.Y.Offset)
            elseif DadosTipo == "UDim2" then
                return Dados
            end

            return nil
        end
    }
}

local ElementoAnalisador = {}; do
    local function CriarAnalisador(
        ElementType: string, 
        LibaryIndex: string, 
        
        Save: (string, any, ...any) -> any, 
        Load: (any?, any) -> any,
        CustomElementFetcher: boolean?
    )
        ElementoAnalisador[ElementType] = { 
            Save = function(Indice: string, Elemento: any, ...)
                local Dados = Save(Indice, Elemento, ...)
                Dados.type = ElementType
                Dados.idx = Indice

                return Dados
            end, 

            Load = function(Indice: string?, Dados: any)
                if CustomElementFetcher == true then
                    return Load(nil, Dados)
                end

                local Elementos = SaveManager.Library and SaveManager.Library[LibaryIndex]
                local Elemento = Elementos and Elementos[Indice]
                return Load(Elemento, Dados)
            end
        }
    end

    CriarAnalisador(
        "Toggle", "Toggles",
        function(Indice: string, Alternador: any)
            return { value = Alternador.Value }
        end,
        function(Elemento: any?, Dados: any)
            if not Elemento then return end
            if Elemento.Value == Dados.value then return end
            
            Elemento:SetValue(Dados.value)
        end
    )

    CriarAnalisador(
        "Slider", "Options",
        function(Indice: string, ControleDeslizante: any)
            return { value = tostring(ControleDeslizante.Value) }
        end,
        function(Elemento: any?, Dados: any)
            if not Elemento then return end
            if Elemento.Value == Dados.value then
                Elemento:RunChanged()
                return
            end

            Elemento:SetValue(Dados.value)
        end
    )

    CriarAnalisador(
        "Dropdown", "Options",
        function(Indice: string, Seletor: any)
            return { value = Seletor.Value, multi = Seletor.Multi }
        end,
        function(Elemento: any?, Dados: any)
            if not Elemento then return end
            if Elemento.Value == Dados.value then
                Elemento:RunChanged()
                return
            end
            
            Elemento:SetValue(Dados.value)
        end
    )

    CriarAnalisador(
        "ColorPicker", "Options",
        function(Indice: string, CorSeletorTecla: any)
            return { value = CorSeletorTecla.Value:ToHex(), transparency = CorSeletorTecla.Transparency }
        end,
        function(Elemento: any?, Dados: any)
            if not Elemento then return end
            
            Elemento:SetValueRGB(Color3.fromHex(Dados.value), Dados.transparency)
        end
    )

    CriarAnalisador(
        "KeyPicker", "Options",
        function(Indice: string, TeclaSeletorTecla: any)
            return { mode = TeclaSeletorTecla.Mode, key = TeclaSeletorTecla.Value, modifiers = TeclaSeletorTecla.Modifiers, toggled = TeclaSeletorTecla.Toggled }
        end,
        function(Elemento: any?, Dados: any)
            if not Elemento then return end
            
            Elemento:SetValue({ Dados.key, Dados.mode, Dados.modifiers })
            if Dados.mode == "Toggle" and Dados.toggled ~= nil then
                Elemento.Toggled = Dados.toggled
                Elemento:Update()
            end
        end
    )

    CriarAnalisador(
        "Input", "Options",
        function(Indice: string, Entrada: any)
            return { text = Entrada.Value }
        end,
        function(Elemento: any?, Dados: any)
            if not Elemento then return end
            if typeof(Dados.text) ~= "string" then return end

            if Elemento.Value == Dados.text then
                Elemento:RunChanged()
                return
            end

            Elemento:SetValue(Dados.text)
        end
    )

    CriarAnalisador(
        "Groupbox", "Tabs",
        function(Indice: string, CaixaGrupo: any, AbaIndice: string)
            return {
                tabIdx = AbaIndice,
                collapsed = CaixaGrupo.Collapsed,
                poppedOut = CaixaGrupo.PoppedOut == true,
                popoutPos = if CaixaGrupo.PoppedOut and CaixaGrupo.PopOutFloat then EspecialValorAnalisador.UDim2.Encode(CaixaGrupo.PopOutFloat.Position) else nil,
            }
        end,
        function(_, Dados: any)
            local AbaIndice, Indice = Dados.tabIdx, Dados.idx
            if typeof(AbaIndice) ~= "string" or typeof(Indice) ~= "string" then return end

            local Abas = SaveManager.Library and SaveManager.Library.Tabs
            local Aba = Abas and Abas[AbaIndice]
            if not Aba then return end

            local CaixaGrupo = Aba.Groupboxes[Indice]
            if not CaixaGrupo then return end

            if CaixaGrupo.Collapsed ~= Dados.collapsed then
                CaixaGrupo:SetCollapsed(Dados.collapsed == true)
            end

            if CaixaGrupo.PopOutEnabled then
                if Dados.poppedOut == true then
                    local Posicao = EspecialValorAnalisador.UDim2.Decode(Dados.popoutPos)
                    CaixaGrupo:SetPoppedOut(true, Posicao)
                elseif CaixaGrupo.PoppedOut then
                    CaixaGrupo:SetPoppedOut(false)
                end
            end
        end,
        true
    )

    CriarAnalisador(
        "Tabbox", "Tabs",
        function(Indice: string, CaixaAbas: any, AbaIndice: string)
            return {
                tabIdx = AbaIndice,
                poppedOut = CaixaAbas.PoppedOut == true,
                popoutPos = if CaixaAbas.PoppedOut and CaixaAbas.PopOutFloat then EspecialValorAnalisador.UDim2.Encode(CaixaAbas.PopOutFloat.Position) else nil,
            }
        end,
        function(_, Dados: any)
            local AbaIndice, Indice = Dados.tabIdx, Dados.idx
            if typeof(AbaIndice) ~= "string" or typeof(Indice) ~= "string" then return end

            local Abas = SaveManager.Library and SaveManager.Library.Tabs
            local Aba = Abas and Abas[AbaIndice]
            if not Aba then return end

            local CaixaAbas = Aba.Tabboxes and Aba.Tabboxes[Indice]
            if not CaixaAbas then return end

            if CaixaAbas.PopOutEnabled then
                if Dados.poppedOut == true then
                    local Posicao = EspecialValorAnalisador.UDim2.Decode(Dados.popoutPos)
                    CaixaAbas:SetPoppedOut(true, Posicao)
                elseif CaixaAbas.PoppedOut then
                    CaixaAbas:SetPoppedOut(false)
                end
            end
        end,
        true
    )
end

local function Aparar(Text: string)
    return Text:match("^%s*(.-)%s*$")
end

local function EhTextoVazio(String: string): boolean
    return if typeof(String) == "string" then Aparar(String) == "" else true
end

local function EhValidoPastaCaminho(Name: string): boolean
    return typeof(Name) == "string" and (
        Aparar(Name) ~= "" and 
        not Name:match("^%s*$") and 
        not Name:find('[<>:"|%?%*%z]')
    )
end

local function DividirCaminho(Caminho: string): {string}
    local Resultado = {}
    local Atual = ""

    for Part in string.gmatch(Caminho, "[^/]+") do
        Atual = if Atual == "" then Part else (Atual .. "/" .. Part)
        table.insert(Resultado, Atual)
    end

    return Resultado
end

local function ObterPastaCaminho(): false | string
    if EhTextoVazio(SaveManager.Folder) then
        return false
    end

    return string.format("%s/settings", SaveManager.Folder)
end

local function ObterSubPastaCaminho(): false | string
    if EhTextoVazio(SaveManager.Folder) or EhTextoVazio(SaveManager.SubFolder) then
        return false
    end

    return string.format("%s/settings/%s", SaveManager.Folder, SaveManager.SubFolder)
end

local function ObterAtualConfiguracoesCaminho(): false | string
    local SubPastaCaminho = ObterSubPastaCaminho()
    return if SubPastaCaminho == false then ObterPastaCaminho() else SubPastaCaminho
end

local function ObterConfigCaminho(ConfigNome: string): false | string
    local AtualConfiguracoesCaminho = ObterAtualConfiguracoesCaminho()
    return if AtualConfiguracoesCaminho == false then false else string.format("%s/%s.json", AtualConfiguracoesCaminho, ConfigNome)
end

local function FazConfigExistir(ConfigNome: string): boolean
    local ConfigCaminho = ObterConfigCaminho(ConfigNome)
    return if ConfigCaminho == false then false else isfile(ConfigCaminho)
end

local function ObterCarregamentoAutoCaminho(): false | string
    local AtualConfiguracoesCaminho = ObterAtualConfiguracoesCaminho()
    return if AtualConfiguracoesCaminho == false then false else string.format("%s/autoload.txt", AtualConfiguracoesCaminho)
end

function SaveManager:SetLoadingOrder(Ativado: boolean, Ordem: {string}?)
    SaveManager.UseLoadingOrder = Ativado == true
    SaveManager.LoadingOrder = typeof(Ordem) == "table" and Ordem or SaveManager.LoadingOrder
end

function SaveManager:SetIgnoreIndexes(Indices: {string}?)
    assert(typeof(Indices) == "table", "Expected table, got " .. typeof(Indices))

    for _, Indice in Indices do
        SaveManager.Ignore[Indice] = true
    end
end

function SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({
        "BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor", "FontFace", "BackgroundImage",
        "ThemeManager_ThemeList", "ThemeManager_CustomThemeList", "ThemeManager_CustomThemeName", "ThemeManager_ThemeJSON"
    })
end

function SaveManager:GetPaths(): {string}
    local SubPastaCaminho = ObterSubPastaCaminho()
    if SubPastaCaminho == false then
        local PastaCaminho = ObterPastaCaminho()
        return if PastaCaminho == false then {} else DividirCaminho(PastaCaminho)
    end

    return DividirCaminho(SubPastaCaminho)
end

function SaveManager:BuildFolderTree(PularWhenCriado: boolean?)
    local Caminhos = SaveManager:GetPaths()
    if #Caminhos == 0 then
        return false
    end

    if PularWhenCriado == true then
        if isfolder(Caminhos[1]) then
            return true
        end
    end

    for _, Caminho in Caminhos do
        if isfolder(Caminho) then continue end
        
        makefolder(Caminho)
    end

    return true
end

function SaveManager:CheckFolderTree()
    return SaveManager:BuildFolderTree(true)
end

function SaveManager:CheckSubFolder(CriarPasta: boolean)
    local SubPastaCaminho = ObterSubPastaCaminho()
    if SubPastaCaminho == false then
        return false
    end

    local PastaExiste = isfolder(SubPastaCaminho)
    if not CriarPasta then
        return PastaExiste
    end

    makefolder(SubPastaCaminho)
    return true
end

function SaveManager:SetFolder(Folder: string)
    assert(EhValidoPastaCaminho(Folder), "Invalid path provided")

    SaveManager.Folder = Folder
    SaveManager:BuildFolderTree()
end

function SaveManager:SetSubFolder(SubPasta: string)
    assert(EhValidoPastaCaminho(SubPasta), "Invalid path provided")

    SaveManager.SubFolder = SubPasta
    SaveManager:BuildFolderTree()
end

function SaveManager:RefreshConfigList()
    local ConfiguracoesCaminho = ObterAtualConfiguracoesCaminho()
    if ConfiguracoesCaminho == false then
        return {}
    end

    pcall(makefolder, ConfiguracoesCaminho)
    local SucessoLista, Arquivos = pcall(listfiles, ConfiguracoesCaminho)
    if not (SucessoLista and typeof(Arquivos) == "table") then
        SaveManager.Library:Notify(string.format("Falha ao carregar lista de configurações: %s", tostring(Arquivos)))
        return {}
    end

    local ArquivoNomes = {}
    for _, ArquivoCaminho in Arquivos do
        local BrutoArquivoNome = ArquivoCaminho:match("(.+)%..+$")
        if not BrutoArquivoNome then continue end

        local Posicao = BrutoArquivoNome:gsub("\\", "/"):find("/[^/]*$")
        local ArquivoNome = Posicao and BrutoArquivoNome:sub(Posicao + 1) or BrutoArquivoNome
        if not ArquivoNome or ArquivoNome == "autoload" then continue end

        table.insert(ArquivoNomes, ArquivoNome)
    end

    return ArquivoNomes
end

function SaveManager:SaveJSON(ConfigNome)
    local Library = SaveManager.Library
    local IgnorarIndices = SaveManager.Ignore
    local AtualDados = {
        timestamp = os.date("%d.%m.%Y %H:%M:%S"),
        name = ConfigNome or "",

        objects = {},
        keybindMenu = if Library.KeybindFrame then {
            visible = Library.KeybindFrame.Visible,
            position = EspecialValorAnalisador.UDim2.Encode(Library.KeybindFrame.Position)
        } else nil
    }

    for Indice, Alternador in Library.Toggles do
        if not Alternador.Type then continue end
        if IgnorarIndices[Indice] then continue end

        local Analisador = ElementoAnalisador[Alternador.Type]
        if not Analisador then continue end

        table.insert(AtualDados.objects, Analisador.Save(Indice, Alternador))
    end

    for Indice, Opcao in Library.Options do
        if not Opcao.Type then continue end
        if IgnorarIndices[Indice] then continue end

        local Analisador = ElementoAnalisador[Opcao.Type]
        if not Analisador then continue end

        table.insert(AtualDados.objects, Analisador.Save(Indice, Opcao))
    end

    for AbaIndice, Aba in Library.Tabs do
        if Aba.Groupboxes then
            for Indice, CaixaGrupo in Aba.Groupboxes do
                if typeof(Indice) ~= "string" or IgnorarIndices[Indice] then continue end

                local Analisador = ElementoAnalisador.Groupbox
                if not Analisador then continue end

                table.insert(AtualDados.objects, Analisador.Save(Indice, CaixaGrupo, AbaIndice))
            end
        end

        if Aba.Tabboxes then
            for Indice, CaixaAbas in Aba.Tabboxes do
                if typeof(Indice) ~= "string" or IgnorarIndices[Indice] then continue end

                local Analisador = ElementoAnalisador.Tabbox
                if not Analisador then continue end

                table.insert(AtualDados.objects, Analisador.Save(Indice, CaixaAbas, AbaIndice))
            end
        end
    end

    local SucessoCodificar, CodificadoDados = pcall(HttpService.JSONEncode, HttpService, AtualDados)
    if not SucessoCodificar then
        return "", false, "Falha ao codificar dados"
    end

    return CodificadoDados, true
end

function SaveManager:Save(ConfigNome: string): (boolean, string?)
    if EhTextoVazio(ConfigNome) then
        return false, "Invalid config name provided"
    end

    if string.lower(ConfigNome) == "autoload" then
        return false, "Invalid config name provided"
    end

    local ConfigCaminho = ObterConfigCaminho(ConfigNome)
    if ConfigCaminho == false then
        return false, "Invalid config name provided"
    end

    SaveManager:CheckFolderTree()

    local CodificadoDados, SucessoCodificar, CodificarErroMensagem = SaveManager:SaveJSON(ConfigNome)
    if not SucessoCodificar then
        return false, CodificarErroMensagem
    end

    local SucessoEscrever, ErroMensagem = pcall(writefile, ConfigCaminho, CodificadoDados)
    if not SucessoEscrever then
        return false, "Failed to write config file: " .. tostring(ErroMensagem)
    end

    return true
end

function SaveManager:LoadJSON(Conteudo: string)
    if EhTextoVazio(Conteudo) then
        return false, "Nenhum JSON informado"
    end

    local SucessoDecodificar, Decodificado = pcall(HttpService.JSONDecode, HttpService, Conteudo)
    if not SucessoDecodificar or typeof(Decodificado) ~= "table" or typeof(Decodificado.objects) ~= "table" then
        return false, "Failed to decode config data"
    end

    local Library = SaveManager.Library
    local CarregandoOrdem = SaveManager.LoadingOrder
    local IgnorarIndices = SaveManager.Ignore

    if SaveManager.UseLoadingOrder == true and typeof(CarregandoOrdem) == "table" then
        table.sort(Decodificado.objects, function(a, b)
            local aIndice = table.find(CarregandoOrdem, a.type) or math.huge
            local bIndice = table.find(CarregandoOrdem, b.type) or math.huge
            return aIndice < bIndice
        end)
    end

    if Library.KeybindFrame and typeof(Decodificado.keybindMenu) == "table" then
        local AtalhoQuadroDados = Decodificado.keybindMenu
        local EhVisivel = AtalhoQuadroDados.visible == true
        local Posicao = EspecialValorAnalisador.UDim2.Decode(AtalhoQuadroDados.position)

        Library.KeybindFrame.Visible = EhVisivel
        Library.KeybindFrame.Position = Posicao or Library.KeybindFrame.Position
        
        local AtalhoMenuAlternador = Library.Options and Library.Options.KeybindMenuOpen
        if AtalhoMenuAlternador then
            AtalhoMenuAlternador:SetValue(EhVisivel)
        end
    end

    for _, Opcao in Decodificado.objects do
        if not Opcao.type then continue end
        if IgnorarIndices[Opcao.idx] then continue end

        local Analisador = ElementoAnalisador[Opcao.type]
        if not Analisador then continue end

        task.defer(Analisador.Load, Opcao.idx, Opcao)
    end

    return true
end

function SaveManager:Load(ConfigNome: string): (boolean, string?)
    if EhTextoVazio(ConfigNome) then
        return false, "No config is selected"
    end

    local ConfigCaminho = ObterConfigCaminho(ConfigNome)
    if ConfigCaminho == false or not isfile(ConfigCaminho) then
        return false, "Config file does not exist"
    end

    local SucessoLer, Conteudo = pcall(readfile, ConfigCaminho)
    if not SucessoLer then
        return false, "Failed to read config file"
    end

    return SaveManager:LoadJSON(Conteudo)
end

function SaveManager:Delete(ConfigNome: string): (boolean | string?)
    if EhTextoVazio(ConfigNome) then
        return false, "No config is selected"
    end

    local ConfigCaminho = ObterConfigCaminho(ConfigNome)
    if ConfigCaminho == false or not isfile(ConfigCaminho) then
        return false, "Config file does not exist"
    end

    local SucessoExcluir, ErroMensagem = pcall(delfile, ConfigCaminho)
    if not SucessoExcluir then
        return false, "Failed to delete config file: " .. tostring(ErroMensagem)
    end

    if ConfigNome == SaveManager.AutoloadConfig then
        SaveManager:DeleteAutoLoadConfig()
    end

    return true
end

function SaveManager:GetAutoloadConfig(): (string, boolean, string?)
    SaveManager:CheckFolderTree()

    local CarregamentoAutoCaminho = ObterCarregamentoAutoCaminho()
    if CarregamentoAutoCaminho == false then
        return "none", false, "Invalid path provided"
    end

    if not isfile(CarregamentoAutoCaminho) then
        return "none", false, "Autoload config is not set"
    end

    local SucessoLer, CarregamentoAutoConfigNome = pcall(readfile, CarregamentoAutoCaminho)
    if not (SucessoLer and typeof(CarregamentoAutoConfigNome) == "string") then
        return "none", false, CarregamentoAutoConfigNome
    end

    local ConfigExiste = FazConfigExistir(CarregamentoAutoConfigNome)
    if not ConfigExiste then
        return "none", false, "Config file not found"
    end

    SaveManager.AutoloadConfig = CarregamentoAutoConfigNome
    return CarregamentoAutoConfigNome, true
end

function SaveManager:SaveAutoloadConfig(ConfigNome: string): (boolean, string?)
    if EhTextoVazio(ConfigNome) then
        return false, "No config is selected"
    end

    SaveManager:CheckFolderTree()

    local CarregamentoAutoCaminho = ObterCarregamentoAutoCaminho()
    if CarregamentoAutoCaminho == false then
        return false, "Invalid path provided"
    end

    if not FazConfigExistir(ConfigNome) then
        return false, "Config does not exist"
    end

    local SucessoEscrever, ErroMensagem = pcall(writefile, CarregamentoAutoCaminho, ConfigNome)
    if not SucessoEscrever then
        return false, ErroMensagem
    end

    SaveManager.AutoloadConfig = ConfigNome
    return true
end

function SaveManager:LoadAutoloadConfig()
    local ConfigNome, Sucesso, BuscarErroMensagem = SaveManager:GetAutoloadConfig()
    if not Sucesso or BuscarErroMensagem then
        if BuscarErroMensagem ~= "Autoload config is not set" then
            SaveManager.Library:Notify(string.format("Falha ao carregar configuração automática: %s", BuscarErroMensagem))
        end

        return
    end

    local SucessoCarregar, CarregarErroMensagem = SaveManager:Load(ConfigNome)
    if not SucessoCarregar then
        SaveManager.Library:Notify(string.format("Falha ao carregar configuração automática: %s", CarregarErroMensagem))
        return
    end

    SaveManager.Library:Notify(string.format("Configuração automática %q carregada com sucesso", ConfigNome))
end

function SaveManager:DeleteAutoLoadConfig(): (boolean, string?)
    SaveManager:CheckFolderTree()

    local CarregamentoAutoCaminho = ObterCarregamentoAutoCaminho()
    if CarregamentoAutoCaminho == false then
        return false, "Invalid path provided"
    end

    if not isfile(CarregamentoAutoCaminho) then
        return false, "Autoload config is not set"
    end

    local SucessoExcluir, ErroMensagem = pcall(delfile, CarregamentoAutoCaminho)
    if not SucessoExcluir then
        return false, ErroMensagem
    end

    SaveManager.AutoloadConfig = nil
    return true
end

local function MostrarDialogo(
    Condition: () -> boolean,

    Indice: string, 
    Title: string, 
    Description: string,

    DestructiveText: string,
    DestructiveAction: () -> nil
)
    if Condition() == false then
        return DestructiveAction()
    end

    return SaveManager.Library.Window:AddDialog(Indice, {
        Title = Title,
        Description = Description,
        AutoDismiss = false,

        FooterButtons = {
            Cancel = {
                Title = "Cancelar",
                Variant = "Ghost",
                Order = 1,
                Callback = function(Dialogo)
                    Dialogo:Dismiss()
                end
            },

            DestructiveAction = {
                Title = DestructiveText,
                Variant = "Destructive",
                Order = 2,
                Callback = function(Dialogo)
                    Dialogo:Dismiss()
                    DestructiveAction()
                end
            }
        }
    })
end

function SaveManager:BuildConfigSection(Aba: any, IconeNome: string)
    assert(SaveManager.Library, "Library is not set, call SaveManager:SetLibrary(Library) first.")
    local ConfiguracaoCaixa = Aba:AddGroupbox({
        Side = "Right",
        Name = "Configuração",
        IconName = IconeNome or "folder-cog",
    })

    local ConfigNomeEntrada, ConfigLista, ConfigJSONEntrada, CarregamentoAutoConfigRotulo
    local function AtualizarLista()
        ConfigLista:SetValues(SaveManager:RefreshConfigList())
        ConfigLista:SetValue(nil)
    end

    local function AtualizarCarregamentoAutoConfigRotulo()
        local CarregamentoAutoConfigNome, _Sucesso, _ErroMensagem = SaveManager:GetAutoloadConfig()

        CarregamentoAutoConfigRotulo:SetText(string.format("Config. automática atual: %s", CarregamentoAutoConfigNome))
        if ConfigLista then AtualizarLista() end
    end

    ConfiguracaoCaixa:AddInput("SaveManager_ConfigName", {
        Text = "Nome da configuração"
    })

    ConfiguracaoCaixa:AddButton("Criar configuração", function()
        local ConfigNome = ConfigNomeEntrada.Value
        if EhTextoVazio(ConfigNome) then
            SaveManager.Library:Notify("O nome da configuração não pode estar vazio.")
            return
        end

        if string.lower(ConfigNome) == "autoload" then
            SaveManager.Library:Notify("Nome de configuração inválido.")
            return
        end
        
        MostrarDialogo(
            function(): boolean
                return FazConfigExistir(ConfigNome)
            end,

            "SaveManager_CreateConfig",
            "Configuração já existe",
            string.format("Já existe uma configuração chamada %q. Sobrescrever substituirá pelas opções atuais.", ConfigNome),

            "Sobrescrever",
            function()
                local Sucesso, ErroMensagem = SaveManager:Save(ConfigNome)
                if not Sucesso then
                    SaveManager.Library:Notify(string.format("Falha ao criar configuração %q: %s", ConfigNome, ErroMensagem))
                    return
                end

                SaveManager.Library:Notify(string.format("Configuração %q criada com sucesso", ConfigNome))
                AtualizarLista()
            end
        )
    end)

    ConfiguracaoCaixa:AddDivider()

    ConfiguracaoCaixa:AddDropdown("SaveManager_ConfigList", {
        Text = "Lista de configurações",

        Values = SaveManager:RefreshConfigList(),
        AllowNull = true,
        Multi = false,

        FormatDisplayValue = function(Valor: any)
            if Valor == SaveManager.AutoloadConfig then
                return string.format("%s (automática)", Valor)
            end

            return Valor
        end,
        FormatListValue = function(Valor: any)
            if Valor == SaveManager.AutoloadConfig then
                return string.format("%s (automática)", Valor)
            end

            return Valor
        end
    })

    ConfiguracaoCaixa:AddButton({
        Text = "Carregar configuração",
        DoubleClick = false,

        Func = function()
            local ConfigNome = ConfigLista.Value
            if EhTextoVazio(ConfigNome) then
                SaveManager.Library:Notify("Selecione uma configuração primeiro.")
                return
            end

            MostrarDialogo(
                function(): boolean
                    return true 
                end,

                "SaveManager_LoadConfig",
                "Carregar configuração",
                string.format("Tem certeza que deseja carregar %q? Suas configurações atuais serão substituídas.", ConfigNome),

                "Carregar",
                function()
                    local Sucesso, ErroMensagem = SaveManager:Load(ConfigNome)
                    if not Sucesso then
                        SaveManager.Library:Notify(string.format("Falha ao carregar configuração %q: %s", ConfigNome, ErroMensagem))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Configuração %q carregada com sucesso", ConfigNome))
                end
            )
        end
    })
    
    ConfiguracaoCaixa:AddButton({
        Text = "Sobrescrever configuração",
        DoubleClick = false,

        Func = function()
            local ConfigNome = ConfigLista.Value
            if EhTextoVazio(ConfigNome) then
                SaveManager.Library:Notify("Selecione uma configuração primeiro.")
                return
            end

            MostrarDialogo(
                function(): boolean
                    return true 
                end,

                "SaveManager_OverwriteConfig",
                "Sobrescrever configuração",
                string.format("Tem certeza que deseja sobrescrever %q com suas opções atuais? Isso não pode ser desfeito.", ConfigNome),

                "Sobrescrever",
                function()
                    local Sucesso, ErroMensagem = SaveManager:Save(ConfigNome)
                    if not Sucesso then
                        SaveManager.Library:Notify(string.format("Falha ao sobrescrever configuração %q: %s", ConfigNome, ErroMensagem))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Configuração %q sobrescrita com sucesso", ConfigNome))
                end
            )
        end
    })

    ConfiguracaoCaixa:AddButton({
        Text = "Excluir configuração",
        DoubleClick = false,

        Func = function()
            local ConfigNome = ConfigLista.Value
            if EhTextoVazio(ConfigNome) then
                SaveManager.Library:Notify("Selecione uma configuração primeiro.")
                return
            end

            MostrarDialogo(
                function(): boolean
                    return true 
                end,

                "SaveManager_DeleteConfig",
                "Excluir configuração",
                string.format("Tem certeza que deseja excluir %q? Isso não pode ser desfeito.", ConfigNome),
                
                "Excluir",
                function()
                    local Sucesso, ErroMensagem = SaveManager:Delete(ConfigNome)
                    if not Sucesso then
                        SaveManager.Library:Notify(string.format("Falha ao excluir configuração %q: %s", ConfigNome, ErroMensagem))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Configuração %q excluída com sucesso", ConfigNome))
                    AtualizarCarregamentoAutoConfigRotulo()
                end
            )
        end
    })

    ConfiguracaoCaixa:AddButton("Atualizar lista", AtualizarLista)

    ConfiguracaoCaixa:AddButton({
        Text = "Definir como automática",
        DoubleClick = false,

        Func = function()
            local ConfigNome = ConfigLista.Value
            if EhTextoVazio(ConfigNome) then
                SaveManager.Library:Notify("Selecione uma configuração primeiro.")
                return
            end

            local Sucesso, ErrorMessage = SaveManager:SaveAutoloadConfig(ConfigNome)
            if not Sucesso then
                SaveManager.Library:Notify(string.format("Falha ao definir config. automática %q: %s", ConfigNome, ErroMensagem))
                return
            end

            SaveManager.Library:Notify(string.format("Configuração automática definida para %q", ConfigNome))
            AtualizarCarregamentoAutoConfigRotulo()
        end
    })

    ConfiguracaoCaixa:AddButton({
        Text = "Limpar config. automática",
        DoubleClick = false,

        Func = function()
            MostrarDialogo(
                function(): boolean
                    return true 
                end,

                "SaveManager_ResetAutoload",
                "Limpar config. automática",
                "Tem certeza que deseja remover a configuração automática? Nenhuma será carregada automaticamente ao iniciar.",
                
                "Resetar",
                function()
                    local Sucesso, ErroMensagem = SaveManager:DeleteAutoLoadConfig()
                    if not Sucesso then
                        SaveManager.Library:Notify(string.format("Falha ao limpar configuração automática: %s", ErroMensagem))
                        return
                    end

                    SaveManager.Library:Notify("Configuração automática limpa com sucesso.")
                    AtualizarCarregamentoAutoConfigRotulo()
                end
            )
        end
    })

    CarregamentoAutoConfigRotulo = ConfiguracaoCaixa:AddLabel("Config. automática atual: ...", true);

    ConfiguracaoCaixa:AddDivider()

    ConfiguracaoCaixa:AddInput("SaveManager_JSON", {
        Text = "JSON da Configuração"
    })

    ConfiguracaoCaixa:AddButton("Importar configuração", function()
        local ConfigJSON = ConfigJSONEntrada.Value
        if EhTextoVazio(ConfigJSON) then
            SaveManager.Library:Notify("O JSON da configuração não pode estar vazio.")
            return
        end

        MostrarDialogo(
            function(): boolean
                return true 
            end,

            "SaveManager_ImportConfig",
            "Importar configuração",
            "Tem certeza que deseja importar esta configuração? Suas opções atuais serão substituídas.",

            "Importar",
            function()
                local Sucesso, ErroMensagem = SaveManager:LoadJSON(ConfigJSON)
                if not Sucesso then
                    SaveManager.Library:Notify(string.format("Falha ao importar configuração: %s", ErroMensagem))
                    return
                end

                SaveManager.Library:Notify("Configuração importada com sucesso")
            end
        )
    end)

    ConfiguracaoCaixa:AddButton("Exportar config. atual", function()
        local CodificadoDados, Sucesso, ErroMensagem = SaveManager:SaveJSON()
        if not Sucesso  then
            SaveManager.Library:Notify(ErroMensagem)
            return
        end

        ConfigJSONEntrada:SetValue(CodificadoDados)
        if setclipboard then
            setclipboard(CodificadoDados)
            SaveManager.Library:Notify("Configuração copiada para a área de transferência")
        end
    end)

    ConfigNomeEntrada, ConfigLista, ConfigJSONEntrada =
        SaveManager.Library.Options.SaveManager_ConfigName, 
        SaveManager.Library.Options.SaveManager_ConfigList,
        SaveManager.Library.Options.SaveManager_JSON;

    AtualizarCarregamentoAutoConfigRotulo()
    SaveManager:SetIgnoreIndexes({ "SaveManager_ConfigList", "SaveManager_ConfigName", "SaveManager_JSON" })

    return ConfiguracaoCaixa
end

SaveManager:BuildFolderTree()
return SaveManager
]]
bundle["IconAtlas"] = [=[
local Lucide = {}

local EH_GETCUSTOMASSET_QUEBRADO = false

if writefile and isfolder and makefolder and getcustomasset then
	if not isfolder("lucide-icons") then
		makefolder("lucide-icons")
	end

	if not isfile("lucide-icons/version.txt") then
		writefile("lucide-icons/version.txt", "2026-09-01T03:49:17.713242330+00:00")
	end

	local DeveAtualizar = readfile("lucide-icons/version.txt") ~= "2026-09-01T03:49:17.713242330+00:00"

	if DeveAtualizar then
		writefile("lucide-icons/version.txt", "2026-09-01T03:49:17.713242330+00:00")
	end

	for spritesheet = 1, 2 do
		if isfile(`lucide-icons/{spritesheet}.png`) and not DeveAtualizar then
			continue
		end

		writefile(
			`lucide-icons/{spritesheet}.png`,
			game:HttpGet(
				`https://raw.githubusercontent.com/mstudio45/lucide-roblox-direct/1c37dd176d79ab42388597aa9dc9e3a1b0dd7416/spritesheets/{spritesheet}.png`
			)
		)
	end

	local Sucesso, _Erro = pcall(function()
		return getcustomasset("lucide-icons/1.png")
	end)

	EH_GETCUSTOMASSET_QUEBRADO = not Sucesso
end

