local iconeIndices: { string } = icones[1]
local idIndices: { string } = icones[2]
local iconeRegistro: { [number]: { number | { number } } } = icones[3]

Lucide.Icons = iconeIndices
function Lucide.GetAsset(nome: string)
	local tamanho = 48

	local iconeIndice = table.find(iconeIndices, nome)

	if not iconeIndice then
		return nil
	end

	local atualDiferenca = math.huge
	local atualTamanho = tamanho

	for registroTamanho, _ in iconeRegistro do
		local diferenca = math.abs(tamanho - registroTamanho)

		if diferenca < atualDiferenca then
			atualDiferenca = diferenca
			atualTamanho = registroTamanho
		end
	end

	local icone = iconeRegistro[atualTamanho][iconeIndice]
	if icone then
		return {
			IconName = nome,
			Url = idIndices[icone[1]],
			ImageRectSize = Vector2.new(icone[2][1], icone[2][2]),
			ImageRectOffset = Vector2.new(icone[3][1], icone[3][2]),
		}
	end

	return nil
end

return Lucide
