							api.ResolverEntradaRecurso = function(arg, arg2, arg3, arg4, arg5, arg6)
								local correspondencia = tostring(arg or ""):match("^%s*(.-)%s*$")
								local personalizadoRecursos = estadoCompartilhado.CustomAssets
								personalizadoRecursos.Requests[arg2] = (personalizadoRecursos.Requests[arg2] or 0) + 1
								local valor24 = personalizadoRecursos.Requests[arg2]

								if correspondencia == "" then
