								local texto6 = correspondencia:lower()
								local correspondencia2 = correspondencia:match("^%d+$") or texto6:match("^rbxassetid://(%d+)$")

								if not correspondencia2 and texto6:find("roblox.com", 1, true) then
									correspondencia2 = texto6:match("[?&]id=(%d+)") or texto6:match("/asset/(%d+)") or texto6:match("/library/(%d+)")
								end

