					filaMetodos.Enfileirar = function(arg, arg2, arg3, arg4)
						if not (arg and arg2 and arg3) then
							return
						end
						arg4 = arg4 or arg
						local tabela16 = filaMetodos.Trabalhadores[arg]

						if not tabela16 then
							tabela16 = { Items = {}, Pending = {}, Head = 1, Tail = 0, Running = false }
							filaMetodos.Trabalhadores[arg] = tabela16
						end

						local numero36 = filaMetodos.Geracoes[arg4] or 0
						local valor24 = tabela16.Pending[arg3]
						if valor24 and valor24.Owner == arg4 and valor24.Epoch == filaMetodos.Epoca and valor24.Generation == numero36 then
							return
						end
						local tabela17 = { Callback = arg2, Player = arg3, Owner = arg4, Epoch = filaMetodos.Epoca, Generation = numero36 }
						tabela16.Tail = tabela16.Tail + 1
						tabela16.Items[tabela16.Tail] = tabela17
						tabela16.Pending[arg3] = tabela17
						if tabela16.Running then
