								local valor25 = tabela16.Items[tabela16.Head]

								if valor25 then
									tabela16.Items[tabela16.Head] = nil
									tabela16.Head = tabela16.Head + 1
									local estado12 = valor25.Epoch == filaMetodos.Epoca

									if estado12 then
										estado12 = valor25.Generation == (filaMetodos.Geracoes[valor25.Owner] or 0)
									end

									if estado12 and valor25.Player.Parent then
										local sucesso, resultado = pcall(valor25.Callback, valor25.Player)

										if not sucesso then
