						local miraRaioFiltro = estadoCompartilhado.AimRaycastFilter
						local miraRaioParametros = api.ParametrosRaioMira
						local enorme = math.huge
						local valor24 = nil

						for _, valor25 in pairs(estadoCompartilhado.PlayerList) do
							if valor25 ~= jogadorLocal and valor25.Character and not api.EhJogadorProtegido(valor25, true) then
								local dentroDoLote2 = valor25:FindFirstChild("InPlot")

