									local humanoide = valor25.Character:FindFirstChild("Humanoid")

									if valor26 and humanoide and humanoide.Health > 0 then
										local valor27, valor28 = mundoParaAreaVisaoPonto(cameraAtual, valor26.Position)

										if valor28 then
											local numero38 = valor27.X - x
