							valor26.Root.Size = valor26.Size
							valor26.Root.CustomPhysicalProperties = valor26.Physics
							valor26.Root.CanCollide = valor26.CanCollide
						end

						silenciosaMiraEstado.Players[arg] = nil
						valor26 = nil
					end

					if not valor25 or not estado12 then
						return
					end

