						silenciosaMiraEstado.HitboxSize = Vector3.new(miraSilenciosaCaixaColisao, miraSilenciosaCaixaColisao, miraSilenciosaCaixaColisao)
						silenciosaMiraEstado.PhysicalProperties = PhysicalProperties.new(2.8 / miraSilenciosaCaixaColisao ^ 3, 0.3, 0.5, 1, 1)
					end

					valor25.Size = silenciosaMiraEstado.HitboxSize
					valor25.CustomPhysicalProperties = silenciosaMiraEstado.PhysicalProperties
