				api.RecarregarMiraSilenciosa = function()
					for _, valor24 in ipairs(estadoCompartilhado.PlayerList) do
						api.AplicarMiraSilenciosaJogador(valor24)
					end

					local estado12 = estadoCompartilhado.SilentAimState.RaycastActive == true
					local silenciosaMiraMetodo = bibliotecaUI.Labels and bibliotecaUI.Labels.SilentAimMethod

					if silenciosaMiraMetodo then
						local valor24 = silenciosaMiraMetodo
						local definirTexto = valor24.SetText
						local metodo

						if estado12 then
							metodo = "Raycast do Jogo"
						else
							metodo = "Hitbox (Compatibilidade)"
						end

						definirTexto(valor24, "Método: " .. metodo)
