					elseif not silenciosaMiraEstado.Patch and type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
						local correcao = {}

						local function envoltorio(arg2, ...)
							local valor24 = table.pack(...)
							if descarregado or not estadoFuncoes.SilentAim or not silenciosaMiraEstado.RaycastActive or arg2 ~= workspace or getnamecallmethod() ~= "Raycast" or checkcaller and checkcaller() then
								return correcao.Original(arg2, ...)
							end
							local valor25 = ...
							local valor = select(2, ...)
							local valor2 = select(3, ...)
							local cameraAtual2 = workspace.CurrentCamera
							if not cameraAtual2 or typeof(valor25) ~= "Vector3" or typeof(valor) ~= "Vector3" or valor.Magnitude <= 0 or (valor25 - cameraAtual2.CFrame.Position).Magnitude >= 0.1 or valor.Unit:Dot(cameraAtual2.CFrame.LookVector) <= 0.999 then
								return correcao.Original(arg2, table.unpack(valor24, 1, valor24.n))
							end
							local sucesso, resultado = pcall(getcallingscript)
							if sucesso and resultado and resultado.Name ~= "GrabbingScript" and resultado.Name ~= "RaycastModule" then
								return correcao.Original(arg2, table.unpack(valor24, 1, valor24.n))
