					local numero = nil
					local numero37 = nil
					local numero38 = 0
					api.DessincronizacaoSuportada = type(sethiddenproperty) == "function" and type(setfflag) == "function" and type(getfflag) == "function"

					local function funcao21(arg)
						for _, valor25 in ipairs({ tostring(arg), arg }) do
