						end

						if agora3 < numero36 then
							if not pcall(sethiddenproperty, valor24, "PhysicsRepRootPart", valor24) then
								return funcao23()
							end
							return
						end

						estado12 = true
						local valor28 = valor24
						local valor29 = numero38
						if not pcall(sethiddenproperty, valor28, "PhysicsRepRootPart", nil) then
