					api.QuebrarSeguravel = function(arg, arg2, arg3)
						local valor22, valor23, valor24 = api.ObterPersonagem()
						local esquerdaPegadaAnexo = valor22 and valor22:FindFirstChild("Left Arm") and valor22["Left Arm"]:FindFirstChild("LeftGripAttachment")
						local segurarParte = arg and arg:FindFirstChild("HoldPart")
						local segurarItemRemotoFuncao = segurarParte and segurarParte:WaitForChild("HoldItemRemoteFunction", 0.45)
						local soltarItemRemotoFuncao = segurarItemRemotoFuncao and segurarParte:WaitForChild("DropItemRemoteFunction", 0.45)
						local rigidoRestricao = soltarItemRemotoFuncao and segurarParte:WaitForChild("RigidConstraint", 0.45)
						if not (valor22 and valor24 and esquerdaPegadaAnexo and segurarItemRemotoFuncao and soltarItemRemotoFuncao and rigidoRestricao) then
							return false
						end

						if arg3 then
