						end

						local agora3 = tick()

						while true do
							local estado12 = valor22.Parent and arg.Parent and esquerdaPegadaAnexo.Parent and rigidoRestricao.Parent and rigidoRestricao.Attachment1 ~= esquerdaPegadaAnexo

							if estado12 then
								estado12 = tick() - agora3 < (arg2 or 0.6)
							end

							if estado12 then
								task.spawn(function()
									pcall(segurarItemRemotoFuncao.InvokeServer, segurarItemRemotoFuncao, arg, valor22)
								end)

								task.wait()
								continue
							end

							break
						end

						if rigidoRestricao.Attachment1 ~= esquerdaPegadaAnexo then
							return false
						end

						task.spawn(function()
							pcall(soltarItemRemotoFuncao.InvokeServer, soltarItemRemotoFuncao, arg)
						end)

						soltarItemRemotoFuncao:Destroy()
						local agora4 = tick()

						while true do
							RunService.Heartbeat:Wait()
							if not (not rigidoRestricao.Parent or rigidoRestricao.Attachment1 ~= esquerdaPegadaAnexo or tick() - agora4 > 0.45) then
								continue
							end
							break
						end

						for _, valor25 in valor24:GetPlayingAnimationTracks() do
							local correspondencia = valor25.Animation and valor25.Animation.AnimationId:match("%d+")

							if not (correspondencia and estadoCompartilhado.AnimationWhitelist[correspondencia]) then
								valor25:Stop()
							end
						end

						return rigidoRestricao.Parent and rigidoRestricao.Attachment1 ~= esquerdaPegadaAnexo
					end

					api.GerarFormasCoco = function()
