						cocoFormas.CapeStart = nil

						for _, valor22 in cocoFormas.Order, nil, nil do
							if selecionado[valor22] and #deslocamentos + cocoFormas.Counts[valor22] <= cocoFormas.Limit then
								if valor22 == "Boobs" then
									local numero37 = #deslocamentos + 1
									local numero38 = #deslocamentos + 2
