									deslocamentos[numero38] = cframe2
								elseif valor22 == "Ass" then
									local numero37 = #deslocamentos + 1
									local numero38 = #deslocamentos + 2
									local cframe = CFrame.new(-0.55, -1, 0.75)
									local cframe2 = CFrame.new(0.55, -1, 0.75)
									deslocamentos[numero37] = cframe
									deslocamentos[numero38] = cframe2
								elseif valor22 == "Penis" then
									local numero37 = #deslocamentos + 1
									local numero38 = #deslocamentos + 2
									local cframe = CFrame.new(-0.55, -1.2, -0.8)
									local cframe2 = CFrame.new(0.55, -1.2, -0.8)
									deslocamentos[numero37] = cframe
									deslocamentos[numero38] = cframe2

									for i = 1, cocoFormas.ShaftLength do
										deslocamentos[#deslocamentos + 1] = CFrame.new(0, -1.2, -0.8 - i * cocoFormas.ShaftSpacing)
									end
								elseif valor22 == "Wings" then
									cocoFormas.WingStart = #deslocamentos + 1

									for i = 1, 12 do
										deslocamentos[#deslocamentos + 1] = CFrame.identity
									end
								elseif valor22 == "Cape" then
									cocoFormas.CapeStart = #deslocamentos + 1
									local numero37 = cocoFormas.Counts.Cape / 3

