					api.DefinirComprimentoCoco = function(arg)
						local cocoFormas = estadoCompartilhado.CoconutForms
						local numero37 = 11

						if cocoFormas.Selected.Penis then
							local numero38 = 0

							for k, valor22 in cocoFormas.Selected, nil, nil do
								valor22 = valor22 and k ~= "Penis"

								if valor22 then
									numero38 += cocoFormas.Counts[k]
								end
							end

							numero37 = math.max(1, cocoFormas.Limit - numero38 - 2)
						end

						local hasteComprimento = math.min(arg, numero37)
						local contagens = cocoFormas.Counts
						cocoFormas.ShaftLength = hasteComprimento
						contagens.Penis = hasteComprimento + 2

						if hasteComprimento ~= arg and opcoes.CoconutShaftLength then
							task.defer(function()
								opcoes.CoconutShaftLength:SetValue(hasteComprimento)
							end)
						end

						api.RecarregarFormasCoco()
					end

					api.LimparFormasCoco = function()
						local cocoFormas = estadoCompartilhado.CoconutForms
						estadoFuncoes.CoconutForms = false
						cocoFormas.Generation = cocoFormas.Generation + 1
						api.DefinirConexaoExecucao("CoconutForms", RunService.Heartbeat, false)

						for _, valor22 in cocoFormas.Models, nil, nil do
							api.DestruirBrinquedo(valor22)
						end

						table.clear(cocoFormas.Models)
