							api.AtualizarAuraBrinquedos = function(arg)
								local valor22, valor23, valor24 = api.ObterPersonagem()
								local estado12 = not brinquedosAuraConfiguracoes.Enabled or #brinquedosAuraConfiguracoes.Models == 0
								local estado13

								if estado12 then
