								while numero37 <= #brinquedosAuraConfiguracoes.Models do
									local valor25 = brinquedosAuraConfiguracoes.Models[numero37]
									local pai2 = valor25.Parent and registroPersonagem.ObterRaiz(valor25)

									if estadoCompartilhado.ObjectStates[valor25] then
										registroPersonagem.LimparMovedores(valor25)
										numero37 += 1
										continue
									end

									local estado14 = pai2 and api.EhDonoDaParte(pai2)

									if pai2 and not estado14 and api.DefinirDonoRede(pai2, 0.18) then
										registroPersonagem.AtualizarRaizesPersonagem()
										estado14 = registroPersonagem.ObterRaiz(valor25) == pai2
									end

									local valor26 = descarregado
									local estado15

