										estado15 = valor26
									else
										estado15 = not brinquedosAuraConfiguracoes.Enabled
									end

									if estado15 then
										registroPersonagem.LimparMovedores()
										return
									end

									if brinquedosAuraConfiguracoes.Models[numero37] == valor25 then
										if estadoCompartilhado.ObjectStates[valor25] then
											registroPersonagem.LimparMovedores(valor25)
											numero37 += 1
										elseif estado14 then
											valido[#valido + 1] = valor25
											raizes[#raizes + 1] = pai2
											numero37 += 1
