				api.CarregarPoseEditorAC = function(arg)
					if not arg then
						return
					end

					if not opcoes.ACCSecXO or not opcoes.ACRSecXOTorso then
						return
					end
					local corpoDeslocamento = arg.BodyOffset

					if not corpoDeslocamento and arg.BodyPos then
						corpoDeslocamento = CFrame.new(tonumber(arg.BodyPos[1]) or 0, tonumber(arg.BodyPos[2]) or 0, tonumber(arg.BodyPos[3]) or -5)
					end

					if corpoDeslocamento then
						local accSecXO = opcoes.ACCSecXO
						local definirValor = accSecXO.SetValue
						local valor22 = table.pack(tonumber(string.format("%.1f", corpoDeslocamento.X)))
						definirValor(accSecXO, table.unpack(valor22, 1, valor22.n))
						local accSecYO = opcoes.ACCSecYO
						local definirValor2 = accSecYO.SetValue
						local valor23 = table.pack(tonumber(string.format("%.1f", corpoDeslocamento.Y)))
						definirValor2(accSecYO, table.unpack(valor23, 1, valor23.n))
						local accSecZO = opcoes.ACCSecZO
						local definirValor3 = accSecZO.SetValue
						local valor24 = table.pack(tonumber(string.format("%.1f", corpoDeslocamento.Z)))
						definirValor3(accSecZO, table.unpack(valor24, 1, valor24.n))
					end

					local rotacao = arg.Rotation or arg

