								local valor25 = opcoes["ACOSecYO" .. k]
								local definirValor2 = valor25.SetValue
								local valor26 = table.pack(tonumber(string.format("%.1f", tonumber(y) or 0)))
								definirValor2(valor25, table.unpack(valor26, 1, valor26.n))
								local valor27 = opcoes["ACOSecZO" .. k]
								local definirValor3 = valor27.SetValue
