				api.TrazerJogador = function(arg)
					local valor22, valor23, valor24 = api.ObterPersonagem(arg)
					local valor25, valor26, valor27 = api.ObterPersonagem()
					local estado12 = arg == jogadorLocal or api.EhJogadorProtegido(arg)

					if not estado12 then
						estado12 = not (valor23 and valor24 and valor24.Health > 0 and valor26 and valor27 and valor27.Health > 0)
					end

					if estado12 then
						return
					end

					if not api.EhDonoDaRede(valor23) and not api.DefinirDonoRede(valor23) then
						return
					end
					local numero36 = valor26.CFrame * CFrame.new(0, 0, -5)
					local BasePart = valor22:QueryDescendants("BasePart")
					local tabela16 = {}

					for i = 1, 3 do
						local estado13 = descarregado

						if not descarregado then
							estado13 = not (valor23.Parent and valor22.Parent)
						end

						if not (estado13 or valor24.Health <= 0) then
							api.MoverPivoPara(valor22, numero36 * valor23.CFrame:Inverse() * valor22:GetPivot(), BasePart, tabela16)

							for _, valor28 in BasePart, nil, nil do
								api.ZerarVelocidade(valor28)
							end

							RunService.Heartbeat:Wait()
							continue
						end

						break
					end

					for _, valor28 in BasePart, nil, nil do
						if valor28.Parent then
							api.ZerarVelocidade(valor28)
						end
					end

					if valor23.Parent then
						api.LiberarDonoRede(valor23)
					end

					return valor23.Parent ~= nil and valor24.Health > 0
				end

				do
					local tabela16 = {}

					api.Matar = function(arg)
						local valor22, valor23, valor24 = api.ObterPersonagem(arg)

						if valor24 and valor24.Health ~= 0 and valor23 and api.ObterDistancia(workspace.SpawnLocation, valor23) < 15000 and not tabela16[valor22] then
							valor24.BreakJointsOnDeath = false
							valor24:ChangeState(Enum.HumanoidStateType.Dead)
							api.DestruirObjeto(valor22, valor23)
							tabela16[valor22] = true

