				end
			end

			api.EnviarParaVoid = function(arg)
				local valor22, valor23, valor24 = api.ObterPersonagem(arg)

				if valor24 and valor24.Health ~= 0 and valor23 and api.ObterDistancia(workspace.SpawnLocation, valor23) < 15000 and api.DefinirDonoRede(valor23) then
					local cframe = CFrame.new(0, 9e9, 0)
					api.MoverPivoPara(valor22, cframe * valor23.CFrame:Inverse() * valor22:GetPivot())
					api.Teleportar(valor23, cframe)
					valor23.Velocity = Vector3.new(0, 9e9, 0)
					task.delay(0.35, api.LiberarDonoRede, valor23)
