				return
			end
			local id = arg.Id or arg.id
			local numero = tonumber(arg.Playing or arg.playing)
			local numero2 = tonumber(arg.MaxPlayers or arg.maxPlayers)
			if type(id) ~= "string" or not numero or not numero2 or numero2 <= 0 then
