			end
			local numero36 = math.min(valoresConfig.ServerHopMinPlayers, valoresConfig.ServerHopMaxPlayers)
			local numero37 = math.max(valoresConfig.ServerHopMinPlayers, valoresConfig.ServerHopMaxPlayers)
			if arg.Playing < numero36 or arg.Playing > numero37 then
				return false
			end

			if not estadoFuncoes.ServerHopIncludeFull and arg.Playing >= arg.MaxPlayers then
				return false
			end
			return true
		end

		api.CarregarCacheServidores = function()
			if not readfile then
				return {}, nil, false, {}
			end

			if isfile and not isfile(estadoCompartilhado.ServerHop.CachePath) then
				return {}, nil, false, {}
			end

			local sucesso, resultado = pcall(function()
				return HttpService:JSONDecode(readfile(estadoCompartilhado.ServerHop.CachePath))
			end)

			if not sucesso or typeof(resultado) ~= "table" or resultado.PlaceId ~= idLugar or resultado.Schema ~= 4 then
				return {}, nil, false, {}
			end
			local tabela16 = {}
			local tabela17 = {}
			local valor22 = ipairs
			local servidores = resultado.Servers or {}

			for _, servidor in valor22(servidores) do
				local valor23 = api.NormalizarServidorTroca(servidor)

				if valor23 and valor23.Id ~= idServidor then
					tabela16[#tabela16 + 1] = valor23
				end
			end

			local valor23 = pairs
			local regioes = resultado.Regions or {}

			for k, regiao in valor23(regioes) do
				if type(k) == "string" and typeof(regiao) == "table" then
					tabela17[k] = {}

					for k2, valor24 in pairs(regiao) do
						if type(k2) == "string" and valor24 == true then
							tabela17[k][k2] = true
						end
					end
				end
			end

			local numero36 = tonumber(resultado.CachedAt) or 0
			local numero37 = os.time() - numero36
			return tabela16, numero36, numero37 >= 0 and numero37 <= 120, tabela17
		end

		api.SalvarCacheServidores = function(arg, arg2)
