		api.BuscarPaginaTrocaServidor = function(arg, arg2, arg3)
			local texto5 = arg3 or "Roblox"
			local sucesso, resultado = pcall(game.HttpGet, game, arg, true)
			if not sucesso then
				return nil, tostring(resultado)
			end

			if type(resultado) ~= "string" or resultado == "" then
				return nil, texto5 .. " returned an empty response"
			end
			local sucesso2, resultado2 = pcall(HttpService.JSONDecode, HttpService, resultado)
			if not sucesso2 or typeof(resultado2) ~= "table" then
				return nil, texto5 .. " returned an invalid JSON response"
			end

			if arg2 and typeof(resultado2[arg2]) ~= "table" then
				local erros = resultado2.errors and resultado2.errors[1]
				local texto6

				if erros then
					texto6 = tostring(erros.message)
				else
					texto6 = texto5 .. " returned no server data"
				end

				return nil, texto6
			end

			return resultado2
		end

