		api.RecarregarRegioesServidor = function()
			local lista, valor22 = api.BuscarPaginaTrocaServidor("https://apis.rovalra.com/v1/datacenters/list", nil, "RoValra")
			if not lista then
				return false, valor22
			end
			local servidorTroca = estadoCompartilhado.ServerHop
			local regiaoNomes = estadoCompartilhado.ServerHop.RegionNames
			local tabela16 = {}
			local regioes = {}

			for i = 2, #regiaoNomes do
				regioes[regiaoNomes[i]] = {}
			end

			for _, valor23 in ipairs(lista) do
				local localizacao = valor23.location
				local pais = localizacao and localizacao.country
				local cidade = localizacao and localizacao.city
				local texto5

				if type(pais) == "string" then
					texto5 = pais:upper()
				else
					texto5 = nil
				end

				local texto6 = texto5 and cidade and texto5 .. "\0" .. cidade
				local valor24 = api.ObterContinenteServidor(texto5)

				if valor23.inactive ~= true and texto6 and valor24 and not tabela16[texto6] then
					tabela16[texto6] = true

					regioes[valor24][#regioes[valor24] + 1] = {
						Country = texto5,
						City = cidade,
						Latitude = tonumber(localizacao.latLong and localizacao.latLong[1]),
						Longitude = tonumber(localizacao.latLong and localizacao.latLong[2]),
					}
				end
			end

			if not next(tabela16) then
				return false, "RoValra returned no active datacenters"
			end
			servidorTroca.Regions = regioes
			servidorTroca.AutomaticCountry = nil
			servidorTroca.PlayerCoordinates = nil
			table.clear(servidorTroca.ResolvedRegions)
			return true
		end

		api.ObterCoordenadasJogador = function()
			local servidorTroca = estadoCompartilhado.ServerHop
			local LocalizationService = game:GetService("LocalizationService")
			local sucesso, resultado = pcall(LocalizationService.GetCountryRegionForPlayerAsync, LocalizationService, jogadorLocal)
			if not sucesso or type(resultado) ~= "string" or resultado == "" then
				return
			end
			local automaticoPais = resultado:upper()
			if servidorTroca.AutomaticCountry == automaticoPais then
				local jogadorCoordenadas = servidorTroca.PlayerCoordinates
				return jogadorCoordenadas and jogadorCoordenadas.X, jogadorCoordenadas and jogadorCoordenadas.Y, automaticoPais
			end
			local correspondencia = nil
			local valor22 = nil

			for _, valor23 in ipairs({
				"https://cdn.jsdelivr.net/gh/google/dspl@master/samples/google/canonical/countries.csv",
				"https://raw.githubusercontent.com/google/dspl/master/samples/google/canonical/countries.csv",
			}) do
				local sucesso2, resultado2 = pcall(game.HttpGet, game, valor23, true)

				if sucesso2 and type(resultado2) == "string" then
					correspondencia, valor22 = resultado2:match("\n" .. automaticoPais .. ",([%d%.%-]+),([%d%.%-]+),")
					if not correspondencia then
						continue
					end
				else
					continue
				end

				break
			end

			local numero = tonumber(correspondencia)
			local numero2 = tonumber(valor22)
			local valor23 = servidorTroca.CountryCoordinates[automaticoPais]

			if not numero and valor23 then
				numero = valor23.X
				numero2 = valor23.Y
			end

			servidorTroca.AutomaticCountry = automaticoPais
			local vetor2

			if numero and numero2 then
				vetor2 = Vector2.new(numero, numero2)
			else
				vetor2 = nil
			end

			servidorTroca.PlayerCoordinates = vetor2
			table.clear(servidorTroca.ResolvedRegions)
			return numero, numero2, automaticoPais
		end

		api.ObterRegioesTrocaServidor = function()
			local servidorTroca = estadoCompartilhado.ServerHop
			local servidorTrocaRegiao = valoresConfig.ServerHopRegion

			if not next(servidorTroca.Regions) then
				local valor22, valor23 = api.RecarregarRegioesServidor()
				if not valor22 then
					return nil, valor23
				end
			end

			if servidorTrocaRegiao ~= "Automatic" and not servidorTroca.Regions[servidorTrocaRegiao] then
				valoresConfig.ServerHopRegion = "Automatic"
				servidorTrocaRegiao = "Automatic"

				if opcoes.ServerHopRegion then
					opcoes.ServerHopRegion:SetValue("Automatic")
				end
			end

			local valor22, valor23, valor24 = api.ObterCoordenadasJogador()
			local texto5 = valor24 and valor24 .. "\0" .. servidorTrocaRegiao
			if texto5 and servidorTroca.ResolvedRegions[texto5] then
