						local tabela16 = servidorTroca.Regions[valor26] or {}

						for _, valor28 in valor27(tabela16) do
							local valor29 = funcao21(valor28)

							if valor29 < enorme then
								enorme = valor29
								servidorTrocaRegiao = valor26
