			if valoresConfig.ServerHopSort == "Closest Datacenter" or valoresConfig.ServerHopSort == "Lowest Ping" or valoresConfig.ServerHopSort == "Random" then
				return arg[math.random(1, #arg)]
			end

			table.sort(arg, function(arg2, arg3)
				local jogando, jogando2

				if valoresConfig.ServerHopSort == "Lowest Players" then
					jogando = arg2.Playing
					jogando2 = arg3.Playing
				elseif valoresConfig.ServerHopSort == "Highest Players" then
					jogando = -arg2.Playing
					jogando2 = -arg3.Playing
				elseif valoresConfig.ServerHopSort == "Highest FPS" then
					jogando = -(arg2.FPS or 0)
					jogando2 = -(arg3.FPS or 0)
				else
					jogando = arg2.Ping or math.huge
					jogando2 = arg3.Ping or math.huge
				end

				if jogando == jogando2 then
