		api.TentarNovamenteServidorCheio = function()
			local valor22 = descarregado
			local cancelado

			if descarregado then
				cancelado = valor22
			else
				cancelado = estadoCompartilhado.ServerHop.Cancelled
			end

			if cancelado then
				return false
			end
			local pendente = estadoCompartilhado.ServerHop.Pending
			if not pendente then
				return estadoCompartilhado.ServerHop.Retrying == true
			end
			estadoCompartilhado.ServerHop.Pending = nil
			estadoCompartilhado.ServerHop.Rejected[pendente.ServerId] = true
			estadoCompartilhado.ServerHop.Busy = false
			estadoCompartilhado.ServerHop.Retrying = true
			local token = estadoCompartilhado.ServerHop.Token
			api.AtualizarBotaoTrocaServidor()
			notificar("Servidor cheio; tentando outro servidor na região selecionada.")

			task.delay(1, function()
				if descarregado or token ~= estadoCompartilhado.ServerHop.Token then
					return
				end
				estadoCompartilhado.ServerHop.Retrying = false

				if not descarregado then
					api.TrocarServidor(pendente.AntiLag, pendente.RestartScript)
				end
			end)

			return true
		end

		api.AgendarTrocaAutomaticaServidor = function(arg)
