			local valor22 = descarregado
			local estado12

			if descarregado then
				estado12 = valor22
			else
				estado12 = not estadoFuncoes.AutoServerHop
			end

			if estado12 then
				return
			end

			task.delay(arg or valoresConfig.AutoServerHopTime, function()
				if descarregado or autoToken ~= estadoCompartilhado.ServerHop.AutoToken or not estadoFuncoes.AutoServerHop then
					return
				end

				if not api.TrocarServidor(estadoFuncoes.RejoinWithAntiLag ~= false, estadoFuncoes.RejoinWithScript) and autoToken == estadoCompartilhado.ServerHop.AutoToken and estadoFuncoes.AutoServerHop then
					api.AgendarTrocaAutomaticaServidor(math.min(15, valoresConfig.AutoServerHopTime))
				end
			end)
		end

