			if arg ~= jogadorLocal or descarregado then
				return
			end

			if estadoCompartilhado.ServerHop.Cancelled or estadoCompartilhado.ServerHop.Busy and not estadoCompartilhado.ServerHop.Pending then
				return
			end

			if estadoCompartilhado.ServerHop.Pending and arg5 and arg5.ServerInstanceId ~= "" and arg5.ServerInstanceId ~= estadoCompartilhado.ServerHop.Pending.ServerId then
				return
			end
			local estado12 = arg2 == Enum.TeleportResult.GameFull

			if not estado12 then
				estado12 = tostring(arg3):lower():find("full", 1, true)
			end

			if estado12 then
				if api.TentarNovamenteServidorCheio() then
					return
				end
			else
				estadoCompartilhado.ServerHop.Pending = nil
			end

			api.AtualizarBotaoTrocaServidor()

			if estadoFuncoes.AutoServerHop then
				api.AgendarTrocaAutomaticaServidor(10)
			end
		end)

