			end
		end

		api.ProcessarJogador = function(arg, arg2, arg3, arg4, arg5)
			local function funcao21(arg6, arg7)
				api.ExecutarMetodoJogador(arg6, arg7, arg, arg2, arg5)
			end

			if arg4 then
				local blobMetodo = valoresConfig.BlobMethod

				if blobMetodo == "Bring" then
					funcao21("Blob_Bring", apiBlobman.Trazer)
				elseif blobMetodo == "Kill" then
					funcao21("Blob_Kill", apiBlobman.Matar)
				elseif blobMetodo == "Follow" then
					funcao21("Blob_Follow", apiBlobman.Seguir)
				elseif blobMetodo == "Remove Gucci" then
					funcao21("Blob_RemoveGucci", apiBlobman.RemoverGucci)
				elseif blobMetodo == "Lock" then
					local funcao22

					if arg2 then
						funcao22 = function(arg6)
							apiBlobman.LoopTravar(arg6, arg5)
						end
					else
						funcao22 = apiBlobman.Travar
					end

					funcao21("Blob_Lock", funcao22)
				elseif blobMetodo == "Kick" and not arg3 then
					local loopExpulsao

					if arg2 then
						loopExpulsao = apiBlobman.LoopExpulsar
					else
						loopExpulsao = apiBlobman.Expulsar
					end

					funcao21("Blob_Kick", loopExpulsao)
				end

				return
			end

			local alvoMetodos = estadoCompartilhado.TargetMethods
			local valor22, valor23 = api.ObterPersonagem(arg)

			if alvoMetodos["Remove Invisibility"] and valor23 then
				valor23.Massless = false
			end

			if alvoMetodos["Resolve Desync"] then
				funcao21("Resolve Desync", api.ResolverDessincronizacao)
			end

			if alvoMetodos.Bring then
				funcao21("Bring", api.TrazerJogador)
			end

			local expulsao = alvoMetodos.Kick
			local estado12

			if expulsao then
				local estado13 = arg3 and valoresConfig.KickServerMethod == "Void"

				if estado13 then
					estado12 = estado13
				else
					estado12 = not arg3 and not arg2
				end
			else
				estado12 = expulsao
			end

			if estado12 then
				funcao21("Kick", api.EnviarParaVoid)
			end

			if alvoMetodos.Kill then
				funcao21("Kill", api.Matar)
			end

			if alvoMetodos.Void then
				funcao21("Void", api.EnviarParaVoid)
			end

			if alvoMetodos["Remove Gucci"] then
				funcao21("Remove Gucci", api.RemoverGucci)
			end

			if alvoMetodos["Break Holdable"] then
				funcao21("Break Holdable", api.ConsumirItemAntiRede)
			end

			if alvoMetodos["Delete Seatables"] then
				funcao21("Delete Seatables", api.ExcluirAssentos)
			end
		end

