						if descendente:IsA("BasePart") and descendente.Name == "PaintPlayerPart" then
							descendente.CanTouch = not antiTinta

							if antiTinta then
								tabela16[descendente] = descendente:GetPropertyChangedSignal("CanTouch"):Connect(function()
