		local antiLagPersConexao = nil

		local function definirRakRedePacoteFiltro(filterOn)
			if typeof(getconnections) ~= "function" then
				return
			end

			for _, valor20 in ipairs({ remotos.Pacote, remotos.CriarLinhaAgarrao }) do
				if valor20 then
					local sucesso, conexoes = pcall(getconnections, valor20.OnClientEvent)

					if sucesso and conexoes then
						for _, valor21 in ipairs(conexoes) do
							if valor21.Disable and valor21.Function then
								local ehNosso = false

								for _, valor22 in ipairs(estadoCompartilhado.PacketDetectCallbacks or {}) do
									if valor21.Function == valor22 then
										ehNosso = true
										break
									end
								end

								if not ehNosso then
									if filterOn then
										valor21:Disable()
									elseif valor21.Enable then
										valor21:Enable()
									end
								end
							end
						end
					end
				end
			end
		end

		local function aplicarProfundoAntiLag(antiLagOn)
			local jogadorScripts = jogadorLocal:FindFirstChildOfClass("PlayerScripts")

			definirRakRedePacoteFiltro(antiLagOn)

			if not jogadorScripts then
				return
			end

			for _, descendente in ipairs(jogadorScripts:GetDescendants()) do
				if descendente:IsA("LocalScript") and (descendente.Name == "StickyPartsTouchDetection" or descendente.Name:lower():find("sticky") or descendente.Name:lower():find("touchdetect")) then
					descendente.Enabled = not antiLagOn
				end
			end
		end

		local function pararProfundoAntiLag()
			if antiLagPersConexao then
				antiLagPersConexao:Disconnect()
				antiLagPersConexao = nil
			end
		end

		local function inicioProfundoAntiLag()
			aplicarProfundoAntiLag(true)
			pararProfundoAntiLag()
			antiLagPersConexao = jogadorLocal.CharacterAdded:Connect(function()
				task.wait(1)

				if descarregado or not (alternadores.AntiLag and alternadores.AntiLag.Value and valoresConfig.AntiLagMode == "New") then
					return
				end

				aplicarProfundoAntiLag(true)
			end)
		end

		Protecoes:AddToggle("AntiLag", {
			Text = "Anti-Lag",
			Default = true,
			Tooltip = "Protege contra Lag de Linha e Lag de Grudentos",
			Callback = function(arg)
				local ativado = not arg
				if ativado and estadoCompartilhado.LookFigures.Enabled then
					alternadores.AntiLag:SetValue(true)
					return
				end
				jogadorLocal.PlayerScripts.CharacterAndBeamMove.Enabled = ativado
				jogadorLocal.PlayerScripts.StickyPartsTouchDetection.Enabled = ativado
				api.DefinirAntiLagShuriken(arg)

				pararProfundoAntiLag()

				if valoresConfig.AntiLagMode == "New" then
					if arg then
						inicioProfundoAntiLag()
					else
						aplicarProfundoAntiLag(false)
					end
				end

				if arg then
					task.delay(1.5, function()
						if descarregado or not alternadores.AntiLag.Value then
							return
						end

						for _, valor20 in pairs(estadoCompartilhado.PlayerList) do
