		local aplicarAntiExpulsaoDeslocamentos = function()
			local personagem, raiz, humanoide = api.ObterPersonagem()

			if not (personagem and humanoide and humanoide.Health > 0) then
				return
			end

			local caixaColisao = personagem:FindFirstChild("RagdollTouchedHitbox")

			if not caixaColisao then
				return
			end

			local cframe = CFrame.new(valoresConfig.AKOffsetX, valoresConfig.AKOffsetY, valoresConfig.AKOffsetZ) * CFrame.Angles(math.rad(valoresConfig.AKRotX), math.rad(valoresConfig.AKRotY), math.rad(valoresConfig.AKRotZ))

			for _, parte in ipairs(personagem:GetChildren()) do
				if parte:IsA("BasePart") then
				for _, conectado in ipairs(parte:GetConnectedParts()) do
					local solda = conectado:FindFirstChild("StickyWeld")

					if solda and solda.Part1 == caixaColisao then
						remotos.EventoParteGrudenta:FireServer(conectado, caixaColisao, cframe)
					end
				end
			end
			end
		end

		local reancorarAntiExpulsaoBrinquedo = function()
			local personagem, raiz, humanoide = api.ObterPersonagem()

			if not personagem then
				return
			end

			local caixaColisao = personagem:FindFirstChild("RagdollTouchedHitbox")

			if not caixaColisao then
				return
			end

			for _, parte in ipairs(personagem:GetChildren()) do
				if parte:IsA("BasePart") then
				for _, conectado in ipairs(parte:GetConnectedParts()) do
					local solda = conectado:FindFirstChild("StickyWeld")

					if solda and solda.Part1 == caixaColisao then
						local modelo = conectado:FindFirstAncestorOfClass("Model")

						if modelo then
							api.DestruirBrinquedo(modelo)
						else
							solda:Destroy()
						end

						return
					end
				end
			end
			end
		end

