	do
		local Barreira = abas.Brinquedos:AddRightGroupbox("Barreira", "circle-slash")
		local estado12 = false
		local estado13 = false

		Barreira:AddToggle("BreakBarrierT", {
			Text = "Desativar Barreira da Casa",
			Default = false,
			Tooltip = "Impede que brinquedos de fora sejam destruídos dentro das casas e vice-versa",
			Callback = function(arg)
				estado12 = arg and not descarregado
				if not estado12 or estado13 then
					return
				end
				estado13 = true

				task.spawn(function()
					local ComidaHamburguer = nil
					local valor20 = nil
					local valor21 = nil
					local estado14 = false

					local function funcao21()
						if valor21 and valor20 and valor20.Parent and jogadorLocal.Character and valor20:IsDescendantOf(jogadorLocal.Character) then
							api.Teleportar(valor20, valor21)
						end

						valor21 = nil
						valor20 = nil

						if estado14 then
							estadoCompartilhado.States.Owning = false
							estado14 = false
						end

						if ComidaHamburguer then
							estadoCompartilhado.ToyAuraReserved[ComidaHamburguer] = nil
							api.DestruirBrinquedo(ComidaHamburguer)
							ComidaHamburguer = nil
						end
					end

					local sucesso, resultado = pcall(function()
						if api.BarreiraEstaQuebrada() then
							if estado12 then
								notificar("A barreira já está quebrada!")

								if alternadores.DeleteBarriers then
									alternadores.DeleteBarriers:SetValue(true)
								end
							end

							return
						end

						while true do
							if estado12 and task.wait() then
								local valor22, valor23, valor24 = api.ObterPersonagem()

								if not (valor23 and valor24 and valor24.Health > 0) or estadoCompartilhado.States.Owning then
									continue
								else
									local function funcao22()
										return estado12 and jogadorLocal.Character == valor22 and valor23.Parent and valor24.Health > 0
									end

									ComidaHamburguer = api.GerarBrinquedo("FoodHamburger", nil, 4, true)

									if not ComidaHamburguer then
										continue
									else
										local segurarParte = ComidaHamburguer:WaitForChild("HoldPart", 0.35)
										local segurarItemRemotoFuncao = segurarParte and segurarParte:WaitForChild("HoldItemRemoteFunction", 0.35)
										local rigidoRestricao = segurarItemRemotoFuncao and segurarParte:WaitForChild("RigidConstraint", 0.35)

										if not (funcao22() and segurarItemRemotoFuncao and rigidoRestricao) then
											funcao21()
											continue
										else
											while funcao22() and estadoCompartilhado.States.Owning do
												task.wait()
											end

											if not funcao22() then
												funcao21()
												break
											else
												local cQuadro2 = valor23.CFrame
												valor20 = valor23
												valor21 = cQuadro2
												estado14 = true
												estadoCompartilhado.States.Owning = true
												api.Teleportar(valor23, workspace.Waypoints.BlueHouse)
												local agora2 = os.clock()

												while true do
													task.wait()
													if not (not funcao22() or jogadorLocal.InPlot.Value or os.clock() - agora2 > 0.7) then
														continue
													end
													break
												end

												if not funcao22() or not jogadorLocal.InPlot.Value then
													funcao21()
													continue
												else
													local valor25 = ComidaHamburguer

													task.spawn(function()
														if funcao22() and valor25.Parent and segurarItemRemotoFuncao.Parent then
															pcall(function()
																segurarItemRemotoFuncao:InvokeServer(valor25, valor22)
															end)
														end
													end)

													local agora3 = os.clock()

													while true do
														task.wait()
														if not (not funcao22() or not rigidoRestricao.Parent or rigidoRestricao.Attachment1 or os.clock() - agora3 > 0.7) then
															continue
														end
														break
													end

													if not funcao22() or not rigidoRestricao.Parent or not rigidoRestricao.Attachment1 then
														funcao21()
														continue
													else
														api.DestruirBrinquedo(ComidaHamburguer)
														estadoCompartilhado.ToyAuraReserved[ComidaHamburguer] = nil
														ComidaHamburguer = nil
														task.wait(0.5)
														funcao21()

														if not funcao22() then
															break
														else
															task.wait(1)

															if estado12 and api.BarreiraEstaQuebrada() then
																if estado12 then
																	notificar("A barreira foi quebrada!")

																	if alternadores.DeleteBarriers then
																		alternadores.DeleteBarriers:SetValue(true)
																	end
																end

																break
															else
																continue
															end
														end
													end
												end
											end
										end
									end
								end
							end

							break
						end
					end)

					funcao21()
					estado13 = false

					if not sucesso then
						warn("[House Barrier] " .. tostring(resultado))
					end
				end)
			end,
		})

		Barreira:AddLabel("BarrierStatus", { Text = "Status atual da barreira: 🟢" })
	end

