		local function funcao22(arg, arg2, arg3, min, max, rounding, arg4)
			local valor21 = valor20
			local adicionarControleDeslizante = valor21.AddSlider
			local tabela16 = { Text = arg2 }
			local valor22

			if arg4 then
				valor22 = brinquedosAuraConfiguracoes[arg3][arg4]
			else
				valor22 = brinquedosAuraConfiguracoes[arg3]
			end

			tabela16.Default = valor22
			tabela16.Min = min
			tabela16.Max = max
			tabela16.Compact = true
			tabela16.Rounding = rounding

			tabela16.Callback = function(arg5)
				if not arg4 then
					brinquedosAuraConfiguracoes[arg3] = arg5
					return
				end
				local valor23 = brinquedosAuraConfiguracoes[arg3]
				local x

				if arg4 == "X" then
					x = arg5
				else
					x = valor23.X
				end

				local y

				if arg4 == "Y" then
					y = arg5
				else
					y = valor23.Y
				end

				if arg4 ~= "Z" then
					arg5 = valor23.Z
				end

				local valor24 = brinquedosAuraConfiguracoes
				local valor25 = arg3
				local cframe

				if arg3 == "Offset" then
					cframe = CFrame.new(x, y, arg5)
				else
					cframe = Vector3.new(x, y, arg5)
				end

				valor24[valor25] = cframe
