								end
							end

							task.wait()
						end
					end

					task.wait()
				end
			end,
		})

		Diversos:AddButton({
			Text = "Destruir Todos os Brinquedos",
			Func = function()
				if estadoCompartilhado.States.DestroyingToys then
					return
				end
				estadoCompartilhado.States.DestroyingToys = true
				local tabela16 = {}

				for _, inventario in pairs(estadoCompartilhado.Inventories) do
					for _, filho in pairs(inventario:GetChildren()) do
						if filho:IsA("Model") then
							tabela16[#tabela16 + 1] = filho
						end
					end
				end

				local valor24 = bibliotecaUI:Notify({
					Title = "Resopaste",
					Description = "Destruídos 0/" .. #tabela16 .. " brinquedos",
					Persist = true,
					SoundId = idSomNotificacao,
					BigIcon = "rbxassetid://79685990879972",
					Volume = volumeNotificacao,
					IconColor = Color3.new(1, 1, 1),
				})

				for i, valor25 in ipairs(tabela16) do
					api.DestruirObjeto(valor25)
					valor24:ChangeDescription("Destruídos " .. i .. "/" .. #tabela16 .. " brinquedos")
				end

				while valoresConfig.DestroyThread and not descarregado do
					RunService.Heartbeat:Wait()
				end

				estadoCompartilhado.States.DestroyingToys = false

				task.delay(0.25, function()
					valor24:Destroy()
				end)
			end,
		})
	end

