		api.SalvarPredefinicoesPersonalizadasAC = function(arg, arg2)
			if not valor20 then
				return false, "Your exploit does not support filesystem presets."
			end

			local sucesso = pcall(function()
				if not isfolder("Resonance") then
					makefolder("Resonance")
				end

				if not isfolder("Resonance/AutoClickerPresets") then
					makefolder("Resonance/AutoClickerPresets")
				end

				writefile(texto5 .. "/" .. arg .. ".json", HttpService:JSONEncode(arg2))
			end)

			local texto6

			if sucesso then
				texto6 = nil
			else
				texto6 = "Não foi possível salvar o arquivo da predefinição."
			end

			return sucesso, texto6
		end

