	api.ObterAlvo = function()
		if not bibliotecaUI.IsMobile and mouse then
			return mouse.Target
		end
		local areaVisaoTamanho = cameraAtual.ViewportSize
		local valor20 = cameraAtual:ViewportPointToRay(areaVisaoTamanho.X / 2, areaVisaoTamanho.Y / 2)
		local raioParametros = RaycastParams.new()
		raioParametros.FilterType = Enum.RaycastFilterType.Exclude
		local valor21 = api.ObterPersonagem()

		if valor21 then
			raioParametros.FilterDescendantsInstances = { valor21 }
		end

		local impacto = workspace:Raycast(valor20.Origin, valor20.Direction * 1000, raioParametros)
		return impacto and impacto.Instance
	end

	api.ObterPontoImpacto = function()
		if not bibliotecaUI.IsMobile and mouse then
			return mouse.Hit
		end
		local areaVisaoTamanho = cameraAtual.ViewportSize
		local valor20 = cameraAtual:ViewportPointToRay(areaVisaoTamanho.X / 2, areaVisaoTamanho.Y / 2)
		local raioParametros = RaycastParams.new()
		raioParametros.FilterType = Enum.RaycastFilterType.Exclude
		local valor21 = api.ObterPersonagem()

		if valor21 then
			raioParametros.FilterDescendantsInstances = { valor21 }
		end

		local impacto = workspace:Raycast(valor20.Origin, valor20.Direction * 1000, raioParametros)
		local cframe

		if impacto then
			cframe = CFrame.new(impacto.Position)
		else
			cframe = CFrame.new(valor20.Origin + valor20.Direction * 1000)
		end

		return cframe
	end

	api.AdicionarAtalho = function(arg, arg2, arg3, arg4, arg5, arg6)
		arg:AddLabel(arg3):AddKeyPicker(arg2, { Text = arg3, Default = arg4, NoUI = true, Mode = arg5, Callback = arg6 })

		if arg5 == "Toggle" then
			estadoCompartilhado.ToggleStates[arg3] = false
		end

		estadoCompartilhado.RegisteredKeybinds[arg3] = function()
			if arg5 == "Toggle" then
				estadoCompartilhado.ToggleStates[arg3] = not estadoCompartilhado.ToggleStates[arg3]
				arg6(estadoCompartilhado.ToggleStates[arg3])
			else
				arg6(true)
			end
		end

		table.insert(estadoCompartilhado.KeybindNames, arg3)
	end

	api.AdicionarBotaoMobile = function(arg, posicao)
		if not estadoCompartilhado.RegisteredKeybinds[arg] or estadoCompartilhado.ActiveDraggableButtons[arg] then
			return
		end

		local valor20 = bibliotecaUI:AddDraggableButton(arg, function()
			local valor20 = estadoCompartilhado.RegisteredKeybinds[arg]

			if valor20 then
				valor20()
			end
		end)

		if typeof(posicao) == "UDim2" then
			valor20.Button.Position = posicao
		end

		estadoCompartilhado.ActiveDraggableButtons[arg] = valor20
		return valor20
	end

	api.RemoverBotaoMobile = function(arg)
		local valor20 = estadoCompartilhado.ActiveDraggableButtons[arg]
		if not valor20 then
			return
		end
		valor20:Destroy()
		estadoCompartilhado.ActiveDraggableButtons[arg] = nil
	end

