					maiorAlcanceAlcance = maiorAlcanceAlcance and maiorAlcanceAlcance.Value
					valor24.Line = booleanoValor
					valor25.LineValue = maiorAlcanceAlcance
					local linha = tabela16.Line
					local linha2 = tabela16.Line
					local valor26 = jogadorLocal
					tabela16.Line.Name = "FartherReach"
					linha.Value = true
					linha2.Parent = valor26
					maiorAlcanceCompradoNotificador.Parent = workspace
					limitadoTempoBrinquedoEvento.Name = "FurtherReachBoughtNotifier"
					limitadoTempoBrinquedoEvento.Parent = passeJogoEventos
					local conexao = nil

					local function funcao21(personagem)
						if not conexao.Connected or descarregado then
							return
						end
						local agarrandoScript = personagem and personagem:WaitForChild("GrabbingScript", 5)
						if not (conexao.Connected and not descarregado and personagem == jogadorLocal.Character and agarrandoScript and agarrandoScript.Parent == personagem and agarrandoScript:IsA("LocalScript")) then
							return
						end

						if tabela16.Script then
							tabela16.Script:Disconnect()
						end

						local function funcao22()
							if conexao.Connected and not descarregado and personagem == jogadorLocal.Character and agarrandoScript.Parent == personagem and agarrandoScript.Enabled and limitadoTempoBrinquedoEvento.Parent then
								limitadoTempoBrinquedoEvento:FireServer()
							end
						end

						agarrandoScript.Enabled = false
						agarrandoScript.Enabled = true

						tabela16.Script = agarrandoScript:GetPropertyChangedSignal("Enabled"):Connect(function()
							if agarrandoScript.Enabled then
								task.delay(1, funcao22)
							end
						end)

						task.delay(1, funcao22)
					end

					conexao = jogadorLocal.CharacterAdded:Connect(funcao21)
					tabela16.Connection = conexao
					task.spawn(funcao21, jogadorLocal.Character)
				else
					tabela16.Enabled = false

					if tabela16.Connection then
						tabela16.Connection:Disconnect()
					end

					if tabela16.Script then
						tabela16.Script:Disconnect()
					end

					if tabela16.Line and tabela16.Line.Parent then
						if tabela16.LineValue == nil then
							tabela16.Line:Destroy()
						else
							tabela16.Line.Value = tabela16.LineValue
						end
					end

					if tabela16.Event and tabela16.Event.Parent and tabela16.Toys.Parent then
						local evento = tabela16.Event
						local brinquedos = tabela16.Toys
						tabela16.Event.Name = "LimitedTimeToyEvent"
						evento.Parent = brinquedos
					end

					if tabela16.Notifier and tabela16.Notifier.Parent and tabela16.Events.Parent then
						tabela16.Notifier.Parent = tabela16.Events
					end

					local valor20 = tabela16
					local valor21 = tabela16
					local valor22 = tabela16
					local valor23 = tabela16
					tabela16.Connection = nil
					valor20.Script = nil
					valor21.Line = nil
					valor22.Event = nil
					valor23.Notifier = nil
					local agarrandoScript = jogadorLocal.Character and jogadorLocal.Character:FindFirstChild("GrabbingScript")

					if agarrandoScript and agarrandoScript:IsA("LocalScript") then
						agarrandoScript.Enabled = false
						agarrandoScript.Enabled = true
					end
				end

				local agarraoPartes = workspace:FindFirstChild("GrabParts")

				if agarraoPartes then
					agarraoPartes:Destroy()
				end
			end,
		})

		PassesJogo2:AddToggle("GradientLineT", {
			Text = "Linha com Gradiente",
			Default = false,
			Tooltip = "Muda a cor da sua linha para o gradiente configurado na aba Configuração",
			Callback = function(gradienteLinha)
				estadoFuncoes.GradientLine = gradienteLinha

				task.spawn(function()
					local gradientes = estadoCompartilhado.Gradients

					while task.wait(0.5) and estadoFuncoes.GradientLine and not descarregado do
						local atualizarLinhaCoresEvento = ReplicatedStorage.DataEvents.UpdateLineColorsEvent
						local dispararServidor = atualizarLinhaCoresEvento.FireServer
						local corSequencia = ColorSequence.new
						local tabela17 = {}
						local valor20 = ColorSequenceKeypoint.new(0, gradientes.Color1)
						local valor21 = ColorSequenceKeypoint.new(0.125, gradientes.Color2)
						local valor22 = ColorSequenceKeypoint.new(0.25, gradientes.Color3)
						local valor23 = ColorSequenceKeypoint.new(0.375, gradientes.Color4)
						local valor24 = ColorSequenceKeypoint.new(0.5, gradientes.Color5)
						local valor25 = ColorSequenceKeypoint.new(0.625, gradientes.Color6)
						local valor26 = ColorSequenceKeypoint.new(0.75, gradientes.Color7)
						local valor27 = ColorSequenceKeypoint.new(0.875, gradientes.Color8)
						local novo = ColorSequenceKeypoint.new
						local pontoCor = gradientes.DotColor
						tabela17[1] = valor20
						tabela17[2] = valor21
						tabela17[3] = valor22
						tabela17[4] = valor23
						tabela17[5] = valor24
						tabela17[6] = valor25
						tabela17[7] = valor26
						tabela17[8] = valor27

						do
							local valores_2 = table.pack(novo(1, pontoCor))
							table.move(valores_2, 1, valores_2.n, 9, tabela17)
						end

						local cor1 = gradientes.Color1
						local cor2 = gradientes.Color2
						local cor3 = gradientes.Color3
						local cor4 = gradientes.Color4
						local cor5 = gradientes.Color5
						local cor6 = gradientes.Color6
						local cor7 = gradientes.Color7
						local cor8 = gradientes.Color8
						local pontoCor2 = gradientes.DotColor
						dispararServidor(atualizarLinhaCoresEvento, corSequencia(tabela17), cor1, cor2, cor3, cor4, cor5, cor6, cor7, cor8, pontoCor2)
					end
				end)
			end,
		})

