		local valor20 = api.CriarSeletorJogadores(ListaBranca, "Whitelist", estadoCompartilhado.Whitelisted)

		valor20:OnChanged(function()
			if estadoFuncoes.SilentAim then
				api.RecarregarMiraSilenciosa()
			end
		end)

		local tabela16 = {}
		local amigoEstadoStatusAlterado = nil

		pcall(function()
			amigoEstadoStatusAlterado = jogadorLocal.FriendStatusChanged
		end)

		local function funcao21(arg, arg2)
			if descarregado or not estadoFuncoes.AutoWhitelistFriends or arg == jogadorLocal or arg.Parent ~= Players or api.EhJogadorProtegido(arg) then
				return
			end
			local estado12 = valor20.Value[arg] == true

			if arg2 then
				if estado12 then
					return
				end
				tabela16[arg.UserId] = true
			else
				if not tabela16[arg.UserId] then
					return
				end
				tabela16[arg.UserId] = nil
				if not estado12 then
					return
				end
			end

			local tabela17 = {}

			for k, valor21 in valor20.Value, nil, nil do
				if k ~= arg then
					tabela17[k] = valor21
				end
			end

			if arg2 then
				tabela17[arg] = true
			end

			valor20:SetValue(tabela17)
		end

		local function funcao22(arg)
			if arg == jogadorLocal or arg.Parent ~= Players or not estadoFuncoes.AutoWhitelistFriends then
				return
			end
			local sucesso, resultado = pcall(jogadorLocal.IsFriendsWith, jogadorLocal, arg.UserId)

			if sucesso then
				funcao21(arg, resultado)
			end
		end

		ListaBranca:AddDivider("Configurações")

		ListaBranca:AddToggle("AutoWhitelistFriends", {
			Text = "Adicionar Amigos à Lista Branca",
			Default = false,
			Tooltip = "Adiciona seus amigos automaticamente à lista branca",
			Callback = function(autoListaBrancaAmigos)
				if estadoFuncoes.AutoWhitelistFriends == autoListaBrancaAmigos then
					return
				end
				estadoFuncoes.AutoWhitelistFriends = autoListaBrancaAmigos
				api.DefinirConexaoExecucao("AutoWhitelistFriends", Players.PlayerAdded, autoListaBrancaAmigos, funcao22)

				if amigoEstadoStatusAlterado then
					pcall(api.DefinirConexaoExecucao, "AutoWhitelistStatus", amigoEstadoStatusAlterado, autoListaBrancaAmigos, function(arg, arg2)
						if arg2 == Enum.FriendStatus.Friend or arg2 == Enum.FriendStatus.NotFriend then
							funcao21(arg, arg2 == Enum.FriendStatus.Friend)
						end
					end)
				end

				if not autoListaBrancaAmigos then
					return
				end

				task.spawn(function()
					for _, valor21 in Players:GetPlayers() do
						if descarregado or not estadoFuncoes.AutoWhitelistFriends then
							return
						end
						funcao22(valor21)
					end
				end)
			end,
		})

