			end
			return valor20, valor21, valor22
		end

		servicoConfigs.LoadJSON = function(arg, arg2)
			local sucesso, resultado = pcall(HttpService.JSONDecode, HttpService, arg2)
			local valor20, valor21 = carregarJSON(arg, arg2)

			if valor20 and sucesso and typeof(resultado) == "table" and typeof(resultado.ResonanceUI) == "table" then
