		if typeof(parte3) == "Instance" then
			parte3:Destroy()
		end

		getgenv().ResonanceRunning = false
        pcall(function() workspace.FallenPartsDestroyHeight = getgenv().ResonanceOriginalFallenHeight end)
		local valor20 = print
		local texto5 = ("Descarregado com sucesso em %* segundos"):format(string.format("%.3f", os.clock() - agora2))
		valor20(texto5)
	end)

	task.spawn(function()
		for _, valor20 in bibliotecaUI.Tabs, nil, nil do
			for _, valor21 in valor20.Groupboxes, nil, nil do
				valor21:Resize()
			end
		end
	end)

	do
		local tabela16 = {}

		Players.PlayerRemoving:Connect(function(jogador)
			if descarregado then
				return
			end

			if valoresConfig.SelectedACPoseCenter == jogador then
				valoresConfig.SelectedACPoseCenter = nil
			end

			local tabela17 = {}
			local estado12 = estadoCompartilhado.SelectedPlayersAC[jogador] == true

			for _, jogadorSeletor in ipairs(estadoCompartilhado.PlayerDropdowns) do
				if jogadorSeletor.Selected[jogador] then
					jogadorSeletor.Selected[jogador] = nil
					jogadorSeletor.Values[jogador] = nil
					table.insert(tabela17, jogadorSeletor)
				end
			end

			if estado12 and api.SincronizarAlvosPoseAC then
				task.defer(api.SincronizarAlvosPoseAC)
			end

			if #tabela17 == 0 then
				return
			end
			api.NotificarEvento("Player Left", { leftPlayer = api.FormatarJogador(jogador), listCount = #tabela17 }, "Jogador Saiu")
			tabela16[jogador.UserId] = tabela17
		end)

		Players.PlayerAdded:Connect(function(jogador)
			local valor20 = tabela16[jogador.UserId]
			if not valor20 or descarregado or not getgenv().ResonanceRunning then
				return
			end
			tabela16[jogador.UserId] = nil

			for _, valor21 in ipairs(valor20) do
				if not table.find(valor21.Dropdown.Values, jogador) then
					valor21.Dropdown:AddValues({ jogador })
				end

				if valor21.Multi == false then
					valor21.Dropdown:SetValue(jogador)
					table.clear(valor21.Values)
					valor21.Values[jogador] = true
					table.clear(valor21.Selected)
					valor21.Selected[jogador] = true
				else
					local tabela17 = {}

					for k, valor22 in pairs(valor21.Selected) do
						tabela17[k] = valor22
					end

					tabela17[jogador] = true
					valor21.Dropdown:SetValue(tabela17)
					table.clear(valor21.Values)

					for k, valor22 in pairs(tabela17) do
						valor21.Values[k] = valor22
					end

					valor21.Selected[jogador] = true
				end
			end

			api.NotificarEvento("Player Rejoined", { rejoinedPlayer = api.FormatarJogador(jogador), listCount = #valor20 }, "Jogador Reentrou")
		end)
	end

	notificar("Script carregado em " .. math.round((tick() - getgenv().LoadTime) * 100) / 100 .. " segundos", "Resopaste", 71450094482101)
	getgenv().LoadTime = nil

	return {
		copyright = "Copyright (c) 2026 Project Resopaste. All rights reserved.",
	}
end
]=]
bundle["Launcher"] = [[
local pacote = ...
local ambiente = getgenv and getgenv() or _G
if ambiente.ResonanceRunning or ambiente.ResonanceStarting then
    warn("O Resopaste já está em execução ou iniciando")
    return
end
assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
ambiente.ResonanceStarting = true
local limpeza
local function registrarLimpeza(fn) limpeza = fn end
local cache = {}
local carregando = {}
local function importarModulo(nome)
    if cache[nome] then return cache[nome] end
    assert(not carregando[nome], "Circular module dependency: " .. tostring(nome))
    assert(type(pacote[nome]) == "string", "Missing module: " .. tostring(nome))
    carregando[nome] = true
    local trecho, mensagem = loadstring(pacote[nome], "@Resonance/" .. nome)
    assert(trecho, mensagem)
    local sucesso, resultado = pcall(trecho, importarModulo)
    carregando[nome] = nil
    assert(sucesso, resultado)
    assert(type(resultado) == "table", "Invalid module: " .. nome)
    cache[nome] = resultado
    return resultado
end
local caminhoRecarga
local sucesso, resultado = xpcall(function()
    if type(writefile) == "function" and type(readfile) == "function" then
        local sucesso_2 = pcall(function()
            local linhas = {"local bundle = {}"}
            for _, nome in ipairs({"Interface", "Themes", "Configs", "IconAtlas", "Runtime", "Launcher", "Credits"}) do
                linhas[#linhas + 1] = string.format("bundle[%q] = %q", nome, pacote[nome])
            end
            linhas[#linhas + 1] = 'local run, message = loadstring(bundle.Launcher, "@Resonance/Launcher"); assert(run, message); return run(bundle)'
            writefile("ResonanceRestored.lua", table.concat(linhas, "\n"))
            assert(type(readfile("ResonanceRestored.lua")) == "string")
        end)
        if sucesso_2 then caminhoRecarga = "ResonanceRestored.lua" end
    end
    local trecho, mensagem = loadstring(pacote.Runtime, "@Resonance/Runtime")
    assert(trecho, mensagem)
    return trecho(importarModulo, caminhoRecarga, registrarLimpeza)
end, function(mensagem)
    if debug and debug.traceback then return debug.traceback(tostring(mensagem), 2) end
    return tostring(mensagem)
end)
ambiente.ResonanceStarting = false
if not sucesso then
    if limpeza then pcall(limpeza) end
    ambiente.ResonanceRunning = false
    warn("Falha na inicialização do Resopaste: " .. tostring(resultado))
    return nil, resultado
end
return resultado
]]
